/* AI 研究知识库，手工策展（本文件不被构建覆盖）。
 * 七组单页：method 方法论 / eng 工程方式 / roles 岗位 / companies 公司 / biz 商业模式 / career 职业路径 / ops 操盘手册。
 * 每页 body 为 markdown（观点与事实分离：客观描述 + 要点），渲染进详情单页。 */
DB.kb = {
  groups: [
    { key: 'method', name: '方法论', en: 'Methodologies', desc: 'AI 领域反复被验证的研究与训练方法论——每条都能在时间线里找到实证事件。', pages: [
      { id: 'scaling', name: 'Scaling Law 规模定律', def: '能力随参数、数据、算力幂律提升的经验规律，是整个行业资本开支的理论依据。', body: '## 定义\n\n模型损失随参数量 N、数据量 D、算力 C 按幂律下降的经验规律（Kaplan 2020 / Chinchilla 2022 修正）。它是「先堆算力再谈其他」路线的理论依据。\n\n## 要点\n\n- Chinchilla 修正：同算力下数据与参数应等比放大，推翻了「参数优先」的旧共识\n- 预训练收益递减后，行业把扩展重心转向后训练与推理时计算\n- 规模定律是统计规律不是保证：具体能力（推理、 agent）并不平滑跟随\n\n## 本库视角\n\n追踪方式：各 lab 的训练规模披露与能力跃迁事件；反例（小模型超越）同样重要。' },
      { id: 'posttrain', name: '后训练三段式', def: 'SFT → 偏好优化 → 可验证奖励强化学习，决定模型可用性的全部训练。', body: '## 定义\n\n预训练之上的完整流水线：监督微调（SFT）教会格式与指令遵循 → 人类/AI 偏好优化（RLHF/DPO）塑造行为与安全边界 → 可验证奖励强化学习（RLVR）强化推理能力。\n\n## 要点\n\n- 模型的「性格」、拒答边界、输出风格主要由后训练决定，与参数规模关系不大\n- 偏好数据质量 > 数量：标注员水平直接封顶模型水平\n- 后训练是「观点注入」环节——本库要求观点与事实分离的根源\n\n## 本库视角\n\n各 lab 的后训练披露极少；可从模型行为差异反推。' },
      { id: 'rlvr', name: 'RLVR 可验证奖励强化学习', def: '用可程序化验证的奖励（数学对错、测试通过）做强化学习，推理模型的核心训练法。', body: '## 定义\n\nReward = 可自动验证的信号：数学答案对错、代码测试通过率、形式化证明。绕开偏好模型的主观性，让强化学习在客观域内尽情扩展。\n\n## 要点\n\n- 推理模型（长思考系列）的能力跃迁主要来自 RLVR，而非更大预训练\n- 适用域受限：可验证的领域（数学/代码/工具调用）进步快，开放域（写作）慢\n- 「验证器」本身成为新的研究资产与瓶颈\n\n## 本库视角\n\n评测与基准主题的levance：谁有更强验证器，谁就能扩展更远。' },
      { id: 'distill', name: '蒸馏 Distillation', def: '用教师模型的输出训练学生模型，把能力搬到低成本推理侧。', body: '## 定义\n\n教师模型生成（或标注）数据，学生模型模仿其分布；是能力从前沿向低成本扩散的主要通道。\n\n## 要点\n\n- 成本收益悬殊：教师推理一次的价格可换取学生无限的部署能力\n- 前沿 lab 的服务条款普遍限制用输出训练竞品——「蒸馏条款」是商业护城河\n- 风险：误差与偏见同样被蒸馏，且学生常高估自己的能力边界\n\n## 本库视角\n\n开源小模型能力的快速跟进多与蒸馏相关；追踪条款变化即追踪商业策略。' },
      { id: 'synthetic', name: '合成数据方法', def: '用模型生成训练数据，缓解高质量人类语料枯竭的数据墙。', body: '## 定义\n\n以模型生成、过滤、改写人类数据替代或扩充真实语料。数据墙（高质量人类文本存量见底）叙事的主流解法。\n\n## 要点\n\n- 关键在「过滤漏斗」而非生成量：质量闸门决定合成数据是补药还是毒药\n- 模式坍缩风险：合成数据训练的模型输出分布收窄，多样性下降\n- 验证闭环（合成数据 + 可验证奖励）是当前最强的组合\n\n## 本库视角\n\n训练与数据主题覆盖不足（覆盖分 2），是采集缺口。' },
      { id: 'testtime', name: '推理时扩展', def: '用更多推理期计算换更强答案：长思考、多次采样、自我验证。', body: '## 定义\n\n把「算力换能力」从训练期搬到推理期：模型在回答时进行更长思考、并行采样、自我校验。\n\n## 要点\n\n- 等效于给每个请求一个可调的「思考预算」：难度越高、预算越值钱\n- 成本结构剧变：token 消耗量级上升，推理基础设施压力陡增\n- 边界：对开放主观问题收益有限，对可验证问题收益巨大\n\n## 本库视角\n\n推理与基础设施主题的直接推手：token 消耗上升利好算力层。' },
      { id: 'retrieval', name: '检索增强（RAG 方法论）', def: '先检索外部知识再生成，把私有知识与时效性接进模型。', body: '## 定义\n\n查询 → 检索（向量/关键词/混合）→ 重排 → 生成 → 引用。把模型从「闭卷考试」变成「开卷考试」。\n\n## 要点\n\n- 分块策略与检索质量决定上限；模型再强也救不回没检索到的事实\n- 引用溯源是幻觉治理与合规的双重刚需\n- 与长上下文的关系是互补非替代：成本与准确性各有所长\n\n## 本库视角\n\n企业落地第一站（产业链 L3 rag 节点）。' },
      { id: 'agenticloop', name: 'Agentic Loop 智能体循环', def: '规划 → 执行 → 观察 → 修正的闭环；智能体可靠性的全部工程都在这个循环里。', body: '## 定义\n\nagent 的最小运行时：模型规划下一步 → 调用工具执行 → 观察结果 → 修正计划 → 循环直至完成。\n\n## 要点\n\n- 可靠性瓶颈在错误传播：单步 95% 正确率的十步流程整体只有约 60%\n- 上下文管理是核心工程：历史压缩、工具结果裁剪、记忆外置\n- 人在回路的插入点设计（何时确认、何时自动）是产品与安全的交汇\n\n## 本库视角\n\n本工作台的构建脚本就是手工版 agentic loop 的产物。' },
      { id: 'multiagent', name: '多智能体编排方法', def: '规划者/执行者/评审者分工协作，用组织结构换单模型能力上限。', body: '## 定义\n\n多个 agent 以固定或动态拓扑协作：主从、流水线、辩论、市场等编排模式。\n\n## 要点\n\n- 收益来自专业分工与交叉验证，成本是 token 翻倍与调试复杂度\n- 失效模式：信息丢失在交接处、集体幻觉互相强化\n- 评审者/验证者角色对可靠性提升最显著\n\n## 本库视角\n\n参考台的 studio 三 agent 模式即此方法论的落地。' },
      { id: 'alignment', name: '对齐方法', def: '让模型行为符合人类意图与价值的全部技术：RLHF、Constitutional、可解释性。', body: '## 定义\n\n对齐 = 意图对齐（做该做的事）+ 行为对齐（不做不该做的事）+ 可审计。主流路线：RLHF、DPO、Constitutional AI（用原则自批判）、可解释性研究。\n\n## 要点\n\n- 对齐税：安全训练常以牺牲少量能力为代价，量化这个税是研究前沿\n- Spec 对齐比价值对齐更易工程化：先让模型稳定遵循规格\n- 可解释性（机制可解释性）是对齐的长期保险：看懂内部再谈控制\n\n## 本库视角\n\nAI 安全与对齐主题政策敞口 5 分，全赛道最高。' },
      { id: 'redteam', name: '红队方法', def: '以攻击者视角系统性探测模型失效模式，发布前评估的标配。', body: '## 定义\n\n组织化地尝试让模型产生有害/失控/越权行为：人工红队 + 自动化攻击 + 对抗用户模拟。\n\n## 要点\n\n- 覆盖面矩阵：内容安全 / 越狱 / 提示注入 / agent 越权 / 能力滥用\n- 攻击与防御同步演化：红队结论的半衰期很短，需回归测试\n- 第三方红队（AISI 类机构）正在成为监管要求的发布前置\n\n## 本库视角\n\n安全护栏节点（L3）与安全主题的连接点。' },
      { id: 'datflywheel', name: '数据飞轮', def: '用户使用产生数据 → 数据改进模型 → 模型吸引更多使用；产品护城河的动力学。', body: '## 定义\n\n产品使用 → 交互数据/偏好数据 → 模型迭代 → 体验提升 → 更多使用的正循环。是应用层少数可持续的护城河形态。\n\n## 要点\n\n- 飞轮的燃料是「带反馈信号的交互」：拒绝/重试/编辑是最有价值的数据\n- 冷启动破解：先用第三方模型 + 人工运营攒信号，再切自研\n- 隐私与授权边界是飞轮的合规约束\n\n## 本库视角\n\n商业与投融资主题的判断依据：看产品有没有飞轮，而不是看 DAU。' },
      { id: 'bitterlesson', name: '苦涩教训', def: 'Sutton 2019：长期看，依赖算力的一般方法总是打败依赖人类知识的精巧方法。', body: '## 定义\n\nRich Sutton 的工程哲学：过去 70 年 AI 进步最大的方法，都是利用更多算力、少依赖人类先验知识的方法。\n\n## 要点\n\n- 用作判断框架：两个方案冲突时，押注「更容易吃进算力与数据」的那个\n- 例外边界：安全、评测、人类偏好这些「人类知识」环节没有被打败\n- 与本库的关系：别为精巧的人工分类学过度投资，保持语料层与结构层的分离\n\n## 本库视角\n\n本库「时间线文档优于精巧 schema」的建库哲学即由此来。' },
      { id: 'anatomy', name: '行业拆解方法论', def: '本台五层产业链 × 节点拆解卡的出处：MECE、波特价值链、炒作曲线、市场地图与卖方研究模板的落地方式。', body: '## 五个被反复验证的范式\n\n本台的拆解不是自创分类学，而是把五个成熟范式各取一面、拼成一个可执行的作业系统：\n\n1. **MECE 与金字塔原理（麦肯锡/明托）**——拆分必须相互独立、完全穷尽。\n   落地：五层之间不重叠（每个节点唯一归属一层）；层内节点并集力争穷尽该层全部供给形态；聚合为零的节点显式暴露「还没建库」的缺口，而不是假装覆盖。\n2. **波特价值链**——按价值流而非产品分类切行业。\n   落地：L1→L5 是一条从算力到商业生态的价值传递链，节点间 upstream/downstream 即价值流边；分析任何事件先问「价值沿链怎么移动」。\n3. **Gartner 炒作曲线 / S 曲线**——技术按阶段演进，阶段决定策略。\n   落地：改造为六阶段（萌芽/过热/挤泡沫/爬坡/成熟/重构），标在每个节点与层页分布上；并入「重构期」刻画被新范式重写的存量。注意：阶段是观点层判断，不是事实。\n4. **a16z / Sequoia 市场地图（market map）**——一张图放进一个赛道的全部玩家与细分。\n   落地：节点页即市场地图的单元格——定义、二级细分、玩家、大事、档案、模型全部聚合在一个坐标上。\n5. **卖方研究 initiation 模板（驱动-护城河-催化剂-风险）**——覆盖一个行业先写首覆盖报告。\n   落地：拆解卡五字段即其变体——价值来源（驱动）、护城河、瓶颈（风险）、领先指标（催化剂）、阶段（周期位置）。\n\n## 本台的附加纪律\n\n- **事实与观点分离**：拆解卡全部是观点层，可被证据整卡推翻，修正走 git 留痕；\n- **领先指标先于结论**：卡上的 signals 是「该看什么」，不是「已发生什么」；\n- **证据挂在结构上**：任何新闻先进节点坐标，再谈判断——这是本台与新闻台的边界；\n- **MECE 是方向不是状态**：缺口节点公开陈列（弱节点仪表），补齐优先于重排。\n\n## 使用动线\n\n产业链全景（拿骨架与阶段分布）→ 层页（成熟度分布 + 弱节点仪表）→ 节点页（读拆解卡 + 证据聚合）→ 二级细分（最细维度）→ 议题账本（把判断写成可结算的账）。\n\n## 本库追踪\n\n骨架：console/chain.js（手工策展，71 节点 + 二级细分）；阶段判断随证据迭代，修正记录可查。' }
    ]},
    { key: 'eng', name: '工程方式', en: 'Engineering Practices', desc: '把模型变成可靠产品的工程实践——评测、上下文、护栏、成本。', pages: [
      { id: 'harness', name: 'Harness 评测与运行外壳', def: '包裹模型的标准运行环境：统一输入输出、工具集、评分器，让能力可比、可回归。', body: '## 定义\n\nHarness 是模型的「考试外壳 + 工作台」：统一加载模型、注入工具与上下文、按协议采集输出、交给评分器。没有 harness 的评测结论不可比。\n\n## 要点\n\n- 构成：任务加载器 + 运行时（工具/沙箱/重试策略）+ 评分器 + 结果登记\n- 同一 harness 跨模型跑分才有意义；换壳即换考试\n- 生产 harness 与评测 harness 应同构——测什么就部署什么\n\n## 本库视角\n\n本库的 validate.py + 构建脚本即是内容库的 harness。' },
      { id: 'evals', name: 'Eval 评测体系', def: '离线基准 + 在线指标 + 回归评测三层，是 AI 产品的「测试驱动开发」。', body: '## 定义\n\n三层评测：离线基准（能力水位）、在线指标（真实使用质量：采纳率/重试率）、回归评测（每次改动必跑的黄金集）。\n\n## 要点\n\n- 先建评测再改提示词/模型——没有 eval 的优化是玄学\n- 黄金集要带「困难负例」与历史事故样本\n- LLM-as-judge 可扩展但有偏，需定期与人工标注对齐\n\n## 本库视角\n\nvalidate.py 六条规则 + md-lint CI 即内容库的回归评测。' },
      { id: 'prompt', name: 'Prompt 工程', def: '以指令、示例与结构化约束稳定地引导模型行为。', body: '## 定义\n\n通过指令设计、少样本示例、输出格式约束、角色设定等手段稳定获得目标行为。\n\n## 要点\n\n- 已从「咒语炼金」工程化：模板版本管理、变量化、评测驱动迭代\n- 结构化输出（JSON schema）比自由文本可靠一个量级\n- 提示是脆弱资产：换模型/版本就要重测——必须进版本库\n\n## 本库视角\n\n本库线索模板即是给「未来的自己」的 prompt。' },
      { id: 'context', name: 'Context 上下文工程', def: '决定什么信息、以什么形式、在什么时机进入模型上下文。', body: '## 定义\n\nPrompt 工程的超集：管理模型可见的全部上下文——系统指令、检索内容、工具结果、历史记忆的取舍与压缩。\n\n## 要点\n\n- 上下文是稀缺资源：无关信息会稀释注意力（context rot）\n- 工具结果要裁剪再进历史；长对话要摘要外置\n- 「写进去」与「检索进来」的边界是核心设计决策\n\n## 本库视角\n\n本工作台把 md 语料外置、按需渲染进上下文，即 context 工程。' },
      { id: 'rageng', name: 'RAG 工程', def: '分块、索引、检索、重排、引用五段的落地工程。', body: '## 定义\n\nRAG 的工程难点不在「能不能用」，在「答得准、可追溯、可维护」：分块策略、混合检索、重排、引用对齐、增量更新。\n\n## 要点\n\n- 分块：语义边界优于固定长度；元数据（标题/日期/来源）随块走\n- 混合检索（向量 + BM25）+ 重排器是性价比最高的组合\n- 引用必须对齐到原文片段，否则合规不可用\n\n## 本库视角\n\n本库全文检索（标题级）+ 双链是内容侧的轻量 RAG 前置。' },
      { id: 'finetune', name: '微调流水线', def: '数据准备 → 训练 → 评测 → 部署的受控迭代。', body: '## 定义\n\n以自有数据定制模型行为的完整流水线：数据清洗配对 → 训练（LoRA/全参）→ 评测对比基线 → 灰度部署。\n\n## 要点\n\n- 先问「提示 + RAG 能否解决」：微调适合风格/格式/领域语言，不适合注入新知识\n- 数据质量与配比决定一切；1000 条精标常胜过 10 万条噪声\n- 必须冻结评测基线，否则「越调越差」不可察觉\n\n## 本库视角\n\n语料层（本库）天然是微调数据源——时间线结构可直接转为训练对。' },
      { id: 'datapipeline', name: '数据管线', def: '采集 → 清洗 → 去重 → 配比 → 版本化的数据基础设施。', body: '## 定义\n\nAI 产品的数据底座：多源采集、质量过滤、去重、配比混合、版本快照，使训练与评测可复现。\n\n## 要点\n\n- 数据版本化与代码同权：没有版本的数据集不可复现也不可回滚\n- 去重（模糊 + 精确）同时影响质量与污染控制\n- 来源配比是隐形的模型策略，配比改动要有评测背书\n\n## 本库视角\n\naihot-mirror 的采集→清洗→入库即一条微型数据管线。' },
      { id: 'inferenceopt', name: '推理优化与部署', def: '量化、批处理、缓存、路由，把推理成本曲线压下来的系统工程。', body: '## 定义\n\n在质量约束下压低延迟与成本：量化、连续批处理、KV cache 复用、语义缓存、大小模型路由。\n\n## 要点\n\n- 成本阶梯：缓存命中 ≈ 1/10 价、小模型 ≈ 1/5 价、量化 ≈ 1/2-1/4 价\n- 路由：简单请求走小模型，难的升级——需要好的「难度判别器」\n- 每次优化必须带质量回归评测，省了钱丢了质量等于没省\n\n## 本库视角\n\n模拟器页签就是这套工程的经济面。' },
      { id: 'observability', name: 'LLM 可观测', def: '对 prompt、上下文、输出、成本的全程留痕与回放。', body: '## 定义\n\nAI 产品特有的可观测：完整记录请求上下文、模型版本、工具调用链、输出与用户反馈，支持回放与归因。\n\n## 要点\n\n- 三类信号：质量（采纳/重试）、成本（token/调用）、安全（拦截/越狱尝试）\n- 模型版本与 prompt 版本必须进 trace，否则不可归因\n- 抽样回放比全量存储更经济，但事故样本必须全留\n\n## 本库视角\n\n本库「时间线 + 留痕」的写法与可观测同哲学。' },
      { id: 'guardrails', name: '护栏与内容审查', def: '输入输出两侧的安全过滤与策略执行层。', body: '## 定义\n\n在模型外再包一层策略执行：输入侧注入检测与合规过滤，输出侧敏感内容拦截、越权动作确认、引用校验。\n\n## 要点\n\n- 模型内对齐 + 模型外护栏双保险：护栏是确定性的最后防线\n- agent 场景重点在「动作护栏」：高危操作强制人在回路\n- 误拦截率与漏拦截率同样重要：过严的产品等于不能用\n\n## 本库视角\n\n安全主题（政策敞口 5）的产品侧出口。' },
      { id: 'mcpeng', name: '工具协议与集成', def: 'MCP 等标准化协议把工具、数据源接入模型的工程。', body: '## 定义\n\n以标准协议（MCP）暴露工具与数据源：一次实现、多模型可用；把 N×M 的集成问题降到 N+M。\n\n## 要点\n\n- 协议价值 = 接入的模型数 × 工具数的乘积效应\n- 工具描述即 prompt：描述写得差，模型就用不对\n- 安全面扩大：每个工具都是攻击面，授权与沙箱必须随协议走\n\n## 本库视角\n\n本库「双链」是内容侧的工具协议雏形。' },
      { id: 'costeng', name: '成本工程', def: '以月账单为 KPI 的反向工程：缓存、路由、批处理、限额。', body: '## 定义\n\n把推理账单当一级工程指标：语义缓存、模型路由、批处理折扣、上下文裁剪、预算与限额。\n\n## 要点\n\n- 先量测再优化：trace 里 token 分布决定优化顺序\n- 缓存是最高性价比：命中一次省 90%，设计「可缓存的任务形态」比调参有用\n- 限额与降级预案是产品韧性的一部分\n\n## 本库视角\n\n成本模拟器（Lab）即此工程的经济沙盘。' },
      { id: 'abtest', name: '灰度与 A/B', def: '模型与提示的变更管理：金丝雀发布与在线对照。', body: '## 定义\n\n模型/提示变更走金丝雀灰度 + 在线 A/B 对照，以采纳率等在线指标而非离线分决定放量。\n\n## 要点\n\n- 模型变更 ≠ 代码变更：同样的「改一版」，分布性影响远大于确定性修复\n- 对照要控制任务分布，否则「提升」只是题目变简单\n- 回滚预案必须先于发布存在\n\n## 本库视角\n\n本库只读快照 + git 版本即是内容侧的灰度机制。' }
    ]},
    { key: 'roles', name: '岗位', en: 'Roles', desc: 'AI 行业的岗位地图：干什么、核心技能、怎么进入、市场信号。', pages: [
      { id: 'res-scientist', name: '研究科学家', def: '提出并验证新方法，以论文与模型能力跃迁为产出。', body: '## 干什么\n\n提出新架构/训练方法/对齐技术，设计并解读实验，产出论文与可复现代码；前沿 lab 中与工程师结对把想法跑成能力。\n\n## 核心技能\n\n- 数学与实验设计；把模糊问题形式化为可测假设\n- 大规模实验的阅读能力：从失败 run 里读出信号\n- 写作与表达：论文即产品\n\n## 入口与信号\n\n- 入口：顶会一作（NeurIPS/ICML/ICLR）→ 实习转正；博士并非唯一路径但仍是主流门票\n- 市场信号：头部 lab 开价已与职业运动员同构；竞争在「品味」而非代码' },
      { id: 'res-eng', name: '研究工程师', def: '把研究想法跑成大规模实验的人，lab 里最稀缺的混合角色。', body: '## 干什么\n\n实现研究想法的训练/评测代码，管理大规模 run，诊断 loss 曲线与失败案例；介于研究与 infra 之间。\n\n## 核心技能\n\n- 分布式训练工程（数据/张量/流水并行）+ 研究品味\n- 调试直觉：从异常曲线反推是数据、超参还是 infra 问题\n- 速度：想法到实验的周转时间是 lab 的核心竞争力\n\n## 入口与信号\n\n- 入口：强工程背景 + 论文复现经历；竞赛（Kaggle 等）仍是有效信号\n- 市场信号：研究工程师在 lab 招聘中与科学家同价，缺口更大' },
      { id: 'llm-eng', name: 'LLM 应用工程师', def: '用模型能力组装产品的全栈工程师：prompt、RAG、工具、评测。', body: '## 干什么\n\n在模型之上做产品：prompt/上下文工程、RAG 管线、工具集成、评测与成本控制。\n\n## 核心技能\n\n- 评测驱动开发习惯；上下文工程与结构化输出\n- 后端工程基本功（数据、缓存、并发）\n- 对模型失效模式的直觉（幻觉、注入、长上下文衰减）\n\n## 入口与信号\n\n- 入口：后端/全栈转岗 + 公开项目（带 eval 的开源 agent）\n- 市场信号：需求最大的岗位，区分度在「有没有评测习惯」' },
      { id: 'agent-eng', name: 'Agent 工程师', def: '构建长程自主系统：规划、工具、记忆、沙箱与可靠性工程。', body: '## 干什么\n\n设计 agentic loop 的生产实现：工具协议（MCP）、沙箱与权限、记忆系统、多步任务可靠性。\n\n## 核心技能\n\n- 可靠性工程：错误传播控制、检查点与回滚\n- 工具设计：工具描述即 prompt，接口即能力边界\n- 安全意识：越权、注入、爆炸半径控制\n\n## 入口与信号\n\n- 入口：LLM 应用工程师进阶 + 自动化/系统背景加分\n- 市场信号：2026 年最热的岗位方向，编码 agent 公司为主要雇主' },
      { id: 'data-eng', name: '数据工程师（AI）', def: '训练与评测数据的采集、清洗、配比、版本化。', body: '## 干什么\n\n构建数据管线：多源采集、去重清洗、质量过滤、配比混合、数据集版本管理。\n\n## 核心技能\n\n- 管线工程（spark/ray 类）+ 去重与质量启发式\n- 数据嗅觉：知道什么数据会改变模型什么行为\n- 版权与合规意识\n\n## 入口与信号\n\n- 入口：数据工程转 AI；有「数据版本化」实践者优先\n- 市场信号：数据墙叙事下，数据获取与合成岗身价上行' },
      { id: 'annotation', name: '标注与专家数据', def: '人类偏好与专家演示的规模化生产，后训练质量的源头。', body: '## 干什么\n\n设计标注任务、培训与质检标注团队；专家数据（医生/律师/工程师演示）的招募与规范。\n\n## 核心技能\n\n- 任务设计与规范撰写：标注指南即产品规格\n- 质量体系：多人交叉、一致性度量、金标抽检\n- 领域网络：专家众包的供给能力\n\n## 入口与信号\n\n- 入口：标注运营/语言学/领域专家转型\n- 市场信号：RLHF 后专家时薪陡涨，「博士标注」成供应链' },
      { id: 'eval-eng', name: '评测工程师', def: '建设基准与回归体系，给模型能力与产品改动发「体检报告」。', body: '## 干什么\n\n设计与维护 benchmark、评测 harness、回归集；区分真提升与刷榜，产出可解释的评测报告。\n\n## 核心技能\n\n- 统计与实验设计（显著性、方差、任务分布）\n- harness 工程（沙箱、工具注入、输出采集）\n- 对数据污染与作弊模式的警觉\n\n## 入口与信号\n\n- 入口：研究/QA 转型；harness 开源贡献是硬通货\n- 市场信号：评测工程师成为 lab 与企业共同的稀缺岗' },
      { id: 'safety-redteam', name: '安全研究员与红队', def: '系统性探测与缓解模型失效模式：越狱、注入、失控、滥用。', body: '## 干什么\n\n攻击自己的模型：设计对抗用例、自动化攻击管线、评估护栏；与政策团队共同定发布门槛。\n\n## 核心技能\n\n- 攻击面知识：提示注入、agent 越权、多模态攻击\n- 报告能力：把漏洞变成可执行的缓解与回归项\n- 伦理与合规框架（AI Act/自监管承诺）\n\n## 入口与信号\n\n- 入口：安全研究（CTF/漏洞挖掘）转 AI；公开红队演练履历\n- 市场信号：监管（欧盟 AI Act）直接创造岗位；AISI 类机构扩编' },
      { id: 'ml-platform', name: 'ML 平台工程师', def: '训练与推理平台的内部产品：算力调度、工作流、模型仓库。', body: '## 干什么\n\n为研究员与产品团队提供自助式 ML 基础设施：训练调度、实验跟踪、模型注册、特征/数据平台。\n\n## 核心技能\n\n- K8s/调度/存储 + GPU 资源管理（配额、抢占、碎片整理）\n- 平台产品思维：内部用户满足度即采用率\n- 成本核算：算力即预算，平台即财务系统\n\n## 入口与信号\n\n- 入口：SRE/平台工程转 ML；GPU 集群运维经验稀缺\n- 市场信号：算力规模每家翻倍，平台岗稳定扩张' },
      { id: 'gpu-sre', name: 'GPU 基础设施 / SRE', def: '万卡集群的可靠性：网络、故障、散热与电力。', body: '## 干什么\n\n建设与运维万卡级集群：拓扑与组网、故障域设计、热与电、检查点与恢复。\n\n## 核心技能\n\n- 网络工程（InfiniBand/以太网 RDMA）+ 硬件故障诊断\n- 大规模系统韧性：MTBF 下的检查点策略\n- 供应链意识：卡、模块、电力交期\n\n## 入口与信号\n\n- 入口：HPC/网络工程转 AI infra\n- 市场信号：资本开支暴涨的直接受益岗，现金报价最高的一档' },
      { id: 'ai-pm', name: 'AI 产品经理', def: '在概率性系统上定义产品：评测即需求文档。', body: '## 干什么\n\n定义 AI 产品行为与边界：把模糊能力翻译成用户价值，设计人在回路、管理不确定性预期、用评测管模型迭代。\n\n## 核心技能\n\n- 评测即 PRD：把「体验变好」拆成可测指标\n- 不确定性设计：置信度呈现、降级路径、期望管理\n- 成本意识：每个功能都有 token 账单\n\n## 入口与信号\n\n- 入口：成熟 PM + 亲手做过 eval/原型（会跑 notebook 成为门槛）\n- 市场信号：会写 eval 的 PM 与不会写的薪资分层明显' },
      { id: 'ai-design', name: 'AI 设计师', def: '为不确定性而设计：交互、置信度呈现与人在回路体验。', body: '## 干什么\n\n设计生成式产品的交互语言：流式输出、编辑而非重试、置信与来源呈现、失败态设计。\n\n## 核心技能\n\n- 不确定性 UX：不承诺确定性，同时不让用户恐慌\n- 人机协作节奏：何时让 AI 先行、何时用户先行\n- 原型能力：能直接用模型拼可玩原型\n\n## 入口与信号\n\n- 入口：产品设计师 + 模型使用深度\n- 市场信号：生成式 UI 的设计语言尚未定型，先入场者定义范式' },
      { id: 'sol-eng', name: '售前 / 解决方案工程师', def: '把模型能力翻译成客户场景与报价的桥梁岗。', body: '## 干什么\n\n客户场景诊断 → 方案设计（模型/微调/RAG/部署）→ POC 交付 → 报价与边界管理。\n\n## 核心技能\n\n- 场景到技术的映射直觉 + 诚实的边界管理（不承诺幻觉）\n- POC 快速交付：两周内跑出客户数据上的 demo\n- 成本报价能力：token 账单即商业方案\n\n## 入口与信号\n\n- 入口：交付/架构师 + 模型实操\n- 市场信号：企业落地潮的最大缺口岗之一' },
      { id: 'fde', name: 'FDE 前沿部署工程师', def: '驻在客户现场把模型接进业务系统的人：交付结果即产出，AI 交付链条上最靠客户的一环。', body: '## 干什么\n\n入职即进客户现场，把模型能力接进真实系统：数据与权限接入、上下文与工具编排、评测与验收口径制定、上线后调优。Palantir 体系中与产品设计者（PD）配对，Echo（领域与判断）与 Delta（工程实现）分工是这个岗位的原型。\n\n## 核心技能\n\n- 现场判断：在没有标准答案的客户环境里定义问题、划定验收边界\n- 全栈交付：读得懂数据、写得了管线、能在业务方前讲清技术取舍\n- 沉淀能力：把一次性交付变成可复用资产（本体论、模板、评测集）\n\n## 与相邻岗位的边界\n\n- 对售前/解决方案工程师：售前止于方案与报价，FDE 对上线结果与续费负责\n- 对 ML 平台工程师：平台服务内部用户，FDE 服务外部客户并承担交付毛利\n- 对 LLM 应用工程师：应用工程师为自己的产品写代码，FDE 在别人的系统里写代码\n\n## 入口与信号\n\n- 入口：咨询/交付/解决方案工程师 + 可演示的模型实操；行业专家（医疗/金融/制造）转岗是主要供给\n- 市场信号：薪酬普遍高于同级软件工程师，但挂牌区间、中位数与自选样本三类口径不可互比 ⚠️；国内需求增速存在 42 倍与 729% 两个异口径（见 docs/2026待核实清单.md 六）\n- 认证缺位：海外把部署写进产品 SKU，国内侧刚出现厂商认证（腾讯云 ADP FDE，2026-08-17），岗位标准尚未定型\n\n## 本库追踪\n\n线索：交付与组织/FDE前沿部署工程师（分级信源见 docs/FDE来源档案.md）。产业链 L5「交付与实施（FDE）」节点。' },
      { id: 'ai-gov', name: 'AI 治理与政策', def: '合规、评估标准与组织内 AI 治理体系的设计与执行。', body: '## 干什么\n\n对内：模型使用的政策、风险分级、审计留痕；对外：监管跟踪（AI Act 等）、标准参与、政府事务。\n\n## 核心技能\n\n- 法规文本到工程要求的翻译能力\n- 风险分级与文档体系（模型卡、评估报告）\n- 多方语言能力：对工程讲控制，对监管讲证据\n\n## 入口与信号\n\n- 入口：合规/政策/安全研究转型\n- 市场信号：欧盟 AI Act 执法期开始，企业端岗位放量' }
    ]},
    { key: 'companies', name: '公司', en: 'Companies', desc: 'AI 产业主要玩家的单页档案：定位、产品、模式与本库追踪。', pages: [
      { id: 'openai', name: 'OpenAI', def: '前沿 lab + 消费级超级入口 ChatGPT，行业叙事的定义者。', body: '## 定位\n\n前沿模型（GPT 系）+ 消费入口（ChatGPT）+ 开发者平台（API/DevDay）三线并行；营利化重组后资本结构独特。\n\n## 产品与模式\n\n- ChatGPT 订阅 + 广告（Ads 年化 10 亿美元级）；API/MaaS 按量计费\n- 与微软的算力与分成结构是行业最大绑定\n\n## 本库追踪\n\n线索：基础模型/GPT系列、消费级AI应用/ChatGPT产品、商业与投融资/OpenAI融资与重组（覆盖最全）。' },
      { id: 'anthropic', name: 'Anthropic', def: '以安全叙事立身的前沿 lab，编码与 Agent 场景的最强卖方。', body: '## 定位\n\nClaude 系模型 + Claude Code/Agent SDK；RSP/ASL 分级的安全框架输出者；编码占比极高的 B 端收入结构。\n\n## 产品与模式\n\n- API 订阅（Fable/Mythos 双旗舰分层）；企业授权\n- ARR 反超 OpenAI 的口径争议（是否扣云分成）是经典案例\n\n## 本库追踪\n\n线索：基础模型/Claude、Agentic编码/ClaudeCode、智能体平台/ClaudeAgentSDK。' },
      { id: 'gdm', name: 'Google DeepMind', def: '研究纵深最强的体系：Gemini 全家桶 + 机器人 + 世界模型 + 科学 AI。', body: '## 定位\n\nGemini 模型矩阵（Flash 双轨）+ Gemini Robotics + 世界模型 + Alpha 系科学成果；自研 TPU 全栈。\n\n## 产品与模式\n\n- 模型 API + 云（Vertex）+ 消费入口（Gemini App）\n- 研究→产品的转化速度是其独有优势\n\n## 本库追踪\n\n线索：基础模型/Gemini、具身智能/GeminiRobotics。' },
      { id: 'meta', name: 'Meta', def: '开源 Llama 路线的旗手，超级智能 lab 重组后策略摇摆。', body: '## 定位\n\nLlama 开源权重路线定义者；超级智能 lab 重组后开源与闭源策略反复，靠广告主业供血算力。\n\n## 产品与模式\n\n- 广告主业 + 开源生态影响力 + AI 眼镜硬件\n- 开源是策略而非慈善：生态标准与人才吸引\n\n## 本库追踪\n\n线索：开源模型与生态/Llama、AI安全与对齐（人才流失事件）。' },
      { id: 'msai', name: 'Microsoft AI', player: 'Microsoft', def: 'Copilot 生态 + 自研 MAI 模型，云与模型绑定销售的样本。', body: '## 定位\n\nMustafa Suleyman 领导的 MAI 自研模型 + Copilot 全家桶 + Azure OpenAI 分销双重身份。\n\n## 产品与模式\n\n- Copilot 订阅与企业授权；GitHub Copilot 独立线\n- 「自研 + 分销竞品」的双轨结构是研究样本\n\n## 本库追踪\n\n线索：开发者工具、智能体平台（MAF/LangGraph 收编）。' },
      { id: 'nvidia', name: 'NVIDIA', def: 'AI 算力垄断者：芯片 + 网络 + CUDA 生态 + 推理引擎全栈。', body: '## 定位\n\n数据中心 GPU 垄断 + 网络互连 + CUDA 软件生态；129.3 亿美元收购 Hugging Face 后把开源社区也纳入版图。\n\n## 产品与模式\n\n- 硬件销售 + 软件订阅（AI Enterprise）+ 生态投资\n- 供应链与出口管制是最大变量\n\n## 本库追踪\n\n线索：推理与基础设施/AI芯片竞争；产业链 L1 gpu 节点核心玩家。' },
      { id: 'xai', name: 'xAI（SpaceXAI）', def: '并入 SpaceX 后的算力怪兽：Grok 系列与 SpaceX 资源整合。', body: '## 定位\n\n2026-02 与 SpaceX 全股合并（估值约 1.25 万亿美元），Grok 系列主打长时运行 Agent，品牌署名 SpaceXAI。\n\n## 产品与模式\n\n- Grok 订阅/API；与 Cursor 的模型栈整合（收购 Anysphere）\n- SpaceX 算力与数据（Starlink/发射）的独家组合\n\n## 本库追踪\n\n线索：基础模型/GPT系列（Grok 事件）、Agentic编码/Cursor、商业与投融资/AI人才与并购潮。' },
      { id: 'deepseek', name: 'DeepSeek', def: '开源高性价比路线的破局者，以极低成本训练出前沿能力。', body: '## 定位\n\nMIT 开源权重 + 极致推理成本，V4 系列延续开源；「效率叙事」的代表。\n\n## 产品与模式\n\n- 开源权重 + 低价 API；对定价体系有系统性冲击\n- 组织形态（小团队 + 研究驱动）本身是研究样本\n\n## 本库追踪\n\n线索：开源模型与生态/DeepSeek。' },
      { id: 'qwen', name: '阿里通义 Qwen', def: '开源权重生态的第一序列：Qwen 系全尺寸开源 + 云上商业化。', body: '## 定位\n\nQwen3.8 系全尺寸开源（Apache 2.0），Max 旗舰登顶 Code Arena；云（百炼）+ 开源双轮。\n\n## 产品与模式\n\n- 开源权重 + 云 API/MaaS（百炼）+ 企业交付\n- 开源即获客：权重先行、云上变现\n\n## 本库追踪\n\n线索：开源模型与生态/Qwen。' },
      { id: 'zhipu', name: '智谱 GLM', def: '国产开源主力：GLM-5.3 前沿编码 + 涌现网安能力。', body: '## 定位\n\nGLM 系开源权重（MIT）+ 降价最激进（API 约 Opus 4.8 的 1/40）+ 全栈国产算力承载。\n\n## 产品与模式\n\n- 开源 + API + 私有化交付\n- 「年营收超 100 亿美元的机构须接受安全审查」的合规样本\n\n## 本库追踪\n\n线索：开源模型与生态/智谱GLM。' },
      { id: 'moonshot', name: '月之暗面', def: 'Kimi 助手的消费级打法与融资速度的争议样本。', body: '## 定位\n\nKimi 消费入口 + Kimi K3 模型（盲测对标 GLM-5.3）；融资节奏（半年多轮、估值跳涨）在待核实清单挂账。\n\n## 产品与模式\n\n- 消费订阅 + API；长上下文叙事的早期定义者\n\n## 本库追踪\n\n线索：消费级AI应用；待核实清单（融资口径存疑 ⚠️）。' },
      { id: 'minimax', name: 'MiniMax', def: '全模态与视频生成的开源竞争者。', body: '## 定位\n\nH3 全模态视频生成开源，与字节 Seedance 正面对垒；海外产品（Talkie 类）起家的双线玩家。\n\n## 产品与模式\n\n- 开源权重 + API + 海外消费产品\n\n## 本库追踪\n\n线索：开源模型与生态/MiniMax、多模态大模型/视频生成竞赛。' },
      { id: 'hunyuan', name: '腾讯混元', def: '大厂开源转向的样本：Hy4 preview 770B 开源。', body: '## 定位\n\n混元 Hy4 preview 开源（770B/49B MoE、1M 上下文），盲测与 GLM-5.3、Kimi K3 分差不足 0.1；大厂从闭源转开源的策略样本。\n\n## 产品与模式\n\n- 开源权重 + 微信生态整合（元宝/微信 AI）\n\n## 本库追踪\n\n线索：开源模型与生态/国产大模型群像。' },
      { id: 'seed', name: '字节跳动 Seed', def: 'Seedance 视频生成与豆包生态：模型 + 应用双轮的大厂。', body: '## 定位\n\nSeed 研究线（视频生成 Seedance 与 MiniMax 对垒）+ 豆包消费入口 + 火山引擎 MaaS 分发。\n\n## 产品与模式\n\n- 消费订阅 + 云 MaaS + 广告主业的算力反哺\n\n## 本库追踪\n\n线索：开源模型与生态/国产大模型群像、多模态大模型/视频生成竞赛。' },
      { id: 'mistral', name: 'Mistral', def: '欧洲开源旗舰：地缘稀缺性即商业模式。', body: '## 定位\n\n欧洲开源模型旗手，「欧洲的自主 AI 选项」地缘定位；开源 + 商业授权双线。\n\n## 产品与模式\n\n- 开源权重 + 企业授权 + 欧洲主权云合作\n\n## 本库追踪\n\n线索：开源模型与生态（覆盖待补，缺口信号）。' },
      { id: 'hf', name: 'Hugging Face', def: '开源模型社区的基础设施：被 NVIDIA 以 129.3 亿美元收购后仍承诺开放。', body: '## 定位\n\n模型/数据集 Hub + transformers 生态 + 评测（Open LLM Leaderboard）；2026-09 被 NVIDIA 收购，黄仁勋承诺保持开放。\n\n## 产品与模式\n\n- 企业版 Hub（私有化/SGE）+ 计算服务（Inference Endpoints）\n- 「开源社区被算力巨头收购」是治理研究的标志性事件\n\n## 本库追踪\n\n线索：推理与基础设施/AI芯片竞争、开源模型与生态。' },
      { id: 'cursor', name: 'Cursor（Anysphere）', player: 'Anysphere', def: 'AI 原生 IDE 代表，被 SpaceX 全资收购后成阵营变量。', body: '## 定位\n\nAI IDE 的商业化标杆（最快 1 亿美元 ARR）；被 OpenAI 断供后模型栈转向 Grok + 自研 Composer；Origin 代码托管 + Self-Hosted Machines 补全企业栈。\n\n## 产品与模式\n\n- 订阅（个人/Teams）+ 企业授权；模型路由（Cursor Router）降成本\n\n## 本库追踪\n\n线索：Agentic编码/Cursor（覆盖最全的线索之一）。' },
      { id: 'perplexity', name: 'Perplexity', def: '答案引擎的代表：AI 搜索对传统分发的正面进攻。', body: '## 定位\n\nAI 搜索/答案引擎品类定义者；检索 + 引用 + 订阅的模式，与浏览器/发布商的分发博弈持续。\n\n## 产品与模式\n\n- 订阅 + 广告试点 + 企业版； Comet 浏览器做入口延伸\n\n## 本库追踪\n\n线索：AI搜索与信息获取（覆盖不足，缺口信号）。' },
      { id: 'midjourney', name: 'Midjourney', def: '图像生成的独立头部：不融资、不 API 的异类样本。', body: '## 定位\n\n图像生成美学标杆；长期不融资不做 API 的独立路线，与生成视频赛道的错位竞争。\n\n## 产品与模式\n\n- 订阅制（Discord/Web）；版权诉讼（对训练数据的行业性挑战）\n\n## 本库追踪\n\n线索：多模态大模型（覆盖待补）。' },
      { id: 'runway', name: 'Runway', def: '视频生成的先行者：从创作者工具到影视工业化。', body: '## 定位\n\n视频生成最早商业化的一批；Gen 系列迭代与好莱坞/广告业渗透，与 Veo/可灵/Seedance 多线对垒。\n\n## 产品与模式\n\n- 订阅 + API（视频按秒计费）+ 影视行业合作\n\n## 本库追踪\n\n线索：多模态大模型/视频生成竞赛。' },
      { id: 'suno', name: 'Suno', def: 'AI 音乐生成的品类定义者，版权诉讼的中心。', body: '## 定位\n\n文生音乐头部；GEMA 案（慕尼黑法院驳回合理使用）是 AI 音乐训练数据版权在欧盟的首挫。\n\n## 产品与模式\n\n- 订阅（创作消费）；版权成本可能重构其单位经济\n\n## 本库追踪\n\n线索：语音与音频/Suno。' },
      { id: 'unitree', name: '宇树科技', def: '「人形机器人第一股」：极致性价比硬件 + 2026 科创板上市。', body: '## 定位\n\n四足起家、人形 G1/H1 系列；2026-08-19 科创板挂牌（发行价 150.8 元/PE 219 倍），资本市场为量产叙事定价。\n\n## 产品与模式\n\n- 整机销售（B 端科研/行业 + C 端开发者）+ 核心零部件自研降本\n\n## 本库追踪\n\n线索：具身智能/宇树科技（时间线完整）。' },
      { id: 'figure', name: 'Figure AI', def: '人形机器人商用化的美系代表：Helix VLA 模型 + 场景落地。', body: '## 定位\n\n人形机器人 + 自研 VLA（视觉-语言-动作）模型 Helix；仓储/制造场景商用化叙事，与宇树的中美对照样本。\n\n## 产品与模式\n\n- RaaS（机器人即服务）探索 + 商业合作（宝马等）\n\n## 本库追踪\n\n线索：具身智能/Figure。' },
      { id: 'scaleai', name: 'Scale AI', def: '数据标注与评测的供应链枢纽，Meta 反向收购后的变形。', body: '## 定位\n\nRLHF/评测数据供应链核心；Meta 反向收购（acqui-hire）后分拆重组，军工线（Defense）独立发展。\n\n## 产品与模式\n\n- 数据标注 + 评测服务 + 政府合同\n- 「数据供应链被模型公司反向收购」是人才并购的形态样本\n\n## 本库追踪\n\n线索：商业与投融资/AI人才与并购潮、训练与数据（覆盖待补）。' },
      { id: 'amd', name: 'AMD', def: '算力第二极：Instinct 加速卡 + EPYC + ROCm，被头部实验室真实押注的替代路线。', body: '## 定位\n\n苏姿丰（Lisa Su）执掌；EPYC 服务器 CPU + Instinct 加速卡 + ROCm 软件栈三线，是大客户对冲单家垄断议价权的第二选择。\n\n## 产品与模式\n\n- 「以投资换采购」：2026-07-22 向 Anthropic 投资 50 亿美元、后者采购 2GW GPU\n- 开源模型的首发适配阵地（DeepSeek 系列、SGLang/vLLM 优化）是 ROCm 追赶 CUDA 的主要抓手\n\n## 本库追踪\n\n线索：推理与基础设施/AI芯片竞争（关键角色）、推理与基础设施/vLLM与推理引擎。产业链 L1「GPU 与 AI 加速卡」节点已登记。\n\n档案命中密集（MI355X 的 DeepSeek-R1 分离式推理 TCO、DeepSeek-V4 Flash RL 上线、单颗 MI300X 跑 V4 Flash、夏季开源生态观察「AMD 与 NVIDIA 主导发布量」）。缺口：尚无 AMD 专属线索，芯片竞争的叙事仍以 NVIDIA 为主角。' },
      { id: 'broadcom', name: 'Broadcom（博通）', def: '陈福阳的并购机器：网络芯片垄断 + 云厂商定制 ASIC 的隐形庄家。', body: '## 定位\n\nHock Tan（陈福阳）领导的并购整合型半导体公司；Tomahawk/Jericho 网络交换芯片是集群互连的在位垄断者，同时承接云厂商自研加速卡（XPU）的设计与量产。\n\n## 产品与模式\n\n- 2026-06-24 与 OpenAI 联合发布 LLM 推理芯片 Jalapeño\n- 定制 ASIC 长约绑定单一大客户；并购整合 + 毛利纪律的资本配置模式\n\n## 本库追踪\n\n线索：推理与基础设施/AI芯片竞争（关键角色）。\n\n缺口：本库档案仅 2 条且集中在 2026-06-24 单一事件；实体名未登记进产业链 L1 节点，定制 ASIC 的订单、产能与客户结构缺连续信源。' },
      { id: 'micron', name: '美光（Micron）', def: 'HBM 三供之一：显存是推理吞吐的真实瓶颈，存储厂因此站上算力牌桌。', body: '## 定位\n\nSanjay Mehrotra 执掌；与 SK 海力士、三星构成 HBM 三家供给格局。推理时代的瓶颈正从算力转向显存带宽与容量，存储厂因此进入 AI 算力牌桌。\n\n## 产品与模式\n\n- HBM 高带宽存储 + DRAM/NAND；Rubin 一代 GPU 配 288GB HBM4、约 22 TB/s 带宽\n- 2026-05-29 三星率先出样 HBM4E；SK 集团宣布五年晶圆产能翻倍\n\n## 本库追踪\n\n线索：推理与基础设施/AI芯片竞争；产业链 L1「HBM 与存储」节点把「美光」列为聚合关键词。\n\n缺口（诚实记录）：机构名录里美光的命中全部来自「HBM」这一话题词，「美光/Micron」实体名在档案与大事记中零直接命中；供给格局的叙述多来自对手侧（SK 海力士/三星）。' },
      { id: 'alphabet', name: 'Alphabet（谷歌母公司）', player: 'Google', def: '唯一全栈巨头：自研 TPU + Gemini + 云 + 分发入口，模型与投资双向下注。', body: '## 定位\n\nSundar Pichai 领导；唯一同时握有自研加速器（TPU）、前沿模型（Gemini）、云（Vertex/GCS）与十亿级分发入口（搜索/Android/Chrome）的公司，同时以投资方身份向下游模型公司下注。\n\n## 产品与模式\n\n- 2026-03-11 完成 320 亿美元收购 Wiz；2026-04-25 拟向 Anthropic 投资至高 400 亿美元\n- 2026-08-05 Jeff Dean 离职创办 Discovery Loop，研究负责人流动成为新变量\n- 广告主业面临 AI 答案式检索的侵蚀，云与订阅是第二曲线\n\n## 本库追踪\n\n单页看研究体系：本组 Google DeepMind 页。谷歌系关键词合并（Alphabet + Google DeepMind + Google Research）在档案侧命中 262 条，单主体口径为全库第三（机构名录口径：档案 168 条、大事记 7 条，次于 Anthropic 459 条、OpenAI 411 条）。\n\n线索：基础模型/Gemini、AI搜索与信息获取/GEO、推理与基础设施/AI芯片竞争。缺口：母公司层资本开支、反垄断进程与广告侵蚀无专属线索。' },
      { id: 'microsoft', name: 'Microsoft', player: 'Microsoft', def: '企业分发与云的超级渠道：Copilot 全家桶 + Azure + 自研 MAI，同时是最大模型买手的东道主。', body: '## 定位\n\nSatya Nadella 领导；AI 产业里唯一「渠道 + 算力 + 自研模型 + 被投公司股东」四重身份叠加的公司，Azure 既是 OpenAI 的算力东道主又是竞品分销口。\n\n## 产品与模式\n\n- 2026-01-26 Maia 200 自研推理芯片发布；2026-08-12 首发自研推理模型 MAI-Thinking-1\n- 2026-08-06 首次披露 OpenAI 贡献其 AI 收入约七成——渠道集中度风险公开化\n- 2025-05 Windows 原生支持 MCP；GitHub Copilot 是开发者侧最强分发资产\n\n## 本库追踪\n\n单页看 AI 事业部：本组 Microsoft AI 页。线索：基础模型/微软MAI、开发者工具/GitHubCopilot（最近一次 2026-07-27）、智能体平台/Agent框架。\n\n缺口：资本开支与电力锁定、Azure 份额竞争无独立线索。' },
      { id: 'amazon', name: 'Amazon（亚马逊）', player: 'Amazon', def: '云 + 电商双入口：AWS 自研芯片与 Bedrock 多模型货架，把 AI 塞进最大的交易与物流系统。', body: '## 定位\n\nJeff Bezos 创立；AWS 是全球最大云货架（Bedrock 多模型路由），电商与物流提供独有的私有数据与内部落地场景，同时是 Anthropic 的算力主力与独家外部分销渠道。\n\n## 产品与模式\n\n- 2026-08-26 英伟达订单增至三倍、新增 200 万颗 GPU；2026-07-01 AWS 砸 10 亿美元派工程师进驻客户\n- Bedrock 上的第三方模型陆续 GA（Grok 4.3 于 2026-06-17、OpenAI 模型于 2026-04-27）\n- 2026-08-05 上诉法院推翻禁令，Perplexity 购物智能体重返 Amazon；入口与数据边界的司法博弈进行中\n- 2026-08-17 被追踪到批量购书扫描训练后销毁——语料获取的灰色样本\n\n## 本库追踪\n\n线索：AI搜索与信息获取/Perplexity、推理与基础设施/AI芯片竞争（关键角色含「亚马逊」）。缺口：AWS 资本开支与 Trainium 自研芯片进展无专属线索。' },
      { id: 'tesla', name: 'Tesla（特斯拉）', def: '把自动驾驶栈搬进人形机器人：Optimus 是具身赛道最大的资本预期放大器。', body: '## 定位\n\nElon Musk 领导；FSD 视觉路线的量产数据积累直接迁移到 Optimus 人形机器人，是具身智能赛道资本预期最强的放大器。\n\n## 产品与模式\n\n- 2026-04-23 Model S/X 产线改建 Optimus 产线、最早 7 月投产；2026-07-09 三代初步定型并向供应链下达军令状\n- 2026-06-30 Cybercab 进入奥斯汀公开道路工程测试；2026-05-31 FSD 完成 6000+ 公里零干预横穿加拿大\n- 风险面：2026-07-03 得州致命车祸再次把自动驾驶责任问题推回台面\n- 模型依赖：Grok 4.5 曾于 SpaceX 与 Tesla 私测（同一集团内的算力与模型共享）\n\n## 本库追踪\n\n线索：具身智能/特斯拉Optimus（最近一次 2026-07-09）。缺口：Tesla 作为 AI 算力资本开支主体（自研训练集群）未单列。' },
      { id: 'spacex', name: 'SpaceX', def: '从发射到轨道算力：并入 xAI 后成为 AI 资本开支与「算力上天」叙事的主体。', body: '## 定位\n\nElon Musk 领导；2026-02-02 全股收购 xAI，合并体估值约 1.25 万亿美元并署名 SpaceXAI。发射与 Starlink 之外的新增叙事是把数据中心送上轨道。\n\n## 产品与模式\n\n- 2026-08-05 宣布 AI 算力上太空、独家采用 NVIDIA Vera Rubin；同日披露 SpaceXAI 单季资本开支 183.7 亿美元（接近微软同期总资本开支的四成）\n- 2026-06-16 宣布 600 亿美元全股收购 Cursor，2026-08-14 完成；2026-08-29 OpenAI 终止向 Cursor 供模型，工具链阵营化\n- 机构名录口径的档案命中在 companies 组居第 17–18 位：档案 30 条（与字节跳动 Seed 并列 30 条）、大事记 4 条\n\n## 本库追踪\n\n单页看模型线：本组 xAI（SpaceXAI）页。线索：Agentic编码/Cursor、推理与基础设施/AI芯片竞争、商业与投融资/AI人才与并购潮。产业链 L5「并购与整合」节点已登记。' },
      { id: 'palantir', name: 'Palantir', def: '把模型接进决策链的乙方：本体论 + 政府长约，AI 落地叙事里最赚钱的样板。', body: '## 定位\n\nAlex Karp（CEO）与 Shyam Sankar（CTO）领导；Foundry/Gotham/AIP 三层把大模型接进企业本体论与政府决策链，是「AI 落地到底谁赚钱」的样板公司。\n\n## 产品与模式\n\n- 软件订阅 + 政府长约；交付前置的ontology 工程是真实壁垒\n- 模型方与乙方的责任边界成为新争议面\n\n## 本库追踪\n\n交付模式侧已建档：Palantir 是线索 交付与组织/FDE前沿部署工程师 与 交付与组织/AI交付成本结构 的关键角色（机构名录口径命中 5 条线索、大事记 0、档案 2 条），Echo/Delta 分工、FDE 招聘与薪酬的一线信源登记在该线索及 docs/FDE来源档案.md（A1 官网招聘页 ✅A）；产业链 L5「交付与实施（FDE）」节点承接。\n\n事故与舆论侧覆盖仍薄：档案 2 条。其一为 2026-06-29 美军用 AI 选目标误炸伊朗学校（Anthropic Claude 嵌入 Palantir 系统，首日建议约 1000 个目标）；其二为 2026-08-03 强劲季度后 Karp 公开批评 AI 行业的「马克思主义」分配观。\n\n缺口：「模型嵌入决策链」作为独立线索仍未登记——它同时是商业模式样本与事故链路样本；Palantir 自身的收入结构、FDE 人数与政府合同节奏未纳入采集面。' },
      { id: 'servicenow', name: 'ServiceNow', def: '工作流 SaaS 的代理化样本：把 AI 装进 IT/HR/客服流程，卖流程而非模型。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2004 / Santa Clara | 官网 |\n| 上市地 / 代码 | NYSE: NOW | 2012-06 IPO |\n| 最新财年营收 | FY2025 $132.78 亿（+20.9%） | 2026-01-28 发布 |\n| 盈利 | FY2025 净利润约 $17 亿（推算）；Q4 $4.01 亿 | ◐ 待 10-K |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露总数；大型企业为主 | ◐ |\n| 员工 | 约 29,187 人（2025 年末） | Macrotrends |\n| 市值 / 估值 | 约 $1,091 亿（2026-11-02）；股价约 $105–109 | Yahoo/Macrotrends |\n| 主要股东 | 机构为主 | ◐ |\n| 数据截至 | 财务 FY2025；行情 2026-11-02 | — |\n\n## 定位与沿革\n\n企业工作流 SaaS 的代理化样本：Now Platform 把 ITSM、ITOM、HR、客服、安全运营与低代码应用串成流程，再用 Now Assist 与 AI Agents 把「流程执行」交给 AI。\n\n- 2004 年由 Fred Luddy 在 Santa Clara 创立；2012-06 在纽交所上市。\n- 2019 年 Bill McDermott 任 CEO，推动从 ITSM 扩展到 HR、客服、安全与低代码平台。\n- FY2025 营收 $132.78 亿（+20.9%）；Q4 营收 $35.7 亿、订阅收入 $34.66 亿、净利 $4.01 亿。\n- Now Assist（生成式 AI）2025 年 ACV 超 $6 亿，公司目标 2026 年超 $10 亿。\n- 2025 年 Q3 授权 5 拆 1 拆股；2026-01 董事会追加 $50 亿回购。\n- 2026 年推进 AI Agents、Armis（安全暴露面管理）等并购；股价从 2024 年 $2,189 亿市值回落至 2026-11 约 $1,091 亿。\n\n## 创始人与管理层\n\n- **Fred Luddy（创始人）**：ServiceNow 创始人，曾任 Peregrine Systems CTO；现为董事会成员/顾问（◐）。\n- **Bill McDermott（董事长 & CEO）**：2019 年加入，此前任 SAP CEO；2026 年仍在任。\n- **Amit Zavery（总裁、首席产品官 & COO）**：负责产品与运营；前 Google Cloud 副总裁（◐ 履历待核）。\n- **Gina Mastantuono（CFO）**：财务负责人；具体任期待核。\n- 董事会：多数独立董事；具体名单待采集。\n\n## 商业模式\n\n- **收入结构**：订阅为主（FY2025 订阅收入占比 >95%）；按席位、工作流/用量与 AI 消费计价。\n- **销售动作**：企业销售驱动，大型企业为主；land-and-expand 从 ITSM 扩展到 HR/客服/安全/低代码。\n- **单位经济**：毛利率约 80%；订阅毛利率更高；销售与研发投入大。\n- **收入质量**：大客户合同期限长、续约率高；cRPO（当前剩余履约义务）是领先指标。\n- **定价趋势**：Now Assist/AI Agents 按消费/席位加购，从「按人」向「按工作流 + AI」迁移。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| ITSM | IT 服务管理、工单、变更 | 按席位 | 主力 |\n| ITOM | IT 运营管理、事件、CMDB | 按席位/用量 | 主力 |\n| HRSD | HR 服务交付 | 按席位 | 增长 |\n| CSM | 客户服务管理 | 按席位 | 增长 |\n| Security Operations | 安全事件与漏洞响应 | 按用量 | 增长 |\n| App Engine | 低代码应用平台 | 按用户/应用 | 增长 |\n| Now Assist | 生成式 AI 助手 | 按消费/席位 | 增长 |\n| AI Agents | 自主执行工作流的 agent | 按消费/agent | 试验/增长 |\n\n- 包装：Now Platform + 工作流模块 + AI 消费；企业版捆绑。\n- 路线图：AI Agents、Armis 安全整合、行业工作流、数据模型。\n\n## 技术栈与壁垒\n\n- **架构**：多租户云平台；统一数据模型（CMDB + 工作流）；低代码 App Engine。\n- **AI 路线**：Now Assist 把 LLM 接进工单、知识库与流程；AI Agents 执行跨系统任务；强调治理与审计。\n- **壁垒**：流程嵌入、CMDB 数据、企业客户关系、合作伙伴生态、迁移成本。\n- **依赖与债务**：AI 可能削弱按席位计价；与 Microsoft/Salesforce/Atlassian 的平台竞争；并购整合。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 大型企业（未具名） | ITSM/ITOM、HR、客服 | 未披露具体数字 | 官网客户故事 |\n| 金融/政府客户 | 安全运营、合规流程 | 未披露具体数字 | 官网 |\n| Now Assist 客户 | 生成式 AI 工单/知识 | ACV >$6 亿（2025） | 公司披露 |\n\n- 客户结构：大型企业、政府、金融、医疗、制造；全球 100+ 国家。\n- 集中度：未披露；大客户合同大、续约率高。\n- 续约/流失：续约率约 98%（◐ 历史口径）；cRPO 增长是关键指标。\n\n## 商业进展\n\n- 2026-01 发布 FY2025：营收 $132.78 亿（+20.9%）；Q4 订阅 $34.66 亿；追加 $50 亿回购。\n- Now Assist 2025 年 ACV 超 $6 亿，目标 2026 年超 $10 亿。\n- 2026 年推进 AI Agents 与 Armis 并购（约 $77.5 亿，◐ 待核）；安全暴露面管理补强。\n- 5 拆 1 拆股（2025 Q3）降低单股价格；股价 2026 年承压。\n- 竞争：Salesforce、Microsoft、Atlassian、BMC、Datadog、PagerDuty。\n\n## 经营业绩\n\n| 指标 | FY2023 | FY2024 | FY2025 | 最新季度 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | $89.71 亿 | $109.84 亿 | $132.78 亿 | Q4 $35.70 亿 | FY2025 +20.9% |\n| 增速 | +23.7% | +22.4% | +20.9% | +20.7% | 增速温和放缓 |\n| 毛利率 | 约 80% | 约 80% | 约 80% | 待核 | ◐ |\n| 营业利润 | 未披露 | 未披露 | 未披露 | 未披露 | — |\n| 净利润 | $17.31 亿 | $14.25 亿 | 约 $17 亿 | Q4 $4.01 亿 | ◐ 推算 |\n\n- 运营指标：Now Assist ACV >$6 亿（2025）；cRPO 增长待核；员工约 29,187。\n- 指引：FY2026 订阅收入目标 $157.35–157.75 亿（◐ 口径待核）。\n- 市场预期：AI 货币化与增长能否守住 20%。\n\n## 股权、融资与股票\n\n- 上市：NYSE NOW；2012-06 IPO。\n- 行情（2026-11-02）：股价约 $105–109；市值约 $1,091 亿；P/E 约 75.75；平均成交量约 1,430 万股。\n- 估值：PS 约 8.2x FY2025 营收；EV/收入待算。\n- 股东：机构为主；创始人 Fred Luddy 持股待核。\n- 资本动作：5 拆 1 拆股（2025 Q3）；追加 $50 亿回购（2026-01）。\n- 风险提示：市值从 2024 年 $2,189 亿回落至 2026 年约 $1,091 亿，估值收缩明显。\n\n## 团队与人员\n\n- 员工约 29,187 人（2025 年末，Macrotrends）；2026 年可能超 30,000（◐）。\n- 研发/销售/服务结构待补；全球办公室。\n- 招聘：2026 年 AI/Armis 整合岗位可能扩张；具体待采集。\n- 薪酬/股权激励：RSU 为主；CEO McDermott 2025 年薪酬包含 $4,348 万股票奖励（媒体口径）。\n- 组织：Bill McDermott（董事长/CEO）、Amit Zavery（总裁/CPO/COO）、Gina Mastantuono（CFO）。\n\n## 竞争格局\n\n- 直接竞品：Salesforce、Microsoft（Dynamics/Power Platform）、Atlassian（Jira Service Management）、BMC Helix、Freshworks。\n- 可观测/事件竞品：Datadog、PagerDuty、BigPanda。\n- 差异：统一数据模型 + 工作流 + 低代码 + AI Agents；弱点：价格高、实施重、AI 可能颠覆席位模式。\n- 竞争动态：Microsoft/Salesforce 把 AI agent 嵌入办公/CRM；Atlassian 以低价挤压 ITSM。\n- 份额：企业 ITSM/工作流市场领先（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：增长放缓、AI 货币化不及预期、大客户预算、并购整合（Armis）。\n- 技术：AI Agents 可靠性、数据安全、平台复杂度。\n- 法律/监管：数据隐私、政府合同、反垄断；待补诉讼。\n- 治理：CEO 继任、董事会独立性；高管薪酬争议。\n- 争议：市值两年跌约 50%，市场担忧 AI 颠覆按席位计价（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：AI Agents 收入、客户数、cRPO、Armis 整合均未入库。建议跟踪：① Now Assist/AI Agents 的 ACV；② cRPO 增速；③ Armis 整合；④ 与 Microsoft/Salesforce 的竞争；⑤ 股价与估值修复。\n\n## 信源与口径\n\n- FY2025 业绩：https://newsroom.servicenow.com/press-releases/details/2026/ServiceNow-Reports-Fourth-Quarter-and-Full-Year-2025-Financial-Results-Board-of-Directors-Authorizes-Additional-5B-for-Share-Repurchase-Program/default.aspx\n- SEC 8-K：https://www.sec.gov/Archives/edgar/data/1373715/000137371526000005/erq4fy25.htm\n- 2025 年报：https://s205.q4cdn.com/916135447/files/doc_downloads/annual-meeting-of-share-holders/2026/NOW-2025-Annual-Report-bookmarked.pdf\n- 员工：https://www.macrotrends.net/stocks/charts/NOW/servicenow/number-of-employees\n- 行情：https://finance.yahoo.com/quote/NOW/\n- 口径：净利润为推算；市值为 2026-11-02 第三方口径；◐ 表示待核。' },
      { id: 'paloaltonetworks', name: 'Palo Alto Networks', def: '安全的平台化整合：网络、云、终端与身份收进一个控制台，AI 既是产品也是攻击面。', body: '## 定位\n\nNikesh Arora 领导；Strata（网络）、Prisma（云）、Cortex（终端与安全运营）三线平台化，同时把 AI 做成产品（安全运营助手）与攻击面（模型与代理的运行时防护）。\n\n## 产品与模式\n\n- 订阅式平台授权；以并购补齐能力（2025 年宣布收购身份安全厂商 CyberArk）\n- 「平台化整合 vs 单点安全」是企业 AI 采购的真实争议\n\n## 本库追踪\n\n本库覆盖为零。\n\n采集缺口说明：AI 安全话题在本库仅覆盖前沿 lab 的安全声明与监管动作，缺安全厂商视角的信源面（产品发布、合同、并购）。' },
      { id: 'exiger', name: 'Exiger', def: '供应链情报的在位者：制裁、受益人与货物流向，AI 芯片管制的执行侧数据层。', body: '## 定位\n\nBrandon Daniels 领导；源自道琼斯风险与合规业务，提供制裁筛查、受益所有人识别与货物流向情报，客户为政府、金融与合规部门。\n\n## 产品与模式\n\n- 数据订阅 + 情报服务；在 AI 芯片出口管制链条上处于「执行侧」而非「政策侧」\n- 研究价值：管制执行强度可由其产品与政府合同节奏反推，比政策声明更早暴露实际松紧\n\n## 本库追踪\n\n本库覆盖为零。\n\n采集缺口说明：建议纳入推理与基础设施/AI芯片竞争线索的补充信源清单——目前该线索只记录禁令与产能，缺执行与规避层的可观测数据。' },
      { id: 'altimeter', name: 'Altimeter Capital', def: 'Gerstner 的 AI 重仓基金：大额领投与公开喊话并行，同时影响一级与二级叙事。', body: '## 定位\n\nBrad Gerstner 管理；以公开喊话与大额集中持仓著称，横跨一级融资与二级叙事，是 AI 资本定价的话语权参与者而非单纯出资方。\n\n## 产品与模式\n\n- 成长期集中投资 + 公开观点输出；同一标的在一级与二端的估值互相传导\n\n## 本库追踪\n\n覆盖薄弱：本库唯一命中为 2026 年 5 月 Anthropic 约 65 亿美元融资（估值约 965 亿美元）由 Altimeter 与 Dragoneer、Greenoaks、红杉领投。\n\n线索：商业与投融资/OpenAI融资与重组（领投署名内 1 次命中）。缺口：投资方的公开信与持仓变动未纳入采集面（Social Capital、Craft Ventures 同批处理）。' },
      { id: 'socialcapital', name: 'Social Capital', def: 'Palihapitiya 的投资公司：CREST 基金与 SPAC 结构，AI 二级市场叙事的供给方。', body: '## 定位\n\nChamath Palihapitiya 管理；以 SPAC sponsor 经济与 CREST 类结构著称，是把一级 AI 估值转译成公开市场叙事的供给方。\n\n## 产品与模式\n\n- 基金管理 + SPAC sponsor 费用结构\n- 研究价值：公开市场载体与个人言论如何放大一级估值，是资本叙事研究的标准样本\n\n## 本库追踪\n\n本库覆盖为零。\n\n采集缺口说明：本库投融资线索聚焦被投公司侧（估值、轮次、股东结构），投资方侧的基金结构与公开言论未成体系。' },
      { id: 'craft', name: 'Craft Ventures', def: 'Sacks 的方法论基金：创始人优先、效率至上，兼政府科技顾问的私人身份来源。', body: '## 定位\n\nDavid Sacks（Palantir 联创）与 Jeff Jordan 等创办；「创始人优先、运营效率至上」的方法论基金，投资组合集中在 AI 基础设施与应用层。\n\n## 产品与模式\n\n- 成长期投资 + 深度运营介入；Sacks 公开批评对冲式组合投资\n- 双重身份样本：Sacks 同时以美国总统科技顾问委员会共同主席身份参与 AI 政策讨论（来源为 2026-09-29 白宫座次表）\n\n## 本库追踪\n\n本库覆盖为零。\n\n缺口：「旋转门」（政策人物 × 资本方）在本库无登记面；此类身份重叠是判断政策走向的关键变量，建议作为独立维度补充。' },
      { id: 'datadog', name: 'Datadog', def: '云原生可观测龙头：遥测数据规模 + Bits AI，把 agent 嵌进监控主界面。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2010 / 纽约 | 官网；2010 年 YC 申请被拒 |\n| 上市地 / 代码 | NASDAQ: DDOG | 2019-09-19 IPO，发行价 $24 |\n| 最新财年营收 | FY2025 $34.27 亿（+28% YoY） | 2026-02-10 发布；FY2026 指引 $44.5–44.7 亿 |\n| 盈利 | FY2025 non-GAAP 营业利润率约 23–24%；Q4 GAAP 营业利润 $900 万（利润率 1%） | ◐ 待 10-K 复核 |\n| 现金流 | FY2025 经营现金流 $10.50 亿；FCF 待核 | ◐ |\n| 客户 | ARR >$100k 客户 4,720 家（2026 Q2）；ARR >$1M 客户 603 家（FY2025） | 公司披露 |\n| 员工 | 约 8,100 人（按人均营收 $42.3 万推算） | ◐ 待 10-K 核实 |\n| 市值 / 估值 | 约 $845 亿；股价约 $242（2026-11-02） | Yahoo/MarketWatch；TTM P/E 约 480 |\n| 主要股东 | 机构为主（Vanguard、BlackRock 等）；创始人持股待核 | ◐ |\n| 数据截至 | 财务 FY2025；行情 2026-11-02 | — |\n\n## 定位与沿革\n\n云原生可观测平台第一梯队：把基础设施监控、APM、日志、RUM、CI Visibility、云安全与事件响应收进一个数据面，再用 Bits AI 把告警调查、根因建议与 SRE 助手嵌进工作流。\n\n- 2010 年由 Olivier Pomel 与 Alexis Lê-Quôc 在纽约创立；同年申请 Y Combinator 被拒，理由是「平台价值取决于生态」。\n- 2019-09-19 在纳斯达克上市，发行价 $24；此后从单点监控扩展到多产品平台。\n- 2024–2026 年推出 Bits AI 系列，把 LLM/agent 接进遥测关联、告警分诊与 SRE 工作流；2026 年主推 Agent Observability。\n- 2025-05 收购 Eppo（feature flag/实验平台），把发布控制与实验能力接入可观测闭环；官方宣布，交易金额约 $2.2 亿（◐ 第三方口径）。\n- FY2026 指引 $44.5–44.7 亿；2026 Q1/Q2 增速回升到 32%/36%，是「可观测平台 agent 化」的头部样本。\n\n## 创始人与管理层\n\n- **Olivier Pomel（CEO，联合创始人）**：法国人，École Centrale Paris 计算机背景；2010 年前的具体雇主待补（◐）。\n- **Alexis Lê-Quôc（CTO，联合创始人）**：同校背景；曾任 Wireless Generation 运营总监，负责运维团队。\n- 两人是长期朋友与同事；公司采用双重股权结构，创始人持有超级投票权（◐ 比例待核）。\n- **David Obstler（CFO）**：2019 年加入，此前任高盛科技部门 CFO；外部兼任 Miro、Rokt 董事（Rokt 审计委员会主席）。\n- 董事会含 Dev Ittycheria 等独立董事（◐ 待核完整名单）；近 24 个月关键人事变动待采集。\n\n## 商业模式\n\n- **收入结构**：订阅 + 用量计费；按主机、数据量、span、席位与模块计价，专业服务收入占比低。\n- **销售动作**：PLG 获客（免费层/试用）+ 企业销售扩张；land-and-expand 路径为监控 → APM → 日志 → 安全 → AI agent。\n- **单位经济**：毛利率约 80%；FY2025 non-GAAP 营业利润率约 23–24%；CAC/LTV 与 NRR 未单独披露（◐）。\n- **收入质量**：经常性收入为主；大客户数持续上升（>$100k ARR 4,720 家，>$1M ARR 603 家）；单一客户占比未披露。\n- **定价趋势**：从「按主机」向「按数据量/用量 + AI agent 交互」迁移，Bits AI 可能带来新的计价单位与毛利结构。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| Infrastructure Monitoring | 主机、容器、云资源监控 | 按主机 | 主力 |\n| APM | 分布式追踪、服务性能 | 按主机/span | 主力 |\n| Log Management | 日志采集、索引、查询 | 按数据量 | 主力 |\n| RUM / Synthetics | 浏览器/移动体验、合成拨测 | 按会话/测试 | 增长 |\n| CI Visibility | CI/CD 与测试可观测 | 按用量 | 增长 |\n| Cloud Security | 云安全态势、威胁检测 | 按主机/用量 | 增长 |\n| Incident Management | 事件响应与值班 | 按席位 | 增长 |\n| Bits AI SRE | 告警调查、根因建议、SRE 助手 | 按 agent 交互 | 试验/增长 |\n| Agent Observability | LLM/agent 调用链、质量与成本 | 按用量 | 试验 |\n\n- 包装：模块可单买，平台捆绑折扣；Bits AI 与核心遥测强绑定。\n- 路线图：agent 可观测、AI SRE 自动处置、安全与可观测融合；Eppo 并入 Experiments/Feature Flags。\n\n## 技术栈与壁垒\n\n- 多租户 SaaS，主要运行在公有云；自研时序/日志存储与查询引擎，标签体系（tagging）是可观测数据关联的核心。\n- AI 路线：Bits AI 把 LLM 接进遥测关联、告警分诊与 SRE 助手；Agent Observability 观测第三方 agent（如 Amazon Bedrock AgentCore）的调用质量与成本。\n- 壁垒：遥测接入广度、模块交叉销售、仪表盘/告警/runbook 的迁移成本、开发者体验。\n- 依赖与风险：公有云基础设施依赖、推理成本、数据驻留与合规；技术债待评估。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| LSEG（伦敦证券交易所集团） | 主动发现问题、避免宕机 | 未披露具体数字 | 官网客户故事 |\n| Forbes | 数字体验监控 | 成本降 2–3%、可用性 >99.5%、RCA 时间改善 10% | 官网案例 |\n| NTT DATA | 验证 Bedrock AgentCore 上的 AI agent 质量 | 成本降低 50% | 官网案例 |\n| PayPal / Itaú Unibanco | 支付/金融场景可观测 | 未披露 | 客户列表 |\n\n- 客户结构：云原生企业、金融、零售、SaaS；北美为主，欧洲/亚太扩张。\n- 集中度：单一客户占比未披露；大客户 ARR 占比待补。\n- 续约/流失：NRR 未单独披露；需从剩余履约义务与客户数变化推断。\n\n## 商业进展\n\n- 2026-02 发布 FY2025，FY2026 指引 $44.5–44.7 亿；Q1/Q2 2026 增速 32%/36%，增长重新加速。\n- 2025-05 收购 Eppo，把 feature flag、实验与产品分析接入可观测闭环；金额约 $2.2 亿（◐ 第三方）。\n- 2026 年 Summit 主推 AI agent 可观测与 Bits AI SRE；云市场（AWS/Azure/GCP）与 MSP 渠道持续扩张。\n- 定价：Bits AI 采用 agent 交互计价，具体打包与折扣待采集。\n- 地域：北美基本盘，欧洲与亚太为增量；组织与销售团队扩张待补。\n\n## 经营业绩\n\n| 指标 | FY2023 | FY2024 | FY2025 | 最新季度 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | $21.28 亿 | $26.84 亿 | $34.27 亿 | 2026 Q2 $11.20 亿 | FY2025 +28%；Q2 2026 +36% |\n| 增速 | +27% | +26% | +28% | +36% | 增长重新加速 |\n| 毛利率 | 约 80% | 约 80% | 约 80% | 待核 | ◐ |\n| 营业利润 | 待核 | 待核 | non-GAAP 利润率 23–24%；Q4 GAAP $900 万 | Q1 2026 GAAP $700 万 | ◐ |\n| FCF | 待核 | 待核 | 经营现金流 $10.50 亿；FCF 待核 | 待核 | ◐ |\n\n- 运营指标：>$100k ARR 客户 4,550（Q1 2026）→ 4,720（Q2 2026）；>$1M ARR 客户 603（FY2025）。\n- 指引：FY2026 营收 $44.5–44.7 亿；non-GAAP 营业利润 $10.1–10.3 亿。\n- 市场预期：Q3 2026 财报定于 2026-11-04；Bernstein 上调至 Outperform，目标价 $350（◐）。\n\n## 股权、融资与股票\n\n- 上市：NASDAQ DDOG；2019-09-19 IPO，发行价 $24；双重股权结构。\n- 行情（2026-11-02）：股价约 $242.46；市值约 $845 亿；52 周区间 $98.01–$300.68；流通股约 3.59 亿。\n- 估值：TTM P/E 约 480；EV 约 $808 亿；PS 待按 TTM 营收计算（◐）。\n- 股东：机构为主（Vanguard、BlackRock 等）；创始人持股与投票权比例待核。\n- 资本动作：回购/分红待查最新 10-Q/10-K；IPO 锁定期已过。\n- 风险提示：高估值对增长与利润率敏感；2026-11-04 财报是短期催化/风险点。\n\n## 团队与人员\n\n- 员工约 8,100 人（按 FY2025 人均营收 $42.3 万推算；◐ 待 10-K）。\n- 研发占比、职能/地域分布待补；销售与市场投入是费用大头。\n- 招聘：2026 年随 AI 与 agent 可观测扩张；具体岗位待采集。\n- 薪酬/股权激励：以 RSU 为主；流失率未披露。\n- 组织：创始人仍任 CEO/CTO；关键高管空缺与变动待补。\n\n## 竞争格局\n\n- 直接竞品：Dynatrace、New Relic、Splunk（思科）、Elastic、Grafana 生态、Sumo Logic。\n- 替代方案：云厂商原生监控（CloudWatch、Azure Monitor、Google Cloud Ops）、开源 Prometheus/Grafana/Loki。\n- 差异：数据面广度、模块交叉销售、开发者体验；弱点：成本可见性、复杂度、大客户议价。\n- 竞争动态：平台厂商把 agent 内置（Bits AI）会挤压单点 AIOps/告警厂商；AI SRE 新锐从告警入口切入。\n- 份额：可观测市场分散，Datadog 约 15%（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：IT 预算收缩、客户优化用量、增长放缓；高估值对指引敏感。\n- 技术：大规模遥测故障、数据泄露、agent 误判导致误操作；推理成本侵蚀毛利。\n- 法律/监管：数据跨境与隐私合规、反垄断；待补诉讼与监管事项。\n- 治理：双重股权结构削弱中小股东影响力；创始人持股比例待核。\n- 争议：2026 年股价从 $300 高点回撤，市场对高 P/E 的容忍度下降（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：财报、产品发布、客户合同、股价与股东结构均未入库。建议跟踪：① >$100k ARR 客户增速；② Bits AI 计价与渗透；③ FY2026 指引达成率；④ AI agent 可观测的竞争格局；⑤ 2026-11-04 财报。\n\n## 信源与口径\n\n- Datadog FY2025 业绩发布（2026-02-10）：https://investors.datadoghq.com/news-releases/news-release-details/datadog-announces-fourth-quarter-and-fiscal-year-2025-financial/\n- Datadog 2026 Q1/Q2 业绩发布：https://investors.datadoghq.com/news-releases/\n- Datadog FY2025 10-K：https://www.sec.gov/Archives/edgar/data/1561550/000162828026028194/dd_annualxreportx2025.pdf\n- 客户案例：https://www.datadoghq.com/customers/ ；https://www.datadoghq.com/case-studies/ntt-data/\n- 行情：https://finance.yahoo.com/quote/DDOG/ ；https://www.marketwatch.com/investing/stock/ddog\n- 创始人与公司史：https://en.wikipedia.org/wiki/Datadog ；https://www.datadoghq.com/about/leadership/\n- 口径：财务数字来自公司披露；员工数为推算；市值/股价为 2026-11-02 收盘；◐ 表示待交叉验证。' },
      { id: 'dynatrace', name: 'Dynatrace', def: '因果 AI 先行者：Davis + Grail，把自动拓扑与根因定位做成平台底座。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2005 / 奥地利林茨创立，总部波士顿 | 官网/Wikipedia |\n| 上市地 / 代码 | NYSE: DT | 2019-08 IPO |\n| 最新财年营收 | FY2026 $20.18 亿（+18.8%）；ARR $20.5 亿 | 2026-05-13 发布 |\n| 盈利 | FY2026 non-GAAP 营业利润率待核；Q1 FY2027 EPS $0.48 | ◐ 待 10-K 复核 |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露总数；大型企业为主 | 官网客户故事 |\n| 员工 | 约 4,200 人（2023 口径；2026 待核） | ◐ |\n| 市值 / 估值 | 约 $168.6 亿（2026-10-30） | Bullfincher；PS 约 8.4x FY2026 |\n| 主要股东 | 机构为主；Thoma Bravo 历史持股已减持 | ◐ 待核 |\n| 数据截至 | 财务 FY2026；行情 2026-10-30 | — |\n\n## 定位与沿革\n\n以「自动拓扑 + 因果 AI」差异化的企业级可观测平台：OneAgent 自动发现组件与依赖，Smartscape 维护实时拓扑，Davis AI 做因果推断与根因定位，Grail 数据湖统一指标、日志与追踪。\n\n- 2005 年由 Bernd Greifeneder、Sok-Kheng Taing、Hubert Gerstmayr 在奥地利林茨创立；2014 年被 Compuware/Thoma Bravo 收购，2019-08 在纽交所上市。\n- 2020 年代把 Davis 从「异常检测」推进到「因果根因 + 自动修复建议」；Grail 把数据孤岛收进统一湖仓。\n- 2026 年 Perform 大会提出「Dynatrace Intelligence」与「受监督的自治运维（supervised autonomous operations）」，把 agent 放进生产控制面。\n- FY2026 营收 $20.18 亿（+18.8%），ARR 首次超过 $20 亿；Q1 FY2027 ARR $21.36 亿（+17%），营收 $5.55 亿（+16%），连续四个季度 16% 固定汇率增长。\n\n## 创始人与管理层\n\n- **Bernd Greifeneder（联合创始人 & CTO）**：林茨约翰内斯·开普勒大学（JKU）背景，仍负责技术路线与林茨工程团队，被称为「首席创新者」。\n- **Sok-Kheng Taing（联合创始人）**：与 Greifeneder 共同创办；具体当前角色待核。\n- **Hubert Gerstmayr（联合创始人）**：部分资料列为第三位联合创始人；当前角色待核。\n- **Rick McConnell（CEO）**：2021-12 上任，此前任 Akamai 产品与研发总裁，并负责过 Akamai 安全技术集团与 Web 部门。\n- **Jim Benson（CFO）**：财报与投资者关系的主要对外面孔；任期与背景待补。\n- 董事会与投票权结构待补；近 24 个月关键人事变动待采集。\n\n## 商业模式\n\n- **收入结构**：订阅为主，采用 Dynatrace Platform Subscription（DPS）年度承诺 +  consumption 计价；按 host unit、DEM unit、Davis data unit 等度量。\n- **销售动作**：企业销售驱动，面向大型企业的 CIO/运维/平台团队；land-and-expand 从 APM 扩展到基础设施、日志、安全与自动化。\n- **单位经济**：毛利率约 80%+；non-GAAP 营业利润率约 25–28%（◐ 待核）；NRR/NDR 未在公开摘要中披露。\n- **收入质量**：ARR 占比高、合同期限多为 1–3 年；大型企业续约稳定，但新单增长对 IT 预算敏感。\n- **定价趋势**：DPS 把「按主机」转为「按消费承诺」，降低采购摩擦，也让收入更依赖客户的实际用量扩张。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| OneAgent | 自动埋点、主机/进程/容器发现 | 按 host unit | 主力 |\n| Smartscape | 实时拓扑与依赖关系 | 随平台 | 主力 |\n| Davis AI | 异常检测、因果根因、事件关联 | 按 Davis data unit | 主力 |\n| Grail | 日志/指标/追踪统一湖仓与 DQL 查询 | 按数据量 | 主力 |\n| Applications & Microservices | APM、分布式追踪、服务性能 | 按 host/DEM | 主力 |\n| Infrastructure Monitoring | 云资源、Kubernetes、网络 | 按 host | 增长 |\n| Log Management | 日志采集、索引、分析 | 按数据量 | 增长 |\n| Digital Experience | RUM、合成监控、Session Replay | 按 DEM unit | 增长 |\n| Application Security | 运行时漏洞与攻击检测 | 按 host | 增长 |\n| Dynatrace Intelligence | agentic 调查、自动化与受控执行 | 按 agent/消费 | 试验/增长 |\n\n- 包装：DPS 统一承诺，模块按消费扣减；大型客户常以平台捆绑替代多点工具。\n- 路线图：受监督自治运维、AI 控制面、安全与可观测融合。\n\n## 技术栈与壁垒\n\n- **架构**：SaaS + 私有化/混合部署；OneAgent 自动注入，Smartscape 维护拓扑，Grail 统一存储，Davis 在拓扑上做因果推断。\n- **AI 路线**：Davis 的因果 AI 是传统优势；2026 年把 LLM/agent 接到「调查 → 建议 → 受控执行」，强调人在回路与审计。\n- **壁垒**：自动拓扑与因果定位的误报率、企业级规模验证、混合云支持、模块交叉销售。\n- **依赖与债务**：私有化/混合部署的运维复杂度；与云厂商原生监控的竞争；agent 执行的信任与责任边界。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| Forrester TEI 复合组织 | 统一可观测、替代多点工具 | 3 年 ROI 466%、回收期 <6 个月、MTTR 最多改善 70%、NPV 约 $2,030 万 | Forrester TEI（厂商委托） |\n| 大型金融/政府客户 | 混合云根因定位、合规审计 | 未披露具体数字 | 官网客户故事 |\n| 大型制造/零售客户 | Kubernetes 与边缘运维 | 未披露具体数字 | 官网客户故事 |\n\n- 客户结构：大型企业、金融、政府、制造、零售；北美与欧洲为主。\n- 集中度：单一客户占比未披露；大型企业合同周期长。\n- 续约/流失：NRR 未公开；需从 ARR 与客户数变化推断。\n\n## 商业进展\n\n- 2026-05 发布 FY2026：营收 $20.18 亿、ARR $20.5 亿；Q1 FY2027 ARR $21.36 亿、营收 $5.55 亿，EPS $0.48 超预期。\n- 2026 Perform 大会发布 Dynatrace Intelligence，把「可观测」升级为「AI 生产控制面」；IDC 将其描述为「受监督自治运维」样本。\n- 与 NVIDIA 等 AI 基础设施厂商的合作待采集；私有化/混合部署是政企与金融的差异化卖点。\n- 定价：DPS 消费承诺继续替代按主机计价；具体折扣与打包待采集。\n- 并购：2023 年收购 Rookout、2024 年收购 Runecast；2025–2026 是否有新并购待核。\n\n## 经营业绩\n\n| 指标 | FY2024 | FY2025 | FY2026 | 最新季度 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | $14.30 亿 | $16.99 亿 | $20.18 亿 | Q1 FY2027 $5.55 亿 | FY2026 +18.8%；Q1 FY2027 +16% |\n| 增速 | +21% | +19% | +18.8% | +16% | 增速温和放缓 |\n| 毛利率 | 约 80% | 约 80% | 约 80% | 待核 | ◐ |\n| 营业利润 | 待核 | 待核 | non-GAAP 利润率约 25–28% | EPS $0.48 | ◐ |\n| FCF | 待核 | 待核 | 待核 | 待核 | ◐ |\n\n- 运营指标：ARR $20.5 亿（FY2026）→ $21.36 亿（Q1 FY2027）；连续四个季度 16% 固定汇率增长。\n- 指引：FY2027 指引待核；市场关注 ARR 增速能否守住 16%。\n- 市场预期：Q1 FY2027 超预期，但增长中枢低于 Datadog；估值 PS 约 8.4x。\n\n## 股权、融资与股票\n\n- 上市：NYSE DT；2019-08 IPO；历史股东包括 Thoma Bravo/Compuware。\n- 行情（2026-10-30）：市值约 $168.6 亿；股价与 52 周区间待补（◐）。\n- 估值：PS 约 8.4x FY2026 营收；EV/ARR 待算；P/E 待按 non-GAAP EPS 计算。\n- 股东：机构为主；Thoma Bravo 减持节奏待核；创始人持股比例待核。\n- 资本动作：回购/分红待查最新 10-K；股权激励以 RSU 为主。\n- 风险提示：增长放缓与估值收缩；AI agent 叙事能否转化为 ARR 增量。\n\n## 团队与人员\n\n- 员工约 4,200 人（2023 口径；2026 待核）；林茨、维也纳、波士顿为主要研发/工程站点。\n- 研发占比与地域分布待补；销售与市场投入随企业扩张上升。\n- 招聘/裁员：2025–2026 动态待采集；AI 与 agent 相关岗位可能扩张。\n- 薪酬/股权激励：RSU 为主；流失率未披露。\n- 组织：创始人 Greifeneder 仍任 CTO；CEO McConnell 来自 Akamai，销售与产品背景。\n\n## 竞争格局\n\n- 直接竞品：Datadog、New Relic、Splunk（思科）、Elastic、Grafana 生态、IBM Instana。\n- 替代方案：云厂商原生监控、开源 Prometheus/Grafana/Loki、AIOps 专业厂商。\n- 差异：自动拓扑 + 因果 AI 的根因准确率、混合云/私有化支持；弱点：价格、开发者体验、云原生灵活度不如 Datadog。\n- 竞争动态：Datadog 用广度与 PLG 挤压；AI SRE 新锐从告警入口切入；云厂商把可观测免费化。\n- 份额：企业可观测市场份额约 8–10%（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：ARR 增速放缓、客户消费优化、IT 预算收紧；大客户合同周期长导致短期波动。\n- 技术：因果 AI 误判、agent 自动执行的生产事故、混合部署的运维复杂度。\n- 法律/监管：数据跨境、隐私合规、政府客户的安全审查；待补诉讼。\n- 治理：Thoma Bravo 历史控制权与减持；董事会结构待核。\n- 争议：高价与「按消费承诺」的透明度常被客户质疑（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：财报、客户案例、ARR 结构、股价与股东均未入库。建议跟踪：① ARR 增速能否守住 16%；② Dynatrace Intelligence 的付费渗透；③ DPS 消费承诺的净扩张；④ 与 Datadog 的份额变化；⑤ 混合部署在政企的订单。\n\n## 信源与口径\n\n- Dynatrace FY2026 业绩发布（2026-05-13）：https://ir.dynatrace.com/news-events/press-releases/detail/425/dynatrace-reports-fourth-quarter-and-full-year-fiscal-2026-financial-results\n- Dynatrace Q1 FY2027 业绩：https://finance.yahoo.com/markets/stocks/articles/dynatrace-reports-first-quarter-financial-103000016.html\n- Forrester TEI：https://tei.forrester.com/go/dynatrace/ObservabilityPlatform/?lang=en-us\n- 客户故事：https://www.dynatrace.com/customers/\n- 公司与创始人：https://en.wikipedia.org/wiki/Dynatrace ；https://www.dynatrace.com/company/leadership/\n- 行情：https://bullfincher.io/companies/dynatrace/overview\n- 口径：FY2026 截至 2026-03-31；市值 2026-10-30；◐ 表示待交叉验证。' },
      { id: 'newrelic', name: 'New Relic', def: '全栈可观测老牌平台：从 APM 起家，转向用量计费与 Agentic AIOps。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2008 / 旧金山 | 官网/Wikipedia |\n| 上市地 / 代码 | 已私有化（2023-11） | Francisco Partners + TPG，$87/股 |\n| 最新财年营收 | 私有化前 FY2023 约 $9.25 亿；2026 未披露 | ◐ 私有公司不披露 |\n| 盈利 | 未披露 | — |\n| 现金流 | 未披露 | — |\n| 客户 | 公司称 >85,000 家；第三方统计口径不一 | ◐ |\n| 员工 | 约 3,000 人（Revelio 2026 估算） | ◐ |\n| 市值 / 估值 | 私有化交易约 $65 亿（2023） | 不适用二级市场 |\n| 主要股东 | Francisco Partners、TPG | 私有化后 |\n| 数据截至 | 2023-11 私有化；2026 公开数据有限 | — |\n\n## 定位与沿革\n\n全栈可观测平台：APM、基础设施、日志、浏览器、合成监控与 AI 监控收在一个平台，以 NRQL 查询与用量计费为核心；2023 年私有化后加速向「AI 驱动的可观测 + Agentic AIOps」转型。\n\n- 2008 年由 Lew Cirne 在旧金山创立（New Relic 是 Lew Cirne 的字母重组）；2014 年 IPO。\n- 2023-07 宣布由 Francisco Partners 与 TPG 以 $87/股、约 $65 亿全现金收购，2023-11 完成私有化，结束九年上市历史。\n- 2026-02 举办 Advance 2026，主题「Operating Beyond Human Scale」，强调可观测要从事后查看走向自动修复。\n- 2026-10-01 任命 Nandini Ramani 为 CEO，接替 Ashan Willy；后者在 2026 年主导了 AI 可观测叙事。\n- 2026 年被 IDC MarketScape 评为全球 AIOps 领导者（公司口径，◐）。\n\n## 创始人与管理层\n\n- **Lew Cirne（创始人）**：连续创业者，首家公司以约 $3.75 亿出售；2008 年创立 New Relic，曾任 CEO，2022 年转任执行董事长。\n- **Nandini Ramani（CEO，2026-10 起）**：接替 Ashan Willy；此前经历与专长待补（◐）。\n- **Ashan Willy（前 CEO）**：2026 年大部分时间任 CEO，主导 Agentic AIOps 与「agent debt」叙事；离任后加入 Sabre 董事会。\n- **Bill Staples（前 CEO，2022–2025）**：推动用量计费与平台整合；任期细节待核。\n- 董事会与私有化后的治理结构待补；Francisco Partners/TPG 的控制安排待核。\n\n## 商业模式\n\n- **收入结构**：订阅 + 用量计费；按用户、主机、数据量、事件量计价，私有化后财务不公开。\n- **销售动作**：企业销售 + 自助试用；land-and-expand 从 APM 扩展到基础设施、日志、AI 监控。\n- **单位经济**：私有化前毛利率约 70–75%（◐）；PE 控股后可能压缩费用、提高现金流。\n- **收入质量**：大客户与中期合同为主；私有化后更关注现金流与利润率，而非公开增速。\n- **定价趋势**：用量计费降低采用门槛，但收入随客户用量波动；AI 功能可能按 agent/事件计价。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| APM | 应用性能、分布式追踪 | 按用户/数据量 | 主力 |\n| Infrastructure | 主机、容器、云资源 | 按主机 | 主力 |\n| Log Management | 日志采集、NRQL 查询 | 按数据量 | 主力 |\n| Browser / Mobile | RUM、真实用户体验 | 按会话 | 增长 |\n| Synthetics | 合成监控与拨测 | 按测试 | 增长 |\n| AI Monitoring | LLM/agent 调用链与质量 | 按用量 | 增长 |\n| Agentic AIOps | 告警关联、根因建议、自动修复 | 按 agent/事件 | 试验/增长 |\n| New Relic AI | 自然语言查询与助手 | 按席位/用量 | 增长 |\n\n- 包装：全栈平台 + 用量计费；私有化后可能推出更多捆绑套餐。\n- 路线图：AI agent 可观测、自动修复、与云厂商/开源生态集成。\n\n## 技术栈与壁垒\n\n- **架构**：多租户 SaaS；NRQL 查询语言、Telemetry Data Platform、OpenTelemetry 兼容。\n- **AI 路线**：AI Monitoring 观测 LLM/agent；Agentic AIOps 把告警关联、根因与修复建议自动化；强调「agent debt」治理。\n- **壁垒**：全栈数据模型、NRQL 生态、开发者社区、企业客户基础。\n- **依赖与债务**：私有化后的研发投入可持续性；与 Datadog/Dynatrace 的功能差距；云厂商原生监控竞争。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 大型金融客户 | 全栈可观测、 outage 成本治理 | 未披露具体数字 | 官网客户故事 |\n| 大型零售/媒体客户 | 数字体验与 APM | 未披露具体数字 | 官网客户故事 |\n| 中小型 SaaS 团队 | APM + 日志 + AI 监控 | 未披露具体数字 | 自助客户 |\n\n- 客户结构：公司称 >85,000 家；第三方统计约 1.8 万家（TheirStack）到 7.5 万家（TechnologyChecker），口径差异大（◐）。\n- 集中度：单一客户占比未披露；大客户以金融、零售、媒体为主。\n- 续约/流失：私有化后不披露 NRR；需从客户数与产品发布推断。\n\n## 商业进展\n\n- 2026-02 Advance 2026：发布 AI 可观测与 Agentic AIOps 路线，主题「超越人类规模运营」。\n- 2026-10-01 换帅：Nandini Ramani 任 CEO，Ashan Willy 离任；战略连续性待观察。\n- 2026 年被 IDC MarketScape 评为全球 AIOps 领导者（公司口径，◐）。\n- 2026-09 报告：高影响 IT 中断每年给企业造成约 $7,400 万损失（New Relic 委托研究，◐）。\n- 私有化后并购/整合：待采集；PE 股东可能推动业务拆分或补强。\n\n## 经营业绩\n\n| 指标 | FY2022 | FY2023 | 私有化后 | 说明 |\n|---|---|---|---|---|\n| 营收 | 约 $7.88 亿 | 约 $9.25 亿 | 未披露 | 私有化前 +17% 左右 |\n| 增速 | +20% | +17% | 未披露 | ◐ |\n| 毛利率 | 约 70–75% | 约 70–75% | 未披露 | ◐ |\n| 营业利润 | 亏损 | 亏损收窄 | 未披露 | ◐ |\n| FCF | 待核 | 待核 | 未披露 | ◐ |\n\n- 私有化交易：$87/股、约 $65 亿，对应 FY2023 营收约 7x PS。\n- 运营指标：客户数、NRR、ARR 均未公开；只能从第三方估算与产品发布推断。\n- 指引：不适用（私有公司）。\n\n## 股权、融资与股票\n\n- **不适用（未上市）**：2023-11 完成私有化，股票不再交易。\n- 私有化对价：$87/股现金，约 $65 亿；买方为 Francisco Partners 与 TPG。\n- 估值：交易对应 FY2023 营收约 7x PS；当前一级/二级估值未披露。\n- 股东：Francisco Partners、TPG 为主要股东；管理层持股与激励待核。\n- 流动性：无公开市场；未来可能 IPO、并购或二级份额交易。\n- 资本动作：PE 控股后的债务结构、分红/再融资待采集。\n\n## 团队与人员\n\n- 员工约 3,000 人（Revelio 2026 估算；◐）；私有化前约 3,000 人。\n- 研发占比、地域分布待补；私有化后可能优化费用结构。\n- 招聘/裁员：2023 私有化后是否有裁员待采集；2026 年 AI 岗位可能扩张。\n- 薪酬/股权激励：私有化后以现金/新激励计划为主；流失率未披露。\n- 组织：CEO Nandini Ramani（2026-10 起）；创始人 Lew Cirne 是否仍任董事长待核。\n\n## 竞争格局\n\n- 直接竞品：Datadog、Dynatrace、Splunk（思科）、Elastic、Grafana 生态、IBM Instana。\n- 替代方案：云厂商原生监控、开源 Prometheus/Grafana/Loki、AIOps 专业厂商。\n- 差异：全栈数据模型 + NRQL + 用量计费；弱点：规模与研发投入不及 Datadog，品牌心智弱于 Dynatrace。\n- 竞争动态：私有化后需在 AI 可观测与价格之间找平衡；AI SRE 新锐从告警入口切入。\n- 份额：企业可观测市场约 5–7%（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：私有化后财务不透明、增长与利润率压力、客户流失；PE 杠杆可能限制研发投入。\n- 技术：AI 功能落地不及预期、平台事故、数据安全；与云厂商原生监控同质化。\n- 法律/监管：数据跨境与隐私合规；私有化交易的债务与治理事项待查。\n- 治理：PE 控股下的董事会与管理层变动；CEO 2026 年更换增加战略不确定性。\n- 争议：2026 年 CEO 更替与「AI 可观测」叙事能否兑现，是市场主要疑问（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：私有化后财务、客户数、产品渗透均无公开数据。建议跟踪：① Nandini Ramani 上任后的战略调整；② AI Monitoring/Agentic AIOps 的付费客户；③ 与 Datadog 的价格战；④ PE 股东的退出路径；⑤ 客户流失与 NRR 的第三方信号。\n\n## 信源与口径\n\n- 私有化公告（2023-07-31）：https://newrelic.com/press-release/20230731\n- CEO 任命（2026-10-01）：https://newrelic.com/press-release/20261001\n- Advance 2026：https://newrelic.com/blog/news/new-relic-advance-2026\n- 客户页：https://newrelic.com/customers\n- 公司与创始人：https://en.wikipedia.org/wiki/New_Relic\n- 员工估算：https://www.reveliolabs.com/companies/new-relic/employees\n- 口径：私有公司不披露财务；2023 年数据为私有化前最后公开口径；◐ 表示估算或待核。' },
      { id: 'splunk', name: 'Splunk（思科）', def: '机器数据平台：日志与安全分析的老牌入口，被思科收编后押注 Agentic AI。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2003 / 圣何塞（旧金山创立） | 官网/Wikipedia |\n| 上市地 / 代码 | 已退市；母公司 Cisco（NASDAQ: CSCO） | 2024-03-18 完成收购 |\n| 最新财年营收 | 被收购前 FY2024 $42 亿；并入思科首个完整财年贡献约 $39 亿 | Cisco/媒体口径 |\n| 盈利 | 并表，未单独披露 | — |\n| 现金流 | 并表，未单独披露 | — |\n| 客户 | 未披露总数；大型企业与政府为主 | ◐ |\n| 员工 | 收购前约 7,000–8,000 人 | ◐ |\n| 市值 / 估值 | 不适用（已退市）；交易对价约 $280 亿 | $157/股 |\n| 主要股东 | Cisco 100% | 2024-03 起 |\n| 数据截至 | 收购 2024-03；并表数据 2026 | — |\n\n## 定位与沿革\n\n机器数据平台：以索引型日志分析（SPL）起家，ITSI 面向 IT 运维、Enterprise Security 面向安全运营；2024 年被思科收购后，成为思科「安全 + 可观测 + AI 数据底座」的核心资产。\n\n- 2003 年由 Michael Baum、Rob Das、Erik Swan 在旧金山创立；最初想解决基因组数据问题，后转向机器日志搜索。\n- 2012 年 IPO；2023-09 思科宣布以约 $280 亿（$157/股）收购，2024-03-18 完成，Splunk 退市。\n- 并入思科后首个完整财年贡献约 $39 亿收入，超过整合目标；思科把 Splunk 与安全、网络、AI 基础设施交叉销售。\n- 2026 年 .conf26 / Cisco Live 主推「Agentic Enterprise」：Agent Observability、Node Tokenomics（追踪 AI 与 coding agent 的 token 成本）、Agentic SOC。\n- 2026-09 宣布与 NVIDIA 合作，把自管理 AI 带到 Splunk Enterprise 本地部署客户。\n\n## 创始人与管理层\n\n- **Michael Baum（联合创始人）**：连续创业者，Splunk 首任 CEO；后创办 Founder.org。\n- **Rob Das（联合创始人）**：技术背景，参与早期架构；后续经历待补。\n- **Erik Swan（联合创始人）**：技术背景；后续经历待补。\n- **Kamal Hathi（SVP & GM, Splunk at Cisco）**：2026 年 Splunk 业务的主要对外负责人，Cisco Live 2026 主讲 Agentic Enterprise。\n- **Gary Steele（前 CEO）**：2022-04 至 2024-03 任 CEO，收购后任思科安全与协作业务总裁；2026 年已离任，现任 Shield AI CEO。\n- 思科层面：CEO Chuck Robbins、安全与协作负责人 Jeetu Patel 对 Splunk 有战略管辖；具体汇报线待核。\n\n## 商业模式\n\n- **收入结构**：软件订阅 + 云服务；按数据摄入量（GB/day）计价，ITSI/ES 按工作负载或节点加价。\n- **销售动作**：企业销售 + 渠道/合作伙伴；大量政府、金融、电信客户；思科交叉销售网络与安全产品。\n- **单位经济**：软件毛利率高（约 80%）；云迁移与本地部署并存；并表后不单独披露。\n- **收入质量**：大客户合同期限长、迁移成本高；数据摄入量是收入与客户成本的共同驱动。\n- **定价趋势**：从「按摄入量」向「工作负载/用例」包装；Agent Observability 可能按 agent/token 计价。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| Splunk Platform | 日志索引、SPL 查询、告警 | 按数据摄入量 | 主力 |\n| Splunk ITSI | IT 服务智能、事件关联、服务健康 | 按工作负载 | 主力 |\n| Splunk Enterprise Security | SIEM、威胁检测、SOC | 按数据量/用户 | 主力 |\n| Splunk Observability Cloud | APM、基础设施、RUM、合成监控 | 按主机/数据量 | 增长 |\n| Agent Observability | AI/agent 调用链、token 成本 | 按用量 | 试验/增长 |\n| Agentic SOC | 身份、凭证、会话、爆炸半径分析 | 按工作负载 | 试验/增长 |\n| Node Tokenomics | 追踪 AI 与 coding agent 的 token 支出 | 按用量 | 试验 |\n\n- 包装：平台 + 用例模块；思科安全/网络捆绑；本地与云并行。\n- 路线图：Agentic SOC、Agent Observability、NVIDIA 本地 AI、数据底座统一。\n\n## 技术栈与壁垒\n\n- **架构**：索引型机器数据平台（schema-on-read），SPL 查询；本地、云、混合部署。\n- **AI 路线**：把机器学习用于异常检测、事件关联与安全分析；2026 年转向 agentic：Agent Observability、Agentic SOC、tokenomics。\n- **壁垒**：海量机器数据的索引与查询能力、SPL 生态、ITSI/ES 的迁移成本、政府与大型企业合规认证。\n- **依赖与债务**：数据摄入成本高、云原生体验弱于 Datadog；思科整合与产品线重叠（安全/可观测）。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 大型政府/国防机构 | SIEM、合规审计、日志留存 | 未披露具体数字 | 官网/思科案例 |\n| 大型金融/电信企业 | ITSI 服务健康、事件关联 | 未披露具体数字 | 官网/思科案例 |\n| Cisco Live 2026 客户 | Agentic SOC / Agent Observability | 未披露具体数字 | 会议内容 |\n\n- 客户结构：政府、金融、电信、制造、大型企业；北美为主，全球部署。\n- 集中度：单一客户占比未披露；政府合同周期长、粘性高。\n- 续约/流失：并表后不披露 NRR；需从思科安全/可观测收入推断。\n- 说明：2026 年未检索到 Splunk 官方命名的量化客户案例，具体名单待采集。\n\n## 商业进展\n\n- 2024-03 完成思科收购；首个完整财年贡献约 $39 亿收入，超过整合目标。\n- 2026-09 .conf26：发布 Agent Observability、Node Tokenomics、Agentic SOC；与 NVIDIA 合作把自管理 AI 带入本地部署。\n- 2026 年 Cisco Live：Kamal Hathi 主讲「Agentic Enterprise」，把 Splunk 定位为 AI 的数据与安全底座。\n- 收购 WideField（身份/凭证/会话可见性）以加速 Agentic SOC（◐ 时间与金额待核）。\n- 思科交叉销售：安全、网络、AI 基础设施；具体协同收入待采集。\n\n## 经营业绩\n\n| 指标 | FY2023 | FY2024 | 并表后 | 说明 |\n|---|---|---|---|---|\n| 营收 | $36.5 亿 | $42.0 亿 | 首个完整财年贡献约 $39 亿 | 收购前 FY2024 截至 2024-01 |\n| 增速 | +39% | +15% | 并表不单列 | ◐ |\n| 毛利率 | 约 80% | 约 80% | 并表 | ◐ |\n| 营业利润 | 亏损/微利 | 亏损/微利 | 并表 | ◐ |\n| FCF | 待核 | 待核 | 并表 | ◐ |\n\n- 运营指标：ARR、客户数、NRR 未单独披露；思科称 Splunk 贡献约 $4B ARR。\n- 指引：不适用（已并表）。\n- 市场关注：思科 AI 订单与 Splunk 交叉销售的协同效应。\n\n## 股权、融资与股票\n\n- **不适用（已退市）**：2024-03-18 被思科收购，Splunk 股票停止交易。\n- 交易对价：约 $280 亿，$157/股现金；思科以现金与债务融资。\n- 母公司：Cisco（NASDAQ: CSCO）；Splunk 作为业务单元并表。\n- 估值：交易对应 FY2024 营收约 6.7x PS；当前无独立估值。\n- 资本动作：并表后无独立回购/分红；思科整体资本配置待查。\n\n## 团队与人员\n\n- 收购前员工约 7,000–8,000 人（◐）；并表后 headcount 不单独披露。\n- 研发/销售地域分布待补；思科整合可能带来重叠岗位优化。\n- 招聘/裁员：2024 年收购后是否有整合裁员待采集；2026 年 AI/安全岗位可能扩张。\n- 薪酬/股权激励：并入思科激励体系；关键人才保留是整合风险。\n- 组织：Kamal Hathi 任 SVP & GM；Gary Steele 已离任；创始人不再参与日常经营。\n\n## 竞争格局\n\n- 直接竞品：Datadog、Dynatrace、Elastic、Sumo Logic、Microsoft Sentinel、Palo Alto Cortex。\n- 替代方案：云厂商原生日志/安全服务、开源 ELK、AIOps 专业厂商。\n- 差异：海量日志索引 + SPL + ITSI/ES 的合规与安全场景；弱点：成本、云原生体验、产品复杂度。\n- 竞争动态：Datadog 从可观测侧侵蚀；Microsoft/Palo Alto 从安全侧挤压；思科捆绑是防守手段。\n- 份额：SIEM/日志分析市场领先，但云原生可观测份额低于 Datadog/Dynatrace（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：数据摄入成本高导致客户优化、云迁移流失；思科整合与交叉销售不及预期。\n- 技术：大规模索引的运维成本、云原生体验差距、AI agent 安全风险。\n- 法律/监管：政府客户合规、数据主权、出口管制；待补诉讼。\n- 治理：作为思科业务单元，战略受母公司 prioritization 影响；关键人才流失。\n- 争议：2024 年收购后的产品路线与定价调整，客户对成本透明度有异议（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：思科并表后的 Splunk 单独收入、客户案例、ARR 结构均未入库。建议跟踪：① 思科安全/可观测收入中的 Splunk 贡献；② Agent Observability/Agentic SOC 的付费采用；③ 与 NVIDIA 本地 AI 合作；④ 客户流失与云迁移；⑤ 与 Datadog/Dynatrace 的份额变化。\n\n## 信源与口径\n\n- 思科收购完成（2024-03）：https://www.cisco.com/site/us/en/about/corporate-strategy-office/acquisitions/splunk/index.html\n- Cisco/Splunk 2026 发布：https://investor.cisco.com/news/news-details/2026/Cisco-Delivers-Trusted-AI-at-Scale-Through-New-Splunk-Advancements/default.aspx\n- Splunk .conf26 / Agentic：https://www.splunk.com/en_us/blog/platform/the-agentic-era-demands-a-new-data-foundation-how-cisco-is-delivering-it-with-splunk.html\n- 公司历史与创始人：https://en.wikipedia.org/wiki/Splunk\n- 收入贡献：https://salesmotion.io/company-intelligence/splunk\n- 口径：收购前财务为最后公开口径；并表后不单独披露；◐ 表示媒体/第三方口径。' },
      { id: 'pagerduty', name: 'PagerDuty', def: '事件编排的定义者：从值班告警到 AI 事件响应，卖「响应流程」。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2009 / 旧金山（创立于多伦多） | 官网/Wikipedia |\n| 上市地 / 代码 | NYSE: PD | 2019-04 IPO |\n| 最新财年营收 | FY2026 $4.925 亿（+5.4%） | 2026-03-12 发布 |\n| 盈利 | Q3 FY2026 营业利润 $810 万（6.5%）；GAAP 净利润含一次性项 | ◐ 待 10-K |\n| 现金流 | 待核 | ◐ |\n| 客户 | ARR >$100k 客户 884 家（2026-07）；总客户数未披露 | 公司披露 |\n| 员工 | 约 1,155 人 | ◐ |\n| 市值 / 估值 | 约 $13–15 亿（2026 年末） | ◐ 第三方行情 |\n| 主要股东 | 机构为主；管理层持股待核 | ◐ |\n| 数据截至 | 财务 FY2026；行情 2026-10/11 | — |\n\n## 定位与沿革\n\n事件管理与值班调度（on-call）的事实标准之一：把告警聚合、升级、事件协作与复盘串成流程，再用 AI 做降噪、摘要、根因建议与自动响应。\n\n- 2009 年由 Alex Solomon、Andrew Miklas、Baskar Puvanathasan 在多伦多创立，三人均为滑铁卢大学背景；2010 年进入 Y Combinator。\n- 2019-04 在纽交所上市；2020 年代从 on-call 工具扩展到 Ops Suite（事件响应、状态页、自动化）。\n- 2026 年管理层交接：Jennifer Tejada（2016 年起任 CEO）转任执行董事长，John DiLullo 接任 CEO。\n- 2026 年 ARR 约 $5.01 亿（Q2 FY2027），>$100k ARR 客户 884 家，美元净留存率 98%。\n- 股价 2026 年 YTD 下跌约 42%，市场担忧 AI 削弱按席位计价的事件管理需求。\n\n## 创始人与管理层\n\n- **Alex Solomon（联合创始人，前 CEO）**：滑铁卢大学背景，任 CEO 约 11 年，2020 年卸任；现角色待核。\n- **Andrew Miklas（联合创始人，前 CTO）**：技术背景；后续角色待核。\n- **Baskar Puvanathasan（联合创始人，早期工程师）**：技术背景；后续角色待核。\n- **John DiLullo（CEO，2026 起）**：接替 Jennifer Tejada；此前经历待补（◐）。\n- **Jennifer Tejada（执行董事长）**：2016-07 加入任 CEO，带领公司从约 $5,000 万收入到 IPO 与 AI 转型；2026 年转任执行董事长。\n- 董事会与投票权结构待补；近 24 个月关键人事变动待采集。\n\n## 商业模式\n\n- **收入结构**：按席位订阅为主，辅以用量/事件量；企业合同按年/多年。\n- **销售动作**：PLG 自助 + 企业销售；land-and-expand 从 on-call 扩展到事件管理、自动化和 AI。\n- **单位经济**：毛利率约 80%+；non-GAAP 营业利润率约 6–10%；NRR 98%（2026-07）。\n- **收入质量**：经常性收入为主；>$100k ARR 客户 884 家；增长放缓至低个位数。\n- **定价趋势**：从「按席位」向「按事件/自动化/AI agent」迁移，以对冲席位被 agent 替代的风险。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| Incident Response | 告警聚合、升级、事件协作 | 按席位 | 主力 |\n| On-Call Management | 值班表、排班、升级策略 | 按席位 | 主力 |\n| StatusPage | 状态页与客户沟通 | 按订阅 | 增长 |\n| Event Orchestration | 事件路由、去重、自动化 | 按事件量 | 增长 |\n| AIOps | 告警降噪、关联、根因建议 | 按用量 | 增长 |\n| AI Agents | 自动调查、摘要、响应建议 | 按 agent/事件 | 试验/增长 |\n| Automation | runbook 自动化、webhook | 按动作 | 增长 |\n\n- 包装：Ops Suite 捆绑；AI 功能作为加购。\n- 路线图：AI 事件指挥、自动修复、与可观测/ITSM 深度集成。\n\n## 技术栈与壁垒\n\n- **架构**：多租户 SaaS；事件摄入与路由引擎，700+ 集成（监控、工单、聊天、云）。\n- **AI 路线**：LLM 用于告警摘要、相似事件检索、根因建议与自动响应；强调人在回路。\n- **壁垒**：流程嵌入与组织习惯、集成数量、值班数据、品牌心智。\n- **依赖与债务**：席位模式受 agent 替代威胁；增长依赖 AI 加购；与可观测平台的功能重叠。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 大型 SaaS/互联网企业 | 7×24 on-call、事件响应 | 未披露具体数字 | 官网客户故事 |\n| 金融/零售企业 | 事件编排、状态页、合规 | 未披露具体数字 | 官网客户故事 |\n| 884 家 >$100k ARR 客户 | 企业级事件管理 | NRR 98% | 公司披露 |\n\n- 客户结构：中大型企业、SaaS、金融、零售；北美为主，全球扩张。\n- 集中度：单一客户占比未披露；大客户数以 >$100k ARR 口径披露。\n- 续约/流失：NRR 98%（2026-07），低于 100% 说明现有客户支出略有收缩。\n\n## 商业进展\n\n- 2026-03 发布 FY2026：营收 $4.925 亿（+5.4%），略低于指引下限。\n- 2026 年 CEO 交接：John DiLullo 接任，Jennifer Tejada 转执行董事长。\n- Q2 FY2027：营收 $1.244 亿（+1%），ARR $5.01 亿；增长几乎停滞。\n- AI 产品：AI Agents、AIOps 加购；具体付费客户与 ARR 贡献待采集。\n- 股价：2026 年 YTD 下跌约 42%，市场担忧 AI 颠覆按席位模式。\n\n## 经营业绩\n\n| 指标 | FY2024 | FY2025 | FY2026 | 最新季度 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | $4.36 亿 | $4.67 亿 | $4.925 亿 | Q2 FY2027 $1.244 亿 | FY2026 +5.4%；Q2 FY2027 +1% |\n| 增速 | +9% | +7% | +5.4% | +1% | 增长持续放缓 |\n| 毛利率 | 约 80% | 约 80% | 约 80% | 待核 | ◐ |\n| 营业利润 | 亏损/微利 | 微利 | Q3 营业利润 $810 万（6.5%） | 待核 | ◐ |\n| FCF | 待核 | 待核 | 待核 | 待核 | ◐ |\n\n- 运营指标：ARR $5.01 亿（2026-07）；>$100k ARR 客户 884 家；NRR 98%。\n- 指引：FY2027 营收 $4.915–4.965 亿，几乎零增长。\n- 市场预期：AI 能否带来第二增长曲线，是估值核心。\n\n## 股权、融资与股票\n\n- 上市：NYSE PD；2019-04 IPO；发行价与首日表现待补。\n- 行情（2026-10/11）：市值约 $13–15 亿；股价约 $18（2026-10-28，◐）；52 周区间待补。\n- 估值：PS 约 2.7–3.0x FY2026 营收；P/E 待按 non-GAAP EPS 计算。\n- 股东：机构为主；管理层持股与投票权待核。\n- 资本动作：回购/分红待查最新 10-Q；股权激励以 RSU 为主。\n- 风险提示：增长停滞 + AI 颠覆叙事，估值可能继续承压。\n\n## 团队与人员\n\n- 员工约 1,155 人（◐）；研发/销售/支持分布待补。\n- 研发占比与地域分布待补；2026 年可能因增长放缓控制招聘。\n- 招聘/裁员：待采集；AI 相关岗位可能扩张。\n- 薪酬/股权激励：RSU 为主；流失率未披露。\n- 组织：CEO John DiLullo；执行董事长 Jennifer Tejada；创始人已不在日常管理层。\n\n## 竞争格局\n\n- 直接竞品：Datadog Incident Management、ServiceNow ITOM、BigPanda、Rootly、incident.io、FireHydrant、Atlassian Opsgenie。\n- 替代方案：云厂商告警、开源 Alertmanager + 自建流程、ITSM 工单。\n- 差异：流程与集成深度、品牌心智；弱点：增长停滞、席位模式受 AI 冲击、可观测平台内置事件能力。\n- 竞争动态：Datadog/ServiceNow 从平台侧挤压；AI SRE 新锐从自动调查切入。\n- 份额：事件管理市场领先，但可观测平台内置能力正在侵蚀（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：增长几乎停滞、NRR 98%、客户预算收紧；FY2027 指引零增长。\n- 技术：AI agent 替代值班席位、平台事故、集成依赖。\n- 法律/监管：数据隐私、SaaS 安全合规；待补诉讼。\n- 治理：CEO 交接后的战略连续性；执行董事长与 CEO 的权力边界。\n- 争议：2026 年股价大跌与「AI 吃掉 on-call」叙事，是市场主要争议（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：AI 产品收入、客户流失、CEO 交接后的战略均未入库。建议跟踪：① ARR 增速能否止跌；② AI Agents 的付费渗透；③ NRR 是否回到 100% 以上；④ 与 Datadog/ServiceNow 的竞争；⑤ 管理层交接后的产品路线。\n\n## 信源与口径\n\n- PagerDuty FY2026 业绩（2026-03-12）：https://www.pagerduty.com/newsroom/pagerduty-announces-fourth-quarter-full-year-fiscal-2026-financial-results/\n- Q2 FY2027 业绩：https://www.pagerduty.com/newsroom/pagerduty-announces-second-quarter-fiscal-2027-financial-results/\n- 公司历史与创始人：https://en.wikipedia.org/wiki/PagerDuty\n- 管理层：https://investor.pagerduty.com/governance/board-of-directors/\n- 行情与员工：https://www.perplexity.ai/finance/PD ；https://koalagains.com/stocks/NYSE/PD/management-team\n- 口径：FY2026 截至 2026-01-31；市值/股价为 2026-10/11 第三方口径；◐ 表示待核。' },
      { id: 'bigpanda', name: 'BigPanda', def: '告警关联专业户：把噪声压成事件，卖给企业 NOC。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2012 / Redwood City（以色列团队创立） | 官网 |\n| 上市地 / 代码 | 未上市 | 不适用 |\n| 最新财年营收 | 约 $8,040 万（2024，GetLatka 估算） | ◐ 私有公司估算 |\n| 盈利 | 未披露 | — |\n| 现金流 | 未披露 | — |\n| 客户 | 约 571 家企业使用；大型企业为主 | 6sense/TheirStack（◐） |\n| 员工 | 约 300–313 人 | ◐ |\n| 市值 / 估值 | 约 $12 亿（2022 Series E 后） | 未上市估值 |\n| 主要股东 | Advent International、Insight Partners 等 | ◐ |\n| 数据截至 | 融资 2022；经营数据 2024–2026 估算 | — |\n\n## 定位与沿革\n\nAIOps 事件智能平台：把多监控源的告警聚合成少量高置信事件，做去重、关联、根因候选与自动化触发，服务企业 NOC 与运维团队。\n\n- 2012 年由 Assaf Resnick（CEO）与 Elik Eizenberg 创立，总部 Redwood City，研发团队在以色列。\n- 2022-01 完成 $1.9 亿 Series E，估值 $12 亿；累计融资口径约 $2.9–5.0 亿（◐ 统计不一）。\n- 2026 年定位升级为「Agentic AI for IT Operations」，从告警关联走向 agentic 自动调查与处置。\n- 2026 年被 Gartner《Market Guide for Event Intelligence》提及；Gartner Peer Insights 有 36 条验证评论。\n- 2025-11 收购 Velocity（◐ 交易金额待核），补强自动化/可观测能力。\n\n## 创始人与管理层\n\n- **Assaf Resnick（联合创始人 & CEO）**：曾任 Sequoia Capital 投资人；2026 年仍在任，主推 Agentic IT Ops。\n- **Elik Eizenberg（联合创始人）**：技术背景，具体角色待补。\n- 其他高管：CTO/CFO/CRO 名单与背景待采集。\n- 董事会：Advent International、Insight Partners 等投资方席位待核。\n- 关键人事变动：2025–2026 年待采集。\n\n## 商业模式\n\n- **收入结构**：订阅为主；按事件量、设备数或企业合同计价。\n- **销售动作**：企业销售驱动，面向大型企业的 NOC/ITOps；与 Datadog、ServiceNow、PagerDuty 等集成/合作。\n- **单位经济**：私有公司不披露；SaaS 毛利率预计 70–80%（◐）。\n- **收入质量**：大型企业合同、续约为主；收入规模约 $8,000 万，增长依赖 agentic 新产品。\n- **定价趋势**：从「按告警量」向「按事件/自动化/AI agent」包装，以提升客单价。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| Event Intelligence | 告警聚合、去重、关联 | 按事件量 | 主力 |\n| Incident Intelligence | 事件上下文、根因候选 | 按事件量 | 主力 |\n| Automation | 自动触发 runbook、工单、协作 | 按动作 | 增长 |\n| Agentic AIOps | agent 自动调查、建议与处置 | 按 agent/事件 | 试验/增长 |\n| Integrations | 监控、ITSM、聊天、云 | 随平台 | 主力 |\n\n- 包装：平台 + 事件量；与 Datadog/ServiceNow/PagerDuty 联合方案。\n- 路线图：Agentic IT Ops、自动修复、AIOps 与可观测数据融合。\n\n## 技术栈与壁垒\n\n- **架构**：SaaS 事件数据平台；多源告警接入、归一化、聚类与关联；ML/LLM 做根因候选。\n- **AI 路线**：从规则/ML 关联走向 agentic 调查；强调「减少噪声、缩短 MTTR」。\n- **壁垒**：企业告警数据与集成库、NOC 流程嵌入、大型企业客户关系。\n- **依赖与债务**：上游可观测平台内置关联能力；独立 AIOps 厂商的生存空间被挤压；LLM 推理成本。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| United Airlines | 与 Datadog 联合客户，事件关联 | 未披露具体数字 | BigPanda/Datadog 2020 新闻稿 |\n| 大型企业 NOC（未具名） | 告警降噪、事件关联 | 未披露具体数字 | 官网客户页 |\n| 178 家 10,000+ 员工企业 | 企业级 ITOps | 未披露具体数字 | 6sense 估算（◐） |\n\n- 客户结构：大型企业为主，覆盖航空、金融、零售、科技；约 571 家企业使用（◐）。\n- 集中度：单一客户占比未披露；大型企业合同周期长。\n- 续约/流失：NRR 未披露；需从客户数与融资节奏推断。\n- 说明：除 United Airlines 外，公开命名的量化案例较少，待采集。\n\n## 商业进展\n\n- 2022-01 $1.9 亿 Series E，估值 $12 亿；此后无新融资公开。\n- 2025-11 收购 Velocity（◐ 金额待核），补强自动化与可观测。\n- 2026 年主推「Agentic AI for IT Operations」；被 Gartner Market Guide 2026 提及。\n- 与 Datadog、ServiceNow、PagerDuty 的集成/联合销售持续；具体合同待采集。\n- 上市/退出路径：未披露；私募股东可能寻求并购或 IPO。\n\n## 经营业绩\n\n| 指标 | 2021 | 2022 | 2024 | 说明 |\n|---|---|---|---|---|\n| 营收 | 约 $2,400 万 | 未披露 | 约 $8,040 万 | GetLatka 估算（◐） |\n| 增速 | 高增长 | 未披露 | 未披露 | 2021 net-new ARR +155% |\n| 毛利率 | 未披露 | 未披露 | 未披露 | — |\n| 营业利润 | 未披露 | 未披露 | 未披露 | — |\n| FCF | 未披露 | 未披露 | 未披露 | — |\n\n- 运营指标：客户数约 571；员工约 300–313；ARR 未披露。\n- 指引：不适用（私有公司）。\n- 市场预期：Agentic IT Ops 能否带来第二增长曲线。\n\n## 股权、融资与股票\n\n- **不适用（未上市）**：无股票代码与二级市场市值。\n- 最新估值：$12 亿（2022-01 Series E，$1.9 亿）。\n- 累计融资：约 $2.9–5.0 亿（口径不一，◐）；投资方包括 Advent International、Insight Partners。\n- 股东结构：创始人、VC/PE；具体持股待核。\n- 流动性：无公开市场；可能通过并购、IPO 或二级份额退出。\n- 资本动作：2025 年收购 Velocity；是否再融资待采集。\n\n## 团队与人员\n\n- 员工约 300–313 人（◐）；研发在以色列，销售/支持在美国。\n- 研发占比、地域分布待补；2026 年可能随 agentic 产品扩张。\n- 招聘/裁员：待采集；2022 年后科技行业收缩可能影响招聘。\n- 薪酬/股权激励：私有公司以期权/RSU 为主；流失率未披露。\n- 组织：CEO Assaf Resnick；联合创始人 Elik Eizenberg；高管名单待补。\n\n## 竞争格局\n\n- 直接竞品：Splunk ITSI、PagerDuty、Dynatrace、Datadog、IBM Instana、Resolve AI、Moogsoft。\n- 替代方案：可观测平台内置告警关联、ITSM 事件管理、自建规则引擎。\n- 差异：多源告警关联与降噪、大型企业 NOC 流程；弱点：独立厂商被平台捆绑挤压、AI 功能差异化不足。\n- 竞争动态：Datadog/Dynatrace 把关联能力内置；AI SRE 新锐从调查侧切入。\n- 份额：AIOps 事件关联细分约 5–8%（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：增长与融资节奏、独立 AIOps 市场被平台侵蚀、客户集中。\n- 技术：关联准确率、LLM 推理成本、agent 误判导致误操作。\n- 法律/监管：数据隐私、SaaS 安全合规；待补诉讼。\n- 治理：私募/VC 股东退出压力；收购整合（Velocity）。\n- 争议：2022 年 $12 亿估值是否仍成立，缺乏新融资验证（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：ARR、NRR、客户名单、融资与估值均未入库。建议跟踪：① Agentic IT Ops 的付费采用；② 是否启动新融资/IPO；③ 与 Datadog/ServiceNow 的竞合；④ 客户数增长；⑤ Velocity 整合效果。\n\n## 信源与口径\n\n- Series E 与估值：https://www.insightpartners.com/ideas/bigpanda-raises-190-million-in-funding-at-1-2-billion-valuation/\n- 公司与客户：https://www.bigpanda.io/company/ ；https://www.bigpanda.io/customers/\n- United Airlines 联合客户：https://www.bigpanda.io/press-release/bigpanda-and-datadog-form-partnership-for-integration-and-go-to-market/\n- 融资/员工估算：https://multiples.vc/private-comps/bigpanda ；https://www.owler.com/company/bigpanda\n- 客户使用量：https://www.6sense.com/tech/system-administration/bigpanda-market-share\n- 口径：私有公司财务为第三方估算；估值停留在 2022 年；◐ 表示待核。' },
      { id: 'resolveai', name: 'Resolve.ai', def: 'AI SRE 新锐标杆：多 agent 并行排障，目标自动处理 80% 报警。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2024 / 旧金山 | Forbes AI 50 Brink List |\n| 上市地 / 代码 | 未上市 | 不适用 |\n| 最新财年营收 | 约 $400 万 ARR（Tracxn 估算） | ◐ 私有公司估算 |\n| 盈利 | 未披露 | — |\n| 现金流 | 未披露 | — |\n| 客户 | 未披露总数；Salesforce、Coinbase、DoorDash 等 | 媒体/官方案例 |\n| 员工 | 未披露（估计 50–100 人） | ◐ |\n| 市值 / 估值 | $15 亿（2026-04 Series A 扩展） | Forbes/公司公告 |\n| 主要股东 | Greylock、DST Global、Salesforce Ventures、Unusual Ventures 等 | 融资公告 |\n| 数据截至 | 融资 2026-04；经营估算 2026-11 | — |\n\n## 定位与沿革\n\nAI SRE 赛道的新锐代表：用多个专职 agent（数据库、基础设施、代码等）并行调查告警，把根因、证据链与处置建议直接推到工程师面前，目标口径是「自动处理 80% 的报警」。\n\n- 2024 年由 Spiros Xanthos（CEO，前 Splunk 可观测业务负责人）与 Mayank Agarwal（CTO，UIUC 背景）在旧金山创立；两人在 UIUC 研究生阶段相识。\n- 2024-10 完成 $3,500 万种子轮，由 Greylock 领投，Unusual Ventures 等参与。\n- 2025 年完成 $1.25 亿 Series A；2026-02 Bloomberg 报道其估值达到 $10 亿。\n- 2026-04 完成 $4,000 万 Series A 扩展，估值 $15 亿，由 DST Global 与 Salesforce Ventures 领投；累计融资 $1.9 亿，同时成立 Resolve AI Labs。\n- 客户包括 Salesforce、Coinbase、DoorDash、Foursquare、Kumo AI、Apoha；Coinbase 案例称事件调查时间缩短 72%。\n\n## 创始人与管理层\n\n- **Spiros Xanthos（联合创始人 & CEO）**：前 Splunk 可观测业务负责人；更早创办 Netsil（被 Nutanix 收购，◐ 待核）。Forbes 部分报道使用全名 Spiros Xanthopoulos。\n- **Mayank Agarwal（联合创始人 & CTO）**：UIUC 背景，负责 agent 架构与工程；此前经历待补。\n- 核心团队：来自 Splunk、Datadog、云厂商的 SRE/可观测工程师；具体名单待采集。\n- 董事会：Greylock、DST Global、Salesforce Ventures 席位待核。\n- 关键人事变动：2024–2026 年快速扩张，招聘节奏待采集。\n\n## 商业模式\n\n- **收入结构**：订阅为主；按席位、按事件量或按自动处理量计价（具体包装未公开）。\n- **销售动作**：企业销售驱动，面向高告警量的云原生企业；以 POC/试点切入，再扩展到更多服务和团队。\n- **单位经济**：ARR 约 $400 万（◐），估值 $15 亿，对应约 375x ARR；早期高估值依赖增长预期。\n- **收入质量**：客户数量少、单客户价值高；Salesforce/Coinbase/DoorDash 等标杆客户带来背书，但集中度风险高。\n- **定价趋势**：AI SRE 可能按「自动闭环的事件数」或「节省的工程师工时」计价，仍需市场验证。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| AI SRE | 告警调查、根因定位、处置建议 | 按席位/事件 | 主力 |\n| Multi-agent Investigation | 数据库、基础设施、代码多 agent 并行 | 按事件/agent | 主力 |\n| Integrations | 对接 Datadog、Splunk、Prometheus、GitHub 等 | 随平台 | 主力 |\n| Resolve AI Labs | 可靠性研究、评测与开源 | 不单独计价 | 试验 |\n| Auto-remediation | 受控自动处置与回滚 | 按动作 | 试验/增长 |\n\n- 包装：以「AI SRE 平台」整体订阅，按接入服务数与事件量分层。\n- 路线图：从调查走向受控执行、跨云/本地部署、行业化 runbook。\n\n## 技术栈与壁垒\n\n- **架构**：多 agent 编排 + 遥测/代码/变更数据关联；每个 agent 负责一个领域（数据库、网络、应用代码），并行调查后汇总证据链。\n- **AI 路线**：LLM 负责规划、工具调用与根因推理；强调可解释的证据链与人在回路，避免「黑箱建议」。\n- **壁垒**：真实故障数据与评测集、与可观测平台的深度集成、客户 SRE 流程嵌入；早期壁垒尚在建立。\n- **依赖与债务**：模型推理成本、幻觉与误判、对第三方遥测数据的依赖；自动执行的信任与责任边界。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| Coinbase | 全球加密基础设施的事件调查 | 调查时间缩短 72% | 官方案例 |\n| DoorDash | 高并发业务的告警调查 | 未披露具体数字 | 创始人公开宣布 |\n| Salesforce | 企业级 SRE 场景 | 未披露具体数字 | Bloomberg 报道 |\n| Foursquare / Kumo AI / Apoha | 云原生故障排查 | 未披露具体数字 | TechCrunch 报道 |\n\n- 客户结构：云原生、金融科技、SaaS、消费互联网；以高告警量、复杂微服务架构的企业为主。\n- 集中度：客户数量少，头部客户占比可能较高（◐）。\n- 续约/流失：NRR 未披露；早期客户以试点扩展为主。\n\n## 商业进展\n\n- 2026-04 Series A 扩展 $4,000 万，估值 $15 亿；DST Global、Salesforce Ventures 领投；累计融资 $1.9 亿。\n- 成立 Resolve AI Labs，投入可靠性研究、评测与开源；具体产出待采集。\n- 客户扩张：Coinbase、DoorDash、Salesforce 等标杆；Salesforce Ventures 同时是投资方与客户。\n- GTM：从硅谷云原生企业向金融、消费互联网扩展；国际化待采集。\n- 竞争：Elastic 2026-06 以最高 $8,500 万收购 Deductive，AI SRE 赛道开始整合（◐）。\n\n## 经营业绩\n\n| 指标 | 2024 | 2025 | 2026 | 说明 |\n|---|---|---|---|---|\n| ARR | 未披露 | 未披露 | 约 $400 万 | Tracxn/raisedly 估算（◐） |\n| 增速 | — | 高增长 | 高增长 | 早期基数低 |\n| 毛利率 | 未披露 | 未披露 | 未披露 | SaaS + 推理成本 |\n| 营业利润 | 未披露 | 未披露 | 未披露 | 投入期 |\n| FCF | 未披露 | 未披露 | 未披露 | — |\n\n- 运营指标：客户数、事件处理量、自动闭环率均未披露；「80% 报警自动处理」是目标口径，不是已验证结果。\n- 指引：不适用（私有公司）。\n- 市场预期：$15 亿估值需要 ARR 与客户数快速扩张来支撑。\n\n## 股权、融资与股票\n\n- **不适用（未上市）**：无股票代码与二级市场市值。\n- 最新估值：$15 亿（2026-04 Series A 扩展）。\n- 累计融资：$1.9 亿（$3,500 万种子 + $1.25 亿 Series A + $4,000 万扩展）。\n- 投资方：Greylock、DST Global、Salesforce Ventures、Unusual Ventures 等。\n- 股东结构：创始人、VC、战略投资方（Salesforce Ventures）；具体持股待核。\n- 流动性：无公开市场；未来可能 IPO、并购或二级份额交易。\n\n## 团队与人员\n\n- 员工估计 50–100 人（◐）；以工程、研究与 GTM 为主。\n- 研发占比高；团队来自 Splunk、Datadog、云厂商与 SRE 社区。\n- 招聘：2026 年随融资扩张；具体岗位待采集。\n- 薪酬/股权激励：早期公司以期权为主；流失率未披露。\n- 组织：CEO Spiros Xanthos、CTO Mayank Agarwal；Resolve AI Labs 负责人待核。\n\n## 竞争格局\n\n- 直接竞品：Datadog Bits AI SRE、Dynatrace Intelligence、PagerDuty AI Agents、Rootly AI SRE、Traversal、Deductive（Elastic 收购）。\n- 替代方案：企业自建 LLM + runbook、传统 AIOps、人工 SRE。\n- 差异：多 agent 并行调查、证据链与可解释性；弱点：早期规模小、对第三方遥测依赖、自动执行信任不足。\n- 竞争动态：可观测平台把 AI SRE 内置，独立厂商需证明「跨平台、更深调查」的价值；赛道开始并购整合。\n- 份额：AI SRE 早期高度分散，Resolve 是声量领先者之一（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：估值与 ARR 严重脱节、客户集中、增长不及预期；AI SRE 预算可能被平台捆绑吞噬。\n- 技术：LLM 幻觉导致错误根因、自动处置引发生产事故、推理成本高。\n- 法律/监管：客户数据接入的隐私与安全、自动执行的责任界定。\n- 治理：早期投资人控制权、创始人依赖；团队快速扩张的管理风险。\n- 争议：「自动处理 80% 报警」是营销目标还是可验证指标，尚缺第三方审计（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：ARR、客户数、自动闭环率、融资条款均未入库。建议跟踪：① ARR 是否从 $400 万快速翻倍；② Coinbase/DoorDash 案例的扩展与续约；③ 「80% 自动处理」的第三方验证；④ Elastic/Deductive 等并购对格局的影响；⑤ 可观测平台内置 AI SRE 的挤压。\n\n## 信源与口径\n\n- Forbes（2026-04-16）：https://www.forbes.com/sites/sofiachierchio/2026/04/16/this-15-billion-ai-startup-steps-in-when-software-breaks/\n- Bloomberg（2026-02-04）：https://www.bloomberg.com/news/articles/2026-02-04/resolve-ai-hits-1-billion-valuation-for-outage-thwarting-ai-agents\n- 公司融资公告：https://resolve.ai/news/Series-A-extension-and-Resolve-AI-Labs\n- Coinbase 案例：https://resolve.ai/customers/coinbase\n- 早期融资：https://www.reuters.com/technology/artificial-intelligence/greylock-backed-resolve-ai-raises-35-million-seed-funding-help-engineers-2024-10-01/\n- 口径：ARR 为第三方估算；估值来自融资公告/媒体；◐ 表示待核。' },
      { id: 'shoreline', name: 'Shoreline.io', def: '修复动作即代码：把重复故障处置写成可审计的自动化动作库。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2019 / Redwood City | 官网/Crunchbase |\n| 上市地 / 代码 | 被 NVIDIA 收购（2024-06） | 不适用；报道价约 $1 亿 |\n| 最新财年营收 | 未披露 | — |\n| 盈利 | 未披露 | — |\n| 现金流 | 未披露 | — |\n| 客户 | 未披露；云运维团队为主 | ◐ |\n| 员工 | 未披露（收购前约 50–100 人） | ◐ |\n| 市值 / 估值 | 不适用（已并入 NVIDIA） | 收购价约 $1 亿（报道） |\n| 主要股东 | NVIDIA 100%（2024 起） | 此前 Insight、Dawn、NTT VC、Canvas |\n| 数据截至 | 收购 2024-06；2026 并入 NVIDIA | — |\n\n## 定位与沿革\n\n以「repair automation」切入运维自动化：用 Op 语言把修复动作脚本化、版本化，跨主机与集群执行，强调可审计与可回滚；核心价值是把「人肉 runbook」变成可测试的代码。\n\n- 2019 年由 Anurag Gupta（前 AWS 副总裁，负责 Amazon Aurora）与多位前 AWS 工程师在 Redwood City 创立。\n- 2019 年完成 $2,200 万 Series A；2022-03 完成 $3,500 万 Series B，由 Insight Partners 领投，Dawn Capital、NTT VC、Canvas Ventures 参与。\n- 2024-06 被 NVIDIA 收购，报道价约 $1 亿美元；这是 NVIDIA 2024 年第三笔收购（前两笔为 Deci、Run:ai）。\n- 并入 NVIDIA 后，Shoreline 的独立产品与品牌是否保留待核；技术可能进入 NVIDIA 的 AI 基础设施/企业软件栈。\n- 在 AIOps 语境里，Shoreline 代表「自动处置执行层」：不只是告诉人怎么修，而是把修复动作变成可执行的代码。\n\n## 创始人与管理层\n\n- **Anurag Gupta（创始人 & 前 CEO）**：前 AWS 副总裁，负责 Amazon Aurora；更早曾在 Oracle 等公司任职（◐ 待核）。收购后是否留在 NVIDIA 待核。\n- 联合创始团队：多位前 AWS 工程师；具体名单待采集。\n- 管理层：收购后并入 NVIDIA，现任负责人待核。\n- 董事会：收购前由 Insight Partners、Dawn Capital、NTT VC、Canvas Ventures 等投资方组成。\n- 关键人事变动：2024 年收购后的整合与离职情况待采集。\n\n## 商业模式\n\n- **收入结构**：订阅为主；按节点/主机或集群计价，企业合同。\n- **销售动作**：企业销售驱动，面向云运维/SRE 团队；以自动化动作库和 Op 语言切入。\n- **单位经济**：私有公司不披露；SaaS 毛利率预计 70–80%（◐）。\n- **收入质量**：大型企业合同、按节点扩张；被收购后不再独立披露。\n- **定价趋势**：从「按节点」向「按自动化动作/修复事件」包装的可能性待观察。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| Shoreline Platform | 跨集群运维自动化与修复 | 按节点 | 主力（收购前） |\n| Op Language | 运维动作的领域特定语言 | 随平台 | 主力 |\n| Op Packs | 预置修复动作库 | 随平台 | 主力 |\n| Incident Automation | 告警触发自动修复、回滚 | 按动作 | 增长 |\n| Integrations | 监控、工单、云平台对接 | 随平台 | 主力 |\n\n- 包装：平台 + 动作库；按节点/集群订阅。\n- 路线图：并入 NVIDIA 后可能转向 GPU 集群运维、AI 基础设施自愈（待核）。\n\n## 技术栈与壁垒\n\n- **架构**：agentless 远程执行；Op 语言描述修复动作；跨主机/集群的分布式执行与审计。\n- **AI 路线**：以规则/脚本自动化为主，AI 用于动作生成与选择；不是纯 LLM agent 路线。\n- **壁垒**：动作库积累、Op 语言生态、企业运维流程嵌入、可审计/可回滚的安全设计。\n- **依赖与债务**：被收购后的产品不确定性；与云厂商原生自动化（SSM、Run Command）竞争。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 大型云运维团队（未具名） | 重复故障自动修复 | 未披露具体数字 | 官网/媒体 |\n| 金融/科技企业（未具名） | 跨集群 runbook 自动化 | 未披露具体数字 | 官网/媒体 |\n| NVIDIA 内部 | GPU 集群运维（推测） | 未披露 | ◐ 待核 |\n\n- 客户结构：云原生企业、大型运维团队；具体名单未公开。\n- 集中度：未披露；被收购后不再单独披露。\n- 续约/流失：未披露；收购后客户关系由 NVIDIA 承接。\n- 说明：Shoreline 公开命名的量化案例很少，模板要求下只能标注「未披露」。\n\n## 商业进展\n\n- 2024-06 被 NVIDIA 收购，报道价约 $1 亿美元；成为 NVIDIA 2024 年第三笔收购。\n- 并入 NVIDIA 后，可能补强 GPU 集群运维、AI 基础设施自愈与企业软件栈；具体整合方案待核。\n- 收购前最后公开融资为 2022-03 $3,500 万 Series B（Insight Partners 领投）。\n- 2026 年是否以 NVIDIA 产品形态重新出现，待采集。\n- 竞争：云厂商原生自动化、Harness、Rundeck、AIOps 自动处置厂商。\n\n## 经营业绩\n\n| 指标 | 2021 | 2022 | 2024 | 说明 |\n|---|---|---|---|---|\n| 营收 | 未披露 | 未披露 | 未披露 | 私有公司 |\n| 增速 | 未披露 | 未披露 | 未披露 | — |\n| 毛利率 | 未披露 | 未披露 | 未披露 | — |\n| 营业利润 | 未披露 | 未披露 | 未披露 | — |\n| FCF | 未披露 | 未披露 | 未披露 | — |\n\n- 运营指标：客户数、节点数、自动化动作执行量均未披露。\n- 融资：$2,200 万 A + $3,500 万 B；2024 年以约 $1 亿被收购。\n- 指引：不适用（已并入 NVIDIA）。\n\n## 股权、融资与股票\n\n- **不适用（已被收购）**：2024-06 并入 NVIDIA，Shoreline 不再独立。\n- 收购价：约 $1 亿美元（Bloomberg/媒体口径；NVIDIA 未正式披露条款）。\n- 历史融资：$2,200 万 Series A（2019）+ $3,500 万 Series B（2022），累计约 $5,700 万。\n- 投资方：Insight Partners、Dawn Capital、NTT VC、Canvas Ventures 等。\n- 股东：2024 年起 NVIDIA 100%；历史股东通过并购退出。\n- 流动性：并购退出；无独立 IPO 计划。\n\n## 团队与人员\n\n- 收购前员工约 50–100 人（◐）；以工程与产品为主。\n- 研发占比高；团队来自 AWS、云基础设施与运维自动化背景。\n- 收购后团队并入 NVIDIA；留任与离职情况待采集。\n- 薪酬/股权激励：收购前以期权为主；并购后转为 NVIDIA 激励。\n- 组织：创始人 Anurag Gupta 收购后角色待核。\n\n## 竞争格局\n\n- 直接竞品：Rundeck（PagerDuty）、Harness Chaos/Automation、AWS Systems Manager、Azure Automation、Google Cloud Ops。\n- 替代方案：自建脚本/Ansible/Terraform、runbook 平台、AIOps 自动处置。\n- 差异：Op 语言 + 动作库 + 跨集群执行 + 可审计；弱点：被收购后产品路线不确定、云厂商原生自动化免费。\n- 竞争动态：AIOps 从「建议」走向「执行」，Shoreline 是执行层的早期样本；NVIDIA 收购说明算力运维是战略场景。\n- 份额：运维自动化细分较小，Shoreline 未形成公开份额（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：被收购后独立产品可能消失；客户迁移与支持连续性风险。\n- 技术：自动修复误操作、跨环境权限、脚本维护成本。\n- 法律/监管：生产变更的审计与责任；被收购后的数据/合同承接。\n- 治理：NVIDIA 整合优先级；创始人及核心团队留任。\n- 争议：收购价约 $1 亿低于 2022 年融资时的预期，反映运维自动化赛道估值承压（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：收购后的产品形态、客户迁移、NVIDIA 整合方案均未入库。建议跟踪：① Shoreline 技术是否进入 NVIDIA AI Enterprise/GPU 运维；② 客户是否续约；③ 创始人去向；④ 运维自动化赛道的并购潮；⑤ 与 Harness/Rundeck 的竞争。\n\n## 信源与口径\n\n- NVIDIA 收购报道（2024-06）：https://www.bloomberg.com/news/articles/2024-06-18/nvidia-agrees-deal-to-buy-software-startup-shoreline\n- SiliconAngle：https://siliconangle.com/2024/06/19/nvidia-reportedly-acquires-incident-automation-startup-shoreline-100m/\n- Series B：https://finance.yahoo.com/news/shoreline-io-closes-35-million-120000001.html\n- 公司与创始人：https://www.crunchbase.com/organization/shoreline-software ；https://medium.com/authority-magazine/anurag-gupta-of-shoreline-io-five-things-you-need-to-create-a-highly-successful-startup-4edc864d0047\n- 口径：收购价与日期为媒体报道；NVIDIA 未正式披露条款；◐ 表示待核。' },
      { id: 'rootly', name: 'Rootly', def: '事件响应 AI：Slack 原生的事故指挥与自动复盘。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2020/2021 / 旧金山 | YC S21；官网称 2021 创立 |\n| 上市地 / 代码 | 未上市 | 不适用 |\n| 最新财年营收 | 未披露（Dealroom 2023 <$1M，已过时） | ◐ |\n| 盈利 | 未披露 | — |\n| 现金流 | 未披露 | — |\n| 客户 | Fortune 100 到初创；Dropbox、Figma、LinkedIn、Postman 等 | 官网/案例 |\n| 员工 | 约 75 人 | ◐ |\n| 市值 / 估值 | 未披露；2023 估值区间 $5,000 万–1 亿（未确认） | ◐ |\n| 主要股东 | Renegade Partners、Google Gradient Ventures、XYZ、8VC、YC | 融资公告 |\n| 数据截至 | 融资 2023-08；经营 2026 | — |\n\n## 定位与沿革\n\nSlack 原生的事件管理平台：把 on-call、事故指挥、状态页、复盘与 AI SRE 收进团队已经在用的聊天工具，降低采用门槛。\n\n- 2020/2021 年由 JJ Tang（CEO）与 Quentin Rousseau 等创立，进入 Y Combinator S21；官网称 2021 年创立。\n- 2021-07 完成 $320 万种子轮（XYZ Venture Capital、8VC、YC）；2023-08 完成 $1,200 万 Series A（Renegade Partners 领投，Google Gradient Ventures、XYZ 参与），累计约 $1,520 万。\n- 2026-07 收购 ThinkHive，把 AI agent 推进到根因分析与修复草稿；此前已推出 AI-agent-first API。\n- 2026 年开源 On-Call Health 项目，并运营 Rootly AI Labs（可靠性研究、知识图谱、AI 复盘）。\n- 客户包括 Dropbox、Figma、LinkedIn、Postman、Recall.ai、Clay；定位从「事件管理」升级为「AI-native reliability platform」。\n\n## 创始人与管理层\n\n- **JJ Tang（联合创始人 & CEO）**：此前创办 PopSQL（YC 公司）；2026 年自称「Forward Deployed CEO」，强调贴近客户。\n- **Quentin Rousseau（联合创始人）**：YC 页面列为主要联合创始人；具体角色待补。\n- **Sylvain Kalache（联合创始人/ Rootly AI Labs 负责人）**：负责 AI Labs、开源与可靠性研究；创始团队名单口径不一（◐）。\n- 高管团队：CTO/CFO/CRO 名单待采集。\n- 董事会：Renegade Partners、Google Gradient Ventures 等投资方席位待核。\n\n## 商业模式\n\n- **收入结构**：按用户/席位订阅，起价约 $20/用户/月；企业合同按年。\n- **销售动作**：PLG + 销售驱动；Slack 原生降低试用门槛，land-and-expand 从 on-call 扩展到事件管理、复盘与 AI SRE。\n- **单位经济**：私有公司不披露；SaaS 毛利率预计 70–80%（◐）。\n- **收入质量**：中小客户数量多、企业客户扩张；ARR 未披露，规模仍小。\n- **定价趋势**：AI 功能可能按事件/agent 加购，从席位向用量迁移。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| Incident Management | 事故指挥、角色分配、时间线 | 按用户 | 主力 |\n| On-Call | 排班、升级、告警路由 | 按用户 | 主力 |\n| Status Pages | 对外状态沟通 | 按订阅 | 增长 |\n| Retrospectives | 自动复盘、行动项 | 按用户 | 增长 |\n| AI SRE | 根因分析、修复草稿、相似事件 | 按 agent/事件 | 试验/增长 |\n| Rootly AI Labs | 知识图谱、On-Call Health 开源 | 不单独计价 | 试验 |\n\n- 包装：按用户分层 + AI 加购；企业版含 SSO、审计、权限。\n- 路线图：AI agent 自动调查、知识图谱、跨事故模式分析。\n\n## 技术栈与壁垒\n\n- **架构**：Slack/Teams 原生工作流；事件数据模型、集成库（监控、工单、聊天、云）。\n- **AI 路线**：LLM 做事故摘要、相似事件检索、复盘草稿与根因建议；ThinkHive 补强 agent 调查。\n- **壁垒**：Slack 工作流嵌入、事件数据积累、开发者体验、快速产品迭代。\n- **依赖与债务**：平台依赖（Slack）、与 PagerDuty/incident.io 的功能同质化、AI 推理成本。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| Dropbox | 事件管理与 on-call | 未披露具体数字 | 官网客户页 |\n| Figma | 事故指挥与复盘 | 未披露具体数字 | 官网客户页 |\n| LinkedIn | 大型组织事件响应 | 未披露具体数字 | 官网客户页 |\n| Postman | Agentic 时代的可靠性 | 未披露具体数字 | 2026-10 案例 |\n| Recall.ai / Clay | 初创团队事件管理 | 未披露具体数字 | 客户故事 |\n\n- 客户结构：Fortune 100 到初创；科技、SaaS、金融科技为主。\n- 集中度：未披露；中小客户数量可能较多。\n- 续约/流失：NRR 未披露；产品迭代快，客户扩张依赖 AI 加购。\n\n## 商业进展\n\n- 2023-08 $1,200 万 Series A 后无公开新融资；累计约 $1,520 万。\n- 2026-07 收购 ThinkHive，补强 AI agent 的根因分析与修复能力。\n- 2026 年推出 AI-agent-first API、AI 自动复盘、On-Call Health 开源项目。\n- 客户案例扩展到 Postman、LinkedIn、Dropbox、Figma 等；企业市场是增长重点。\n- 竞争：与 PagerDuty、incident.io、FireHydrant、Opsgenie 正面竞争。\n\n## 经营业绩\n\n| 指标 | 2021 | 2023 | 2026 | 说明 |\n|---|---|---|---|---|\n| 营收 | 未披露 | <$100 万（Dealroom） | 未披露 | ◐ 估算已过时 |\n| 增速 | — | 高增长 | 未披露 | 早期 |\n| 毛利率 | 未披露 | 未披露 | 未披露 | — |\n| 营业利润 | 未披露 | 未披露 | 未披露 | — |\n| FCF | 未披露 | 未披露 | 未披露 | — |\n\n- 运营指标：累计管理 60,000+ 事故（2023 口径）；客户数、ARR 未披露。\n- 融资：$320 万种子 + $1,200 万 A，累计 $1,520 万。\n- 指引：不适用（私有公司）。\n\n## 股权、融资与股票\n\n- **不适用（未上市）**：无股票代码与二级市场市值。\n- 最新融资：$1,200 万 Series A（2023-08），估值未披露。\n- 累计融资：约 $1,520 万。\n- 投资方：Renegade Partners、Google Gradient Ventures、XYZ Venture Capital、8VC、Y Combinator。\n- 股东结构：创始人、VC；具体持股待核。\n- 流动性：无公开市场；未来可能 IPO、并购或二级份额交易。\n\n## 团队与人员\n\n- 员工约 75 人（◐）；以工程、产品、GTM 为主。\n- 研发占比高；团队分布在旧金山与远程。\n- 招聘：2026 年随 AI 产品扩张；具体岗位待采集。\n- 薪酬/股权激励：早期公司以期权为主；流失率未披露。\n- 组织：CEO JJ Tang；AI Labs 由 Sylvain Kalache 负责；CTO 待补。\n\n## 竞争格局\n\n- 直接竞品：PagerDuty、incident.io、FireHydrant、Atlassian Opsgenie、Datadog Incident Management。\n- 替代方案：Slack 自建流程、Jira Service Management、自研 on-call 工具。\n- 差异：Slack 原生体验、快速迭代、AI 复盘/知识图谱；弱点：规模小、品牌弱、功能易被复制。\n- 竞争动态：PagerDuty 增长停滞给新锐机会；incident.io 同样主打 Slack 原生，竞争激烈。\n- 份额：事件管理新锐中声量靠前，但整体份额小（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：融资规模小、增长与盈利压力、客户集中度；被 PagerDuty/平台厂商挤压。\n- 技术：AI 复盘准确性、Slack 平台依赖、数据安全。\n- 法律/监管：事故数据隐私、SaaS 合规；待补诉讼。\n- 治理：创始团队小、关键人依赖；收购整合（ThinkHive）。\n- 争议：AI 自动复盘能否替代人工复盘，客户接受度待验证（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：ARR、客户数、融资估值、ThinkHive 整合均未入库。建议跟踪：① 是否启动新一轮融资；② AI SRE/ThinkHive 的付费采用；③ 企业客户扩张；④ 与 incident.io/PagerDuty 的竞争；⑤ On-Call Health 开源社区。\n\n## 信源与口径\n\n- Series A：https://rootly.com/blog/rootly-raises-12-million-from-renegade-partners-google-gradient-ventures-xyz-ventures\n- 公司与客户：https://rootly.com/about ；https://rootly.com/customers\n- ThinkHive 收购：https://rootly.com/blog/why-rootly-acquired-thinkhive\n- YC 页面：https://www.ycombinator.com/companies/rootly\n- 融资/员工估算：https://dealroom.co/companies/rootly/ ；https://tracxn.com/d/companies/rootly/\n- 口径：私有公司财务未披露；员工数/估值为第三方；◐ 表示待核。' },
      { id: 'harnessio', name: 'Harness', def: '交付与运维一体：CI/CD 平台把 AI SRE 与混沌工程接进发布链路。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2017 / 旧金山 | 官网/ Fortune |\n| 上市地 / 代码 | 未上市 | 不适用 |\n| 最新财年营收 | 2025 ARR >$2.5 亿（+50%+） | 融资报道/公司口径 |\n| 盈利 | 未披露 | — |\n| 现金流 | 未披露 | — |\n| 客户 | 未披露总数；Experian、Twilio、Ulta Beauty 等 | 第三方/案例 |\n| 员工 | 1,000+ 人（2025 预计） | ◐ |\n| 市值 / 估值 | $55 亿（2025-12 Series E） | Goldman Sachs 领投 |\n| 主要股东 | Goldman Sachs、IVP、Menlo Ventures、Unusual Ventures 等 | ◐ |\n| 数据截至 | 融资 2025-12；经营 2026 | — |\n\n## 定位与沿革\n\nAI DevOps / 自治软件交付平台：把 CI、CD、Feature Flags、混沌工程、云成本与 AI SRE 收进一个平台，主张「交付与运维同一数据面」，把可靠性左移到发布阶段。\n\n- 2017 年由 Jyoti Bansal（AppDynamics 创始人，2017 年以 $37 亿卖给 Cisco）与 Sanjay Nagaraj 在旧金山创立。\n- 2021 年完成 $2.25 亿 Series D，估值 $37 亿；此后经历科技估值回调。\n- 2025-02 把 Traceable（API 安全）并入 Harness，补齐安全能力；Bansal 同时管理两家公司。\n- 2025-12 完成 $2.4 亿 Series E：$2 亿 primary + $4,000 万老股 tender，Goldman Sachs 领投，估值 $55 亿。\n- 2025 年 ARR 超过 $2.5 亿、同比增长 50%+；2026 年入选 Fortune「美国最具创新力公司」第 24 名。\n- 产品线覆盖 CI/CD、Feature Flags、Chaos Engineering、Cloud Cost、AI SRE、API 安全（Traceable）。\n\n## 创始人与管理层\n\n- **Jyoti Bansal（创始人 & CEO）**：AppDynamics 创始人，2017 年以 $37 亿出售给 Cisco；同时创办 Traceable、Unusual Ventures、Big Bang Labs。\n- **Sanjay Nagaraj（联合创始人 & SVP Engineering）**：负责全球工程组织；同时任 Traceable CTO；部分资料列 Rishi Singh 为联合创始人（◐ 口径不一）。\n- 高管团队：CFO/CRO/CPO 名单待采集。\n- 董事会：Goldman Sachs、IVP、Menlo Ventures 等投资方席位待核。\n- 关键人事变动：2025 年 Traceable 并入后的组织整合；2026 年 IPO 准备传闻待核。\n\n## 商业模式\n\n- **收入结构**：模块化 SaaS 订阅；按开发者、服务、部署或用量计价。\n- **销售动作**：企业销售驱动，以「替代 Jenkins/自建工具链」获客；land-and-expand 从 CI/CD 扩展到 chaos、成本、安全与 AI SRE。\n- **单位经济**：ARR >$2.5 亿、+50% 增长；估值 $55 亿对应约 22x ARR；毛利率预计 70–80%（◐）。\n- **收入质量**：企业客户为主，合同按年；模块交叉销售是增长引擎。\n- **定价趋势**：从「按开发者/服务」向「按用量 + AI agent」扩展。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| Continuous Integration | 云端 CI、构建缓存 | 按开发者/用量 | 主力 |\n| Continuous Delivery | 部署编排、GitOps、审批 | 按服务/部署 | 主力 |\n| Feature Flags | 发布控制、实验 | 按用户/用量 | 增长 |\n| Chaos Engineering | 故障注入、韧性验证 | 按实验/服务 | 增长 |\n| Cloud Cost Management | 云成本可见性与优化 | 按云支出 | 增长 |\n| AI SRE | 部署风险、事件调查、自动修复 | 按 agent/事件 | 试验/增长 |\n| Traceable API Security | API 发现、防护、攻击面 | 按 API/用量 | 增长（2025 并入） |\n\n- 包装：模块可单买，平台捆绑折扣；企业版含治理、审计、权限。\n- 路线图：AI agent 贯穿「构建 → 发布 → 运行」、自治 SDLC、安全左移。\n\n## 技术栈与壁垒\n\n- **架构**：SaaS 交付平台；CI 构建、CD 部署、Feature Flags、Chaos、成本与安全模块共享数据面。\n- **AI 路线**：AI 用于失败构建分析、部署风险、事件调查与自动修复；2025 年把 GenAI 引入混沌工程测试。\n- **壁垒**：模块广度、企业交付流程嵌入、与云厂商/ Kubernetes 生态集成、Bansal 的创业者品牌。\n- **依赖与债务**：模块过多导致复杂度；与 GitLab/GitHub 的平台竞争；Traceable 整合风险。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| Experian | CI/CD 与发布治理 | 未披露具体数字 | 第三方用户统计 |\n| Twilio | 软件交付与可靠性 | 未披露具体数字 | 第三方用户统计 |\n| Ulta Beauty | 云成本与交付效率 | 未披露具体数字 | 第三方用户统计 |\n| Fortune 100 企业 | 自治 SDLC、混沌工程 | 未披露具体数字 | 官网案例 |\n\n- 客户结构：大型企业、金融、零售、科技；北美为主，全球扩张。\n- 集中度：未披露；企业客户合同较大。\n- 续约/流失：NRR 未披露；模块交叉销售是扩张核心。\n- 说明：公开命名的量化案例较少，具体效果待采集。\n\n## 商业进展\n\n- 2025-02 Traceable 并入 Harness，补齐 API 安全；Bansal 同时管理两家公司。\n- 2025-12 $2.4 亿 Series E，Goldman Sachs 领投，估值 $55 亿；含 $4,000 万老股 tender，给长期员工流动性。\n- 2025 年 ARR >$2.5 亿、+50% 增长；2026 年 Fortune 最具创新力公司第 24 名。\n- 2026-05 产品更新：60+ 新功能，围绕 AI-native 开发、交付与安全。\n- IPO：Bansal 公开谈论 IPO 计划，时间表待核；Goldman 领投被视为 IPO 准备信号。\n\n## 经营业绩\n\n| 指标 | 2021 | 2023 | 2025 | 说明 |\n|---|---|---|---|---|\n| 营收/ARR | 未披露 | 未披露 | >$2.5 亿 ARR | +50%+ YoY |\n| 增速 | 高增长 | 高增长 | 50%+ | 2025 口径 |\n| 毛利率 | 未披露 | 未披露 | 70–80%（估算） | ◐ |\n| 营业利润 | 未披露 | 未披露 | 未披露 | — |\n| FCF | 未披露 | 未披露 | 未披露 | — |\n\n- 运营指标：客户数、NRR、模块渗透率未披露；1,000+ 员工（◐）。\n- 估值：$55 亿（2025-12），对应约 22x ARR。\n- 指引：不适用（私有公司）。\n\n## 股权、融资与股票\n\n- **不适用（未上市）**：无股票代码与二级市场市值。\n- 最新估值：$55 亿（2025-12 Series E）。\n- 最新融资：$2.4 亿（$2 亿 primary + $4,000 万 tender），Goldman Sachs 领投。\n- 历史融资：2021 年 $2.25 亿 Series D，估值 $37 亿；累计融资待核。\n- 投资方：Goldman Sachs、IVP、Menlo Ventures、Unusual Ventures 等。\n- 流动性：老股 tender 提供部分流动性；IPO 是主要退出路径。\n\n## 团队与人员\n\n- 员工 1,000+ 人（2025 预计；◐）；全球分布，旧金山与纽约为主要办公室。\n- 研发占比高；Traceable 并入后安全团队扩张。\n- 招聘：2025–2026 年随 AI 与安全扩张；具体岗位待采集。\n- 薪酬/股权激励：RSU/期权；2025 年 tender 给长期员工流动性。\n- 组织：CEO Jyoti Bansal；SVP Engineering Sanjay Nagaraj；Traceable 团队整合中。\n\n## 竞争格局\n\n- 直接竞品：GitLab、GitHub Actions、Jenkins/CloudBees、CircleCI、Argo CD、Spinnaker。\n- AI SRE 竞品：PagerDuty、Datadog、Rootly、Resolve AI。\n- 安全竞品：Traceable 对 Checkmarx、Snyk、Salt Security 等。\n- 差异：模块广度 + 交付/运维/安全一体；弱点：复杂度、与 GitLab/GitHub 的平台竞争、AI SRE 产品尚早。\n- 份额：DevOps 平台市场份额低于 GitLab/GitHub，但在企业 CI/CD 与混沌工程细分领先（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：高估值对增长敏感、模块过多导致聚焦不足、与 GitLab/GitHub 的价格战。\n- 技术：平台事故、AI 自动修复误判、Traceable 整合风险。\n- 法律/监管：API 安全与数据隐私、开源许可证；待补诉讼。\n- 治理：创始人同时管理多家公司；IPO 时间表与市场窗口。\n- 争议：$55 亿估值对应 22x ARR，高于多数 DevOps 同行（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：ARR 结构、客户数、AI SRE 收入、IPO 进展均未入库。建议跟踪：① ARR 能否维持 50% 增长；② AI SRE/Chaos 的付费渗透；③ Traceable 整合与安全收入；④ IPO 时间表；⑤ 与 GitLab/GitHub 的竞争。\n\n## 信源与口径\n\n- Series E 与估值：https://finance.yahoo.com/news/harness-hits-5-5b-valuation-103000855.html\n- CNBC：https://www.cnbc.com/2025/12/11/harness-is-worth-5point5-billion-in-round-led-by-goldman-sachs.html\n- 公司与创始人：https://www.harness.io/company/about-us\n- Fortune 2026：https://www.harness.io/press-and-news/harness-named-to-fortunes-2026-americas-most-innovative-companies-list\n- 客户名单：https://www.usedby.ai/tools/harness\n- 口径：ARR/估值为公司/媒体口径；员工数为预计；◐ 表示待核。' },
      { id: 'jiaweilanjing', name: '嘉为蓝鲸', def: '国内 Agentic Ops 一体化：蓝鲸 PaaS + 运维大模型 + A2A 多智能体协同。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2001 / 广州（嘉为科技） | 官网/百度百科 |\n| 上市地 / 代码 | 未上市 | 不适用 |\n| 最新财年营收 | 2025 年营收同比 +11%，回款 +24%（绝对值未披露） | 公司 2026-01 披露 |\n| 盈利 | 未披露 | — |\n| 现金流 | 未披露 | — |\n| 客户 | 累计 >1,000 家政企；金融、能源、运营商、政务、交通、制造 | 公司口径 |\n| 员工 | 未披露 | — |\n| 市值 / 估值 | 未披露；2023-07 C 轮超 2 亿元 | 钟鼎资本领投 |\n| 主要股东 | 钟鼎资本等 C 轮投资方 | ◐ 待核完整股东 |\n| 数据截至 | 融资 2023-07；经营 2025 年度 | — |\n\n## 定位与沿革\n\n嘉为科技旗下的数字研运品牌：以腾讯蓝鲸 PaaS 为底座，把 DevOps、AIOps、ITSM、CMDB、自动化与可观测整合成一体化平台，再用「鲸智」运维大模型与 AIDev 智能体开发平台做 Agentic Ops。\n\n- 嘉为科技成立于 2001 年，总部广州，早期以 IT 服务与腾讯蓝鲸生态交付起家，后产品化为「嘉为蓝鲸」品牌。\n- 产品族：鲸眼（全栈可观测）、鲸舟（自动化/流程/ITSM）、鲸智（AIOps 与运维大模型）、AIDev 智能体开发平台、WeOps 订阅制运维。\n- 2023-07 完成超 2 亿元 C 轮融资，钟鼎资本领投；此后无公开新融资。\n- 2025 年营收同比 +11%、回款 +24%，公司强调「控本提效 + 规模扩张」。\n- 2026-10 发布 AIDev 智能体开发平台 V2.3，主打 AI 原生研发、岗位化执行、零代码配置、知识运营闭环与身份安全代理。\n- 累计服务 >1,000 家政企客户；ITSM 有平替 ServiceNow 的全量切换案例；某集团 DevOps 案例接入 80+ 系统、托管约 2 亿行代码、3.6 万次自动化部署、效率提升 10 倍。\n\n## 创始人与管理层\n\n- 嘉为科技创始团队：姓名与履历待核；公司自 2001 年经营 IT 服务，管理层具备大型政企交付背景。\n- **鲸智/AIDev 产品线**：由嘉为蓝鲸 AI 研发团队负责；具体负责人待采集。\n- 核心高管：CEO/CTO/CFO 名单待补；C 轮投资方钟鼎资本是否进入董事会待核。\n- 组织：广州总部，北京/上海/深圳等地设分支机构（◐ 待核）。\n- 关键人事变动：2023–2026 年待采集。\n\n## 商业模式\n\n- **收入结构**：项目制交付 + 平台订阅 + WeOps 订阅制运维；软件、服务与运维人力混合。\n- **销售动作**：大客户销售 + 蓝鲸生态渠道；面向政企、金融、能源、运营商的 IT 运维/研发部门。\n- **单位经济**：私有公司不披露；项目制毛利率低于纯 SaaS，但客单价高、粘性强。\n- **收入质量**：>1,000 家客户、大型政企为主；收入可能集中于头部项目（◐）。\n- **定价趋势**：从「项目制」向「平台订阅 + 运维订阅」迁移，AIDev 可能按智能体/席位计价。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 鲸眼 | 全栈可观测、APM、日志、链路 | 项目/订阅 | 主力 |\n| 鲸舟 | 自动化、流程、ITSM、CMDB | 项目/订阅 | 主力 |\n| 鲸智 | AIOps、运维大模型、根因分析 | 项目/订阅 | 增长 |\n| AIDev | 智能体开发平台、A2A 协同 | 按平台/智能体 | 增长 |\n| WeOps | 订阅制一体化运维 | 按年订阅 | 增长 |\n| DevOps 平台 | 研发效能、CI/CD、代码托管 | 项目/订阅 | 主力 |\n\n- 包装：一体化平台 + 模块选配；政企项目常含实施、迁移与运维服务。\n- 路线图：A2A 多智能体协同、运维大模型、AI 原生研发、信创适配。\n\n## 技术栈与壁垒\n\n- **架构**：基于腾讯蓝鲸 PaaS（CMDB、作业平台、流程引擎、配置平台），私有化/混合部署为主。\n- **AI 路线**：鲸智运维大模型 + AIDev 智能体平台；宣称 60+ 模型赋能运维全生命周期；A2A 支持多智能体协同。\n- **壁垒**：大型政企流程与权限整合、蓝鲸生态、ITSM/CMDB 数据积累、信创合规与本地服务。\n- **依赖与债务**：对腾讯蓝鲸生态的依赖；项目制交付的规模化瓶颈；大模型能力的差异化待验证。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 某大型集团 | DevOps 一体化 | 80+ 系统、约 2 亿行代码、3.6 万次自动化部署、效率 10 倍 | 公司案例 |\n| 某大型企业 | ITSM 平替 ServiceNow | 全量切换如期落地 | 公司案例 |\n| 三大央国企 | AIOps/数智化转型 | 未披露具体数字 | 2025-07 报道 |\n| 金融/能源/运营商客户 | 全栈可观测、智能运维 | 未披露具体数字 | 行业口径 |\n\n- 客户结构：政务、金融、能源、运营商、交通、制造、医疗；累计 >1,000 家。\n- 集中度：未披露；大型项目占比可能较高（◐）。\n- 续约/流失：未披露；政企客户粘性强、替换成本高。\n\n## 商业进展\n\n- 2023-07 超 2 亿元 C 轮，钟鼎资本领投；此后无公开融资。\n- 2025 年营收 +11%、回款 +24%；在 IT 预算收紧环境下保持正增长。\n- 2026-10 AIDev V2.3 发布；2026-06 亮相安徽数智峰会，主打制造业 AI 研发运维。\n- ITSM 平替 ServiceNow 案例成为国产替代标杆；信创全栈可观测中心是重点方案。\n- 生态：腾讯蓝鲸、信创厂商、区域 SI；具体合作待采集。\n\n## 经营业绩\n\n| 指标 | 2023 | 2024 | 2025 | 说明 |\n|---|---|---|---|---|\n| 营收 | 未披露 | 未披露 | 同比 +11% | 绝对值未披露 |\n| 增速 | 未披露 | 未披露 | +11% | 回款 +24% |\n| 毛利率 | 未披露 | 未披露 | 未披露 | 项目制为主 |\n| 营业利润 | 未披露 | 未披露 | 未披露 | — |\n| FCF | 未披露 | 未披露 | 未披露 | — |\n\n- 运营指标：客户 >1,000 家；员工数、ARR、续约率未披露。\n- 融资：2023-07 C 轮超 2 亿元；估值未披露。\n- 指引：不适用（私有公司）。\n\n## 股权、融资与股票\n\n- **不适用（未上市）**：无股票代码与二级市场市值。\n- 最新融资：2023-07 C 轮超 2 亿元，钟鼎资本领投；估值未披露。\n- 历史融资：A/B 轮信息待采集；累计融资待核。\n- 股东：创始团队、钟鼎资本等；具体持股待核。\n- 流动性：无公开市场；未来可能 IPO、并购或老股交易。\n- 资本动作：C 轮后无公开新融资；是否启动 D 轮待采集。\n\n## 团队与人员\n\n- 员工人数未披露；公司自 2001 年经营，服务团队规模较大（◐）。\n- 研发/交付/服务结构待补；广州总部，区域分支机构待核。\n- 招聘：2026 年 AI/AIDev 岗位可能扩张；具体岗位待采集。\n- 薪酬/股权激励：未披露；项目制交付团队以固定薪酬 + 项目奖金为主（◐）。\n- 组织：创始团队 + 职业经理人；AIDev/鲸智团队为新增 AI 组织。\n\n## 竞争格局\n\n- 直接竞品：云智慧、必示科技、擎创科技、华为、新华三、ServiceNow（ITSM）。\n- 替代方案：自建蓝鲸、开源监控 + 自研流程、云厂商运维平台。\n- 差异：蓝鲸 PaaS 一体化、政企流程/权限整合、ITSM 国产替代、AIDev 智能体平台。\n- 竞争动态：华为/新华三从基础设施内嵌挤压；云智慧/必示从根因算法切入；ServiceNow 在高端 ITSM 仍有品牌优势。\n- 份额：国内 AIOps/ITSM 市场分散，嘉为在蓝鲸生态与政企一体化细分领先（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：项目制交付规模化难、客户集中、IT 预算收紧；C 轮后增长依赖 AI 新品。\n- 技术：运维大模型效果与幻觉、A2A 协同落地、信创适配成本。\n- 法律/监管：政企数据安全、等保合规、信创目录；待补诉讼。\n- 治理：创始团队与投资方关系、区域分支机构管理。\n- 争议：AIDev/鲸智的实际客户案例与效果数据较少，需第三方验证（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：营收绝对值、员工数、客户名单、AIDev 落地案例均未入库。建议跟踪：① AIDev/鲸智的付费客户与续约；② 2026 年营收增速；③ ITSM 平替 ServiceNow 的复制性；④ 与华为/新华三的政企竞争；⑤ 是否启动新融资。\n\n## 信源与口径\n\n- 官网：https://www.canway.net/\n- 百度百科：https://baike.baidu.com/item/%E5%98%89%E4%B8%BA%E8%93%9D%E9%B2%B8/67707181\n- C 轮融资：https://zhuanlan.zhihu.com/p/646355892\n- AIDev V2.3：https://blog.csdn.net/weixin_42556618/article/details/168135881\n- 客户案例：https://www.canway.net/others_case/2438.html ；https://ex.chinadaily.com.cn/exchange/partners/82/rss/channel/cn/columns/snl9a7/stories/WS68808df8a310028a84abf512.html\n- 口径：营收增速为公司口径；融资/估值为公开报道；◐ 表示待核。' },
      { id: 'flashcat', name: '快猫星云', def: '开源可观测 + 调查型 Agent：夜莺 Nightingale 的社区底座。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2021-10 / 北京 | 工商信息 |\n| 上市地 / 代码 | 未上市 | 不适用 |\n| 最新财年营收 | 未披露 | — |\n| 盈利 | 未披露 | — |\n| 现金流 | 未披露 | — |\n| 客户 | 未披露总数；宏地科技等案例 | 官网客户页 |\n| 员工 | 约 27 人（参保口径） | 爱企查（◐） |\n| 市值 / 估值 | 未披露；2021-10 天使轮 | 高瓴创投、初心资本 |\n| 主要股东 | 来炜 30.87%、秦晓辉 11.08%、章文嵩 9.13%、初心资本等 | 工商信息 |\n| 数据截至 | 工商 2026；融资 2021-10 | — |\n\n## 定位与沿革\n\n由 Nightingale（夜莺监控）核心团队创立，走「开源可观测 + 商业告警响应」路线：夜莺在 Prometheus 生态中提供统一告警、分发与可视化，商业侧用 Flashcat 专业版与 FlashDuty 做告警响应、协同与调查型 Agent。\n\n- 2021-10 成立于北京，天使轮由高瓴创投、初心资本投资，金额未披露。\n- 开源项目：Nightingale（夜莺）监控与告警、Categraf 采集器；夜莺源自滴滴开源，现由社区维护（◐ 治理归属待核）。\n- 商业产品：Flashcat 专业版（夜莺企业增强）、FlashDuty（SaaS 故障响应平台）。\n- 2024 年夜莺 v6.7 推送部分商业版功能，开源与商业边界持续调整。\n- 2026 年主推调查型 Agent、协同控制台、自动化护栏；客户案例包括宏地科技（7 大业务系统、多数据源监控中台）。\n\n## 创始人与管理层\n\n- **来炜（大股东，30.87%）**：CEO/创始人（◐ 角色待核）；此前经历待补。\n- **秦晓辉（11.08%）**：夜莺 Nightingale 项目作者、CTO；技术社区影响力强，常以夜莺作者身份发布技术内容。\n- **章文嵩（9.13%）**：知名技术人，曾任滴滴出行高级副总裁；在公司中的角色可能是顾问/股东（◐）。\n- 其他股东：北京快猫星云科技发展合伙企业（15.83%）、华明（13.46%）等。\n- 董事会与管理层：待补；2021 年后无公开融资，团队规模保持精简。\n\n## 商业模式\n\n- **收入结构**：开源免费 + Flashcat 专业版订阅 + FlashDuty SaaS 订阅 + 私有化交付。\n- **销售动作**：开源社区获客，商业版转化；中小企业自助 + 大型企业私有化。\n- **单位经济**：私有公司不披露；小团队（约 27 人）控制成本，毛利率预计较高（◐）。\n- **收入质量**：开源用户基数大、付费转化率未知；收入规模可能较小。\n- **定价趋势**：按节点/数据量订阅；FlashDuty 按用户/事件计价；调查型 Agent 可能按事件/agent 加购。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| Nightingale（夜莺） | 开源监控、告警、可视化 | 免费 | 主力 |\n| Categraf | 统一采集器 | 免费 | 主力 |\n| Flashcat 专业版 | 夜莺企业增强、集群管理 | 按节点/订阅 | 主力 |\n| FlashDuty | 告警响应、协同、值班 | SaaS 订阅 | 增长 |\n| 调查型 Agent | 告警调查、根因建议、自动化护栏 | 按事件/agent | 试验/增长 |\n\n- 包装：开源底座 + 商业增强；FlashDuty 独立 SaaS。\n- 路线图：调查型 Agent、协同控制台、自动化护栏、AI 可观测。\n\n## 技术栈与壁垒\n\n- **架构**：Prometheus 兼容的时序监控与告警；Categraf 统一采集；夜莺做告警规则、分发与可视化。\n- **AI 路线**：调查型 Agent 把告警、指标、日志与变更关联，给出根因建议；强调可解释与自动化护栏。\n- **壁垒**：夜莺开源社区、Prometheus 生态、告警规则与运维知识积累、小团队迭代速度。\n- **依赖与债务**：开源商业化难度、与大厂监控免费层竞争、Agent 效果待验证。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 宏地科技 | 跨平台监控中台，7 大业务系统 | 多数据源、标签降级兼容、语义化告警 | 官网案例 |\n| Prometheus 生态用户 | 自建监控与告警 | 未披露具体数字 | 社区 |\n| 中小企业 | FlashDuty 告警响应 | 未披露具体数字 | 官网 |\n\n- 客户结构：Prometheus 生态用户、中小企业、自建监控团队；大型企业以私有化为主。\n- 集中度：未披露；客户数量可能较多但客单价低。\n- 续约/流失：未披露；开源用户转化是核心变量。\n\n## 商业进展\n\n- 2021-10 天使轮（高瓴创投、初心资本），此后无公开融资。\n- 2024 年夜莺 v6.7 推送部分商业版功能，开源与商业边界调整引发社区讨论。\n- 2026 年主推调查型 Agent、协同控制台、自动化护栏；官网客户案例更新。\n- 生态：Prometheus/Grafana 社区、云厂商、系统集成商；具体合作待采集。\n- 竞争：观测云、Grafana 生态、云厂商监控、嘉为蓝鲸。\n\n## 经营业绩\n\n| 指标 | 2021 | 2024 | 2026 | 说明 |\n|---|---|---|---|---|\n| 营收 | 未披露 | 未披露 | 未披露 | 私有公司 |\n| 增速 | — | 未披露 | 未披露 | — |\n| 毛利率 | 未披露 | 未披露 | 未披露 | 开源+订阅 |\n| 营业利润 | 未披露 | 未披露 | 未披露 | — |\n| FCF | 未披露 | 未披露 | 未披露 | — |\n\n- 运营指标：员工约 27 人；夜莺社区规模、付费客户数未披露。\n- 融资：2021-10 天使轮，金额未披露；估值未披露。\n- 指引：不适用（私有公司）。\n\n## 股权、融资与股票\n\n- **不适用（未上市）**：无股票代码与二级市场市值。\n- 最新融资：2021-10 天使轮，高瓴创投、初心资本；金额未披露。\n- 股权结构（工商）：来炜 30.87%、北京快猫星云科技发展合伙企业 15.83%、华明 13.46%、秦晓辉 11.08%、章文嵩 9.13%、初心资本关联主体 6.77%、巍赛有限公司等。\n- 估值：未披露；无公开新一轮融资。\n- 流动性：无公开市场；未来可能被并购或继续独立发展。\n\n## 团队与人员\n\n- 员工约 27 人（参保口径；◐）；小团队、技术驱动。\n- 研发占比高；核心成员来自滴滴、开源社区与云厂商（◐）。\n- 招聘：2026 年 AI/Agent 岗位可能扩张；具体岗位待采集。\n- 薪酬/股权激励：早期公司以期权为主；流失率未披露。\n- 组织：来炜（CEO/大股东）、秦晓辉（CTO/夜莺作者）、章文嵩（顾问/股东）。\n\n## 竞争格局\n\n- 直接竞品：观测云、Grafana 生态、Prometheus 托管服务、云厂商监控（ARMS、腾讯云可观测）、嘉为蓝鲸。\n- 替代方案：自建 Prometheus + Alertmanager、Zabbix、ELK。\n- 差异：夜莺开源社区、告警治理、轻量部署、FlashDuty 响应；弱点：规模小、品牌弱、商业化有限。\n- 竞争动态：云厂商监控免费化挤压；开源商业化需平衡社区与付费。\n- 份额：国内开源监控细分有影响力，整体市场份额小（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：小团队、融资少、商业化不确定；开源用户付费转化低。\n- 技术：Agent 效果与幻觉、告警数据规模、社区版本与商业版边界。\n- 法律/监管：开源许可证、数据隐私；待补诉讼。\n- 治理：股权分散、创始人角色；社区治理与公司治理的平衡。\n- 争议：夜莺 v6.7 商业功能回流的社区讨论（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：营收、付费客户数、融资估值、Agent 落地均未入库。建议跟踪：① 夜莺社区规模与商业转化；② 调查型 Agent 的付费采用；③ 是否启动新融资；④ 与观测云/云厂商监控的竞争；⑤ 开源许可证与治理变化。\n\n## 信源与口径\n\n- 官网：https://flashcat.cloud/\n- 夜莺专题：https://flashcat.cloud/topic/nightingale/\n- 客户案例：https://flashcat.cloud/customers/\n- 工商/股权：https://www.qcc.com/firm/17d98d76fd1b86c6e5cd2b897336cd08.html ；https://aiqicha.baidu.com/company_detail_93026772371589\n- 融资：https://pitchhub.36kr.com/project/1958585858298885\n- 口径：员工数为参保口径；融资/估值未披露；◐ 表示待核。' },
      { id: 'guance', name: '观测云', def: '一体化可观测：DataKit 采集 + 全栈数据，向智能体可观测延伸。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2013（驻云科技）/ 上海 | 百度百科/官网 |\n| 上市地 / 代码 | 未上市 | 不适用 |\n| 最新财年营收 | 2023 约 ¥3,000 万；2024 预计翻倍（◐） | 媒体专访 |\n| 盈利 | 未披露 | — |\n| 现金流 | 未披露 | — |\n| 客户 | 未披露总数；数字原生、互联网、电商、零售 | 媒体口径 |\n| 员工 | 未披露 | — |\n| 市值 / 估值 | 未披露；2022-01 融资 2 亿元，准独角兽 | 华创资本 |\n| 主要股东 | 华创资本等 | ◐ 待核完整股东 |\n| 数据截至 | 融资 2022-01；经营 2024–2026 | — |\n\n## 定位与沿革\n\n国内一体化可观测平台：以 DataKit 采集器统一指标、日志、追踪、RUM 与安全数据，提供 SaaS 与私有化部署；2025–2026 年把「AI/智能体可观测」作为新增场景，推出 Guance Agent Teams 与 AgentMeter。\n\n- 母公司上海驻云信息科技成立于 2013 年，创始人/CEO 蒋烁淼；早期以阿里云 MSP/云服务起家，后转型产品化，推出「观测云」品牌。\n- 2022-01 完成 2 亿元新一轮融资，华创资本等参与，被称为可观测领域「准独角兽」；估值未披露。\n- 2023 年营收约 ¥3,000 万，2024 年预计翻倍（◐）；此后未披露新财务数据。\n- 2025 年发布 GuanceDB 3.0 与 AI 功能；2026-01 公布产品路线图，覆盖测试、业务、数据分析与 SRE 场景。\n- 2026 年主推 Guance Agent Teams（企业级可观测 AI 智能体团队）与 AgentMeter（AI 用量统计与调用链路采集）。\n- AWS 中国区 APN 合作伙伴，可通过 AWS Marketplace 开通。\n\n## 创始人与管理层\n\n- **蒋烁淼（创始人 & CEO）**：1983 年生，云计算连续创业者，2013 年创办驻云科技；曾被称作「云计算的试飞员」，担任阿里云顾问（◐ 头衔待核）。\n- 核心团队：来自阿里云、云厂商与可观测社区；具体名单待采集。\n- 董事会：华创资本等投资方席位待核。\n- 关键人事变动：2022 年融资后是否有高管调整待采集。\n\n## 商业模式\n\n- **收入结构**：SaaS 订阅 + 私有化交付 + 咨询/服务；按数据量、节点、用户或功能模块计价。\n- **销售动作**：自助试用 + 企业销售；AWS Marketplace/云市场获客；面向数字原生、互联网、电商、零售。\n- **单位经济**：私有公司不披露；2023 年营收约 ¥3,000 万，规模仍小；毛利率预计 60–75%（◐）。\n- **收入质量**：SaaS + 项目制混合；客户数以中小为主，大客户贡献待核。\n- **定价趋势**：免费版/商业版/企业版 + 按量计费；咨询 ¥6,000/天；Agent 功能可能按 agent/用量计价。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| Guance 可观测平台 | 指标、日志、追踪、RUM、安全 | 按量/订阅 | 主力 |\n| DataKit | 统一采集器 | 随平台 | 主力 |\n| GuanceDB | 时序/事件存储与查询 | 随平台 | 主力 |\n| Agent Teams | 企业级可观测 AI 智能体团队 | 按 agent/用量 | 试验/增长 |\n| AgentMeter | AI 用量统计与调用链路采集 | 按用量 | 试验 |\n| 咨询/服务 | 可观测体系咨询、迁移 | ¥6,000/天 | 增长 |\n\n- 包装：免费版 → 商业版 → 企业版；私有化另计。\n- 路线图：智能体可观测、SRE 场景、测试与业务分析。\n\n## 技术栈与壁垒\n\n- **架构**：DataKit 统一采集 + GuanceDB 存储计算分离；SaaS/私有化双形态。\n- **AI 路线**：Agent Teams 把 APM/日志/追踪/RUM 上下文交给 agent 做根因分析与审批式动作；AgentMeter 观测 AI 调用与成本。\n- **壁垒**：采集器统一、国产化部署、云市场渠道、价格透明；技术壁垒中等。\n- **依赖与债务**：与阿里云/腾讯云/华为云监控竞争；规模小、研发投入有限；Agent 效果待验证。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 数字原生/互联网企业 | 全栈可观测、APM | 未披露具体数字 | 媒体/官网 |\n| 电商/零售客户 | 大促稳定性、业务观测 | 未披露具体数字 | 媒体 |\n| AWS Marketplace 客户 | 云上可观测开通 | 未披露具体数字 | 官网 |\n\n- 客户结构：数字原生、互联网、电商、零售；中小客户为主，大客户待采集。\n- 集中度：未披露；2023 年营收约 ¥3,000 万，客户数可能较多但客单价低。\n- 续约/流失：未披露；SaaS 自助客户流失率可能较高（◐）。\n\n## 商业进展\n\n- 2022-01 完成 2 亿元融资，华创资本等参与；此后无公开新融资。\n- 2025 年发布 GuanceDB 3.0 与 AI 功能；2026-01 公布产品路线图。\n- 2026 年主推 Agent Teams、AgentMeter，切入智能体可观测与 AI 成本治理。\n- AWS 中国区 APN 合作、AWS Marketplace 开通；云市场是重要获客渠道。\n- 竞争：阿里云 ARMS、腾讯云可观测、华为云 AOM、夜莺、博睿数据。\n\n## 经营业绩\n\n| 指标 | 2022 | 2023 | 2024 | 说明 |\n|---|---|---|---|---|\n| 营收 | 未披露 | 约 ¥3,000 万 | 预计翻倍（约 ¥6,000 万） | 媒体口径（◐） |\n| 增速 | — | 未披露 | 约 +100% | 预计 |\n| 毛利率 | 未披露 | 未披露 | 未披露 | SaaS+项目 |\n| 营业利润 | 未披露 | 未披露 | 未披露 | — |\n| FCF | 未披露 | 未披露 | 未披露 | — |\n\n- 运营指标：客户数、ARR、续约率未披露；2022 年管理对象目标 5 万（历史口径）。\n- 融资：2022-01 2 亿元；估值未披露。\n- 指引：不适用（私有公司）。\n\n## 股权、融资与股票\n\n- **不适用（未上市）**：无股票代码与二级市场市值。\n- 最新融资：2022-01 2 亿元，华创资本等参与；估值未披露。\n- 历史融资：A/B 轮信息待采集；累计融资待核。\n- 股东：蒋烁淼、华创资本等；具体持股待核。\n- 流动性：无公开市场；未来可能 IPO、并购或老股交易。\n- 资本动作：2022 年后无公开新融资；是否启动新一轮待采集。\n\n## 团队与人员\n\n- 员工人数未披露；研发/销售/服务结构待补。\n- 总部上海，AWS/云厂商生态团队；具体分布待核。\n- 招聘：2026 年 Agent/AI 可观测岗位可能扩张；官网招聘页有研发岗位。\n- 薪酬/股权激励：未披露；早期公司以期权为主（◐）。\n- 组织：创始人蒋烁淼任 CEO；核心高管名单待补。\n\n## 竞争格局\n\n- 直接竞品：阿里云 ARMS、腾讯云可观测、华为云 AOM、Datadog（海外）、博睿数据、夜莺。\n- 替代方案：自建 Prometheus/Grafana/Loki、ELK、云厂商原生监控。\n- 差异：DataKit 统一采集、价格透明、国产化/私有化、AWS 生态；弱点：规模小、品牌弱、云厂商捆绑。\n- 竞争动态：云厂商把可观测作为云服务捆绑，独立厂商需靠多云/私有化与价格差异化。\n- 份额：国内独立可观测市场份额较小（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：营收规模小、增长依赖融资、云厂商竞争；2022 年后无新融资。\n- 技术：Agent 效果、数据规模、私有化运维成本。\n- 法律/监管：数据跨境、隐私合规；待补诉讼。\n- 治理：创始人控制权、投资方退出压力。\n- 争议：2023 年营收与「准独角兽」估值是否匹配，缺乏后续融资验证（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：2025–2026 营收、客户数、融资估值、Agent Teams 落地均未入库。建议跟踪：① Agent Teams/AgentMeter 的付费客户；② 营收是否延续翻倍；③ 是否启动新融资；④ 与云厂商监控的竞合；⑤ 私有化/信创订单。\n\n## 信源与口径\n\n- 官网：https://www.guance.com/\n- 2026 路线图：https://www.guance.com/learn/articles/article-197\n- 创始人专访：https://www.guance.com/learn/articles/article-179 ；https://baike.baidu.com/item/%E8%92%8B%E7%83%81%E6%B7%BC/20592353\n- 融资：https://www.huacapital.com/news_detail_36.html\n- 营收：https://www.600895.com/index/news/detail.html?type=active&id=223\n- 口径：营收为媒体口径；估值未披露；◐ 表示待核。' },
      { id: 'qingchuang', name: '擎创科技', def: '首批国产 AIOps：夏洛克平台以日志聚类与根因推荐立足金融能源。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2016（◐）/ 上海 | 官网/融资报道 |\n| 上市地 / 代码 | 未上市 | 不适用 |\n| 最新财年营收 | 未披露 | — |\n| 盈利 | 未披露 | — |\n| 现金流 | 未披露 | — |\n| 客户 | 未披露总数；银行、保险、能源为主 | 创始人项目背景/官网 |\n| 员工 | 未披露 | — |\n| 市值 / 估值 | 未披露；Pre-A 数百万美元、A 轮数千万人民币 | 融资报道 |\n| 主要股东 | 火山石投资、元璟资本、晨晖创投、原子创投 | 融资报道 |\n| 数据截至 | 融资 A 轮；经营 2026 | — |\n\n## 定位与沿革\n\n国内较早的 AIOps 厂商之一：核心产品「夏洛克」一体化数智运维平台，主打日志聚类、异常检测、根因推荐与运维数据分析，客户集中在金融、保险、能源等强运维场景。\n\n- 2016 年前后成立于上海（◐ 待核）；创始人/CEO 杨辰，约 20 年运维软件从业经验，曾负责中国银行、农业银行、华为、广发银行、太平保险等大型客户项目。\n- Pre-A 轮数百万美元，元璟资本领投、原子创投跟投；A 轮数千万人民币，火山石投资领投，晨晖创投、元璟资本跟投。\n- 官网称连续获 Gartner 推荐；2022 年发布《夏洛克 AIOps 智慧运营平台白皮书》。\n- 2026 年仍以《老杨说运维》内容与夏洛克平台做市场教育，主题聚焦企业运维痛点与 AIOps 落地。\n- 产品线覆盖 AIOps、一体化数智运维、FinOps；私有化交付为主。\n\n## 创始人与管理层\n\n- **杨辰（创始人 & CEO）**：约 20 年运维软件从业经验；曾负责中国银行、农业银行、华为、广发银行、太平保险等大型运维项目（GOPS 2021 讲者介绍）。\n- 核心团队：来自 ITOM/AIOps 厂商与金融行业运维背景；具体名单待采集。\n- 董事会：火山石投资、元璟资本、晨晖创投等投资方席位待核。\n- 关键人事变动：A 轮后是否有高管调整待采集。\n\n## 商业模式\n\n- **收入结构**：私有化软件授权 + 项目交付 + 年度运维/订阅；以大型企业项目为主。\n- **销售动作**：企业销售 + 金融/能源行业渠道；POC 后项目制交付。\n- **单位经济**：私有公司不披露；项目制毛利率低于纯 SaaS，但客单价高、粘性强。\n- **收入质量**：金融、保险、能源大客户为主；收入可能集中于头部项目（◐）。\n- **定价趋势**：从「软件授权」向「平台订阅 + 运维服务」迁移；AI 功能可能按模块加购。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 夏洛克 AIOps | 日志聚类、异常检测、根因推荐 | 软件授权/项目 | 主力 |\n| 一体化数智运维 | 监控、CMDB、流程、自动化 | 项目/订阅 | 主力 |\n| FinOps | 云成本/资源优化 | 模块加购 | 增长 |\n| 运维数据分析 | 日志/指标关联、容量预测 | 模块加购 | 增长 |\n| AI 运维助手 | LLM 根因解释、运维问答 | 试验 | 试验 |\n\n- 包装：平台 + 模块；金融/能源行业方案。\n- 路线图：LLM 根因解释、自动化处置、FinOps 融合。\n\n## 技术栈与壁垒\n\n- **架构**：私有化部署；日志/指标/告警采集与关联；夏洛克平台做聚类、异常检测与根因推荐。\n- **AI 路线**：传统 ML（日志聚类、异常检测）+ LLM 运维助手；强调场景化算法与金融客户数据积累。\n- **壁垒**：金融/保险场景知识、根因算法、私有化交付、客户关系。\n- **依赖与债务**：大模型削弱单点算法溢价；项目制规模化难；研发投入有限。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 中国银行/农业银行/广发银行 | 大型银行运维 | 未披露具体数字 | 创始人项目背景（◐ 非公司客户确认） |\n| 太平保险 | 保险运维 | 未披露具体数字 | 创始人项目背景（◐） |\n| 华为 | 运维项目 | 未披露具体数字 | 创始人项目背景（◐） |\n| 能源/金融客户 | 夏洛克 AIOps | 未披露具体数字 | 官网案例 |\n\n- 客户结构：银行、保险、能源、政企；大型企业为主。\n- 集中度：未披露；头部金融客户占比可能较高（◐）。\n- 续约/流失：未披露；私有化项目粘性强、续约依赖运维服务。\n\n## 商业进展\n\n- Pre-A 数百万美元、A 轮数千万人民币；此后无公开新融资。\n- 2022 年发布夏洛克 AIOps 白皮书；2026 年继续通过《老杨说运维》做市场教育。\n- 产品向一体化数智运维、FinOps、LLM 运维助手延伸。\n- 客户以金融、保险、能源为主；具体新签订单待采集。\n- 竞争：云智慧、必示科技、嘉为蓝鲸、华为、新华三。\n\n## 经营业绩\n\n| 指标 | 2022 | 2024 | 2026 | 说明 |\n|---|---|---|---|---|\n| 营收 | 未披露 | 未披露 | 未披露 | 私有公司 |\n| 增速 | 未披露 | 未披露 | 未披露 | — |\n| 毛利率 | 未披露 | 未披露 | 未披露 | 项目制 |\n| 营业利润 | 未披露 | 未披露 | 未披露 | — |\n| FCF | 未披露 | 未披露 | 未披露 | — |\n\n- 运营指标：客户数、员工数、ARR 均未披露。\n- 融资：Pre-A 数百万美元 + A 轮数千万人民币；估值未披露。\n- 指引：不适用（私有公司）。\n\n## 股权、融资与股票\n\n- **不适用（未上市）**：无股票代码与二级市场市值。\n- 融资：Pre-A 数百万美元（元璟资本领投、原子创投跟投）；A 轮数千万人民币（火山石投资领投，晨晖创投、元璟资本跟投）。\n- 估值：未披露；A 轮后无公开新融资。\n- 股东：创始团队、火山石投资、元璟资本、晨晖创投、原子创投。\n- 流动性：无公开市场；未来可能 IPO、并购或老股交易。\n\n## 团队与人员\n\n- 员工人数未披露；以研发、交付与行业销售为主（◐）。\n- 研发占比、地域分布待补；上海总部，金融客户现场交付团队。\n- 招聘：2026 年 AI/LLM 岗位可能扩张；具体岗位待采集。\n- 薪酬/股权激励：未披露；项目制团队以固定薪酬 + 奖金为主（◐）。\n- 组织：创始人杨辰任 CEO；核心高管名单待补。\n\n## 竞争格局\n\n- 直接竞品：云智慧、必示科技、嘉为蓝鲸、华为、新华三、IBM Instana。\n- 替代方案：自建 ELK + 规则引擎、开源 AIOps、云厂商监控。\n- 差异：金融/保险场景知识、日志聚类与根因推荐、私有化交付；弱点：规模小、品牌弱、LLM 转型慢。\n- 竞争动态：大模型削弱单点算法溢价；平台厂商与基础设施厂商挤压独立 AIOps。\n- 份额：国内 AIOps 市场分散，擎创在金融细分有一定位置（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：项目制规模化难、客户集中、融资少；A 轮后增长依赖金融 IT 预算。\n- 技术：算法效果衰减、LLM 转型不及预期、数据安全。\n- 法律/监管：金融数据合规、等保；待补诉讼。\n- 治理：创始人依赖、投资方退出压力。\n- 争议：官网/Gartner 推荐口径需核实；客户案例多为创始人项目背景而非公司确认（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：营收、员工数、客户名单、A 轮后融资均未入库。建议跟踪：① 金融客户续约与新单；② LLM 运维助手的落地；③ 是否启动 B 轮；④ 与云智慧/必示的份额变化；⑤ FinOps 产品进展。\n\n## 信源与口径\n\n- 官网：https://www.eoitek.com/\n- 客户案例：https://www.eoitek.com/case.html\n- 发展历程：https://www.eoitek.com/about1.html\n- Pre-A 融资：https://m.cyzone.cn/article/173684\n- A 轮融资：https://www.niutoushe.com/lives/qing-chuang-ke-ji-xuan-bu-wan-shu-qian-wan-ren-min-bi-a-lun-rong-zi\n- 创始人背景：GOPS 2021 讲者介绍（bagevent）\n- 口径：客户案例多为创始人项目背景，非公司确认；◐ 表示待核。' },
      { id: 'cloudwise', name: '云智慧', def: '国内 AIOps 头部：从 APM/拨测起家，做全景运维与根因分析。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2009 / 北京 | 天眼查/官网 |\n| 上市地 / 代码 | 未上市 | 不适用 |\n| 最新财年营收 | 未披露 | — |\n| 盈利 | 未披露 | — |\n| 现金流 | 未披露 | — |\n| 客户 | 数千家（2021 口径）；金融、政府、电信、能源等 | 清华访谈/官网 |\n| 员工 | 128 人（2025 工商口径） | 天眼查 |\n| 市值 / 估值 | 约 $4.6 亿（2020-12 D3 轮） | 融资报道 |\n| 主要股东 | CPE、云晖资本、越秀产业基金、朗玛峰创投等 | 融资报道 |\n| 数据截至 | 融资 2020-12；工商 2025 | — |\n\n## 定位与沿革\n\n国内 AIOps 代表厂商：从 APM/拨测（监控宝、透视宝）起家，扩展到全景运维、根因分析与数字化运维平台（DOCP），客户以金融、政企与大型企业为主。\n\n- 2009 年由殷晋在北京创立；早期以 SaaS 监控（监控宝）获客，后推出透视宝（APM）与企业级运维平台。\n- 2020-03 完成 D+ 轮 2,400 万美元（朗玛峰创投）；2020-12 完成 D3 轮 6,000 万美元，CPE 领投，云晖资本、越秀产业基金等参与，估值约 $4.6 亿，当时为国内智能运维最大单笔融资。\n- 产品线延伸到 AIOps、ITSM、DOCP；殷晋主张从业务视角反推 IT 问题，把运维价值呈现给 CIO。\n- 2021 年口径累计服务数千家客户，覆盖政府、金融、电信、能源、交通、制造、地产、互联网。\n- 2025 年工商口径员工 128 人；营收与 IPO 进展未公开。\n\n## 创始人与管理层\n\n- **殷晋（创始人 & CEO）**：1981 年生，北京信息科技大学市场营销学士、清华大学软件学院硕士（2005）；曾在 Everbridge 任工程总监/高级开发经理；2010 年起任云智慧 CEO。\n- 联合创始人/核心高管：名单待采集；早期团队来自 APM/SaaS 与云服务背景。\n- 董事会：CPE、云晖资本、越秀产业基金等投资方席位待核。\n- 关键人事变动：2020 年融资后是否有高管调整待采集；IPO 计划未公开。\n\n## 商业模式\n\n- **收入结构**：软件订阅 + 项目交付 + 运维服务；SaaS（监控宝）与企业私有化混合。\n- **销售动作**：企业销售 + 行业渠道；金融、政府、电信为重点；POC 后项目制交付。\n- **单位经济**：私有公司不披露；项目制毛利率低于纯 SaaS；员工 128 人，人均产出待核。\n- **收入质量**：数千家客户、金融行业为主；收入可能集中于头部项目（◐）。\n- **定价趋势**：从「按节点/应用」向「平台订阅 + AIOps 模块」迁移；AI 功能可能按模块加购。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 监控宝 | SaaS 网站/基础设施监控 | 按套餐 | 主力（历史） |\n| 透视宝 | APM、应用性能监控 | 按节点/应用 | 主力 |\n| 全景运维 | 业务视角的全栈运维 | 项目/订阅 | 主力 |\n| AIOps | 告警收敛、异常检测、根因分析 | 模块/项目 | 增长 |\n| DOCP | 数字化运维平台 | 项目/订阅 | 增长 |\n| ITSM | IT 服务管理 | 项目/订阅 | 增长 |\n\n- 包装：平台 + 行业方案；金融/政府项目含实施与运维。\n- 路线图：AIOps → ITSM → 业务运维；LLM 根因解释与自动化。\n\n## 技术栈与壁垒\n\n- **架构**：SaaS + 私有化；APM 探针、日志/指标采集、告警与拓扑关联。\n- **AI 路线**：传统 ML 异常检测 + 告警收敛 + 因果推断；LLM 用于根因解释与运维问答（◐）。\n- **壁垒**：金融/政府客户关系、APM 数据积累、行业运维知识、项目交付能力。\n- **依赖与债务**：项目制规模化难；大模型削弱单点算法溢价；与云厂商监控竞争。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 银行客户 | APM、AIOps、业务运维 | 未披露具体数字 | 官网/媒体 |\n| 政府/电信客户 | 全景运维、DOCP | 未披露具体数字 | 官网 |\n| 数千家客户 | 监控宝/透视宝 | 未披露 | 2021 口径 |\n\n- 客户结构：金融（银行）为核心，政府、电信、能源、交通、制造、互联网。\n- 集中度：未披露；金融大客户占比可能较高（◐）。\n- 续约/流失：未披露；私有化项目粘性强。\n\n## 商业进展\n\n- 2020-03 D+ 轮 2,400 万美元；2020-12 D3 轮 6,000 万美元、估值约 $4.6 亿。\n- 2020 年后无公开新融资；IPO 计划未公开。\n- 产品从 APM 扩展到 AIOps、ITSM、DOCP；金融行业是主要增长来源。\n- 2025 年员工 128 人，规模精简；营收未披露。\n- 竞争：必示科技、擎创科技、嘉为蓝鲸、博睿数据、华为、新华三。\n\n## 经营业绩\n\n| 指标 | 2020 | 2023 | 2025 | 说明 |\n|---|---|---|---|---|\n| 营收 | 未披露 | 未披露 | 未披露 | 私有公司 |\n| 增速 | 未披露 | 未披露 | 未披露 | — |\n| 毛利率 | 未披露 | 未披露 | 未披露 | 项目制 |\n| 营业利润 | 未披露 | 未披露 | 未披露 | — |\n| FCF | 未披露 | 未披露 | 未披露 | — |\n\n- 运营指标：客户数千家（2021）；员工 128 人（2025）；ARR 未披露。\n- 融资：D3 轮 6,000 万美元，估值约 $4.6 亿（2020）。\n- 指引：不适用（私有公司）。\n\n## 股权、融资与股票\n\n- **不适用（未上市）**：无股票代码与二级市场市值。\n- 最新估值：约 $4.6 亿（2020-12 D3 轮）。\n- 融资：D+ 轮 2,400 万美元（2020-03，朗玛峰创投）；D3 轮 6,000 万美元（2020-12，CPE 领投，云晖资本、越秀产业基金等）。\n- 股东：创始团队、CPE、云晖资本、越秀产业基金、朗玛峰创投等。\n- 流动性：无公开市场；未来可能 IPO、并购或老股交易。\n- 资本动作：2020 年后无公开新融资；IPO 状态待采集。\n\n## 团队与人员\n\n- 员工 128 人（2025 工商口径）；以研发、交付、行业销售为主。\n- 研发占比、地域分布待补；北京总部，金融客户现场团队。\n- 招聘：2025–2026 年可能控制规模；AI 岗位待采集。\n- 薪酬/股权激励：未披露；项目制团队以固定薪酬 + 奖金为主（◐）。\n- 组织：创始人殷晋任 CEO；核心高管名单待补。\n\n## 竞争格局\n\n- 直接竞品：必示科技、擎创科技、嘉为蓝鲸、博睿数据、华为、新华三、IBM Instana。\n- 替代方案：自建 ELK/Prometheus、云厂商监控、开源 AIOps。\n- 差异：APM 起家、金融行业积累、业务视角运维；弱点：规模小、品牌弱、LLM 转型慢。\n- 竞争动态：基础设施厂商内嵌运维；云厂商监控免费化；独立 AIOps 被挤压。\n- 份额：国内 AIOps 市场分散，云智慧在金融细分领先（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：营收不透明、IPO 未落地、项目制规模化难；2020 年后无新融资。\n- 技术：算法效果衰减、LLM 转型不及预期、数据安全。\n- 法律/监管：金融数据合规、等保；待补诉讼。\n- 治理：创始人控制权、投资方退出压力。\n- 争议：$4.6 亿估值停留在 2020 年，后续增长缺乏公开验证（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：营收、客户数、IPO 进展、LLM 产品均未入库。建议跟踪：① 是否启动 IPO/新融资；② 金融客户续约；③ AIOps 收入占比；④ 与必示/擎创的份额变化；⑤ 员工规模变化。\n\n## 信源与口径\n\n- 官网：https://www.cloudwise.com/（◐ 待核）\n- 创始人访谈：https://www.thss.tsinghua.edu.cn/info/1025/1047.htm ；https://www.tsinghua.org.cn/info/1014/11457.htm\n- 融资：https://pitchhub.36kr.com/project/1678266129003528\n- 工商/员工：https://www.tianyancha.com/company/24739983\n- 口径：员工数为工商口径；营收未披露；◐ 表示待核。' },
      { id: 'bizseer', name: '必示科技', def: '根因定位专业厂商：清华系算法团队，深耕银行与运营商。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2016-11 / 北京海淀 | 阿里云社区/百度百科 |\n| 上市地 / 代码 | 未上市 | 不适用 |\n| 最新财年营收 | 未披露 | — |\n| 盈利 | 未披露 | — |\n| 现金流 | 未披露 | — |\n| 客户 | 30+ 银行/证券客户 | 媒体报道 |\n| 员工 | 51–200 人（LinkedIn）/100–499 人（看准） | ◐ 口径不一 |\n| 市值 / 估值 | 未披露；C 轮近 2 亿元 | 晨壹投资领投 |\n| 主要股东 | 晨壹投资、红杉中国、高榕资本、三奕资本等 | 融资报道 |\n| 数据截至 | 融资 C 轮；经营 2026 | — |\n\n## 定位与沿革\n\n清华系 AIOps 厂商：核心团队来自清华大学计算机系智能运维实验室，专注异常检测、告警收敛与根因定位算法，产品以智能排障/智能运维平台形式交付，客户集中在银行、证券与运营商。\n\n- 2016-11 成立于北京海淀，核心团队来自清华计算机系智能运维实验室，并有微软亚洲研究院、阿里、百度背景。\n- 创始人裴丹：清华大学计算机系长聘副教授、UCLA 计算机博士、青年千人；联合创始人兼 CEO 程世文：清华计算机系本科/硕士、经管双学位、数学奥赛银牌、连续创业者。\n- 2019-07 A+ 轮数千万元；2020-10 B 轮 1.5 亿元，红杉中国领投，高榕资本等参与；此后 C 轮近 2 亿元，晨壹投资领投，三奕资本等参与。\n- 产品覆盖异常发现、故障根因定位、多维明细异常定位、日志异常定位、容量预测；拥有多项核心算法发明专利。\n- 客户包括中国建设银行、中国人民银行清算中心、交通银行、招商银行、光大银行、民生银行、广发银行、中国光大证券等 30+ 家。\n\n## 创始人与管理层\n\n- **裴丹（创始人）**：清华大学计算机系长聘副教授、UCLA 计算机博士、青年千人；研究方向为智能运维/AIOps。\n- **程世文（联合创始人 & CEO）**：清华计算机系本科/硕士、经管学院经济学双学位；数学奥赛银牌；连续创业者；曾任 CTO。\n- 核心团队：清华智能运维实验室、微软亚洲研究院、阿里、百度背景；具体名单待采集。\n- 董事会：晨壹投资、红杉中国、高榕资本等投资方席位待核。\n- 关键人事变动：C 轮后是否有高管调整待采集。\n\n## 商业模式\n\n- **收入结构**：私有化软件授权 + 项目交付 + 年度运维/算法订阅。\n- **销售动作**：企业销售 + 金融行业渠道；POC 后项目制交付；银行客户为主。\n- **单位经济**：私有公司不披露；项目制毛利率低于纯 SaaS，但客单价高、粘性强。\n- **收入质量**：30+ 银行/证券客户；收入可能集中于头部银行（◐）。\n- **定价趋势**：从「算法模块授权」向「平台订阅 + 运维服务」迁移；LLM 根因解释可能加购。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 智能排障平台 | 故障发现、根因定位、排障闭环 | 软件授权/项目 | 主力 |\n| 异常检测 | 指标/日志/多维异常发现 | 模块 | 主力 |\n| 根因定位 | 因果推断、拓扑关联、根因推荐 | 模块 | 主力 |\n| 日志异常定位 | 日志聚类、模式识别 | 模块 | 增长 |\n| 容量预测 | 容量规划与资源优化 | 模块 | 增长 |\n| LLM 运维助手 | 根因解释、运维问答 | 试验 | 试验 |\n\n- 包装：平台 + 算法模块；银行/证券行业方案。\n- 路线图：LLM 根因解释、自动化处置、跨云/信创适配。\n\n## 技术栈与壁垒\n\n- **架构**：私有化部署；指标/日志/告警/CMDB 数据接入；算法引擎做异常检测与根因定位。\n- **AI 路线**：传统 ML（异常检测、因果推断、日志聚类）+ LLM 运维助手；强调算法专利与金融场景数据。\n- **壁垒**：清华智能运维实验室的算法积累、银行客户数据与场景知识、专利、私有化交付。\n- **依赖与债务**：大模型削弱单点算法溢价；项目制规模化难；银行客户集中。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 中国建设银行 | 智能运维、根因定位 | 未披露具体数字 | 媒体报道 |\n| 中国人民银行清算中心 | 运维算法、异常检测 | 未披露具体数字 | 媒体报道 |\n| 交通银行/招商银行/光大银行 | 根因定位、告警收敛 | 未披露具体数字 | 媒体报道 |\n| 民生银行/广发银行/光大证券 | 智能排障 | 未披露具体数字 | 媒体报道 |\n\n- 客户结构：银行、证券、运营商；30+ 家，金融为主。\n- 集中度：未披露；头部银行占比可能较高（◐）。\n- 续约/流失：未披露；私有化项目粘性强、续约依赖算法效果。\n\n## 商业进展\n\n- 2019-07 A+ 轮数千万元；2020-10 B 轮 1.5 亿元（红杉中国领投）；C 轮近 2 亿元（晨壹投资领投）。\n- 客户扩展到建设银行、人民银行清算中心、交通银行、招商银行、光大银行、民生银行、广发银行、光大证券等 30+ 家。\n- 2026 年 AIOps 与 LLM 结合是产品主线；具体发布待采集。\n- 竞争：云智慧、擎创科技、嘉为蓝鲸、华为、新华三。\n- 融资：C 轮后无公开新融资；IPO 计划未公开。\n\n## 经营业绩\n\n| 指标 | 2020 | 2022 | 2026 | 说明 |\n|---|---|---|---|---|\n| 营收 | 未披露 | 未披露 | 未披露 | 私有公司 |\n| 增速 | 未披露 | 未披露 | 未披露 | — |\n| 毛利率 | 未披露 | 未披露 | 未披露 | 项目制 |\n| 营业利润 | 未披露 | 未披露 | 未披露 | — |\n| FCF | 未披露 | 未披露 | 未披露 | — |\n\n- 运营指标：30+ 金融客户；员工 51–499（口径不一）；ARR 未披露。\n- 融资：B 轮 1.5 亿元 + C 轮近 2 亿元；估值未披露。\n- 指引：不适用（私有公司）。\n\n## 股权、融资与股票\n\n- **不适用（未上市）**：无股票代码与二级市场市值。\n- 融资：A+ 轮数千万元（2019-07）；B 轮 1.5 亿元（2020-10，红杉中国领投，高榕资本等）；C 轮近 2 亿元（晨壹投资领投，三奕资本等）。\n- 估值：未披露；C 轮后无公开新融资。\n- 股东：裴丹、程世文、晨壹投资、红杉中国、高榕资本、三奕资本等。\n- 流动性：无公开市场；未来可能 IPO、并购或老股交易。\n\n## 团队与人员\n\n- 员工 51–200 人（LinkedIn）/100–499 人（看准）；口径不一（◐）。\n- 研发占比高；核心团队来自清华智能运维实验室、微软亚洲研究院、阿里、百度。\n- 招聘：2026 年 LLM/AIOps 岗位可能扩张；具体岗位待采集。\n- 薪酬/股权激励：未披露；技术团队以期权/项目奖金为主（◐）。\n- 组织：裴丹（创始人）、程世文（CEO）；核心高管名单待补。\n\n## 竞争格局\n\n- 直接竞品：云智慧、擎创科技、嘉为蓝鲸、华为、新华三、IBM Instana。\n- 替代方案：自建 ELK + 规则引擎、开源 AIOps、云厂商监控。\n- 差异：清华系算法、根因定位专利、银行客户数据；弱点：规模小、品牌弱、LLM 转型待验证。\n- 竞争动态：大模型削弱单点算法溢价；平台厂商与基础设施厂商挤压独立 AIOps。\n- 份额：国内 AIOps 根因定位细分领先，整体市场分散（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：银行客户集中、项目制规模化难、融资少；C 轮后增长依赖金融 IT 预算。\n- 技术：算法效果衰减、LLM 转型不及预期、数据安全。\n- 法律/监管：金融数据合规、等保；待补诉讼。\n- 治理：创始人（教授）与 CEO 的分工、投资方退出压力。\n- 争议：算法效果与客户案例缺乏第三方量化验证（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：营收、员工数、客户名单、C 轮后融资均未入库。建议跟踪：① 银行客户续约与新单；② LLM 根因产品的落地；③ 是否启动 D 轮/IPO；④ 与云智慧/擎创的份额变化；⑤ 运营商客户拓展。\n\n## 信源与口径\n\n- B 轮：https://finance.sina.cn/tech/2020-10-28/detail-iiznctkc8212062.d.html\n- C 轮：https://m.cyzone.cn/article/702227.html\n- 公司/创始人：https://baike.baidu.com/item/%E5%8C%97%E4%BA%AC%E5%BF%85%E7%A4%BA%E7%A7%91%E6%8A%80%E6%9C%89%E9%99%90%E5%85%AC%E5%8F%B8/24551296 ；https://cn.linkedin.com/in/chengshiwen/zh-cn\n- 客户：https://www.cww.net.cn/article?id=457153\n- 口径：员工数口径不一；营收未披露；◐ 表示待核。' },
      { id: 'yunshan', name: '云杉网络', def: '网络可观测：DeepFlow 以 eBPF 做零侵扰全栈追踪。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2011-12 / 北京 | 百度百科/官网 |\n| 上市地 / 代码 | 未上市 | 不适用 |\n| 最新财年营收 | 未披露 | — |\n| 盈利 | 未披露 | — |\n| 现金流 | 未披露 | — |\n| 客户 | 四川电力、甜橙金融、四川银行、阿里混合云、腾讯金融云、华为云等 | 官方案例 |\n| 员工 | 100+（B+ 期）；注册实体 24 人（2025 社保口径） | ◐ 口径不一 |\n| 市值 / 估值 | 未披露；B+ 轮 $1,100 万 | 融资报道 |\n| 主要股东 | 联想创投、华创资本、红点、北极光、经纬等 | 融资报道 |\n| 数据截至 | 融资 2021-12 D+；经营 2026 | — |\n\n## 定位与沿革\n\n以 DeepFlow 为核心的可观测厂商：用 eBPF 与流量采集实现零侵扰的应用/网络全栈追踪，覆盖云网络诊断、服务依赖、性能分析与 AI Agent 智能运维。\n\n- 2011-12 成立于北京，创始人为亓亚烜（CEO，清华大学博士）与张天鹏（联合创始人/CTO）；早期做 SDN/云网络，是国内最早的 SDN 厂商之一。\n- 产品从网络流量采集/分发扩展到 DeepFlow 可观测性与智能体平台，目标客户为中国 500 强企业。\n- 2019 年前后完成 B+ 轮 1,100 万美元，联想创投、华创资本领投，红点、北极光、经纬等参与；2021-12 完成 D+ 轮（金额未披露），为目前最新公开融资。\n- 客户案例：四川电力（全栈可观测 + AI Agent 智能运维，覆盖华为云营销 2.0 关键节点）、甜橙金融（中国电信翼支付金融云网络分析）、四川银行（云原生全链路交易监控）、阿里混合云、腾讯金融云、华为云等。\n- 2026 年定位升级为「DeepFlow 可观测性与智能体平台」，强调 AI Agent 驱动的智能运维。\n\n## 创始人与管理层\n\n- **亓亚烜（创始人 & CEO）**：清华大学博士，清华企业家协会（TEEC）成员；2006 年起在清华研究数据中心/云计算。\n- **张天鹏（联合创始人 & CTO）**：有美国网络厂商背景；负责研发与技术路线（◐ 具体履历待补）。\n- 核心团队：来自清华、Juniper/网络厂商与云厂商；具体名单待采集。\n- 董事会：联想创投、华创资本等投资方席位待核。\n- 关键人事变动：2021 年后是否有高管调整待采集。\n\n## 商业模式\n\n- **收入结构**：软件授权 + 私有化项目 + 年度订阅/支持；DeepFlow 企业版为主。\n- **销售动作**：企业销售 + 云厂商/集成商渠道；面向金融、电力、电信、政府、互联网。\n- **单位经济**：私有公司不披露；项目制毛利率低于纯 SaaS，但客单价高。\n- **收入质量**：中国 500 强客户为主；收入可能集中于头部项目（◐）。\n- **定价趋势**：从「按节点/流量」向「平台订阅 + AI Agent」迁移；开源社区版做获客。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| DeepFlow | eBPF 零侵扰全栈可观测 | 按节点/订阅 | 主力 |\n| 网络流量采集/分发 | SDN/云网络流量治理 | 项目 | 主力（历史） |\n| 服务依赖与拓扑 | 自动发现、调用链、网络诊断 | 随平台 | 主力 |\n| AI Agent 智能运维 | 根因分析、自动调查 | 按 agent/项目 | 试验/增长 |\n| 开源社区版 | DeepFlow 开源 | 免费 | 获客 |\n\n- 包装：开源版 + 企业版；金融/电力行业方案。\n- 路线图：AI Agent 运维、eBPF 深度分析、多云/信创适配。\n\n## 技术栈与壁垒\n\n- **架构**：eBPF/流量采集 + 全栈数据关联；零侵扰、无需改代码；支持 Kubernetes/混合云。\n- **AI 路线**：DeepFlow 提供网络与应用证据层；AI Agent 做根因分析与自动调查（◐ 成熟度待核）。\n- **壁垒**：eBPF 工程能力、网络层视角、中国 500 强客户、开源社区。\n- **依赖与债务**：细分市场小；与 APM/可观测平台竞争；项目制规模化难。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 四川电力 | 全栈可观测 + AI Agent 智能运维 | 覆盖华为云营销 2.0 关键节点 | 官方案例 |\n| 甜橙金融（翼支付） | 金融云网络分析与治理 | 提升云平台/SDN 集成 | 官方案例 |\n| 四川银行 | 云原生全链路交易监控 | 未披露具体数字 | 《金融电子化》2026-06 |\n| 阿里混合云/腾讯金融云/华为云 | 云网络监控 | 未披露具体数字 | 官方案例 |\n\n- 客户结构：金融、电力、电信、政府、教育、能源、互联网；中国 500 强为主。\n- 集中度：未披露；大客户占比可能较高（◐）。\n- 续约/流失：未披露；私有化项目粘性强。\n\n## 商业进展\n\n- 2019 年前后 B+ 轮 1,100 万美元；2021-12 D+ 轮（金额未披露），此后无公开新融资。\n- 2026 年 DeepFlow 与四川电力落地 AI Agent 智能运维；四川银行案例登上《金融电子化》。\n- 定位从「网络可观测」升级为「可观测性与智能体平台」。\n- 生态：阿里云、腾讯云、华为云、联想创投等；具体合作待采集。\n- 竞争：Datadog、观测云、博睿数据、云智慧、网络厂商。\n\n## 经营业绩\n\n| 指标 | 2019 | 2021 | 2026 | 说明 |\n|---|---|---|---|---|\n| 营收 | 未披露 | 未披露 | 未披露 | 私有公司 |\n| 增速 | 未披露 | 未披露 | 未披露 | — |\n| 毛利率 | 未披露 | 未披露 | 未披露 | 项目制 |\n| 营业利润 | 未披露 | 未披露 | 未披露 | — |\n| FCF | 未披露 | 未披露 | 未披露 | — |\n\n- 运营指标：员工 100+（B+ 期）；注册实体 24 人（2025 社保口径，参考性低）；ARR 未披露。\n- 融资：B+ 轮 1,100 万美元；D+ 轮金额未披露。\n- 指引：不适用（私有公司）。\n\n## 股权、融资与股票\n\n- **不适用（未上市）**：无股票代码与二级市场市值。\n- 融资：B+ 轮 1,100 万美元（联想创投、华创资本领投，红点、北极光、经纬等参与）；D+ 轮 2021-12（金额未披露）。\n- 估值：未披露；D+ 后无公开新融资。\n- 股东：亓亚烜、张天鹏、联想创投、华创资本、红点、北极光、经纬等。\n- 流动性：无公开市场；未来可能 IPO、并购或老股交易。\n\n## 团队与人员\n\n- 员工 100+（B+ 期口径）；注册实体 24 人（2025 社保口径，参考性低）。\n- 研发占比高；核心团队来自清华、Juniper/网络厂商、云厂商。\n- 招聘：2026 年 AI Agent/eBPF 岗位可能扩张；具体岗位待采集。\n- 薪酬/股权激励：未披露；技术团队以期权为主（◐）。\n- 组织：亓亚烜（CEO）、张天鹏（CTO）；核心高管名单待补。\n\n## 竞争格局\n\n- 直接竞品：Datadog、观测云、博睿数据、云智慧、网络厂商（华为/新华三）自带网络可观测。\n- 替代方案：自建 eBPF/Prometheus、云厂商网络监控、APM 厂商。\n- 差异：eBPF 零侵扰、网络层证据、中国 500 强客户；弱点：细分市场小、品牌弱、项目制。\n- 竞争动态：APM/可观测平台向上整合网络层；云厂商自带网络监控。\n- 份额：国内网络可观测细分领先，整体市场小（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：细分市场天花板、项目制规模化难、融资少；2021 年后无新融资。\n- 技术：eBPF 兼容性/性能、AI Agent 效果、数据安全。\n- 法律/监管：金融/电力数据合规、信创适配；待补诉讼。\n- 治理：创始人控制权、投资方退出压力。\n- 争议：注册实体员工数与 100+ 口径差异大，实际规模待核（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：营收、员工数、客户名单、D+ 后融资均未入库。建议跟踪：① AI Agent 智能运维的付费客户；② 四川电力/四川银行案例复制；③ 是否启动新融资/IPO；④ 与 APM 厂商的竞合；⑤ 信创订单。\n\n## 信源与口径\n\n- 官网：https://www.yunshan.net/ ；https://deepflow.io/about/\n- 客户案例：https://deepflow.io/about/news/detail/42255 ；https://www.deepflow.io/cases/\n- 融资：https://startup.aliyun.com/info/1051066.html ；https://pitchhub.36kr.com/project/1678266337293317\n- 工商/员工：https://baike.baidu.com/item/%E5%8C%97%E4%BA%AC%E4%BA%91%E6%9D%89%E4%B8%96%E7%BA%AA%E7%BD%91%E7%BB%9C%E7%A7%91%E6%8A%80%E6%9C%89%E9%99%90%E5%85%AC%E5%8F%B8/18434102\n- 口径：员工数口径不一；营收未披露；◐ 表示待核。' },
      { id: 'bonree', name: '博睿数据', def: 'APM 老兵：拨测与性能监控起家，转向 DataFabius 可观测。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2008-02 / 北京 | 百度百科/官网 |\n| 上市地 / 代码 | 科创板 688229 | 2020-08-17 IPO，发行价 ¥65.82 |\n| 最新财年营收 | FY2025 ¥1.27 亿（-9.9%） | 2025 年报（2026-04-28） |\n| 盈利 | FY2025 归母净利 -¥9,683.5 万 | 2025 年报 |\n| 现金流 | 未披露；经营现金流为负（◐） | — |\n| 客户 | 1,000+ 头部客户（公司口径）；金融为主 | 官网 |\n| 员工 | 394 人 | 同花顺/年报 |\n| 市值 / 估值 | 约 ¥27 亿（股价 ¥61.40 × 4,440 万股） | 2026-10/11 行情（◐） |\n| 主要股东 | 李凯、上海佳合兴利等 | 2025 年报（◐） |\n| 数据截至 | FY2025 年报；行情 2026-10/11 | — |\n\n## 定位与沿革\n\n国内 APM 老牌厂商：从拨测、应用性能监控扩展到全栈可观测平台 DataFabius/Bonree ONE，服务金融、运营商与大型企业；2020 年登陆科创板，是国产 APM 中少数上市公司。\n\n- 2008-02 成立于北京，创始人/董事长兼 CEO 李凯；早期以拨测（Bonree 监测）与 APM 起家。\n- 2020-08-17 科创板上市，代码 688229，发行价 ¥65.82，发行 1,110 万股。\n- 产品线扩展到 Bonree ONE 一体化可观测、DataFabius 数据平台、AIOps/智能运维。\n- FY2025 营收 ¥1.27 亿（-9.9%），归母净利 -¥9,683.5 万；员工 394 人；收入下滑、亏损扩大。\n- 2026 年前三季度营收 ¥8,272 万（-18.1%），归母净利 -¥5,860.5 万；经营压力持续。\n- 公司称 1,000+ 头部客户、蝉联中国 APM/可观测性市场份额第一（公司口径，◐）。\n\n## 创始人与管理层\n\n- **李凯（创始人、董事长 & CEO）**：1974 年生，本科学历；公司法定代表人/总经理；2026 年 2 月有控制权相关披露（◐ 待核）。\n- **孟曦东（总裁/董秘）**：负责经营与资本市场；具体履历待补。\n- 核心团队：APM/运维监控行业背景；具体名单待采集。\n- 董事会：李凯、上海佳合兴利等；2026 年控制权变动待核。\n- 关键人事变动：2026 年控制权/股东事项需持续跟踪。\n\n## 商业模式\n\n- **收入结构**：软件授权 + SaaS 订阅 + 项目交付 + 运维服务；APM/拨测/可观测混合。\n- **销售动作**：企业销售 + 金融/运营商渠道；POC 后项目制交付。\n- **单位经济**：FY2025 营收 ¥1.27 亿、员工 394 人、人工成本 ¥1.42 亿，人工成本高于营收，是亏损主因。\n- **收入质量**：1,000+ 客户、金融为主；收入下滑、客户预算收紧。\n- **定价趋势**：从「按节点/拨测」向「平台订阅 + 可观测数据量」迁移；AI 功能可能加购。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| Bonree ONE | 一体化可观测平台 | 订阅/项目 | 主力 |\n| APM | 应用性能监控、分布式追踪 | 按节点/应用 | 主力 |\n| 拨测 | 网络/应用可用性监测 | 按任务/套餐 | 主力（历史） |\n| DataFabius | 可观测数据平台 | 项目/订阅 | 增长 |\n| AIOps | 告警收敛、根因分析 | 模块 | 增长 |\n| 智能运维 | IT 运维分析、容量 | 项目 | 增长 |\n\n- 包装：平台 + 模块；金融/运营商行业方案。\n- 路线图：DataFabius、AIOps、LLM 运维助手；信创适配。\n\n## 技术栈与壁垒\n\n- **架构**：SaaS + 私有化；拨测网络、APM 探针、日志/指标/追踪采集。\n- **AI 路线**：AIOps 告警收敛与根因分析；LLM 运维助手待采集。\n- **壁垒**：拨测网络与 APM 数据积累、金融客户、上市公司品牌、科创板融资渠道。\n- **依赖与债务**：收入下滑、亏损扩大、人工成本高；与云厂商/开源监控竞争。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 金融行业客户 | APM、可观测、智能运维 | 未披露具体数字 | 官网/案例集 |\n| 运营商客户 | 拨测、网络性能 | 未披露具体数字 | 官网 |\n| 1,000+ 头部客户 | 应用性能监控 | 未披露 | 公司口径 |\n| 88 个标杆案例 | 2025 可观测实践案例集 | 未披露 | 公司口径 |\n\n- 客户结构：金融为主，运营商、政企、互联网；1,000+ 头部客户。\n- 集中度：未披露；金融大客户占比可能较高（◐）。\n- 续约/流失：收入下滑 9.9%（FY2025）、2026 前三季度 -18.1%，显示客户预算/续约承压。\n\n## 商业进展\n\n- 2020-08 科创板上市，发行价 ¥65.82；当前股价约 ¥61.40，低于发行价（◐）。\n- FY2025 营收 ¥1.27 亿（-9.9%）、归母净利 -¥9,683.5 万；2026 前三季度营收 -18.1%、亏损扩大。\n- 公司称蝉联中国 APM/可观测性市场份额第一；发布 2025 可观测实践案例集（88 个标杆）。\n- 2026 年控制权/股东事项披露，需持续跟踪。\n- 竞争：云智慧、观测云、Datadog、阿里云 ARMS、听云、华为云 APM。\n\n## 经营业绩\n\n| 指标 | FY2023 | FY2024 | FY2025 | 2026 前三季度 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | 未披露 | ¥1.405 亿 | ¥1.266 亿 | ¥0.827 亿 | FY2025 -9.9%；2026 9M -18.1% |\n| 增速 | 未披露 | 未披露 | -9.9% | -18.1% | 持续下滑 |\n| 毛利率 | 未披露 | 未披露 | 约 68.6% | 待核 | 营业成本 ¥3,975.6 万 |\n| 营业利润 | 未披露 | 亏损 | 亏损 | 亏损 | 归母净利 -¥9,683.5 万（FY2025） |\n| FCF | 未披露 | 未披露 | 负（◐） | 待核 | — |\n\n- 运营指标：员工 394 人；1,000+ 头部客户；人工成本 ¥1.42 亿 > 营收。\n- 指引：未披露；经营重点是降本与收入企稳。\n- 市场预期：股价低于 IPO 发行价，市值约 ¥27 亿。\n\n## 股权、融资与股票\n\n- 上市：科创板 688229；2020-08-17 IPO，发行价 ¥65.82，发行 1,110 万股。\n- 行情（2026-10/11）：股价约 ¥61.40；总股本约 4,440 万股；市值约 ¥27 亿（◐）。\n- 估值：PS 约 21x FY2025 营收（亏损，PE 不适用）；PB 约 7.5x（每股净资产 ¥8.23）。\n- 股东：李凯、上海佳合兴利等；2026 年控制权事项待核。\n- 资本动作：科创板上市后是否有再融资/回购待查；2026 年股东变动需跟踪。\n- 风险提示：收入下滑、亏损扩大、股价低于发行价。\n\n## 团队与人员\n\n- 员工 394 人（FY2025）；研发/销售/交付结构待补。\n- 人工成本 ¥1.42 亿，占营收约 112%，是亏损主因；降本是关键。\n- 招聘/裁员：2025–2026 年可能控制规模；具体动态待采集。\n- 薪酬/股权激励：上市公司，有股权激励计划（◐ 待查）；流失率未披露。\n- 组织：李凯（董事长/CEO）、孟曦东（总裁/董秘）；2026 年控制权变动待核。\n\n## 竞争格局\n\n- 直接竞品：云智慧、观测云、Datadog、阿里云 ARMS、听云、华为云 APM、腾讯云可观测。\n- 替代方案：自建 Prometheus/Grafana/ELK、开源 APM、云厂商原生监控。\n- 差异：拨测网络 + APM 积累、金融客户、科创板品牌；弱点：收入下滑、亏损、产品创新不足。\n- 竞争动态：云厂商监控免费化/捆绑；独立 APM 厂商被挤压；AIOps/LLM 是新战场。\n- 份额：公司称中国 APM/可观测性市场份额第一（口径待核）；整体市场分散（◐）。\n\n## 风险与争议\n\n- 经营：营收连续下滑、亏损扩大、人工成本高；2026 年前三季度 -18.1%。\n- 技术：产品竞争力、LLM/AIOps 转型、数据安全。\n- 法律/监管：金融数据合规、上市公司信息披露；2026 年控制权事项。\n- 治理：控制权/股东变动、管理层稳定；科创板监管。\n- 争议：市场份额第一的口径与收入下滑的矛盾，需第三方验证（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：客户名单、AIOps 收入、控制权变动、扭亏计划均未入库。建议跟踪：① 2026 全年营收能否企稳；② 降本与亏损收窄；③ 控制权/股东事项；④ DataFabius/AIOps 的付费客户；⑤ 与云厂商监控的竞争。\n\n## 信源与口径\n\n- FY2025 年报：https://money.finance.sina.com.cn/corp/view/vCB_AllBulletinDetail.php?stockid=688229&id=12224392\n- 年报摘要：https://money.finance.sina.com.cn/corp/view/vCB_AllBulletinDetail.php?stockid=688229&id=12224385\n- 2025 净利润：https://wap.eastmoney.com/a/202604283721811782.html\n- 公司资料：https://basic.10jqka.com.cn/688229/company.html\n- 官网：https://cn.bonree.com/s/about\n- 口径：财务为年报/第三方摘要；市值为股价×股本估算；◐ 表示待核。' },
      { id: 'huawei', name: '华为', def: 'AI-Native 运维：昇腾底座 + 运维大模型，把智能运维做进全栈基础设施。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 1987 / 深圳 | 官网 |\n| 上市地 / 代码 | 未上市；员工持股 | 工会持股平台 |\n| 最新财年营收 | FY2025 ¥8,809 亿（+2.18%） | 2026-03-31 年报 |\n| 盈利 | 净利润 ¥680 亿（+8.63%）；营业利润率 11.0% | 2025 年报 |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露总数；运营商、政企、智算中心 | ◐ |\n| 员工 | 约 16.5 万；研发 11.4 万（53.7%） | 2025 年报 |\n| 市值 / 估值 | 不适用（未上市） | — |\n| 主要股东 | 员工持股计划 169,054 人；任正非等 | 2025 年报 |\n| 数据截至 | FY2025 年报（2026-03-31） | — |\n\n## 定位与沿革\n\n以「AI-Native」重塑运维：FusionCube 超融合、AgentArts 智能体平台与 AIOps 能力打包进政企与信创项目；昇腾算力底座让运维大模型可私有化部署。\n\n- 1987 年由任正非在深圳创立；员工持股，未上市；轮值董事长制（梁华、徐直军、胡厚崑等轮值）。\n- 2025 年营收 ¥8,809 亿（+2.18%）、净利润 ¥680 亿（+8.63%）、研发投入 ¥1,923 亿（占收入 21.8%）；员工约 16.5 万，研发 11.4 万。\n- 业务分运营商、企业、终端、云计算、数字能源、智能汽车等；智能汽车 2025 年收入大增 72%。\n- 2026 年发布《AI DC 白皮书 2026》，提出「可观测、可预测、智能化」的运维体系，覆盖模型应用可观测、光模块脏污预防、告警聚类与根因定位。\n- 2026-03 发布 FusionCube A1000，通算/智算融合一体化，预集成数据处理、训练与推理。\n- 2026-09 华为云开放 AgentArts 智能体平台，强调智能体可观测、评估与风险可控；Agent Team 支持多 agent 协作拓扑编排。\n\n## 创始人与管理层\n\n- **任正非（创始人 & CEO）**：1987 年创立华为；长期主导战略与文化。\n- **轮值董事长**：梁华、徐直军、胡厚崑等轮值；具体轮值周期待核。\n- **孟晚舟（副董事长、CFO）**：2025 年报发布时对外阐述 AI 战略，称 AI 是未来十年最确定性机会。\n- 董事会：华为投资控股有限公司董事会；员工持股计划参与人 169,054 人。\n- 关键人事变动：轮值董事长轮换、终端/云业务负责人调整待采集。\n\n## 商业模式\n\n- **收入结构**：运营商网络、企业业务、终端、云计算、数字能源、智能汽车等多板块；硬件 + 软件 + 服务混合。\n- **销售动作**：大客户/政企直销 + 渠道/生态；项目制交付 + 订阅/维保。\n- **单位经济**：未上市不披露分部利润；研发投入高（21.8%），硬件毛利低于软件。\n- **收入质量**：政企/运营商长周期合同；智算中心与信创是增量。\n- **定价趋势**：从「卖设备」向「卖算力 + 云 + 运维服务」；AgentArts/AIOps 可能按平台/智能体计价。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| FusionCube | 超融合/智算一体化基础设施 | 项目/订阅 | 主力 |\n| AgentArts | 智能体开发、观测、评估平台 | 平台/智能体 | 增长 |\n| AIOps/智能运维 | 告警聚类、根因定位、容量预测 | 项目/订阅 | 增长 |\n| 华为云 | 公有云/混合云 | 按用量 | 主力 |\n| 昇腾（Ascend） | AI 芯片/集群 | 硬件 | 主力 |\n| AI DC | 智算中心方案 | 项目 | 增长 |\n\n- 包装：全栈捆绑（算力 + 云 + 运维）+ 项目制交付；政企/信创方案。\n- 路线图：AI DC、AgentArts 多 agent、智能运维大模型、昇腾生态。\n\n## 技术栈与壁垒\n\n- **架构**：昇腾/CANN 算力底座 + 华为云 + FusionCube；私有化/混合部署。\n- **AI 路线**：盘古大模型、AgentArts 智能体平台、AIOps 大模型；强调可观测、评估与风险可控。\n- **壁垒**：政企渠道、信创合规、全栈一体化、昇腾生态、研发投入。\n- **依赖与债务**：美国制裁/芯片供应限制；地缘政治；硬件毛利率；AIOps 产品独立收入不透明。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 大型政企/运营商 | 全栈智能运维、AIOps | 未披露具体数字 | 官网/白皮书 |\n| 国家智算中心 | FusionCube/AI DC 运维 | 未披露具体数字 | 官方案例 |\n| 金融/能源客户 | 信创云、智能运维 | 未披露具体数字 | 行业口径 |\n| 智能汽车客户 | 车 BU 解决方案 | 2025 年收入 +72% | 年报 |\n\n- 客户结构：运营商、政企、金融、能源、智算中心、车企；全球运营商客户。\n- 集中度：未披露；政企大项目占比高（◐）。\n- 续约/流失：未披露；政企粘性强、替换成本高。\n\n## 商业进展\n\n- 2026-03 发布 FY2025 年报：营收 ¥8,809 亿、净利 ¥680 亿、研发 ¥1,923 亿。\n- 2026-03 发布《AI DC 白皮书 2026》与 FusionCube A1000；2026-09 华为云开放 AgentArts。\n- 智能汽车业务 2025 年收入 +72%，成为增长最快的板块之一。\n- 智能运维：AI DC 白皮书提出告警聚类、根因定位、光模块脏污预防等场景；具体产品收入待采集。\n- 生态：昇腾伙伴、华为云市场、政企 SI；具体合作待采集。\n\n## 经营业绩\n\n| 指标 | FY2023 | FY2024 | FY2025 | 说明 |\n|---|---|---|---|---|\n| 营收 | ¥7,042 亿 | ¥8,621 亿 | ¥8,809 亿 | +2.18% |\n| 增速 | +9.6% | +22.4% | +2.18% | 增速放缓 |\n| 毛利率 | 未披露 | 未披露 | 未披露 | 硬件为主 |\n| 营业利润 | 未披露 | 未披露 | 营业利润率 11.0% | — |\n| 净利润 | ¥870 亿 | ¥626 亿 | ¥680 亿 | +8.63% |\n\n- 研发：2025 年 ¥1,923 亿（21.8%）；近十年累计超 ¥13,820 亿。\n- 员工：约 16.5 万；研发 11.4 万（53.7%）；持股员工 169,054 人。\n- 指引：未上市，不披露指引。\n\n## 股权、融资与股票\n\n- **不适用（未上市）**：无股票代码与二级市场市值。\n- 股权：员工持股计划（工会持股平台）参与人 169,054 人；任正非持股比例低（◐ 具体待核）。\n- 融资：未上市，无公开融资轮次；通过内部持股与债务融资。\n- 估值：无公开市场估值；部分榜单估算（◐ 待核）。\n- 流动性：无公开市场；员工持股分红/回购机制待核。\n- 资本动作：无公开 IPO 计划；债券融资与投资待采集。\n\n## 团队与人员\n\n- 员工约 16.5 万；研发 11.4 万（53.7%）；全球布局。\n- 研发投入 ¥1,923 亿（2025），占收入 21.8%；专利约 16.5 万件。\n- 招聘：2026 年 AI/算力/智能汽车岗位扩张；具体岗位待采集。\n- 薪酬/股权激励：员工持股计划 + 薪酬；流失率未披露。\n- 组织：轮值董事长制；任正非 CEO；孟晚舟 CFO；业务 BG 制。\n\n## 竞争格局\n\n- 直接竞品：新华三、浪潮信息、联想、戴尔、HPE（服务器/超融合）；阿里云、腾讯云（云）。\n- AI 算力：NVIDIA、AMD、寒武纪、海光（昇腾的竞争对手）。\n- 差异：全栈一体化、政企渠道、信创合规、昇腾生态；弱点：制裁/芯片供应、软件生态。\n- 竞争动态：智算中心与信创是增量；美国出口管制是最大变量。\n- 份额：国内服务器/网络/云市场份额领先（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：美国制裁/芯片供应限制、地缘政治、硬件毛利率、政企预算。\n- 技术：昇腾生态成熟度、AIOps 大模型效果、AgentArts 落地。\n- 法律/监管：出口管制、数据安全、各国 5G/ telecom 审查。\n- 治理：员工持股与轮值制度；接班人安排。\n- 争议：智能运维产品收入不透明，AIOps 能力多与基础设施捆绑（◐）。\n\n## 本库追踪\n\n本库覆盖集中在算力与芯片侧：昇腾路线、国产芯片训练、CloudRobo 等（线索多条、档案多条）；**AIOps 运维口径覆盖为零**。缺口：智能运维产品独立收入、客户案例、AgentArts 交付形态均未入库。建议跟踪：① AI DC/FusionCube 的智算订单；② AgentArts 的付费采用；③ AIOps 大模型的客户案例；④ 昇腾生态与制裁变化；⑤ 智能汽车收入。\n\n## 信源与口径\n\n- 华为 2025 年报：https://www.huawei.com/cn/news/2026/3/annual-report-2025\n- 2025 年报 PDF：https://www-file.huawei.com/dam/asset/view/3022d6c92652427fa0d7f72dcc72daa2.pdf\n- AI DC 白皮书 2026：https://www-file.huawei.com/dam/asset/view/ai-dc-white-paper-2026-cn.pdf\n- AgentArts：https://www.huawei.com/cn/news/2026/9/hc-solve-industry-challenges-ai\n- FusionCube A1000：https://www.guancha.cn/economy/2026_03_18_810471.shtml\n- 口径：财务为 2025 年报；员工/持股为年报口径；◐ 表示待核。' },
      { id: 'sangfor', name: '深信服', def: '超融合承载者：把 AI 智能运维并入全栈超融合口径。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2000 / 深圳 | 官网 |\n| 上市地 / 代码 | 深交所创业板 300454 | 2018-05 IPO |\n| 最新财年营收 | FY2025 ¥80.43 亿（+6.96%） | 2025 年报（2026-03-31） |\n| 盈利 | 归母净利 ¥3.93 亿（+99.52%） | 2025 年报 |\n| 现金流 | 经营现金流 ¥13.42 亿 | 2025 年报 |\n| 客户 | 未披露总数；覆盖 70+ 国家 | 官网 |\n| 员工 | 约 7,280 人；研发 2,636 人（36.2%） | 年报推算/官网 |\n| 市值 / 估值 | 约 ¥530–540 亿（2026-11-02 股价 ¥127.77） | ◐ 股本推算 |\n| 主要股东 | 何朝曦等创始团队 | ◐ 待核 |\n| 数据截至 | FY2025 年报；行情 2026-11-02 | — |\n\n## 定位与沿革\n\n以网络安全与超融合（HCI）为主业的基础设施厂商；「全栈超融合 + AI 智能运维」把监控、容量与故障处置内嵌到私有云底座，主打 VMware 替代与政企信创。\n\n- 2000 年由何朝曦、熊武、冯毅在深圳创立；2018-05 创业板上市（300454）。\n- 业务从上网行为管理、VPN 扩展到网络安全、超融合、桌面云、SASE 与私有云。\n- FY2025 营收 ¥80.43 亿（+6.96%）、归母净利 ¥3.93 亿（+99.52%）、经营现金流 ¥13.42 亿；研发投入 ¥20.55 亿。\n- 2026 H1 营收 ¥39.98 亿（+32.85%）、归母净利 ¥2.31 亿（扭亏为盈），增长重新加速。\n- 智能运维：把监控、容量、故障处置内嵌到 HCI/私有云方案，作为「全栈超融合」的附加值；独立 AIOps 产品化程度较低。\n\n## 创始人与管理层\n\n- **何朝曦（创始人、董事长）**：2000 年创立深信服；2025 年薪酬 ¥40.21 万（媒体关注其低于部分副总）。\n- **熊武（联合创始人、副总裁）**：技术/产品背景；具体分工待补。\n- **冯毅（联合创始人、副总裁）**：技术/产品背景；具体分工待补。\n- 高管：副总蒋文光 2025 年薪酬 ¥169 万（媒体披露）；CFO/CTO 名单待补。\n- 董事会：创始团队 + 投资方；具体席位待核。\n\n## 商业模式\n\n- **收入结构**：网络安全 + 超融合/私有云 + 桌面云 + SASE；硬件、软件、订阅与服务混合。\n- **销售动作**：渠道/代理商为主 + 行业销售；政企、教育、医疗、金融。\n- **单位经济**：FY2025 毛利率约 60–65%（◐）；研发投入 20.55 亿，费用控制带动净利翻倍。\n- **收入质量**：70+ 国家、政企客户；硬件占比高，毛利低于纯软件。\n- **定价趋势**：从「卖盒子」向「订阅 + 云服务 + AI 运维」迁移；AI 功能随全栈方案打包。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 超融合/私有云 | HCI、VMware 替代、信创云 | 项目/订阅 | 主力 |\n| 网络安全 | 防火墙、上网行为管理、SASE | 硬件/订阅 | 主力 |\n| 桌面云 | 虚拟桌面、终端安全 | 项目/订阅 | 增长 |\n| AI 智能运维 | 监控、容量、故障处置 | 随方案 | 增长 |\n| 安全服务 | MSS、等保合规 | 订阅/服务 | 增长 |\n\n- 包装：全栈超融合 + 安全 + 桌面云；政企/信创方案。\n- 路线图：AI 运维内嵌、VMware 替代、SASE、信创适配。\n\n## 技术栈与壁垒\n\n- **架构**：HCI 软件定义基础设施；安全网关/终端；私有云/混合云。\n- **AI 路线**：AI 智能运维内嵌到 HCI/私有云，做监控、容量与故障处置；独立大模型能力待采集。\n- **壁垒**：渠道网络、政企客户、VMware 替代窗口、安全合规资质、成本控制。\n- **依赖与债务**：硬件毛利、安全业务竞争、AI 运维差异化不足；应收账款较大（媒体风险提示）。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 政企/教育/医疗客户 | 超融合、私有云、VMware 替代 | 未披露具体数字 | 官网/渠道 |\n| 金融客户 | 网络安全、等保合规 | 未披露具体数字 | 官网 |\n| 70+ 国家客户 | 安全与云基础设施 | 未披露具体数字 | 官网 |\n\n- 客户结构：政企、教育、医疗、金融、制造；70+ 国家。\n- 集中度：未披露；渠道分散，单一客户占比低（◐）。\n- 续约/流失：未披露；硬件替换周期与维保续约是收入基础。\n\n## 商业进展\n\n- FY2025 营收 ¥80.43 亿（+6.96%）、净利 ¥3.93 亿（+99.52%）、经营现金流 ¥13.42 亿；研发投入 ¥20.55 亿。\n- 2026 H1 营收 ¥39.98 亿（+32.85%）、净利 ¥2.31 亿（扭亏），增长加速。\n- VMware 替代与信创是超融合增长主线；AI 智能运维随全栈方案交付。\n- 2026-10 使用节余募集资金永久补充流动资金（公告）。\n- 竞争：华为、新华三、奇安信、启明星辰、VMware。\n\n## 经营业绩\n\n| 指标 | FY2023 | FY2024 | FY2025 | 2026 H1 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | 未披露 | ¥75.20 亿 | ¥80.43 亿 | ¥39.98 亿 | FY2025 +6.96%；H1 +32.85% |\n| 增速 | 未披露 | 未披露 | +6.96% | +32.85% | 重新加速 |\n| 毛利率 | 未披露 | 约 60–65% | 约 60–65% | 待核 | ◐ |\n| 营业利润 | 未披露 | 未披露 | 未披露 | 未披露 | — |\n| 归母净利 | 未披露 | ¥1.97 亿 | ¥3.93 亿 | ¥2.31 亿 | FY2025 +99.52% |\n\n- 研发：2025 年 ¥20.55 亿（-2.96%）；研发人员 2,636 人（36.2%）。\n- 员工：约 7,280 人；官网称 7,000+，研发占比约 40%（口径差异）。\n- 现金流：2025 年经营现金流 ¥13.42 亿，为成立以来最高。\n\n## 股权、融资与股票\n\n- 上市：深交所创业板 300454；2018-05 IPO。\n- 行情（2026-11-02）：股价 ¥127.77（+4.09%）；52 周区间 ¥88.25–¥188.00；月环比 +11.15%。\n- 市值：约 ¥530–540 亿（按总股本约 4.2 亿股推算；◐）。\n- 估值：PE 待按 2025 净利计算（约 135x）；PS 约 6.7x。\n- 股东：何朝曦等创始团队；机构持股待核。\n- 资本动作：2025 年分红 10 派 1.1 元；2026-10 节余募集资金补流。\n\n## 团队与人员\n\n- 员工约 7,280 人；研发 2,636 人（36.2%）；官网称研发占比约 40%、AI 专研 1,000+。\n- 研发投入 ¥20.55 亿（2025），同比 -2.96%；专利 3,200+ 件。\n- 招聘：2026 年 AI/安全/云岗位可能扩张；具体岗位待采集。\n- 薪酬/股权激励：创始人薪酬较低、副总较高（媒体关注）；股权激励计划待查。\n- 组织：何朝曦（董事长）、熊武/冯毅（副总裁）；职业经理人团队。\n\n## 竞争格局\n\n- 直接竞品：华为、新华三、奇安信、启明星辰、VMware（HCI/安全）。\n- 替代方案：公有云、开源 HCI、自建安全。\n- 差异：渠道/政企覆盖、VMware 替代、全栈超融合 + 安全；弱点：硬件毛利、AI 运维差异化不足。\n- 竞争动态：华为/新华三从基础设施挤压；奇安信/启明星辰从安全侧竞争；VMware 替代窗口是增量。\n- 份额：国内超融合市场份额领先（公司口径，◐）；安全市场份额分散。\n\n## 风险与争议\n\n- 经营：硬件毛利、安全业务竞争、应收账款较大、AI 运维变现不清晰。\n- 技术：HCI 同质化、AI 运维能力、信创适配。\n- 法律/监管：网络安全合规、数据安全；待补诉讼。\n- 治理：创始团队控制权、股权激励。\n- 争议：2026 年股价波动大（52 周 ¥88–188），市场对增长持续性存疑（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：AI 运维收入、客户名单、超融合份额均未入库。建议跟踪：① 2026 全年营收/净利；② VMware 替代订单；③ AI 智能运维的付费形态；④ 应收账款与现金流；⑤ 与华为/新华三的份额变化。\n\n## 信源与口径\n\n- 2025 年报：https://money.finance.sina.com.cn/corp/view/vCB_AllBulletinDetail.php?stockid=300454&id=12052056\n- 2025 净利：https://wap.eastmoney.com/a/202603313690596621.html\n- 研发人员：https://m.jrj.com.cn/madapter/finance/2026/05/27155357222343.shtml\n- 2026 H1：https://finance.eastmoney.com/a/202608213849847211.html\n- 行情：https://www.google.com/finance/quote/300454:SHE\n- 口径：员工数为年报推算/官网口径；市值为股本推算；◐ 表示待核。' },
      { id: 'h3c', name: '新华三', def: 'UIS 智能运维：智简网络 + 超融合，把运维自动化做进政企网络。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2003（华为3Com）/ 杭州、北京 | 官网/百度百科 |\n| 上市地 / 代码 | 未上市；母公司紫光股份 000938 | 不适用 |\n| 最新财年营收 | 2025 ¥759.81 亿（+37.96%） | 紫光股份/媒体 |\n| 盈利 | 未单独披露；紫光股份 2025 1-9 月归母净利 ¥14.04 亿 | 并表 |\n| 现金流 | 并表，未单独披露 | — |\n| 客户 | 政企、教育、医疗、运营商 | 官网 |\n| 员工 | 未披露；研发占比 >50% | 官网 |\n| 市值 / 估值 | 不适用；母公司紫光股份市值待核 | — |\n| 主要股东 | 紫光股份（控股） | 并表 |\n| 数据截至 | 2025 年经营；2026 Q1 | — |\n\n## 定位与沿革\n\n紫光旗下 ICT 基础设施厂商：产品覆盖网络、服务器、存储与超融合（UIS）；SeerEngine 等网络控制器与运维自动化能力，服务政企、教育、医疗。\n\n- 2003 年由华为与 3Com 合资成立（华为3Com），后更名 H3C；2016 年被紫光股份控股，成为新紫光集团核心企业。\n- 2025 年营收 ¥759.81 亿（+37.96%）；2026 Q1 营收 ¥221.89 亿（+45.08%），增长强劲。\n- 2026-06 换帅：于英涛辞任总裁兼 CEO（任职约 10 年），王竑弢接任；于英涛继续任紫光集团执行副总裁、联席总裁。\n- 产品线：网络（交换机/路由器/WLAN）、服务器、存储、超融合 UIS、SeerEngine 控制器、AI 运维。\n- 研发人员占比 >50%，专利申请 17,000+ 件（90%+ 发明专利）；总部杭州滨江，北京为行政/市场总部。\n\n## 创始人与管理层\n\n- **王竑弢（总裁 & CEO，2026-06 起）**：此前任紫光股份董事、总裁；接替于英涛。\n- **于英涛（前总裁 & CEO，2016-2026）**：任职约 3,700 天；曾任紫光股份董事长（2018-04 至 2026-06）；现任紫光集团执行副总裁、联席总裁。\n- 核心团队：网络/服务器/存储/云背景；具体名单待采集。\n- 董事会：紫光股份控盘；具体席位待核。\n- 关键人事变动：2026 年 6 月换帅，战略连续性待观察。\n\n## 商业模式\n\n- **收入结构**：网络设备、服务器、存储、超融合、云与服务的硬件+软件+服务混合。\n- **销售动作**：渠道/合作伙伴为主 + 政企直销；教育、医疗、政府、运营商。\n- **单位经济**：硬件毛利低于软件；规模效应与供应链是关键；未单独披露利润率。\n- **收入质量**：政企项目制为主；2025 年 +37.96% 增长强劲，2026 Q1 +45.08%。\n- **定价趋势**：从「卖设备」向「卖方案 + 订阅 + 运维服务」；AI 运维随基础设施打包。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 网络 | 交换机、路由器、WLAN | 硬件/项目 | 主力 |\n| 服务器/存储 | 通用/智算服务器、存储 | 硬件/项目 | 主力 |\n| UIS 超融合 | 软件定义基础设施 | 项目/订阅 | 主力 |\n| SeerEngine | 网络控制器、智简网络 | 软件/项目 | 增长 |\n| AI 运维 | 监控、自动化、根因 | 随方案 | 增长 |\n| 云/服务 | 私有云、维保、集成 | 项目/订阅 | 增长 |\n\n- 包装：网络 + 算力 + 存储 + 云 + 运维一体化；政企/教育/医疗方案。\n- 路线图：智算、AI 运维、信创适配、SeerEngine 网络自动化。\n\n## 技术栈与壁垒\n\n- **架构**：网络/服务器/存储硬件 + UIS 超融合 + SeerEngine 控制器；私有云/混合云。\n- **AI 路线**：AI 运维内嵌到网络/超融合方案，做监控、自动化与根因；独立大模型能力待采集。\n- **壁垒**：政企渠道、网络+算力一体化、研发占比 >50%、专利、服务网络。\n- **依赖与债务**：硬件毛利、母公司控制、与华为/深信服竞争；AI 运维独立产品化程度低。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 政企客户 | 网络、超融合、私有云 | 未披露具体数字 | 官网 |\n| 教育/医疗客户 | 校园网、医院云 | 未披露具体数字 | 官网 |\n| 运营商客户 | 网络与算力基础设施 | 未披露具体数字 | 官网 |\n\n- 客户结构：政府、教育、医疗、运营商、金融、制造；渠道覆盖广。\n- 集中度：未披露；政企项目占比高（◐）。\n- 续约/流失：未披露；硬件维保与项目续约是基础。\n\n## 商业进展\n\n- 2025 年营收 ¥759.81 亿（+37.96%）；2026 Q1 ¥221.89 亿（+45.08%）。\n- 2026-06 换帅：王竑弢接任总裁兼 CEO，于英涛辞任。\n- 紫光股份 2026 H1 营收 ¥635.16 亿（+33.93%）、归母净利 ¥21.67 亿（+108.18%），新华三是核心增量。\n- 智算/AI 服务器与网络是增长主线；AI 运维随方案交付。\n- 竞争：华为、深信服、浪潮信息、联想、锐捷。\n\n## 经营业绩\n\n| 指标 | 2023 | 2024 | 2025 | 2026 Q1 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | 未披露 | ¥550.74 亿 | ¥759.81 亿 | ¥221.89 亿 | 2025 +37.96%；Q1 +45.08% |\n| 增速 | 未披露 | 未披露 | +37.96% | +45.08% | 强劲增长 |\n| 毛利率 | 未披露 | 未披露 | 未披露 | 未披露 | 并表 |\n| 营业利润 | 未披露 | 未披露 | 未披露 | 未披露 | — |\n| 归母净利 | 未披露 | 未披露 | 紫光股份 1-9 月 ¥14.04 亿 | 紫光股份 Q1 归母净利 ¥7.88 亿 | 并表 |\n\n- 运营指标：员工数未披露；研发占比 >50%；专利 17,000+ 件。\n- 指引：未单独披露；母公司紫光股份指引待查。\n- 市场预期：智算与国产替代驱动增长，关注毛利率与换帅后的战略。\n\n## 股权、融资与股票\n\n- **不适用（未上市）**：新华三未独立上市；母公司紫光股份（000938）在深交所上市。\n- 股权：紫光股份控股；具体持股比例待核（历史上 51%，后收购 HPE 剩余股权）。\n- 估值：无独立市值；按紫光股份市值与新华三利润贡献推算（◐）。\n- 融资：通过母公司/债务融资；无独立融资轮次。\n- 流动性：无独立股票；投资者通过紫光股份间接持有。\n\n## 团队与人员\n\n- 员工数未披露；研发人员占比 >50%；专利 17,000+ 件（90%+ 发明专利）。\n- 总部杭州滨江（运营），北京为行政/市场总部；全国服务网络。\n- 招聘：2026 届校招进行中；AI/智算岗位可能扩张。\n- 薪酬/股权激励：母公司紫光股份激励体系；具体待核。\n- 组织：王竑弢（总裁/CEO，2026-06 起）；于英涛（前 CEO，紫光集团）。\n\n## 竞争格局\n\n- 直接竞品：华为、深信服、浪潮信息、联想、锐捷网络。\n- 替代方案：白牌硬件 + 开源云、云厂商基础设施。\n- 差异：网络+算力+存储+云+运维一体化、政企渠道、研发投入；弱点：硬件毛利、品牌弱于华为。\n- 竞争动态：智算/国产替代是增量；华为从全栈挤压；浪潮从服务器侧竞争。\n- 份额：国内网络设备/超融合市场份额领先（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：硬件毛利、政企预算、换帅后的战略连续性、母公司控制。\n- 技术：AI 运维差异化不足、智算产品竞争、供应链。\n- 法律/监管：信创合规、数据安全、出口管制（母公司）。\n- 治理：紫光股份控制、管理层交接。\n- 争议：2026 年换帅与「千亿目标」未达成的讨论（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：新华三单独利润、员工数、AI 运维收入、换帅后的战略均未入库。建议跟踪：① 2026 全年营收/利润；② 智算订单；③ 王竑弢上任后的战略；④ AI 运维产品化；⑤ 与华为/深信服的份额变化。\n\n## 信源与口径\n\n- 官网：https://www.h3c.com/cn/About_H3C/Company_Information/Company_Introduce/\n- 换帅：https://m.c114.com.cn/w240-1313053.html ；https://www.thepaper.cn/newsDetail_forward_33487589\n- 2025 营收：https://cn.chinadaily.com.cn/a/202505/06/WS68198a25a310205377031b1a.html\n- 紫光股份 2026 H1：https://www.h3c.com/cn/d_202604/2833690_30008_0.htm\n- 口径：新华三未单独披露利润；营收/增速为媒体与母公司口径；◐ 表示待核。' },
      { id: 'sugon', name: '中科曙光', def: '智算运维服务：液冷集群运维与调度，承接国家智算中心。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 1995（◐）/ 北京 | 官网/百度百科 |\n| 上市地 / 代码 | 上交所 603019 | 2014-09 IPO |\n| 最新财年营收 | FY2025 ¥149.64 亿（+13.8%） | 券商/媒体口径（◐） |\n| 盈利 | 归母净利 ¥21.76 亿（+13.9%） | ◐ 待年报复核 |\n| 现金流 | 待核 | ◐ |\n| 客户 | 国家智算中心、科研、政务 | 官网 |\n| 员工 | 6,025 人 | 同花顺 |\n| 市值 / 估值 | 约 ¥1,040 亿（股价 ¥71.29，2026-10） | ◐ 股本推算 |\n| 主要股东 | 中科院系/控股股东；李国杰已退场（2025） | 媒体 |\n| 数据截至 | FY2025；行情 2026-10 | — |\n\n## 定位与沿革\n\n中科院背景的算力基础设施厂商：覆盖服务器、存储、液冷与智算中心建设；运维服务围绕 GPU 集群的巡检、故障定位与调度优化，客户以国家智算中心与科研机构为主。\n\n- 1995 年前后成立（◐ 待核），源自中科院计算所；2014-09 在上交所上市（603019）。\n- 创始人李国杰（中科院院士）2025 年退场；历军任董事长兼总经理（2026 年「一肩挑」）。\n- FY2025 营收 ¥149.64 亿（+13.8%）、归母净利 ¥21.76 亿（+13.9%）；2026 前三季度营收 ¥122.38 亿（+38.75%）、归母净利 ¥17.24 亿（+78%），Q3 单季净利 +217%。\n- 业务：高端计算机整机、AI 服务器与训推一体机、分布式存储、液冷数据中心、智算中心运维。\n- 2026-10 曙光系拟 4.6 亿元入局太空算力；董事长提议 3–5 亿元回购。\n- 员工 6,025 人；注册资金 14.63 亿元；总部北京海淀。\n\n## 创始人与管理层\n\n- **李国杰（创始人）**：1943 年生，中科院院士，北京大学数学力学系毕业；2025 年退场，不再参与日常经营。\n- **历军（董事长 & 总经理）**：1968 年生，北京交通大学工业经济学博士，教授级高工；1997 年加入曙光，2001 年任曙光信息产业（北京）总裁，2006 年起任董事长/总经理；2026 年 5 月起「一肩挑」。\n- 核心团队：中科院计算所背景；具体名单待采集。\n- 董事会：中科院系/控股股东；李国杰退场后的治理结构待核。\n- 关键人事变动：2025 年创始人退场、控股股东减持；2026 年历军兼任总经理。\n\n## 商业模式\n\n- **收入结构**：高端计算机/服务器硬件 + 存储 + 液冷/智算中心方案 + 运维服务；硬件为主。\n- **销售动作**：政企/科研直销 + 渠道；国家智算中心、科研机构、政务。\n- **单位经济**：硬件毛利较低；规模效应与供应链是关键；智算运维服务毛利高于硬件（◐）。\n- **收入质量**：政企/科研项目制；2026 年前三季度 +38.75%，AI 算力需求驱动。\n- **定价趋势**：从「卖服务器」向「卖智算中心 + 运维订阅」；液冷/运维服务是增值点。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 高端计算机/AI 服务器 | 通用/智算服务器、训推一体机 | 硬件/项目 | 主力 |\n| 分布式存储 | 并行存储、海量数据 | 硬件/项目 | 主力 |\n| 液冷数据中心 | 液冷集群、机房方案 | 项目 | 增长 |\n| 智算中心 | 建设、调度、运维 | 项目/订阅 | 增长 |\n| 运维服务 | GPU 集群巡检、故障定位 | 订阅/驻场 | 增长 |\n| 太空算力 | 卫星/太空计算（2026 拟入局） | 项目 | 试验 |\n\n- 包装：硬件 + 液冷 + 智算中心 + 运维一体化；政府/科研方案。\n- 路线图：液冷、智算调度、太空算力、国产芯片适配。\n\n## 技术栈与壁垒\n\n- **架构**：服务器/存储硬件 + 液冷 + 智算中心；国产芯片（海光/昇腾等）适配。\n- **AI 路线**：AI 服务器/训推一体机 + 智算调度 + 运维；大模型运维能力待采集。\n- **壁垒**：中科院背景、政企/科研渠道、液冷工程、国产算力生态。\n- **依赖与债务**：硬件毛利、供应链（GPU/芯片）、客户集中、治理变动。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 国家智算中心 | 智算集群建设与运维 | 未披露具体数字 | 官网/媒体 |\n| 科研机构 | 高性能计算、存储 | 未披露具体数字 | 官网 |\n| 政务客户 | 信创云、算力基础设施 | 未披露具体数字 | 官网 |\n\n- 客户结构：国家智算中心、科研、政务、能源；政企为主。\n- 集中度：未披露；大项目占比可能较高（◐）。\n- 续约/流失：未披露；硬件维保与运维订阅是持续收入。\n\n## 商业进展\n\n- FY2025 营收 ¥149.64 亿（+13.8%）、净利 ¥21.76 亿（+13.9%）。\n- 2026 前三季度营收 ¥122.38 亿（+38.75%）、净利 ¥17.24 亿（+78%）；Q3 净利 +217%。\n- 2026-10 拟 4.6 亿元入局太空算力；董事长提议 3–5 亿元回购。\n- 液冷/智算中心是增长主线；国产芯片供应改善带动需求。\n- 竞争：浪潮信息、华为、联想、新华三、海光/寒武纪生态。\n\n## 经营业绩\n\n| 指标 | FY2023 | FY2024 | FY2025 | 2026 前三季度 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | 未披露 | 约 ¥131.5 亿 | ¥149.64 亿 | ¥122.38 亿 | FY2025 +13.8%；9M26 +38.75% |\n| 增速 | 未披露 | 未披露 | +13.8% | +38.75% | 加速 |\n| 毛利率 | 未披露 | 未披露 | 未披露 | 未披露 | 硬件为主 |\n| 营业利润 | 未披露 | 未披露 | 未披露 | 未披露 | — |\n| 归母净利 | 未披露 | ¥19.11 亿 | ¥21.76 亿 | ¥17.24 亿 | FY2025 +13.9%；9M26 +78% |\n\n- 运营指标：员工 6,025 人；注册资金 14.63 亿元。\n- 指引：2026 年机构一致预期归母净利约 ¥30.16 亿（+38.6%）。\n- 市场预期：AI 算力/液冷驱动高增长，关注毛利率与治理。\n\n## 股权、融资与股票\n\n- 上市：上交所 603019；2014-09 IPO。\n- 行情（2026-10）：股价约 ¥71.29；按 14.63 亿股本推算市值约 ¥1,040 亿（◐）。\n- 估值：PE 约 48x（按 2025 净利）；PS 约 7x。\n- 股东：中科院系/控股股东；李国杰退场；历军减持计划（2026）。\n- 资本动作：董事长提议 3–5 亿元回购（2026-10）；分红待查。\n- 风险提示：控股股东减持、创始人退场、硬件毛利。\n\n## 团队与人员\n\n- 员工 6,025 人（同花顺）；研发占比待补。\n- 总部北京海淀；液冷/智算工程团队。\n- 招聘：2026 年 AI/液冷/智算岗位可能扩张；具体待采集。\n- 薪酬/股权激励：国资背景；股权激励计划待查。\n- 组织：历军（董事长/总经理）；李国杰退场；中科院系治理。\n\n## 竞争格局\n\n- 直接竞品：浪潮信息、华为、联想、新华三、戴尔/HPE。\n- AI 芯片生态：海光、昇腾、寒武纪；曙光与海光同属中科院系（◐）。\n- 差异：中科院背景、液冷工程、政企/科研渠道、国产算力；弱点：硬件毛利、品牌弱于华为/浪潮。\n- 竞争动态：智算中心放量；国产芯片供应改善；华为全栈挤压。\n- 份额：国内高性能计算/服务器市场份额领先（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：硬件毛利、客户集中、控股股东减持、创始人退场后的治理。\n- 技术：液冷工程、国产芯片适配、智算调度。\n- 法律/监管：出口管制、信创合规、国资监管。\n- 治理：中科院系控制、历军「一肩挑」、减持计划。\n- 争议：2025 年创始人退场与控股股东减持引发高增长叙事质疑（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中；华为算力线索可作参照）。缺口：智算运维收入、客户名单、液冷份额均未入库。建议跟踪：① 2026 全年营收/净利；② 智算中心订单；③ 液冷渗透率；④ 太空算力进展；⑤ 治理/减持。\n\n## 信源与口径\n\n- 2026 三季报：https://m.21jingji.com/article/20261016/herald/d667fe6ddbc62c78ab1af6ac9422028a_zaker.html\n- 高管/员工：https://basic.10jqka.com.cn/603019/company.html\n- 历军：https://baike.baidu.com/item/%E5%8E%86%E5%86%9B/4558059\n- 创始人退场：https://www.21jingji.com/article/20250514/herald/d4a5550f62740250e448047a430af76c.html\n- 行情：https://q.stock.sohu.com/cn/603019/information.shtml\n- 口径：FY2025 数据为券商/媒体口径，待年报复核；市值为股本推算；◐ 表示待核。' },
      { id: 'lenovo', name: '联想', def: '端到端算力服务：问天服务器 + TruScale，把运维做成订阅。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 1984 / 北京（总部北京/香港） | 官网 |\n| 上市地 / 代码 | 港交所 0992.HK | 1994 IPO |\n| 最新财年营收 | FY2025/26 $831 亿（+20%） | 2026-05-21 发布 |\n| 盈利 | 净利 $19 亿（+38%） | FY2025/26 |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露总数；全球企业/政企 | ◐ |\n| 员工 | 约 71,500 人（2021 口径；2026 待核） | Wikipedia |\n| 市值 / 估值 | 约 HK$1,954–1,959 亿（2026-05）；7 月一度 >HK$3,000 亿 | 媒体 |\n| 主要股东 | 联想控股、机构 | ◐ |\n| 数据截至 | FY2025/26（2026-03-31）；行情 2026-05/07 | — |\n\n## 定位与沿革\n\n以 PC 为基本盘、向 AI 基础设施与服务延伸的全球化硬件厂商：问天服务器 + TruScale 即服务，把硬件、云与运维打包成订阅，降低政企算力持有门槛。\n\n- 1984 年由柳传志等在北京创立（Legend）；2005 年收购 IBM PC 业务，全球化；杨元庆任董事长兼 CEO。\n- 业务：智能设备（PC/手机）、基础设施方案（ISG：服务器/存储/边缘）、方案服务（SSG）。\n- FY2025/26 营收 $831 亿（+20%）、净利 $19 亿（+38%）；ISG 营收人民币 1,360 亿（+32%），首次全年盈利。\n- FY2026/27 Q1 营收人民币 1,834 亿（+43%），营收/利润双破纪录；非 PC 收入占比 >54%。\n- 目标：两年左右年营收达 $1,000 亿；TruScale 即服务是运维订阅化的载体。\n- 2026 年首次入选《时代》周刊「全球最佳公司」。\n\n## 创始人与管理层\n\n- **杨元庆（董事长 & CEO）**：联想集团董事长兼 CEO；长期主导全球化与 AI 转型。\n- **柳传志（创始人）**：1984 年创立联想；现为联想控股名誉董事长（◐）。\n- 核心高管：ISG/SSG/智能设备业务负责人；具体名单待采集。\n- 董事会：联想控股 + 独立董事；具体席位待核。\n- 关键人事变动：2025–2026 年 AI 基础设施团队扩张；具体待采集。\n\n## 商业模式\n\n- **收入结构**：智能设备（PC/手机）为主，ISG（服务器/存储）与 SSG（服务/方案）为增长极。\n- **销售动作**：全球渠道 + 企业直销；政企、教育、中小企业。\n- **单位经济**：PC 毛利低、周转快；ISG 毛利改善、首次全年盈利；SSG 毛利最高。\n- **收入质量**：全球多元化；AI 服务器/算力订阅是增量；PC 周期影响大。\n- **定价趋势**：从「卖硬件」向「TruScale 订阅 + 运维服务」；AI 基础设施按项目/订阅。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 问天服务器 | AI/通用服务器、存储 | 硬件/项目 | 主力 |\n| TruScale | 算力即服务、运维订阅 | 按用量/期限 | 增长 |\n| ISG 基础设施 | 服务器、存储、边缘 | 硬件/项目 | 主力 |\n| SSG 方案服务 | IT 服务、运维、方案 | 订阅/项目 | 增长 |\n| PC/手机 | 消费与商用终端 | 硬件 | 主力 |\n| AI 基础设施 | 智算集群、液冷 | 项目 | 增长 |\n\n- 包装：硬件 + TruScale 订阅 + SSG 服务；政企智算方案。\n- 路线图：AI 服务器、液冷、TruScale 扩张、边缘算力。\n\n## 技术栈与壁垒\n\n- **架构**：全球供应链 + 服务器/存储硬件 + TruScale 云化交付。\n- **AI 路线**：AI 服务器/智算集群；运维通过 TruScale/SSG 订阅化；大模型运维能力待采集。\n- **壁垒**：全球供应链、渠道、PC 基本盘、TruScale 订阅模式、成本控制。\n- **依赖与债务**：PC 周期、AI 服务器毛利、地缘政治/供应链、GPU 供应。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 政企客户 | 智算中心、TruScale | 未披露具体数字 | 官网/媒体 |\n| 全球企业 | PC/服务器/服务 | 未披露具体数字 | 官网 |\n| 教育/中小企业 | 终端与云服务 | 未披露具体数字 | 官网 |\n\n- 客户结构：全球企业、政企、教育、中小企业；PC 客户基数大。\n- 集中度：未披露；PC 渠道分散，ISG 大客户占比待核。\n- 续约/流失：未披露；TruScale 订阅续约是关键。\n\n## 商业进展\n\n- FY2025/26 营收 $831 亿（+20%）、净利 $19 亿（+38%）；ISG 首次全年盈利。\n- FY2026/27 Q1 营收人民币 1,834 亿（+43%），非 PC 收入占比 >54%。\n- 目标两年左右营收 $1,000 亿；AI 基础设施爆发式增长。\n- 2026 年市值一度超 HK$3,000 亿；股价创 26 年新高。\n- 竞争：戴尔、HPE、华为、浪潮信息、惠普。\n\n## 经营业绩\n\n| 指标 | FY2023/24 | FY2024/25 | FY2025/26 | 说明 |\n|---|---|---|---|---|\n| 营收 | $569 亿 | $691 亿 | $831 亿 | +20% |\n| 增速 | -14% | +21% | +20% | 复苏 |\n| 毛利率 | 约 17% | 约 17% | 约 16–17% | ◐ |\n| 营业利润 | 未披露 | 未披露 | 未披露 | — |\n| 净利 | $10.1 亿 | $13.8 亿 | $19 亿 | +38% |\n\n- 运营指标：ISG 营收人民币 1,360 亿（+32%）；非 PC 收入占比 >54%（Q1 FY26/27）。\n- 指引：两年左右营收 $1,000 亿目标。\n- 市场预期：AI 基础设施驱动增长，关注 ISG 毛利与 PC 周期。\n\n## 股权、融资与股票\n\n- 上市：港交所 0992.HK；1994 年上市。\n- 行情（2026-05）：市值约 HK$1,954–1,959 亿；2026-07 一度 >HK$3,000 亿；股价 HK$22.02（2026-07-02）。\n- 估值：PE 待按 FY2025/26 净利计算；PS 约 0.3x。\n- 股东：联想控股、机构；具体持股待核。\n- 资本动作：分红/回购待查；2026 年股价大涨。\n- 风险提示：PC 周期、AI 服务器毛利、地缘政治。\n\n## 团队与人员\n\n- 员工约 71,500 人（2021 口径；2026 待核）；全球分布。\n- 研发/制造/服务结构待补；中国、美国、印度等研发中心。\n- 招聘：2026 年 AI 基础设施/服务岗位扩张；具体待采集。\n- 薪酬/股权激励：港股上市公司，有股权激励；流失率未披露。\n- 组织：杨元庆（董事长/CEO）；ISG/SSG/IDG 业务集团。\n\n## 竞争格局\n\n- 直接竞品：戴尔、HPE、惠普、华为、浪潮信息、新华三。\n- 替代方案：云厂商算力、白牌服务器、ODM。\n- 差异：全球供应链、渠道、PC 基本盘、TruScale 订阅；弱点：AI 服务器毛利、地缘政治。\n- 竞争动态：AI 服务器需求爆发；华为/浪潮在国内挤压；戴尔/HPE 全球竞争。\n- 份额：全球 PC 市场份额领先；服务器份额前三（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：PC 周期、AI 服务器毛利、供应链/地缘政治、汇率。\n- 技术：液冷/智算、AI 运维能力、TruScale 规模化。\n- 法律/监管：出口管制、数据安全、各国合规。\n- 治理：联想控股控制、管理层激励。\n- 争议：AI 服务器增长能否持续、ISG 盈利稳定性（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：TruScale 收入、智算运维订单、员工数均未入库。建议跟踪：① ISG 营收/毛利；② TruScale 订阅规模；③ AI 服务器订单；④ PC 周期；⑤ 地缘政治/供应链。\n\n## 信源与口径\n\n- FY2025/26 业绩：https://www.businesswire.com/news/home/20260521161813/zh-CN\n- 季度业绩：https://news.lenovo.com/pressroom/press-releases/q3-fy-2025-26/?lg=zh\n- 市值/股价：https://www.guancha.cn/economy/2026_05_22_818027.shtml ；https://finance.sina.cn/stock/jdts/2026-07-06/detail-inifwfpv8741814.d.html\n- 公司资料：https://zh.wikipedia.org/zh-hans/%E8%81%94%E6%83%B3%E9%9B%86%E5%9B%A2\n- 口径：FY2025/26 截至 2026-03-31；员工数为 2021 口径；◐ 表示待核。' },
      { id: 'gds', name: '万国数据', def: '第三方 IDC 运营：高功率机房运维体系承接智算托管。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2001（◐）/ 上海 | 官网/百度百科 |\n| 上市地 / 代码 | NASDAQ: GDS；港交所 9698 | 双重上市 |\n| 最新财年营收 | FY2025 ¥114.32 亿（+10.3%） | 2026-03-17 发布 |\n| 盈利 | 净利约 ¥9.59 亿（净利率 8.4%），首次全年盈利 | ◐ 待 20-F |\n| 现金流 | 待核 | ◐ |\n| 客户 | 近 900 家 | 公司口径 |\n| 员工 | 未披露 | — |\n| 市值 / 估值 | 待核 | ◐ |\n| 主要股东 | 黄伟/管理层、高瓴等 | ◐ |\n| 数据截至 | FY2025；2026 Q2 | — |\n\n## 定位与沿革\n\n第三方数据中心运营商（GDS）：在高功率密度机柜、液冷与智算托管上扩张；运维体系覆盖电力、制冷、网络与驻场服务，是「算力托管」的物理底座。\n\n- 2001 年前后成立（◐），总部上海；黄伟任董事长兼 CEO。\n- 2007 年起转型第三方 IDC 运营商，在核心经济区域布局数据中心；纳斯达克上市，后在港交所双重上市（9698）。\n- FY2025 净营收 ¥114.32 亿（+10.3%），净利率 8.4%，首次实现全年盈利（净利约 ¥9.59 亿）。\n- 2026 Q1 净营收 ¥33.67 亿（+23.6%）、净利 ¥26.52 亿（+247.1%，含一次性收益）；新增签约约 200MW，创单季纪录。\n- 2026 Q2 净利 ¥8.376 亿（去年同期亏损 ¥0.706 亿），净利率 27.1%。\n- 黄伟宣布未来三年投入 300–500 亿元加码国内 AI 基础设施；服务近 900 家客户。\n\n## 创始人与管理层\n\n- **黄伟（William Wei Huang，创始人、董事长 & CEO）**：2002 年起任 CEO；长期主导 GDS 的数据中心扩张与资本运作。\n- 核心高管：CFO/COO 名单待采集；国际业务负责人待核。\n- 董事会：高瓴等投资方席位待核。\n- 关键人事变动：2025–2026 年融资/资产重组待采集。\n- 公司结构：GDS Holdings（开曼）控制境内运营主体；国际业务与国内业务分拆待核。\n\n## 商业模式\n\n- **收入结构**：数据中心托管订阅（按机柜/功率/面积）+ 运维服务 +  interconnection；长期合同为主。\n- **销售动作**：大客户直销（云厂商、互联网、金融、电信）+ 渠道；长约锁价。\n- **单位经济**：重资产、高 capex；上架率与电价是核心；EBITDA 率高，净利受折旧/利息影响。\n- **收入质量**：近 900 家客户、长约；2025 年首次全年盈利，2026 年增长加速。\n- **定价趋势**：高功率/液冷机柜溢价；AI 算力托管按功率/机柜计价。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| IDC 托管 | 机柜/功率/面积租赁 | 按机柜/功率 | 主力 |\n| 高功率/液冷机房 | AI 算力托管 | 按功率/项目 | 增长 |\n| 智算中心 | 建设、运营、运维 | 项目/订阅 | 增长 |\n| 运维服务 | 电力、制冷、网络、驻场 | 订阅/服务 | 增长 |\n| 互联/云接入 | 多云互联、交换 | 按端口/流量 | 增长 |\n\n- 包装：机柜/功率订阅 + 运维服务；大客户长约。\n- 路线图：高功率液冷、智算托管、海外业务、REITs/资产证券化（◐）。\n\n## 技术栈与壁垒\n\n- **架构**：高功率数据中心、液冷、双路电力、网络互联；全国核心经济区域布局。\n- **AI 路线**：AI 算力托管与智算中心运维；液冷/高功率工程能力是关键。\n- **壁垒**：一线城市/枢纽节点资源、电力指标、大客户长约、运维体系、资本。\n- **依赖与债务**：重资产/高杠杆、电价、上架率、客户集中、资本开支。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 大型云厂商 | 数据中心托管、智算 | 未披露具体数字 | 公司口径 |\n| 互联网/科技公司 | 高功率机柜、互联 | 未披露具体数字 | 公司口径 |\n| 金融/电信客户 | 合规托管、灾备 | 未披露具体数字 | 公司口径 |\n\n- 客户结构：云厂商、互联网、金融、电信、跨国企业；近 900 家。\n- 集中度：未披露；头部云厂商占比可能较高（◐）。\n- 续约/流失：长约为主；上架率与续约率待核。\n\n## 商业进展\n\n- FY2025 净营收 ¥114.32 亿（+10.3%），首次全年盈利（净利率 8.4%）。\n- 2026 Q1 净营收 ¥33.67 亿（+23.6%）、净利 ¥26.52 亿；新增签约 200MW 创纪录。\n- 2026 Q2 净利 ¥8.376 亿，净利率 27.1%。\n- 未来三年投入 300–500 亿元加码国内 AI 基础设施；国产芯片供应改善带动需求。\n- 竞争：世纪互联、润泽科技、秦淮数据、三大运营商 IDC。\n\n## 经营业绩\n\n| 指标 | FY2023 | FY2024 | FY2025 | 2026 Q2 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | 未披露 | ¥103.6 亿 | ¥114.32 亿 | ¥30.88 亿 | FY2025 +10.3% |\n| 增速 | 未披露 | 未披露 | +10.3% | 待核 | 加速 |\n| 毛利率 | 未披露 | 未披露 | 未披露 | 未披露 | 重资产 |\n| 净利 | 亏损 | 亏损 | ¥9.59 亿 | ¥8.376 亿 | 首次全年盈利 |\n| 净利率 | 负 | -7.5% | 8.4% | 27.1% | 改善 |\n\n- 运营指标：近 900 家客户；2026 Q1 新增签约 200MW；上架率待核。\n- 指引：2026 年营收/ capex 指引待查。\n- 市场预期：AI 算力托管驱动增长，关注杠杆与资本开支。\n\n## 股权、融资与股票\n\n- 上市：NASDAQ GDS；港交所 9698（双重上市）。\n- 行情（2026）：市值待核；股价/52 周区间待补（◐）。\n- 估值：EV/EBITDA 是核心；P/FFO 待算；净利受一次性收益影响。\n- 股东：黄伟/管理层、高瓴等；具体持股待核。\n- 资本动作：未来三年 300–500 亿元投资；REITs/资产证券化待核。\n- 风险提示：高杠杆、利率、资本开支、客户集中。\n\n## 团队与人员\n\n- 员工人数未披露；运维/工程/销售团队为主。\n- 总部上海；全国数据中心集群；海外业务团队待核。\n- 招聘：2026 年 AI 基础设施/运维岗位扩张；具体待采集。\n- 薪酬/股权激励：美股/港股上市公司，有股权激励；流失率未披露。\n- 组织：黄伟（董事长/CEO）；CFO/COO 待补。\n\n## 竞争格局\n\n- 直接竞品：世纪互联、润泽科技、秦淮数据、光环新网、三大运营商 IDC。\n- 替代方案：自建数据中心、云厂商自有 IDC。\n- 差异：一线城市/枢纽资源、高功率/液冷、大客户长约、运维体系；弱点：重资产/杠杆、电价。\n- 竞争动态：AI 算力托管需求爆发；运营商/云厂商自建挤压；资源稀缺性提升。\n- 份额：第三方 IDC 市场领先（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：高杠杆/利率、资本开支、上架率、客户集中、电价。\n- 技术：液冷/高功率工程、智算运维能力。\n- 法律/监管：数据安全、能耗指标、外资/VIE 结构。\n- 治理：双重股权/VIE、关联交易、国际业务分拆。\n- 争议：2026 年业绩飘红但资本市场「遇冷」（媒体口径，◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：员工数、市值、上架率、客户名单均未入库。建议跟踪：① 2026 营收/EBITDA；② 200MW 签约转化；③ 300–500 亿投资节奏；④ 杠杆/利率；⑤ 与运营商 IDC 的竞争。\n\n## 信源与口径\n\n- FY2025 业绩：https://www.nasdaq.com/press-release/gds-holdings-limited-reports-fourth-quarter-and-full-year-2025-results-2026-03-17\n- 2026 Q2：https://investors.gds-services.com/news-releases/news-release-details/gds-holdings-limited-reports-second-quarter-2026-results/\n- 2026 Q1：https://www.sec.gov/Archives/edgar/data/1526125/000110465926064164/tm2614459d3_ex99-1.htm\n- 投资计划：https://www.gds-services.com/zh_cn/newsshow_332.html\n- 管理层：https://investors.gds-services.com/zh-hans/management/william-wei-huang\n- 口径：净利/净利率为公司口径；市值/员工数待核；◐ 表示待核。' },
      { id: 'chinasoft', name: '中软国际', def: 'IT 服务人力替代：解放号 + 智算运维外包，承接运维长尾。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2000 / 北京 | 官网 |\n| 上市地 / 代码 | 港交所 0354.HK | 2003 创业板/后转主板 |\n| 最新财年营收 | FY2025 ¥170.27 亿（+0.5%） | 2026-03-26 发布 |\n| 盈利 | 净利 ¥3.24 亿（-36.7%）；2026 H1 ¥3.50 亿（+11.1%） | 年报/中报 |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露总数；政企、金融、运营商 | ◐ |\n| 员工 | 78,030 人（2025 年末） | 年报/媒体 |\n| 市值 / 估值 | 待核 | ◐ |\n| 主要股东 | 陈宇红/管理层、机构 | ◐ |\n| 数据截至 | FY2025；2026 H1 | — |\n\n## 定位与沿革\n\n大型 IT 服务与外包厂商：通过「解放号」平台与行业解决方案提供 IT 运维、智算运维与人力外包；在 AIOps 语境里代表「服务与人力替代」的一端。\n\n- 2000 年成立于北京；2003 年港股创业板上市，后转主板（0354.HK）；董事局主席兼 CEO 陈宇红。\n- 业务：IT 外包/驻场运维、行业解决方案、解放号（IT 服务交易平台）、AI 产品与智算运维。\n- FY2025 营收 ¥170.27 亿（+0.5%）、净利 ¥3.24 亿（-36.7%）；离职补偿 ¥1.77 亿（AI 转型人员优化）。\n- 2025 年 AI 产品及服务收入 ¥20.02 亿（+109.2%），占总收入 11.76%。\n- 2026 H1 营收 ¥89.48 亿（+5.2%）、净利 ¥3.50 亿（+11.1%），盈利修复。\n- 员工 78,030 人（2025 年末），较 2024 年 75,075 人增长；平均员工 76,553 人。\n- 陈宇红曾提出「未来 10 年收入破千亿、跻身全球 IT 前十」；解放号是供需匹配平台。\n\n## 创始人与管理层\n\n- **陈宇红（董事局主席 & CEO）**：中软国际创始人/掌舵人；长期提出千亿收入目标。\n- 核心高管：CFO/COO/业务线负责人名单待采集。\n- 董事会：陈宇红、机构投资方；具体席位待核。\n- 关键人事变动：2025 年 AI 转型人员优化（离职补偿 ¥1.77 亿）；2026 年盈利修复。\n- 组织：北京总部；全国交付中心；解放号平台团队。\n\n## 商业模式\n\n- **收入结构**：IT 外包/人力服务为主，行业解决方案、AI 产品/智算运维、解放号平台为辅。\n- **销售动作**：大客户直销 + 框架合同；政企、金融、运营商、华为生态。\n- **单位经济**：人力密集型，毛利率低（约 20%）；人均管理规模是核心；AI 转型提升毛利。\n- **收入质量**：78,030 员工、大客户框架合同；收入稳定但增长慢（FY2025 +0.5%）。\n- **定价趋势**：从「按人头」向「按项目/成果/订阅」迁移；智算运维按节点/服务计价。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| IT 外包/驻场运维 | 人力外包、运维服务 | 按人头/项目 | 主力 |\n| 行业解决方案 | 金融/政企/运营商 | 项目 | 主力 |\n| 解放号 | IT 服务交易/供需匹配 | 平台佣金/服务 | 增长 |\n| AI 产品与服务 | 大模型应用、智算 | 项目/订阅 | 增长 |\n| 智算运维 | 昇腾/智算中心运维 | 按节点/项目 | 增长 |\n| 鸿蒙/信创 | 鸿蒙生态、信创适配 | 项目 | 增长 |\n\n- 包装：人力 + 项目 + 平台；华为生态/智算运维是增长点。\n- 路线图：AI 转型、智算运维、解放号平台化、鸿蒙生态。\n\n## 技术栈与壁垒\n\n- **架构**：人力交付网络 + 行业解决方案 + 解放号平台；智算运维与华为昇腾生态绑定（◐）。\n- **AI 路线**：AI 产品/服务收入 ¥20.02 亿（2025，+109.2%）；大模型应用与智算运维。\n- **壁垒**：78,000 人交付规模、政企/华为生态关系、成本结构、解放号平台。\n- **依赖与债务**：人力成本、低毛利、AI 替代人力、客户集中、离职补偿。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 政企客户 | IT 外包、运维、信创 | 未披露具体数字 | 官网/年报 |\n| 金融/运营商 | 行业解决方案、驻场 | 未披露具体数字 | 官网 |\n| 华为生态 | 昇腾智算运维 | 未披露具体数字 | 券商研报（2023，◐） |\n\n- 客户结构：政企、金融、运营商、华为生态；大客户框架合同为主。\n- 集中度：未披露；华为相关收入占比可能较高（◐）。\n- 续约/流失：框架合同续约；2025 年人员优化显示部分低毛利业务收缩。\n\n## 商业进展\n\n- FY2025 营收 ¥170.27 亿（+0.5%）、净利 ¥3.24 亿（-36.7%）；离职补偿 ¥1.77 亿。\n- 2025 年 AI 产品/服务收入 ¥20.02 亿（+109.2%），占比 11.76%。\n- 2026 H1 营收 ¥89.48 亿（+5.2%）、净利 ¥3.50 亿（+11.1%），盈利修复。\n- 智算运维/华为昇腾生态是增长主线；解放号平台化待采集。\n- 竞争：软通动力、神州数码、东软集团、太极股份、中电金信。\n\n## 经营业绩\n\n| 指标 | FY2023 | FY2024 | FY2025 | 2026 H1 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | 未披露 | ¥169.4 亿 | ¥170.27 亿 | ¥89.48 亿 | FY2025 +0.5%；H1 +5.2% |\n| 增速 | 未披露 | 未披露 | +0.5% | +5.2% | 低速 |\n| 毛利率 | 未披露 | 约 20% | 约 20% | 待核 | 人力密集 |\n| 净利 | 未披露 | ¥5.12 亿 | ¥3.24 亿 | ¥3.50 亿 | FY2025 -36.7%；H1 +11.1% |\n| 员工 | 未披露 | 75,075 | 78,030 | 待核 | 2025 年末 |\n\n- 运营指标：员工 78,030；平均员工 76,553；AI 收入占比 11.76%。\n- 指引：未披露；重点是 AI 转型与盈利修复。\n- 市场预期：AI/智算运维能否带动毛利与增长。\n\n## 股权、融资与股票\n\n- 上市：港交所 0354.HK；2003 年创业板上市，后转主板。\n- 行情（2026）：市值待核；股价/52 周区间待补（◐）。\n- 估值：PE 待按 2025 净利计算；PS 约 0.4x（◐）。\n- 股东：陈宇红/管理层、机构；具体持股待核。\n- 资本动作：分红/回购待查；2025 年离职补偿影响利润。\n- 风险提示：人力成本、AI 替代、客户集中、低毛利。\n\n## 团队与人员\n\n- 员工 78,030 人（2025 年末）；平均 76,553 人；以交付/运维为主。\n- 研发占比待补；全国交付中心；华为生态团队。\n- 招聘/裁员：2025 年人员优化（离职补偿 ¥1.77 亿）；2026 年 AI/智算岗位扩张。\n- 薪酬/股权激励：人力密集型；股权激励待查；流失率未披露。\n- 组织：陈宇红（董事局主席/CEO）；业务线/交付中心。\n\n## 竞争格局\n\n- 直接竞品：软通动力、神州数码、东软集团、太极股份、中电金信、文思海辉。\n- 替代方案：企业自建 IT 团队、云厂商托管服务、AI 运维工具。\n- 差异：78,000 人交付规模、政企/华为生态、解放号平台、成本结构；弱点：低毛利、AI 替代人力。\n- 竞争动态：AI 运维工具替代驻场人力；华为生态绑定带来增量也带来集中度。\n- 份额：国内 IT 服务外包市场领先（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：人力成本、低毛利、AI 替代、客户集中、离职补偿。\n- 技术：AI 转型成效、智算运维能力、解放号平台化。\n- 法律/监管：数据安全、劳务合规、港股披露。\n- 治理：创始人控制权、股权激励。\n- 争议：2025 年净利 -36.7% 与 AI 收入 +109.2% 的剪刀差，转型阵痛（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：智算运维收入、解放号数据、客户名单均未入库。建议跟踪：① 2026 全年营收/净利；② AI 收入占比；③ 智算运维订单；④ 人均管理规模；⑤ 华为生态依赖。\n\n## 信源与口径\n\n- 2025 年报：https://www.chinasofti.com/pages/investor-reports\n- 2025 业绩：https://caifuhao.eastmoney.com/news/20260326215533065826450\n- 2026 H1：https://www.guandian.cn/m/show/592375\n- 员工/离职补偿：https://finance.sina.com.cn/wm/2026-05-12/doc-inhxsicz8063486.shtml\n- 陈宇红：https://m.c114.com.cn/w16-1177473.html\n- 口径：员工数为 2025 年末；净利/营收为年报口径；市值待核；◐ 表示待核。' },
      { id: 'intel', name: 'Intel', def: 'x86 与 IDM 的守成者：Gaudi/Max 追赶 AI 加速，代工转型决定第二曲线。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 1968 / Santa Clara | 官网 |\n| 上市地 / 代码 | NASDAQ: INTC | 1971 IPO |\n| 最新财年营收 | FY2025 $529 亿（-0.5%） | 2026-01-22 发布 |\n| 盈利 | FY2025 净利 -$2.67 亿（FY2024 -$188 亿） | 2025 10-K |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露；OEM、云厂商、企业 | ◐ |\n| 员工 | 85,100 人（2025 年末） | 10-K；较 2024 减少 23,800 |\n| 市值 / 估值 | 约 $3,300–3,500 亿（2026-11） | Macrotrends/MarketWatch |\n| 主要股东 | 机构为主；美国政府、软银、英伟达等战略持股（2025，◐） | 媒体 |\n| 数据截至 | FY2025；行情 2026-11-02 | — |\n\n## 定位与沿革\n\nx86 架构与 IDM 模式的守成者：PC/服务器 CPU 是基本盘，Gaudi/Max 追赶 AI 加速，代工（Intel Foundry）转型决定第二曲线。\n\n- 1968 年由 Gordon Moore、Robert Noyce、Andy Grove 创立；1971 年上市；x86 生态与自建晶圆厂是长期壁垒。\n- 2021 年重启代工业务（Intel Foundry），押注 18A/14A 制程；2024 年因重组与减值巨亏 $188 亿。\n- 2025 年 Lip-Bu Tan 任 CEO，收缩战线、裁员、聚焦执行；2025 年末员工 85,100 人（两年减少约 39,700 人）。\n- FY2025 营收 $529 亿（-0.5%）、净利 -$2.67 亿（接近盈亏平衡）；Q2 2026 营收 $161.3 亿（+25%），DCAI 数据中心与 AI 部门 $62.6 亿（+59%）。\n- AI 加速卡：Gaudi 3、Max 系列 GPU；服务器 CPU Xeon 是 AI 集群的配套受益者。\n- 2026 年股价大起大落（52 周 $32.89–$142.35），并宣布 $150 亿股票增发。\n\n## 创始人与管理层\n\n- **Gordon Moore（联合创始人）**：摩尔定律提出者；1975–1987 任 CEO。\n- **Robert Noyce（联合创始人）**：集成电路共同发明人；Intel 首任 CEO。\n- **Andy Grove（联合创始人/前 CEO）**：1987–1998 任 CEO，塑造 Intel 的执行文化。\n- **Lip-Bu Tan（CEO，2025 起）**：前 Cadence CEO、Walden International 创始人；主导重组与代工转型。\n- **Dave Zinsner（CFO）**：财务负责人；与 CEO 共同对外沟通重组进展。\n- 董事会：机构与政府/战略股东影响上升；具体席位待核。\n\n## 商业模式\n\n- **收入结构**：CCG（客户端 CPU）、DCAI（数据中心与 AI）、NEX（网络与边缘）、Foundry、Mobileye 等。\n- **销售动作**：OEM/ODM + 云厂商 + 企业直销；代工业务靠外部客户。\n- **单位经济**：IDM 重资产、高 capex；制程落后时毛利承压；代工外部客户不足。\n- **收入质量**：PC/服务器 CPU 基本盘稳定；AI 加速卡份额小；代工仍在投入期。\n- **定价趋势**：CPU 按型号/平台；Gaudi/Max 按加速卡/系统；代工按 wafer/节点。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| Xeon | 服务器 CPU | 按芯片/平台 | 主力 |\n| Core | PC/客户端 CPU | 按芯片 | 主力 |\n| Gaudi 3 | AI 训练/推理加速卡 | 按卡/系统 | 增长 |\n| Max 系列 GPU | 数据中心 GPU | 按卡/系统 | 试验/增长 |\n| Intel Foundry | 晶圆代工（18A/14A） | 按 wafer | 转型 |\n| AI PC | 端侧 AI 平台 | 按芯片 | 增长 |\n| Mobileye | 自动驾驶芯片 | 按芯片/项目 | 增长 |\n\n- 包装：CPU + 加速卡 + 代工；OEM/云厂商捆绑。\n- 路线图：18A 量产、Gaudi 下一代、AI PC、代工外部客户。\n\n## 技术栈与壁垒\n\n- **架构**：x86 + IDM + 先进封装（EMIB/Foveros）；18A/14A 制程。\n- **AI 路线**：Gaudi/Max 加速卡 + Xeon 配套；软件栈 oneAPI；与 NVIDIA CUDA 生态差距大。\n- **壁垒**：x86 生态、晶圆厂、封装、政府/客户关系；弱点：制程落后、代工外部客户少、AI 份额低。\n- **依赖与债务**：高 capex、代工亏损、重组执行、地缘政治/出口管制。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 云厂商/OEM | 服务器 CPU、AI 集群配套 | 未披露具体数字 | 财报/媒体 |\n| 企业/政府 | PC、服务器、AI PC | 未披露具体数字 | 官网 |\n| 代工客户 | 18A/14A 代工 | 外部客户极少 | 10-K |\n\n- 客户结构：OEM/ODM、云厂商、企业、政府；代工外部客户待采集。\n- 集中度：未披露；PC/服务器客户集中度中等。\n- 续约/流失：CPU 平台周期；代工客户导入是关键。\n\n## 商业进展\n\n- FY2025 营收 $529 亿、净利 -$2.67 亿；重组接近盈亏平衡。\n- 2026 Q2 营收 $161.3 亿（+25%），DCAI $62.6 亿（+59%），服务器 CPU 需求强劲。\n- 2026 年宣布 $150 亿股票增发；股价 52 周 $32.89–$142.35，波动剧烈。\n- 18A 制程与代工外部客户是核心看点；Gaudi 3/Max 的客户与出货待采集。\n- 竞争：NVIDIA、AMD、TSMC、Samsung、Arm、Qualcomm。\n\n## 经营业绩\n\n| 指标 | FY2023 | FY2024 | FY2025 | 2026 Q2 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | $542 亿 | $531 亿 | $529 亿 | $161.3 亿 | FY2025 -0.5%；Q2 2026 +25% |\n| 增速 | -14% | -2% | -0.5% | +25% | 复苏 |\n| 毛利率 | 约 40% | 约 33% | 待核 | 待核 | ◐ |\n| 营业利润 | 亏损 | 巨亏 | 接近盈亏平衡 | 待核 | ◐ |\n| 净利 | $17 亿 | -$188 亿 | -$2.67 亿 | 待核 | 重组/减值影响 |\n\n- 员工：85,100（2025 年末）；两年减少约 39,700 人。\n- 分部：Intel Products $491 亿（2025）；Foundry 外部客户极少。\n- 指引：Q3 2026 营收 $158–168 亿、EPS $0.31（◐）。\n\n## 股权、融资与股票\n\n- 上市：NASDAQ INTC；1971 年 IPO。\n- 行情（2026-11-02）：股价约 $64–66；市值约 $3,300–3,500 亿；52 周 $32.89–$142.35。\n- 估值：PE 不适用（亏损）；PS 约 6.3x；代工估值待重估。\n- 股东：机构为主；2025 年美国政府、软银、英伟达等战略入股（◐ 待核比例）。\n- 资本动作：2026 年 $150 亿股票增发；分红已暂停/削减（◐）。\n- 风险提示：股价波动极大；代工与 AI 份额是估值核心。\n\n## 团队与人员\n\n- 员工 85,100 人（2025 年末）；研发/制造/销售结构待补。\n- 制造与代工团队是核心；美国/以色列/爱尔兰/马来西亚等基地。\n- 招聘/裁员：2024–2025 年裁员约 39,700 人；2026 年可能稳定。\n- 薪酬/股权激励：RSU + 现金；重组期士气与流失率待采集。\n- 组织：Lip-Bu Tan（CEO）、Dave Zinsner（CFO）；业务部门负责人待补。\n\n## 竞争格局\n\n- 直接竞品：AMD（CPU/GPU）、NVIDIA（AI 加速）、Qualcomm/Arm（PC/边缘）。\n- 代工竞品：TSMC、Samsung Foundry、中芯国际。\n- 差异：x86 生态、IDM、先进封装、政府支持；弱点：制程落后、AI 份额低、代工外部客户少。\n- 竞争动态：NVIDIA 垄断 AI 训练；AMD 侵蚀服务器 CPU；Arm PC 崛起。\n- 份额：PC CPU 约 70%、服务器 CPU 约 70%（本库估算，◐）；AI 加速卡份额 <5%。\n\n## 风险与争议\n\n- 经营：代工亏损、capex、AI 份额低、重组执行、政府/战略股东影响。\n- 技术：18A 良率、Gaudi 软件生态、制程追赶。\n- 法律/监管：出口管制、反垄断、政府入股的公司治理。\n- 治理：CEO 重组授权、董事会与政府/战略股东关系。\n- 争议：2026 年市值大起大落与 $150 亿增发，市场对转型分歧大（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：Gaudi 出货、18A 客户、代工收入、政府持股均未入库。建议跟踪：① 18A 量产与外部客户；② Gaudi/Max 出货；③ DCAI 增速；④ 代工亏损收窄；⑤ 资本开支/增发。\n\n## 信源与口径\n\n- FY2025 业绩：https://www.intc.com/news-events/press-releases/detail/1759/intel-reports-fourth-quarter-and-full-year-2025-financial\n- 2025 10-K：https://www.sec.gov/Archives/edgar/data/50863/000005086326000011/intc-20251227.htm\n- Q2 2026：https://www.intc.com/news-events/press-releases/detail/1776/intel-reports-second-quarter-2026-financial-results\n- 员工：https://stockanalysis.com/stocks/intc/employees/\n- 行情：https://finance.yahoo.com/quote/INTC/\n- 口径：FY2025 数据为 10-K；市值/股价为 2026-11 第三方；◐ 表示待核。' },
      { id: 'moorethreads', name: '摩尔线程', def: '国产 GPU 第一股：MUSA 全功能 GPU + 夸娥智算集群，2025 科创板上市。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2020 / 北京 | 招股书 |\n| 上市地 / 代码 | 科创板 688795 | 2025-11/12 上市 |\n| 最新财年营收 | FY2025 ¥15.06 亿（+243.37%） | 2025 年报（2026-04） |\n| 盈利 | 归母净利 -¥10.01 亿（亏损收窄） | 2025 年报 |\n| 现金流 | 待核 | ◐ |\n| 客户 | 前五大客户占比 91.36%（2025） | 年报/媒体 |\n| 员工 | 未披露（招股书待查） | ◐ |\n| 市值 / 估值 | 上市后一度约 ¥3,000 亿；Pre-IPO 近 ¥300 亿 | 媒体 |\n| 主要股东 | 张建中 11.06%；南京神傲/杭州华傲等一致行动人 | 招股书 |\n| 数据截至 | FY2025 年报；IPO 2025-11/12 | — |\n\n## 定位与沿革\n\n国产全功能 GPU 代表：以 MUSA 统一系统架构覆盖 AI 计算、图形渲染与视频编解码，产品包括 MTT S 系列 GPU 与夸娥（KUAE）智算集群；2025 年科创板上市，被称为「A 股 GPU 第一股」。\n\n- 2020 年由张建中（前 NVIDIA 全球副总裁、中国区总经理）创立，成立不到 100 天完成两轮数十亿元融资，估值超 10 亿美元。\n- 2021-11 A 轮 20 亿元，投后估值 119 亿元；2022-12 B 轮 15 亿元；2024 年 Pre-IPO 轮超 50 亿元，投前估值近 300 亿元。\n- 2025-06 科创板 IPO 受理，2025-09 过会，2025-11/12 上市（688795），拟募资 80 亿元，为当年科创板最大 IPO；上市后市值一度约 3,000 亿元。\n- 2022–2024 营收 0.46/1.24/4.38 亿元，三年复合增长率超 200%；2025 年营收 15.06 亿元（+243.37%），归母净利 -10.01 亿元。\n- 客户高度集中：2025 年前五大客户占比 91.36%，上半年前两大客户合计 84.6%；主要采购 AI 智算集群设备。\n\n## 创始人与管理层\n\n- **张建中（创始人 & CEO）**：曾任 NVIDIA 全球副总裁及中国区总经理；IPO 前直接持股 11.06%，与南京神傲、杭州华傲等持股平台签署一致行动人协议。\n- 联合创始人/核心团队：来自 NVIDIA、AMD、Microsoft 等 GPU/芯片公司；具体名单待采集。\n- 董事会：张建中 + 投资方；具体席位待核。\n- 关键人事变动：IPO 前后高管团队稳定；研发团队规模待查。\n\n## 商业模式\n\n- **收入结构**：GPU 芯片/板卡 + AI 智算集群（夸娥）+ 软件/服务；集群设备是主要收入。\n- **销售动作**：政企/智算中心项目制 + 渠道；客户集中度高。\n- **单位经济**：早期毛利率从 -70% 提升至 70% 左右（2024）；2025 年亏损收窄，规模效应显现。\n- **收入质量**：前五大客户 91.36%，单一客户依赖高；项目制收入波动大。\n- **定价趋势**：GPU 按卡/集群；MUSA 软件生态免费，靠硬件与服务变现。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| MTT S 系列 | 全功能 GPU（AI/图形/视频） | 按卡 | 主力 |\n| 夸娥（KUAE） | 智算集群/一体机 | 按集群/项目 | 主力 |\n| MUSA | 统一系统架构/软件栈 | 随硬件 | 主力 |\n| AI SoC | 端侧/边缘 AI | 按芯片 | 试验 |\n| 图形/视频 | 渲染、编解码 | 按卡 | 增长 |\n\n- 包装：GPU + 集群 + MUSA 软件；政企智算方案。\n- 路线图：新一代 AI 训推一体芯片、图形芯片、AI SoC；2027 年目标盈利（公司口径）。\n\n## 技术栈与壁垒\n\n- **架构**：全功能 GPU（AI 计算 + 图形 + 视频）；MUSA 软件栈兼容 CUDA 生态（◐ 兼容度待核）。\n- **AI 路线**：训推一体 GPU + 夸娥集群；支持大模型训练/推理。\n- **壁垒**：国产 GPU 全功能路线、MUSA 生态、政企渠道、IPO 资金；弱点：客户集中、软件生态弱于 CUDA。\n- **依赖与债务**：先进制程/代工（台积电？）、出口管制、客户集中、亏损。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 前两大客户 | AI 智算集群设备 | 合计占营收 84.6%（2025H1） | 招股书 |\n| 政企/智算中心 | 国产算力集群 | 未披露具体数字 | 官网/媒体 |\n| 边缘/图形客户 | 国产 GPU 替代 | 未披露具体数字 | 官网 |\n\n- 客户结构：政企、智算中心、AI 集群集成商；前五大 91.36%。\n- 集中度：极高；客户 B3 2024 年合作、2025 年未续作，需求偶发。\n- 续约/流失：项目制；客户续作率待采集。\n\n## 商业进展\n\n- 2025-11/12 科创板上市（688795），募资 80 亿元；市值一度约 3,000 亿元。\n- FY2025 营收 15.06 亿元（+243.37%）、净利 -10.01 亿元；亏损收窄。\n- 2026 年计划推进新一代 AI 训推一体芯片、图形芯片、AI SoC；是否赴港上市待核（媒体 2026-08 提及）。\n- 国产替代/信创是主要需求；客户集中度高是最大风险。\n- 竞争：壁仞科技、沐曦、寒武纪、海光、NVIDIA。\n\n## 经营业绩\n\n| 指标 | 2022 | 2023 | 2024 | 2025 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | ¥0.46 亿 | ¥1.24 亿 | ¥4.38 亿 | ¥15.06 亿 | +243.37% |\n| 增速 | — | +169% | +253% | +243% | 高速 |\n| 毛利率 | -70.08% | 待核 | 70.71% | 待核 | 改善 |\n| 营业利润 | 亏损 | 亏损 | 亏损 | 亏损 | — |\n| 归母净利 | 亏损 | 亏损 | 亏损 | -¥10.01 亿 | 收窄 |\n\n- 客户：前五大 91.36%（2025）；前两大 84.6%（2025H1）。\n- 指引：公司曾预计最早 2027 年实现合并报表盈利。\n- 市场预期：国产 GPU 放量 + 科创板估值。\n\n## 股权、融资与股票\n\n- 上市：科创板 688795；2025-11/12 IPO，募资 80 亿元。\n- 行情：上市后市值一度约 ¥3,000 亿；当前股价/市值待刷新（◐）。\n- 估值：PS 约 200x（按 2025 营收 15.06 亿、市值 3,000 亿）；亏损，PE 不适用。\n- 股东：张建中 11.06%；南京神傲、杭州华傲等一致行动人；机构投资方。\n- 资本动作：IPO 募资 80 亿；是否赴港二次上市待核。\n- 风险提示：高估值、客户集中、亏损。\n\n## 团队与人员\n\n- 员工人数未披露（招股书应有）；研发占比高。\n- 团队来自 NVIDIA、AMD、Microsoft 等；北京总部。\n- 招聘：2026 年 AI 芯片/软件岗位扩张；具体待采集。\n- 薪酬/股权激励：科创板上市，有员工持股平台；流失率未披露。\n- 组织：张建中（CEO）；联合创始人/高管名单待补。\n\n## 竞争格局\n\n- 直接竞品：壁仞科技、沐曦、寒武纪、海光信息、天数智芯。\n- 国际竞品：NVIDIA、AMD、Intel。\n- 差异：全功能 GPU（AI+图形+视频）、MUSA 生态、国产替代；弱点：客户集中、软件生态、制程。\n- 竞争动态：国产 GPU 集中上市（摩尔线程、沐曦、壁仞），资本与订单竞争激烈。\n- 份额：国产 GPU 第一梯队（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：客户集中（91.36%）、亏损、项目制波动、估值高。\n- 技术：MUSA 生态兼容性、先进制程/代工、软件工具链。\n- 法律/监管：出口管制、科创板信息披露、信创合规。\n- 治理：创始人控制权、一致行动人、员工持股平台。\n- 争议：高市值与亏损/客户集中的反差；「国产 GPU 第一股」叙事（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：员工数、客户名单、MUSA 生态、2026 订单均未入库。建议跟踪：① 2026 营收/亏损；② 客户集中度是否下降；③ 新一代芯片流片；④ 是否赴港上市；⑤ 与壁仞/沐曦的份额。\n\n## 信源与口径\n\n- 招股书：https://static.sse.com.cn/stock/disclosure/announcement/c/202509/002098_20250919_IP6Z.pdf\n- 2025 年报：https://www.21jingji.com/article/20260426/herald/bd6179a905d222e8ce86b4b3c9f5ea5e.html\n- IPO/市值：https://www.21jingji.com/article/20251205/herald/87ef9aff589eeb2e7e65abb094d614ff.html\n- 创始人：https://baike.baidu.com/item/%E5%BC%A0%E5%BB%BA%E4%B8%AD/60960388\n- 口径：财务为 2025 年报/媒体；员工数未披露；◐ 表示待核。' },
      { id: 'biren', name: '壁仞科技', def: '港股国产 GPU 第一股：BR10X 放量，2026 年登陆港交所。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2019 / 上海 | 招股书/官网 |\n| 上市地 / 代码 | 港交所 06082 | 2026-01-02 上市 |\n| 最新财年营收 | FY2025 ¥10.35 亿（+207.2%） | 2025 年报 |\n| 盈利 | 净亏 ¥164.93 亿（含优先股公允价值变动等） | 2025 年报 |\n| 现金流 | 待核 | ◐ |\n| 客户 | 前五大客户占比 97.9%（2025H1） | 招股书 |\n| 员工 | 约 842 人；研发 689 人（81.8%） | 年报推算 |\n| 市值 / 估值 | 约 HK$900–1,000 亿（上市首日 2026-01） | 媒体 |\n| 主要股东 | 张文 8.68%；上海壁立仞员工平台 | 招股书 |\n| 数据截至 | FY2025 年报；IPO 2026-01 | — |\n\n## 定位与沿革\n\n国产通用 GPU 厂商：以 BR100 系列切入训练/推理，2026-01 在港交所上市，成为「港股国产 GPU 第一股」；BR10X 放量带动 2025 年营收增长 207%。\n\n- 2019 年由张文（前商汤科技总裁，◐ 待核）在上海创立；核心团队来自 NVIDIA、AMD、华为等。\n- 2022 年发布首款通用 GPU BR100，号称创全球算力纪录；后续 BR10X 系列（BR106/BR166）量产。\n- 累计融资超 50 亿元；B+ 轮投后估值超 130 亿元；2025-08 Pre-IPO 轮 19 亿元，投后估值 209 亿元。\n- 2025-12 通过港交所聆讯，2026-01-02 上市（06082），首日大涨约 75%，市值一度 900–1,000 亿港元。\n- FY2025 营收 10.35 亿元（+207.2%），毛利 5.57 亿元（毛利率 53.8%），净亏 164.93 亿元（含优先股公允价值变动等非现金项目）。\n- 2026 上半年营收 12.36 亿元，同比增近 2000%；下一代 BR20X 计划 2026 年上市。\n\n## 创始人与管理层\n\n- **张文（创始人 & 董事长）**：曾任商汤科技总裁（◐ 待核）；直接持股 8.68%，与员工持股平台「上海壁立仞」构成单一最大股东。\n- 核心技术人员：洪洲、张凌岚等通过员工平台间接持股；具体履历待采集。\n- 董事会：张文 + 投资方；具体席位待核。\n- 关键人事变动：IPO 前后团队稳定；研发人员 689 人（81.8%）。\n\n## 商业模式\n\n- **收入结构**：智能计算解决方案（BR10X 系列 GPU 集群）占 99.3%；少数为 IP/服务。\n- **销售动作**：政企/运营商/智算中心项目制；中国移动是战略合作伙伴与重要客户。\n- **单位经济**：毛利率 53.8%（2025）；研发投入高，净亏损含优先股公允价值变动等非现金项。\n- **收入质量**：前五大客户 97.9%（2025H1），客户集中度极高；项目制波动大。\n- **定价趋势**：GPU 按卡/集群；BR20X 上市后可能提升单价与毛利。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| BR10X 系列 | 通用 GPU（训练/推理） | 按卡/集群 | 主力 |\n| BR100 | 首款通用 GPU（2022） | 按卡 | 主力（历史） |\n| BR20X | 下一代 GPU（2026 计划） | 按卡/集群 | 试验/增长 |\n| 智算集群 | 国产算力集群方案 | 按项目 | 主力 |\n| IP/服务 | 芯片 IP、技术支持 | 按项目 | 增长 |\n\n- 包装：GPU + 集群 + 软件栈；运营商/政企方案。\n- 路线图：BR20X（2026）、BR30X/BR31X；募资 85% 用于研发。\n\n## 技术栈与壁垒\n\n- **架构**：通用 GPU（GPGPU）+ 自研软件栈；支持大模型训练/推理。\n- **AI 路线**：BR10X/BR20X + 智算集群；与运营商/国产算力生态绑定。\n- **壁垒**：国产 GPU 先发、运营商客户、港股融资、研发团队；弱点：客户集中、软件生态、制程。\n- **依赖与债务**：先进制程/代工、出口管制、客户集中、亏损。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 中国移动 | 国产算力集群/智算 | 未披露具体数字 | 战略合作/大会 |\n| 前五大客户 | 智算解决方案 | 占营收 97.9%（2025H1） | 招股书 |\n| 政企/运营商 | 国产 GPU 替代 | 未披露具体数字 | 官网 |\n\n- 客户结构：运营商、政企、智算中心；2024/2025H1 特专科技客户 14/12 名。\n- 集中度：极高（97.9%）；项目制、客户数量少。\n- 续约/流失：待采集；BR20X 放量是客户扩张关键。\n\n## 商业进展\n\n- 2026-01-02 港交所上市（06082），首日 +75%，市值 900–1,000 亿港元；IPO 募资 40 多亿元。\n- FY2025 营收 10.35 亿元（+207.2%）、毛利率 53.8%、净亏 164.93 亿元。\n- 2026 上半年营收 12.36 亿元，同比增近 2000%；BR20X 计划 2026 年上市。\n- 2026 年又计划募资 70 亿元（媒体口径）；中国移动战略合作。\n- 竞争：摩尔线程、沐曦、寒武纪、海光、NVIDIA。\n\n## 经营业绩\n\n| 指标 | 2023 | 2024 | 2025 | 2026 H1 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | ¥0.62 亿 | ¥3.37 亿 | ¥10.35 亿 | ¥12.36 亿 | 2025 +207.2% |\n| 增速 | — | +444% | +207.2% | 近 +2000% | 高速 |\n| 毛利率 | 待核 | 待核 | 53.8% | 待核 | 改善 |\n| 营业利润 | 亏损 | 亏损 | 亏损 | 待核 | — |\n| 净利 | 亏损 | 亏损 | -¥164.93 亿 | 待核 | 含非现金项 |\n\n- 客户：前五大 97.9%（2025H1）；2024/2025H1 客户 14/12 名。\n- 研发：2025 年研发投入 +78.5%；研发人员 689 人（81.8%）。\n- 指引：BR20X 2026 年上市；盈利时间表待核。\n\n## 股权、融资与股票\n\n- 上市：港交所 06082；2026-01-02 IPO，首日 +75%。\n- 行情：市值一度 HK$900–1,000 亿；当前股价/市值待刷新（◐）。\n- 估值：PS 约 80–90x（按 2025 营收 10.35 亿人民币、市值 900–1,000 亿港元）；亏损，PE 不适用。\n- 股东：张文 8.68%；上海壁立仞员工平台；机构投资方。\n- 资本动作：IPO 募资 40 多亿元；2026 年计划再募 70 亿元（◐）。\n- 风险提示：高估值、客户集中、亏损、解禁。\n\n## 团队与人员\n\n- 员工约 842 人；研发 689 人（81.8%）；硕博超 75%，10 年以上经验近 240 人。\n- 上海总部；研发为主。\n- 招聘：2026 年 BR20X/软件岗位扩张；具体待采集。\n- 薪酬/股权激励：员工持股平台「上海壁立仞」；流失率未披露。\n- 组织：张文（董事长）；核心技术人员洪洲、张凌岚等。\n\n## 竞争格局\n\n- 直接竞品：摩尔线程、沐曦、寒武纪、海光信息、天数智芯。\n- 国际竞品：NVIDIA、AMD、Intel。\n- 差异：国产 GPU 先发、运营商客户、港股融资；弱点：客户集中、软件生态、制程。\n- 竞争动态：国产 GPU 集中上市，资本/订单竞争激烈；BR20X 是代际关键。\n- 份额：国产 GPU 第一梯队（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：客户集中（97.9%）、亏损、项目制波动、估值高。\n- 技术：BR20X 量产/性能、软件生态、先进制程/代工。\n- 法律/监管：出口管制、港股披露、信创合规。\n- 治理：创始人控制权、员工平台、解禁压力。\n- 争议：净亏 164.93 亿含非现金项，与经营亏损口径需区分（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：客户名单、BR20X 进度、员工数、盈利路径均未入库。建议跟踪：① BR20X 2026 量产；② 客户集中度；③ 2026 营收/亏损；④ 再融资；⑤ 与摩尔线程/沐曦的份额。\n\n## 信源与口径\n\n- 2025 年报：https://finance.sina.com.cn/jjxw/2026-03-31/doc-inhswxzn3164937.shtml\n- 亏损：https://wap.eastmoney.com/a/202604223713537746.html\n- IPO：https://m.ofweek.com/ai/2026-01/ART-201700-12001-30678046.html\n- 招股书：https://www1.hkexnews.hk/listedco/listconews/sehk/2025/1222/2025122200020_c.pdf\n- 口径：财务为 2025 年报；员工数为研发占比推算；市值/股价为上市初期媒体口径；◐ 表示待核。' },
      { id: 'metax', name: '沐曦', def: '国产 GPU 第二股：曦云 C 系列训推一体，2025 科创板上市。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2020 / 上海 | 招股书 |\n| 上市地 / 代码 | 科创板 688802 | 2025-12-17 上市 |\n| 最新财年营收 | FY2025 ¥16.44 亿（+121.26%） | 2025 年报 |\n| 盈利 | 归母净利 -¥7.89 亿（减亏约 44%） | 2025 年报 |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露具体名单；GPU 销量翻倍 | 年报 |\n| 员工 | 研发 652 人（2025-03-31）；总数待查 | 招股书/媒体 |\n| 市值 / 估值 | 约 ¥2,100 亿（2026-03）；上市初期一度 ¥3,000 亿 | 媒体 |\n| 主要股东 | 陈维良、和暄资本、Monolith 等 | 招股书 |\n| 数据截至 | FY2025 年报；IPO 2025-12 | — |\n\n## 定位与沿革\n\n国产训推一体 GPU 厂商：核心产品曦云 C500/C600 系列面向 AI 训练与推理，2025-12 科创板上市，被称为「国产 GPU 第二股」。\n\n- 2020 年由陈维良（前 AMD 高管）在上海创立；核心团队来自 AMD、NVIDIA 等。\n- 累计 8 轮融资、超 20 亿元；2024 年胡润独角兽榜估值约 100 亿元；Pre-IPO 投后估值约 210.71 亿元。\n- 2025-12-17 科创板上市（688802），发行价 104.66 元/股，募资约 41.86 亿元，首日高开 568%，市值一度突破 3,000 亿元。\n- FY2025 营收 16.44 亿元（+121.26%），归母净利 -7.89 亿元（减亏约 44%）；GPU 产品及配件销量翻倍。\n- 2026 年 3 月股价较峰值缩水约四成，市值约 2,100 亿元；下一代 C600 实现全国产工艺（媒体口径）。\n- 产品：曦云 C500/C600 训推一体 GPU、曦思系列；IP/技术服务收入占比较小。\n\n## 创始人与管理层\n\n- **陈维良（创始人 & CEO）**：曾任 AMD 高管；具体职务与履历待补。\n- 核心团队：来自 AMD、NVIDIA、Intel 等；具体名单待采集。\n- 董事会：陈维良 + 投资方；具体席位待核。\n- 关键人事变动：IPO 前研发团队「缩编」（媒体口径）；2026 年团队稳定。\n\n## 商业模式\n\n- **收入结构**：GPU 产品及配件为主（曦云 C 系列占近 98%）；IP/技术服务收入约 1.25%。\n- **销售动作**：政企/智算中心项目制 + 渠道；客户以国产算力集成商为主。\n- **单位经济**：2025 年毛利率待核；GPU 放量带动营收翻倍，亏损收窄。\n- **收入质量**：客户集中度未披露；GPU 销量翻倍，需求受国产替代驱动。\n- **定价趋势**：GPU 按卡/集群；C600 全国产工艺可能提升毛利与供应安全。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 曦云 C500 | 训推一体 GPU | 按卡 | 主力 |\n| 曦云 C600 | 下一代训推一体 GPU | 按卡/集群 | 增长 |\n| 曦思系列 | 推理 GPU | 按卡 | 增长 |\n| 智算集群 | 国产 GPU 集群方案 | 按项目 | 增长 |\n| IP/技术服务 | 芯片 IP、技术支持 | 按项目 | 增长 |\n\n- 包装：GPU + 集群 + 软件栈；政企/智算方案。\n- 路线图：C600 全国产工艺、下一代 GPU、软件生态。\n\n## 技术栈与壁垒\n\n- **架构**：训推一体 GPU（GPGPU）+ 自研软件栈；C600 全国产工艺。\n- **AI 路线**：曦云 C 系列支持大模型训练/推理；国产供应链是差异化。\n- **壁垒**：国产 GPU 第一梯队、AMD 系团队、科创板融资、国产工艺；弱点：客户集中、软件生态、亏损。\n- **依赖与债务**：先进制程/代工、出口管制、客户集中、研发投入。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 国产算力集成商 | 智算集群/训推一体 | 未披露具体数字 | 年报/媒体 |\n| 政企/智算中心 | 国产 GPU 替代 | 未披露具体数字 | 官网 |\n| IP/技术服务客户 | 芯片 IP 授权 | 收入 1,333.90 万元（+59.59%） | 年报 |\n\n- 客户结构：政企、智算中心、集成商；具体名单未披露。\n- 集中度：未披露；GPU 销量翻倍，客户数待采集。\n- 续约/流失：项目制；C600 放量是客户扩张关键。\n\n## 商业进展\n\n- 2025-12-17 科创板上市（688802），发行价 104.66 元，募资 41.86 亿元；首日 +568%，市值一度 3,000 亿元。\n- FY2025 营收 16.44 亿元（+121.26%）、归母净利 -7.89 亿元（减亏 44%）。\n- 2026 年 3 月市值约 2,100 亿元，股价较峰值缩水约四成；C600 全国产工艺。\n- 国产替代/信创是主要需求；GPU 销量翻倍。\n- 竞争：摩尔线程、壁仞科技、寒武纪、海光、NVIDIA。\n\n## 经营业绩\n\n| 指标 | 2023 | 2024 | 2025 | 说明 |\n|---|---|---|---|---|\n| 营收 | ¥0.53 亿 | ¥7.43 亿 | ¥16.44 亿 | +121.26% |\n| 增速 | — | +1302% | +121% | 高速 |\n| 毛利率 | 待核 | 待核 | 待核 | ◐ |\n| 营业利润 | 亏损 | 亏损 | 亏损 | — |\n| 归母净利 | 亏损 | -¥14.09 亿 | -¥7.89 亿 | 减亏 44% |\n\n- 研发：研发人员 652 人（2025-03-31）；研发投入待核。\n- 累计未弥补亏损 15.49 亿元。\n- 指引：未披露；盈利时间表待核。\n\n## 股权、融资与股票\n\n- 上市：科创板 688802；2025-12-17 IPO，发行价 ¥104.66。\n- 行情：上市初期市值一度 ¥3,000 亿；2026-03 约 ¥2,100 亿；当前待刷新（◐）。\n- 估值：PS 约 128x（按 2025 营收 16.44 亿、市值 2,100 亿）；亏损，PE 不适用。\n- 股东：陈维良、和暄资本、Monolith 砺思资本等；具体持股待核。\n- 资本动作：IPO 募资 41.86 亿元；是否再融资待采集。\n- 风险提示：高估值、亏损、客户集中、解禁。\n\n## 团队与人员\n\n- 研发 652 人（2025-03-31）；员工总数待查。\n- 上海总部；团队来自 AMD、NVIDIA、Intel。\n- 招聘：2026 年 C600/软件岗位扩张；具体待采集。\n- 薪酬/股权激励：科创板上市，有员工持股平台；流失率未披露。\n- 组织：陈维良（CEO）；核心高管名单待补。\n\n## 竞争格局\n\n- 直接竞品：摩尔线程、壁仞科技、寒武纪、海光信息、天数智芯。\n- 国际竞品：NVIDIA、AMD、Intel。\n- 差异：训推一体、AMD 系团队、C600 全国产工艺；弱点：客户集中、软件生态、亏损。\n- 竞争动态：国产 GPU 集中上市，资本/订单竞争激烈；全国产工艺是差异化。\n- 份额：国产 GPU 第一梯队（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：客户集中、亏损、估值高、项目制波动。\n- 技术：C600 量产/性能、软件生态、先进制程/代工。\n- 法律/监管：出口管制、科创板披露、信创合规。\n- 治理：创始人控制权、员工平台、解禁压力。\n- 争议：股价从峰值缩水四成，市场对高估值分歧（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：客户名单、C600 进度、员工总数、毛利率均未入库。建议跟踪：① C600 量产/全国产工艺；② 2026 营收/亏损；③ 客户集中度；④ 与摩尔线程/壁仞的份额；⑤ 股价/解禁。\n\n## 信源与口径\n\n- 2025 年报：https://www.cls.cn/detail/2326549\n- 营收/减亏：https://wallstreetcn.com/articles/3766370\n- IPO/市值：https://www.21jingji.com/article/20251217/herald/44bf9a236ee5f0c2b9e0ea8cf4ce5483.html\n- 研发人员：https://m.dzplus.dzng.com/share/general/0/NEWS2828935RMZSNUVVYPZVE\n- 口径：财务为 2025 年报；员工总数为待查；市值/股价为媒体口径；◐ 表示待核。' },
      { id: 'aws', name: 'AWS', def: '云计算定义者：EC2/S3 基本盘 + Trainium/Bedrock，AI 需求推动增长再加速。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2006 / 西雅图 | Amazon 子公司 |\n| 上市地 / 代码 | 不独立上市；母公司 Amazon（NASDAQ: AMZN） | 并表 |\n| 最新财年营收 | FY2025 约 $1,290 亿（Q1–Q4 汇总） | ◐ 待 10-K |\n| 盈利 | 营业利润率约 35%（◐） | 并表 |\n| 现金流 | 并表，未单独披露 | — |\n| 客户 | 未披露；数百万客户 | ◐ |\n| 员工 | 未单独披露；Amazon 全球约 150 万（含仓储） | ◐ |\n| 市值 / 估值 | 不适用；Amazon 市值约 $2.59 万亿（2026-11-02） | Macrotrends |\n| 主要股东 | Amazon 100% | 并表 |\n| 数据截至 | FY2025；行情 2026-11-02 | — |\n\n## 定位与沿革\n\n云计算的定义者：2006 年以 S3/EC2 开创公有云，现为全球 IaaS/PaaS 市场份额第一（约 29–30%）；AI 时代用 Trainium 自研芯片、Bedrock 模型平台与 SageMaker 构建第二增长曲线。\n\n- 2006 年推出 S3、EC2；Andy Jassy 领导 AWS 至 2021 年（后任 Amazon CEO）；Matt Garman 2024 年起任 AWS CEO。\n- 2025 年增长逐季加速：Q2 +18%、Q3 +20.2%、Q4 +24%；Trainium + Graviton 合计年化收入超 $100 亿。\n- 2026 年继续加速：Q2 +37%、Q3 +39.3%，为近五年最快；AWS AI 业务年化收入约 $250 亿（2026-08）。\n- Bedrock 从 2025 年初约占 AWS AI 收入 9% 升至 2026 年中约 37%；SemiAnalysis 估算 Bedrock 年化约 $55 亿。\n- re:Invent 2025：Trainium3 UltraServers、Graviton5、Bedrock AgentCore、Nova 2、AI Factories；Trainium 芯片部署超 100 万颗。\n\n## 创始人与管理层\n\n- **Andy Jassy（AWS 创始人/前 CEO）**：2003 年组建 AWS，2021 年升任 Amazon CEO。\n- **Matt Garman（AWS CEO，2024 起）**：此前负责 AWS 销售与市场；主导 AI/芯片战略。\n- **Werner Vogels（CTO）**：AWS 技术布道者与架构方向。\n- **Amazon 管理层**：Andy Jassy（CEO）、Brian Olsavsky（CFO，◐ 任期待核）。\n- 董事会：Amazon 董事会；AWS 无独立董事会。\n\n## 商业模式\n\n- **收入结构**：IaaS（EC2/S3/EBS）、PaaS（数据库/容器/分析）、AI（Bedrock/SageMaker/Trainium）、SaaS；按用量计费。\n- **销售动作**：自助注册 + 企业销售 + 合作伙伴/MSP；初创与大型企业并重。\n- **单位经济**：规模效应 + 自研芯片（Trainium/Graviton）降本；营业利润率约 35%。\n- **收入质量**：经常性用量收入；AI 训练/推理是增量；客户集中度低。\n- **定价趋势**：按秒/按 token/按实例；Bedrock 按 token；Trainium 按实例。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| EC2 | 云服务器/GPU 实例 | 按秒/实例 | 主力 |\n| S3/EBS | 对象/块存储 | 按 GB/请求 | 主力 |\n| Bedrock | 多模型 API/agent 平台 | 按 token | 增长 |\n| SageMaker | 模型训练/部署 | 按实例/用量 | 增长 |\n| Trainium | 自研 AI 训练芯片 | 按实例 | 增长 |\n| Graviton | 自研 ARM CPU | 按实例 | 主力 |\n| Lambda | Serverless | 按调用/时长 | 主力 |\n\n- 包装：按需/预留/Spot；企业折扣（EDP）。\n- 路线图：Trainium3、Bedrock AgentCore、Nova 2、AI Factories。\n\n## 技术栈与壁垒\n\n- **架构**：全球区域/可用区；自研芯片（Trainium/Graviton/Inferentia）；Nitro 虚拟化。\n- **AI 路线**：Bedrock 聚合第三方模型 + Nova 自研模型；Trainium 训练/推理；AgentCore agent 运行时。\n- **壁垒**：规模/区域覆盖、自研芯片成本、生态（数百万客户/ISV）、企业合同。\n- **依赖与债务**：AI capex 巨大；NVIDIA GPU 供应；Anthropic/OpenAI 等模型方关系。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| Anthropic | 模型训练/推理，AWS 战略投资 | 未披露具体数字 | 投资/合作 |\n| 大型企业/初创 | 云迁移、AI 应用 | 未披露具体数字 | 官网 |\n| Bedrock 客户 | 多模型 API/agent | Bedrock 年化约 $55 亿（◐） | SemiAnalysis |\n\n- 客户结构：初创、企业、政府、AI labs；数百万客户。\n- 集中度：未披露；AI labs 大单占比上升。\n- 续约/流失：EDP 长约；AI 用量增长是核心。\n\n## 商业进展\n\n- 2025 年增长逐季加速，Q4 +24%；Trainium+Graviton 年化超 $100 亿。\n- 2026 Q2 +37%、Q3 +39.3%；AI 业务年化约 $250 亿；Bedrock 占比升至约 37%。\n- re:Invent 2025 发布 Trainium3、Graviton5、Bedrock AgentCore、Nova 2、AI Factories。\n- 与 Anthropic 深度合作（投资 + 算力）；与 OpenAI 的云合作待核。\n- 竞争：Azure、Google Cloud、Oracle Cloud、阿里云。\n\n## 经营业绩\n\n| 指标 | 2023 | 2024 | 2025 | 2026 Q3 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | $908 亿 | $1,076 亿 | 约 $1,290 亿 | 待核 | 2025 汇总（◐） |\n| 增速 | +13% | +19% | +20% | +39.3% | 加速 |\n| 营业利润 | $246 亿 | $399 亿 | 约 $450 亿 | 待核 | 利润率约 35%（◐） |\n| 资本开支 | 高 | 高 | 极高 | 极高 | AI 数据中心 |\n\n- 运营指标：Trainium+Graviton 年化 >$100 亿；Bedrock 年化约 $55 亿（◐）；AI 业务年化约 $250 亿。\n- 指引：Amazon 未单独指引 AWS；2026 年 AI capex 继续上升。\n- 市场预期：AWS 增长再加速，AI 利润率与 capex 是焦点。\n\n## 股权、融资与股票\n\n- **不适用（业务单元）**：AWS 不独立上市；母公司 Amazon（AMZN）。\n- 行情（2026-11-02）：Amazon 股价约 $240；市值约 $2.59 万亿；52 周 $196–$287.20。\n- 估值：Amazon PE 约 30x（◐）；AWS 单独估值常按 10–15x 收入估算。\n- 股东：Amazon 100%；AWS 无独立股东。\n- 资本动作：Amazon 整体回购/分红；AWS capex 是主要资本去向。\n\n## 团队与人员\n\n- AWS 员工数未单独披露；Amazon 全球约 150 万（含仓储），AWS 为高毛利业务、人数占比低。\n- 研发/销售/支持结构待补；西雅图总部 + 全球区域团队。\n- 招聘：2026 年 AI/芯片/数据中心岗位扩张；具体待采集。\n- 薪酬/股权激励：Amazon RSU；AWS 销售有配额激励。\n- 组织：Matt Garman（CEO）；Werner Vogels（CTO）；服务团队按产品线划分。\n\n## 竞争格局\n\n- 直接竞品：Microsoft Azure、Google Cloud、Oracle Cloud、阿里云、腾讯云。\n- 替代方案：私有云、托管数据中心、边缘云。\n- 差异：规模/区域、自研芯片、Bedrock 多模型、生态；弱点：成本复杂度、AI 利润率、反垄断。\n- 竞争动态：Azure 靠 OpenAI/Copilot；GCP 靠 TPU/Gemini；Oracle 靠数据库/GPU 集群。\n- 份额：全球云基础设施约 29–30%，第一（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：AI capex 回报周期、客户优化成本、竞争加剧。\n- 技术：Trainium 生态、Bedrock 模型依赖、GPU 供应。\n- 法律/监管：反垄断、数据主权、AI 监管。\n- 治理：Amazon 整体治理；AWS 管理层变动。\n- 争议：AI 资本开支是否过度、Bedrock 利润率（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：AWS 单独财务、Trainium 出货、Bedrock ARR、客户名单均未入库。建议跟踪：① AWS 增速；② Trainium/Bedrock 收入；③ AI capex；④ 与 Azure/GCP 的份额；⑤ Anthropic/OpenAI 合作。\n\n## 信源与口径\n\n- Q4/FY2025：https://ir.aboutamazon.com/quarterly-results/default.aspx\n- AWS Q3 2026：https://www.cnbc.com/2025/10/30/aws-q3-2025-earnings-report-amazon-cloud.html\n- Matt Garman 表态：https://www.linkedin.com/posts/mattgarman_q4-closed-out-a-year-of-continued-customer-activity-7425606633122304000-5NYD\n- Bedrock 分析：https://newsletter.semianalysis.com/p/anthropic-growth-and-bedrock-mix\n- 行情：https://finance.yahoo.com/quote/AMZN/\n- 口径：AWS 单独收入为季度汇总；利润率为估算；◐ 表示待核。' },
      { id: 'azure', name: 'Microsoft Azure', def: '企业云与 OpenAI 生态的结合体：Azure 收入 FY2026 破千亿美元。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2010 / Redmond | Microsoft 子公司 |\n| 上市地 / 代码 | 不独立上市；母公司 Microsoft（NASDAQ: MSFT） | 并表 |\n| 最新财年营收 | Azure FY2026 >$1,000 亿（+41%） | 2026-07-29 发布 |\n| 盈利 | 并表；Microsoft FY2026 净利 $1,337 亿 | 2026 年报 |\n| 现金流 | 并表，未单独披露 | — |\n| 客户 | 未披露；企业/政府/OpenAI | ◐ |\n| 员工 | 未单独披露；Microsoft 约 22.8 万（◐） | — |\n| 市值 / 估值 | Microsoft 约 $3.88 万亿（2026-11） | CompaniesMarketCap |\n| 主要股东 | Microsoft 100% | 并表 |\n| 数据截至 | FY2026（2026-06-30）；Q1 FY2027 | — |\n\n## 定位与沿革\n\n企业云与 OpenAI 生态的结合体：Azure 提供 IaaS/PaaS、AI Foundry、OpenAI Service 与 Copilot 底座；FY2026 Azure 收入首次突破 $1,000 亿，Q1 FY2027 单季 $332 亿（+48%）。\n\n- 2010 年正式推出 Azure；Satya Nadella 2014 年任 CEO 后转向「云优先 + AI 优先」。\n- 与 OpenAI 的深度合作（投资 + 独家云/模型服务）让 Azure 成为企业接入 GPT 系列的主要通道。\n- FY2025 Microsoft 营收 $2,817 亿（+15%），Azure 首次突破 $750 亿（+34%）。\n- FY2026 Microsoft 营收 $3,318 亿（+16%）、净利 $1,337 亿（+31%）；Azure 突破 $1,000 亿（+41%）。\n- Q1 FY2027（2026-09 季）：Microsoft 营收 $923 亿（+19%），Azure $332 亿（+48%），超预期。\n- AI Foundry、Copilot、Fabric 是 AI 商业化的主要载体；capex 持续处于高位。\n\n## 创始人与管理层\n\n- **Satya Nadella（Microsoft CEO）**：2014 年上任，主导云与 AI 转型；2026 年仍任 CEO。\n- **Scott Guthrie（Cloud + AI 负责人）**：长期负责 Azure 与 AI 平台（◐ 头衔待核）。\n- **Amy Hood（CFO）**：Microsoft 财务负责人。\n- **Bill Gates/Paul Allen（Microsoft 创始人）**：公司历史；与 Azure 日常经营无关。\n- 董事会：Microsoft 董事会；Azure 无独立董事会。\n\n## 商业模式\n\n- **收入结构**：Azure 消费（IaaS/PaaS）、AI 服务、企业订阅（Microsoft 365/Windows）、Copilot。\n- **销售动作**：企业协议（EA）/云解决方案提供商（CSP）+ 直销；与 OpenAI 绑定。\n- **单位经济**：Azure 毛利率受 AI capex/折旧影响；Microsoft 整体营业利润率约 45%（◐）。\n- **收入质量**：企业长约、订阅为主；AI 消费增长快但毛利较低。\n- **定价趋势**：按用量（VM/存储/token）+ 订阅（Copilot/Foundry）。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| Azure Compute | VM/GPU（ND/NC 系列） | 按用量 | 主力 |\n| Azure AI Foundry | 模型目录/agent/评测 | 按 token/用量 | 增长 |\n| Azure OpenAI Service | GPT 系列企业接入 | 按 token | 主力 |\n| Microsoft Fabric | 数据分析平台 | 按容量 | 增长 |\n| Azure Arc | 混合云管理 | 按资源 | 增长 |\n| Copilot | M365/GitHub 等 AI 助手 | 按席位 | 增长 |\n\n- 包装：Azure 消费 + Microsoft 365/Copilot 订阅；企业协议捆绑。\n- 路线图：AI Foundry、agent、Copilot 全家桶、自研芯片（Maia/Cobalt）。\n\n## 技术栈与壁垒\n\n- **架构**：全球区域 + 企业级网络；NVIDIA GPU 集群 + 自研 Maia/Cobalt（◐ 规模待核）。\n- **AI 路线**：OpenAI 模型 + 开源模型目录 + AI Foundry；Copilot 分发。\n- **壁垒**：企业客户/渠道、OpenAI 关系、Microsoft 365 分发、合规认证。\n- **依赖与债务**：OpenAI 关系变化、AI capex、反垄断、云竞争。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| OpenAI | 模型训练/推理云 | 未披露具体数字 | 合作 |\n| 大型企业/政府 | 云迁移、Copilot | 未披露具体数字 | 官网 |\n| AI Foundry 客户 | 模型/agent 开发 | 未披露具体数字 | 官网 |\n\n- 客户结构：企业、政府、AI labs；全球覆盖。\n- 集中度：未披露；OpenAI 相关收入占比是市场关注点。\n- 续约/流失：企业协议长约；Copilot 渗透是增量。\n\n## 商业进展\n\n- FY2026 Azure 收入 >$1,000 亿（+41%）；Q1 FY2027 Azure $332 亿（+48%）。\n- AI Foundry、Copilot、Fabric 是 2026 年主推；OpenAI 合作持续。\n- Microsoft FY2026 营收 $3,318 亿、净利 $1,337 亿；capex 高位。\n- 与 OpenAI 的关系（投资/云独家）是估值核心；具体条款待核。\n- 竞争：AWS、Google Cloud、Oracle Cloud、阿里云。\n\n## 经营业绩\n\n| 指标 | FY2024 | FY2025 | FY2026 | Q1 FY2027 | 说明 |\n|---|---|---|---|---|---|\n| Microsoft 营收 | $2,451 亿 | $2,817 亿 | $3,318 亿 | $923 亿 | FY2026 +16% |\n| Microsoft 净利 | $881 亿 | $1,018 亿 | $1,337 亿 | 待核 | FY2026 +31% |\n| Azure 收入 | 未披露 | >$750 亿 | >$1,000 亿 | $332 亿 | +34%/+41%/+48% |\n| Azure 增速 | +30% | +34% | +41% | +48% | 加速 |\n\n- 运营指标：Azure 占比、AI 收入、Copilot 席位未单独披露。\n- 指引：Microsoft 未单独指引 Azure；AI capex 继续上升。\n- 市场预期：Azure 增速与 OpenAI 关系是核心。\n\n## 股权、融资与股票\n\n- **不适用（业务单元）**：Azure 不独立上市；母公司 Microsoft（MSFT）。\n- 行情（2026-11）：MSFT 股价约 $522；市值约 $3.88 万亿；P/E 约 27.25；52 周高 $551.15。\n- 估值：Microsoft PE 27x；Azure 单独估值常按 10–15x 收入。\n- 股东：Microsoft 100%；Azure 无独立股东。\n- 资本动作：Microsoft 分红/回购；Azure capex 是主要资本去向。\n\n## 团队与人员\n\n- Azure 员工数未单独披露；Microsoft 全球约 22.8 万（◐）。\n- 研发/销售/支持结构待补；Redmond 总部 + 全球区域。\n- 招聘：2026 年 AI/云岗位扩张；具体待采集。\n- 薪酬/股权激励：Microsoft RSU；销售配额激励。\n- 组织：Satya Nadella（CEO）、Scott Guthrie（Cloud+AI）、Amy Hood（CFO）。\n\n## 竞争格局\n\n- 直接竞品：AWS、Google Cloud、Oracle Cloud、阿里云、IBM Cloud。\n- 替代方案：私有云、托管数据中心。\n- 差异：企业渠道、OpenAI/Copilot、Microsoft 365 分发；弱点：AI capex、OpenAI 依赖、反垄断。\n- 竞争动态：AWS 自研芯片/Bedrock；GCP TPU/Gemini；Oracle GPU 集群。\n- 份额：全球云基础设施约 20–21%，第二（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：AI capex 回报、OpenAI 关系、云竞争、企业预算。\n- 技术：自研芯片进度、AI Foundry 可靠性、数据安全。\n- 法律/监管：反垄断、数据主权、AI 监管。\n- 治理：Microsoft 董事会；OpenAI 治理冲突的外溢。\n- 争议：OpenAI 依赖与 AI 投资回报（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：Azure 单独收入/利润、OpenAI 贡献、Copilot 渗透均未入库。建议跟踪：① Azure 增速；② AI Foundry/Copilot 收入；③ OpenAI 关系；④ capex；⑤ 与 AWS/GCP 的份额。\n\n## 信源与口径\n\n- FY2025 年报：https://www.microsoft.com/investor/reports/ar25/index.html\n- FY2026 年报：https://www.microsoft.com/investor/reports/ar26/index.html\n- Q1 FY2027：https://www.geekwire.com/2026/microsoft-azure-revenue-surges-48-to-33-2b-beating-expectations-as-cloud-and-ai-demand-grows/\n- 行情：https://companiesmarketcap.com/microsoft/marketcap/\n- 口径：Azure 收入为公司披露；Microsoft 员工数为第三方；◐ 表示待核。' },
      { id: 'gcp', name: 'Google Cloud', def: 'TPU + Gemini 的差异化云：2026 年增速与利润率同步跃升。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2008 / Mountain View | Alphabet 子公司 |\n| 上市地 / 代码 | 不独立上市；母公司 Alphabet（NASDAQ: GOOGL） | 并表 |\n| 最新财年营收 | 2025 约 $580 亿（季度汇总，◐）；2026 Q3 单季 $307.1 亿 | Alphabet 财报 |\n| 盈利 | 2026 Q3 营业利润 $111.2 亿（+209%） | Alphabet 财报 |\n| 现金流 | 并表，未单独披露 | — |\n| 客户 | 未披露；企业/AI labs | ◐ |\n| 员工 | 未单独披露；Alphabet 约 19 万（◐） | — |\n| 市值 / 估值 | Alphabet 约 $3.42–3.49 万亿（2026-11） | Macrotrends |\n| 主要股东 | Alphabet 100% | 并表 |\n| 数据截至 | 2026 Q3；行情 2026-11-02 | — |\n\n## 定位与沿革\n\n以 TPU + Gemini 差异化的公有云：从 IaaS/PaaS 扩展到 AI 平台（Vertex AI）、数据分析（BigQuery）与 Workspace；2026 年 Q3 营收同比 +103%、营业利润 +209%，增速与利润率同步跃升。\n\n- 2008 年推出 Google Cloud；Diane Greene 等首任负责人；Thomas Kurian 2019 年起任 CEO。\n- 2024 年 Google Cloud 营收约 $430 亿（+30%）；2025 年约 $580 亿（◐ 季度汇总）。\n- 2026 年加速：Q2 营收约 $247.7 亿（+82%）；Q3 营收 $307.1 亿（+103%）、营业利润 $111.2 亿（+209%）。\n- TPU 是核心差异化：Gemini 训练/推理 + 对外 TPU 租赁；Vertex AI 提供模型/agent 平台。\n- 与 Anthropic 的合作/投资是 AI 云需求的重要来源（◐ 条款待核）。\n- 全球云基础设施份额约 12–13%，第三。\n\n## 创始人与管理层\n\n- **Thomas Kurian（Google Cloud CEO，2019 起）**：前 Oracle 产品开发总裁；主导企业化与 AI 转型。\n- **Sundar Pichai（Alphabet CEO）**：整体战略与 AI 投资。\n- **Diane Greene（首任 Google Cloud CEO，2015–2018）**：整合云业务。\n- **Urs Hölzle（技术基础设施负责人）**：数据中心/TPU 体系（◐ 任期待核）。\n- 董事会：Alphabet 董事会；Google Cloud 无独立董事会。\n\n## 商业模式\n\n- **收入结构**：Google Cloud Platform（IaaS/PaaS）、Google Workspace、AI/TPU 服务；按用量/订阅。\n- **销售动作**：企业销售 + 合作伙伴；AI labs 大单 + 企业迁移。\n- **单位经济**：2026 Q3 营业利润率约 36%；TPU 自研降低推理成本。\n- **收入质量**：企业长约 + AI 消费；Workspace 订阅稳定。\n- **定价趋势**：按用量/TPU 小时/token；Gemini API 按 token。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| Compute Engine/GKE | VM/容器 | 按用量 | 主力 |\n| BigQuery | 数据仓库/分析 | 按查询/存储 | 主力 |\n| Vertex AI | 模型/agent 平台 | 按用量 | 增长 |\n| TPU | 自研 AI 芯片/租赁 | 按小时 | 增长 |\n| Gemini | 多模态模型 API | 按 token | 增长 |\n| Workspace | 办公协作 | 按席位 | 主力 |\n\n- 包装：GCP 消费 + Workspace 订阅；企业协议。\n- 路线图：TPU 下一代、Gemini、Agent Builder、AI 基础设施。\n\n## 技术栈与壁垒\n\n- **架构**：全球数据中心 + TPU/GPU；GKE/Kubernetes 原生。\n- **AI 路线**：Gemini + Vertex AI + TPU；从训练到推理全栈。\n- **壁垒**：TPU 成本/性能、BigQuery 数据生态、Kubernetes、Gemini。\n- **依赖与债务**：AI capex、TPU 对外供应、企业销售能力、反垄断。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| Anthropic | 模型训练/推理、TPU | 未披露具体数字 | 合作/投资 |\n| 大型企业 | 数据/云迁移、Gemini | 未披露具体数字 | 官网 |\n| AI 初创 | Vertex AI/TPU | 未披露具体数字 | 官网 |\n\n- 客户结构：企业、AI labs、开发者；全球覆盖。\n- 集中度：未披露；AI labs 大单占比上升。\n- 续约/流失：企业长约；AI 消费增长是核心。\n\n## 商业进展\n\n- 2026 Q3 营收 $307.1 亿（+103%）、营业利润 $111.2 亿（+209%），增速/利润率双升。\n- TPU 需求「extraordinary」；Gemini/Vertex AI 是增长引擎。\n- 与 Anthropic 的云/芯片合作深化；企业客户支出增加约 50%（Kurian 口径）。\n- Alphabet 2026 年资本开支高位；云业务是 AI 投资的主要承接方。\n- 竞争：AWS、Azure、Oracle Cloud、阿里云。\n\n## 经营业绩\n\n| 指标 | 2023 | 2024 | 2025 | 2026 Q3 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | $331 亿 | $430 亿 | 约 $580 亿 | $307.1 亿 | 2026 Q3 +103% |\n| 增速 | +26% | +30% | 约 +35% | +103% | 加速 |\n| 营业利润 | 亏损/微利 | 约 $60 亿 | 待核 | $111.2 亿 | 2026 Q3 +209% |\n| 营业利润率 | 负/低 | 约 14% | 待核 | 约 36% | 改善 |\n\n- 运营指标：TPU 部署、Gemini API 用量、企业客户数未单独披露。\n- 指引：Alphabet 未单独指引 Google Cloud；capex 继续上升。\n- 市场预期：TPU/Gemini 驱动份额提升。\n\n## 股权、融资与股票\n\n- **不适用（业务单元）**：Google Cloud 不独立上市；母公司 Alphabet（GOOGL）。\n- 行情（2026-11-02）：GOOGL 约 $279.84；市值约 $3.42–3.49 万亿；P/E 约 14.6。\n- 估值：Alphabet PE 14.6x；Google Cloud 单独估值常按 8–12x 收入。\n- 股东：Alphabet 100%；Google Cloud 无独立股东。\n- 资本动作：Alphabet 分红/回购；云 capex 是主要资本去向。\n\n## 团队与人员\n\n- Google Cloud 员工数未单独披露；Alphabet 约 19 万（◐）。\n- 研发/销售/支持结构待补；Mountain View 总部 + 全球区域。\n- 招聘：2026 年 AI/TPU/云岗位扩张；具体待采集。\n- 薪酬/股权激励：Alphabet RSU；销售配额激励。\n- 组织：Thomas Kurian（CEO）；Sundar Pichai（Alphabet CEO）。\n\n## 竞争格局\n\n- 直接竞品：AWS、Microsoft Azure、Oracle Cloud、阿里云、IBM Cloud。\n- 替代方案：私有云、托管数据中心。\n- 差异：TPU、BigQuery、Kubernetes、Gemini；弱点：企业销售、份额第三、capex。\n- 竞争动态：AWS 自研芯片/Bedrock；Azure OpenAI/Copilot；Oracle GPU 集群。\n- 份额：全球云基础设施约 12–13%，第三（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：AI capex、企业销售、云竞争、客户集中。\n- 技术：TPU 供应、Gemini 可靠性、Vertex AI 生态。\n- 法律/监管：反垄断、数据主权、AI 监管。\n- 治理：Alphabet 董事会；AI 投资回报。\n- 争议：AI 收入/利润的可持续性（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：Google Cloud 单独利润、TPU 出货、Gemini 收入均未入库。建议跟踪：① 云增速；② TPU 对外供应；③ Gemini/Vertex AI 收入；④ capex；⑤ 与 AWS/Azure 的份额。\n\n## 信源与口径\n\n- Google Cloud Q3 2026：https://www.crn.com/news/cloud/2026/google-cloud-sales-explode-103-percent-as-ceo-touts-tpu-extraordinary-demand\n- Kurian 采访：https://www.cnbc.com/2026/07/23/google-cloud-kurian-revenue-earnings.html\n- 行情：https://companiesmarketcap.com/alphabet-google/marketcap/\n- 口径：Google Cloud 收入为季度披露；2025 全年为季度汇总；◐ 表示待核。' },
      { id: 'coreweave', name: 'CoreWeave', def: 'GPU 专项云：从加密矿场转型 AI 算力，2025 年营收 $51 亿。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2017 / 新泽西 Livingston（◐） | Wikipedia |\n| 上市地 / 代码 | NASDAQ: CRWV | 2025-03 IPO |\n| 最新财年营收 | FY2025 $51 亿（+168%） | 2026-02-26 发布 |\n| 盈利 | FY2025 净亏；2026 季度营业利润转正、净亏仍存 | ◐ |\n| 现金流 | 待核（重资产/债务） | ◐ |\n| 客户 | 未披露；Microsoft、OpenAI、Meta 等 | 媒体 |\n| 员工 | 未披露 | — |\n| 市值 / 估值 | 约 $251–303 亿（2026-11） | Macrotrends/Yahoo |\n| 主要股东 | 创始人/PE、机构 | ◐ |\n| 数据截至 | FY2025；行情 2026-11-02 | — |\n\n## 定位与沿革\n\nGPU 专项云：从加密矿场转型 AI 算力租赁，提供 NVIDIA GPU 裸金属/集群、推理与存储；以「最快达到 $50 亿年收入」的云公司叙事上市。\n\n- 2017 年由 Michael Intrator（CEO）、Brian Venturo、Brannin McBee、Peter Salanki 创立；早期做加密挖矿，后转向 GPU 云。\n- 2025-03 在纳斯达克上市（CRWV）；NVIDIA 是投资方/供应商（◐）。\n- FY2025 营收 $51 亿（2024 $19 亿、2023 $2.29 亿），同比增长约 168%；CEO 称「史上最快达到 $50 亿年收入的云」。\n- 2026 Q1 营收 $20.8 亿，新增客户承诺 $400 亿；Q2 营收约 $26 亿（+112%），backlog 约 $1,040 亿，营业利润 $1.28 亿、净亏 $6.26 亿。\n- 2026 年指引营收 $120–130 亿，年底 run-rate 下限 $180 亿；客户包括 Microsoft、OpenAI、Meta。\n\n## 创始人与管理层\n\n- **Michael Intrator（联合创始人、董事长 & CEO）**：前量化/能源交易背景（◐ 待核）。\n- **Brian Venturo（联合创始人 & CTO）**：技术架构。\n- **Brannin McBee（联合创始人 & 首席战略官）**：资本/战略。\n- **Peter Salanki（联合创始人）**：工程/基础设施。\n- 董事会：创始人 + 投资方；NVIDIA 关系待核。\n\n## 商业模式\n\n- **收入结构**：GPU 云租赁（裸金属/集群/推理）+ 存储/网络；长期合同为主。\n- **销售动作**：大客户直销（AI labs/云厂商）+ 合同承诺；backlog 是核心指标。\n- **单位经济**：重资产、高债务；GPU 折旧与电价是关键；营业利润率转正但净亏。\n- **收入质量**：backlog $1,040 亿；客户集中度高（Microsoft/OpenAI/Meta）。\n- **定价趋势**：按 GPU 小时/合同承诺；推理按 token/用量。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| GPU 云 | NVIDIA H100/H200/GB200 集群 | 按 GPU 小时/合同 | 主力 |\n| 推理云 | 模型推理/agent | 按 token/用量 | 增长 |\n| 存储/网络 | 高性能存储、InfiniBand | 按用量 | 主力 |\n| 托管 Kubernetes | GPU 集群编排 | 按集群 | 增长 |\n| 预留容量 | 长期合同/预留 | 按合同 | 主力 |\n\n- 包装：按需/预留/长期合同；大客户定制集群。\n- 路线图：GW 级数据中心、推理、欧洲扩张。\n\n## 技术栈与壁垒\n\n- **架构**：NVIDIA GPU 集群 + InfiniBand + Kubernetes；自建/租赁数据中心。\n- **AI 路线**：训练/推理算力；与 NVIDIA 深度绑定。\n- **壁垒**：GPU 供应/集群规模、长期合同、backlog、上市融资；弱点：客户集中、债务、GPU 折旧。\n- **依赖与债务**：NVIDIA 供应、债务融资、电价/数据中心、客户集中。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| Microsoft | GPU 算力/云 | 未披露具体数字 | 媒体 |\n| OpenAI | 模型训练/推理 | 未披露具体数字 | 媒体 |\n| Meta | AI 算力 | 未披露具体数字 | 媒体 |\n\n- 客户结构：AI labs、云厂商、企业；集中度极高。\n- 集中度：Microsoft/OpenAI/Meta 等大客户占比高（◐）。\n- 续约/流失：长期合同/backlog；客户续约是关键。\n\n## 商业进展\n\n- 2025-03 上市；FY2025 营收 $51 亿（+168%）。\n- 2026 Q1 营收 $20.8 亿、新增承诺 $400 亿；Q2 营收约 $26 亿、backlog $1,040 亿。\n- 2026 年指引营收 $120–130 亿，年底 run-rate 下限 $180 亿。\n- GW 级数据中心/欧洲扩张；债务融资支持 capex。\n- 竞争：AWS/Azure/GCP、Lambda、Crusoe、Nebius。\n\n## 经营业绩\n\n| 指标 | 2023 | 2024 | 2025 | 2026 Q2 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | $2.29 亿 | $19 亿 | $51 亿 | 约 $26 亿 | 2025 +168%；Q2 +112% |\n| 增速 | — | +730% | +168% | +112% | 高速 |\n| 毛利率 | 待核 | 待核 | 待核 | 待核 | 重资产 |\n| 营业利润 | 亏损 | 亏损 | 亏损 | $1.28 亿 | 转正 |\n| 净利 | 亏损 | 亏损 | 亏损 | -$6.26 亿 | 利息/折旧 |\n\n- 运营指标：backlog $1,040 亿；活跃容量 >1GW；客户承诺 $400 亿（Q1 2026）。\n- 指引：2026 营收 $120–130 亿；年底 run-rate 下限 $180 亿。\n- 市场预期：AI 算力需求 vs 债务/客户集中。\n\n## 股权、融资与股票\n\n- 上市：NASDAQ CRWV；2025-03 IPO。\n- 行情（2026-11）：股价约 $55；市值约 $251–303 亿；52 周区间待补（◐）。\n- 估值：PS 约 5–6x（按 2025 营收 51 亿、市值 250–300 亿）；2026 指引 PS 约 2x。\n- 股东：创始人/PE、机构；NVIDIA 投资待核。\n- 资本动作：债务融资/数据中心 capex；IPO 后是否有增发待查。\n- 风险提示：高杠杆、客户集中、GPU 折旧。\n\n## 团队与人员\n\n- 员工数未披露；工程/数据中心/销售团队。\n- 总部新泽西；数据中心遍布美国/欧洲。\n- 招聘：2026 年 GW 级数据中心扩张；具体待采集。\n- 薪酬/股权激励：上市公司 RSU；流失率未披露。\n- 组织：Michael Intrator（CEO）、Brian Venturo（CTO）、Brannin McBee（CSO）。\n\n## 竞争格局\n\n- 直接竞品：AWS、Azure、GCP（GPU 实例）、Lambda、Crusoe、Nebius、Together AI。\n- 替代方案：自建 GPU 集群、其他 neo-cloud。\n- 差异：GPU 专项规模/速度、长期合同、NVIDIA 关系；弱点：客户集中、债务、折旧。\n- 竞争动态：hyperscaler 扩产；neo-cloud 价格/容量竞争。\n- 份额：GPU 云细分领先（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：客户集中、债务/利息、GPU 折旧、AI 需求波动。\n- 技术：GPU 代际更替、数据中心交付、网络。\n- 法律/监管：证券披露、数据安全、能源。\n- 治理：创始人控制、债务契约。\n- 争议：高杠杆扩张与「AI 泡沫」质疑（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：员工数、客户合同、债务结构、GPU 利用率均未入库。建议跟踪：① backlog 转化；② 2026 营收/run-rate；③ 客户集中度；④ 债务/利息；⑤ GPU 折旧。\n\n## 信源与口径\n\n- FY2025：https://investors.coreweave.com/news/news-details/2026/CoreWeave-Reports-Strong-Fourth-Quarter-and-Fiscal-Year-2025-Results/default.aspx\n- Q1 2026：https://investors.coreweave.com/news/news-details/2026/CoreWeave-Reports-Strong-First-Quarter-2026-Results/\n- 10-K：https://www.sec.gov/Archives/edgar/data/1769628/000176962826000104/crwv-20251231.htm\n- 行情：https://www.macrotrends.net/stocks/charts/CRWV/coreweave/market-cap\n- 口径：财务为公司披露；员工数未披露；◐ 表示待核。' },
      { id: 'alicloud', name: '阿里云', def: '中国公有云第一：飞天 + 通义 + 百炼，AI 收入占比突破 30%。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2009 / 杭州 | 阿里巴巴子公司 |\n| 上市地 / 代码 | 不独立上市；母公司 阿里巴巴（HK 9988 / NYSE BABA） | 并表 |\n| 最新财年营收 | FY2026 云智能约 ¥1,300 亿（◐ 汇总）；外部商业化收入首破 ¥1,000 亿 | 阿里财报 |\n| 盈利 | 云智能利润占比待核；集团 FY2026 经调整净利承压 | ◐ |\n| 现金流 | 并表 | — |\n| 客户 | 未披露；中国 IaaS 份额 32.8% | Gartner |\n| 员工 | 集团约 13 万；阿里云单列未披露 | 阿里财报 |\n| 市值 / 估值 | 阿里巴巴约 HK$1.98 万亿 / $2,460 亿（2026-11-02） | Yahoo/Bloomberg |\n| 主要股东 | 阿里巴巴 100% | 并表 |\n| 数据截至 | FY2026；行情 2026-11-02 | — |\n\n## 定位与沿革\n\n中国公有云第一：以飞天操作系统、ECS/灵骏智算、百炼 MaaS 与通义大模型构成全栈；FY2026 外部商业化收入首破 ¥1,000 亿，AI 相关收入占比约 30%。\n\n- 2009 年成立，王坚主导飞天；现为阿里巴巴集团云智能集团，吴泳铭任集团 CEO。\n- Gartner 2025 中国 IaaS 市场份额 32.8%，第一（2024 年 30.1%）；IDC/Omdia 多项中国 AI 云/数据平台份额第一。\n- FY2026：Q3 云智能收入 ¥432.84 亿（+36%）、Q4 ¥416.26 亿（+38%）；外部商业化收入增速约 40%。\n- 截至 2026-02，阿里云 FY2026 外部商业化收入首破 ¥1,000 亿；AI 相关产品收入连续 11 个季度三位数增长，AI ARR 突破 ¥358 亿，占外部商业化收入约 30%。\n- 吴泳铭提出未来五年「云 + AI」年收入突破 $1,000 亿；MaaS 收入将超过 IaaS。\n- 集团 FY2025 营收 ¥9,963 亿；员工 124,320（2025-03），2026-03 约 13 万。\n\n## 创始人与管理层\n\n- **吴泳铭（阿里巴巴集团 CEO）**：2023 年起任集团 CEO，兼任云智能集团负责人；主导「用户为先、AI 驱动」战略。\n- **王坚（阿里云创始人/首任总裁）**：中国工程院院士，主导飞天。\n- **蒋凡/其他合伙人**：电商与云协同；具体分工待核。\n- 董事会：阿里巴巴董事会；阿里云无独立董事会。\n- 关键人事变动：2023 年组织变革后，吴泳铭集权；云业务管理层调整待采集。\n\n## 商业模式\n\n- **收入结构**：IaaS（ECS/存储/网络）、PaaS（数据库/大数据）、MaaS（百炼/通义 API）、行业解决方案。\n- **销售动作**：企业直销 + 渠道/生态；政企、金融、互联网、AI 初创。\n- **单位经济**：IaaS 毛利低、规模效应强；MaaS/AI 毛利更高；资本开支高。\n- **收入质量**：外部商业化收入 >¥1,000 亿；AI 收入占比约 30%；客户数未披露。\n- **定价趋势**：按量/订阅；通义 API 大幅降价；MaaS 按 token。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| ECS | 云服务器/GPU 实例 | 按量/包年 | 主力 |\n| 灵骏 | 智算集群 | 按集群/项目 | 增长 |\n| 百炼 | MaaS/模型 API/agent | 按 token | 增长 |\n| 通义千问 | 开源/闭源大模型 | 按 token/免费 | 主力 |\n| PolarDB/OSS | 数据库/存储 | 按量/订阅 | 主力 |\n| 无影/钉钉 | 云电脑/协同 | 按席位 | 增长 |\n\n- 包装：IaaS + PaaS + MaaS；政企/AI 方案。\n- 路线图：AI 算力、MaaS、通义、全球化。\n\n## 技术栈与壁垒\n\n- **架构**：飞天操作系统 + 自研芯片（含光/倚天，◐）+ 数据中心；公共云/混合云。\n- **AI 路线**：通义大模型 + 百炼 MaaS + 灵骏智算；开源生态（Qwen）。\n- **壁垒**：中国市场份额、飞天/自研芯片、政企渠道、Qwen 开源生态。\n- **依赖与债务**：美国芯片出口限制、价格战、资本开支、集团盈利压力。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 中国大型企业/政企 | 云迁移、AI 平台 | 未披露具体数字 | 官网 |\n| AI 初创 | 百炼/通义 API | 未披露具体数字 | 官网 |\n| 金融机构 | 混合云/数据库 | 未披露具体数字 | 官网 |\n\n- 客户结构：互联网、金融、政企、AI 初创；中国 IaaS 份额 32.8%。\n- 集中度：未披露；大客户与政企占比高。\n- 续约/流失：企业长约；AI 用量增长是核心。\n\n## 商业进展\n\n- FY2026 云智能增速回升至 36–38%；外部商业化收入首破 ¥1,000 亿。\n- AI ARR ¥358 亿、占外部商业化收入约 30%；连续 11 个季度三位数增长。\n- 吴泳铭提出五年云+AI 年收入 $1,000 亿；MaaS 超过 IaaS。\n- 集团 FY2026 资本开支创历史新高；通义开源生态扩张。\n- 竞争：华为云、腾讯云、火山引擎、百度智能云、AWS/Azure。\n\n## 经营业绩\n\n| 指标 | FY2024 | FY2025 | FY2026 | 说明 |\n|---|---|---|---|---|\n| 集团营收 | ¥9,411 亿 | ¥9,963 亿 | 待核 | FY2025 +7% |\n| 云智能收入 | 约 ¥1,064 亿 | 约 ¥1,180 亿 | 约 ¥1,300 亿 | ◐ 汇总 |\n| 云增速 | +3% | +7% | +36–38% | 加速 |\n| 云利润占比 | 5.1% | 5.1% | 待核 | FY2025 |\n| 集团员工 | 124,320 | 124,320 | 约 13 万 | 2025-03/2026-03 |\n\n- 运营指标：AI ARR ¥358 亿；AI 收入占比约 30%；中国 IaaS 份额 32.8%。\n- 指引：五年云+AI 年收入 $1,000 亿；资本开支三年内完成（吴泳铭口径）。\n- 市场预期：AI 云驱动阿里估值修复。\n\n## 股权、融资与股票\n\n- **不适用（业务单元）**：阿里云不独立上市；母公司阿里巴巴（9988.HK/BABA）。\n- 行情（2026-11-02）：9988.HK 约 HK$97–100；市值约 HK$1.98 万亿 / $2,460 亿；BABA 约 $103.56。\n- 估值：集团 PE 约 23–24x；阿里云单独估值常按 5–8x 收入。\n- 股东：阿里巴巴 100%；软银等历史股东减持（◐）。\n- 资本动作：集团回购/分红；云 capex 是主要资本去向。\n\n## 团队与人员\n\n- 集团员工约 13 万（2026-03）；阿里云单列员工数未披露。\n- 研发/销售/交付结构待补；杭州总部 + 全球区域。\n- 招聘：2026 年 AI/云岗位扩张；具体待采集。\n- 薪酬/股权激励：阿里 RSU；云业务有专项激励（◐）。\n- 组织：吴泳铭（集团 CEO）；云智能集团管理层待补。\n\n## 竞争格局\n\n- 直接竞品：华为云、腾讯云、火山引擎、百度智能云、天翼云。\n- 国际竞品：AWS、Azure、Google Cloud。\n- 差异：中国份额第一、飞天/自研芯片、Qwen 开源、政企渠道；弱点：芯片限制、价格战、利润。\n- 竞争动态：火山引擎以 MaaS/低价进攻；华为云以政企/昇腾；腾讯云以生态。\n- 份额：中国 IaaS 32.8%，第一（Gartner 2025）。\n\n## 风险与争议\n\n- 经营：价格战、资本开支、集团盈利压力、客户集中。\n- 技术：美国芯片限制、自研芯片进度、MaaS 竞争。\n- 法律/监管：数据安全、反垄断、云合规。\n- 治理：集团组织变革、管理层集权。\n- 争议：AI 收入口径与盈利质量（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：阿里云单独利润、AI ARR 构成、客户数均未入库。建议跟踪：① 云增速；② AI ARR/占比；③ MaaS 竞争；④ capex；⑤ 芯片供应。\n\n## 信源与口径\n\n- 阿里 FY2026 业绩：https://ali-home.alibaba.com/document-1991237455038119936\n- 云收入/AI ARR：https://m.c114.com.cn/w16-1310211.html ；https://finance.sina.cn/stock/jdts/2026-05-14/detail-inhxvihv4060041.d.html\n- 份额：https://www.aliyun.com/analyst-reports/idc-bdp-2025 ；https://www.aliyun.com/analyst-reports/omdia-aicloud-2025\n- 行情：https://finance.yahoo.com/quote/9988.HK/\n- 口径：云智能收入为集团分部口径；FY2026 全年为季度汇总；◐ 表示待核。' },
      { id: 'volcengine', name: '火山引擎', def: '字节跳动的 AI 云：豆包 + 火山方舟，MaaS 调用量份额第一。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2020 / 北京 | 字节跳动子公司 |\n| 上市地 / 代码 | 未上市；母公司字节跳动 | 不适用 |\n| 最新财年营收 | 2025 超 ¥200 亿（+100%，◐） | 媒体/公司口径 |\n| 盈利 | 未披露 | — |\n| 现金流 | 未披露 | — |\n| 客户 | 未披露；豆包/火山方舟企业客户 | ◐ |\n| 员工 | 产品+研发约 1 万人（2024 口径） | 谭待采访 |\n| 市值 / 估值 | 不适用（未上市） | — |\n| 主要股东 | 字节跳动 100% | 并表 |\n| 数据截至 | 2025 营收；2026 经营 | — |\n\n## 定位与沿革\n\n字节跳动的 AI 云：以豆包大模型、火山方舟 MaaS、GPU 云与 veFaaS 构成 AI 原生云；2025 年营收超 ¥200 亿（+100%），MaaS 调用量份额约 49.5%，居中国第一。\n\n- 2020 年推出火山引擎，承接字节内部技术外溢；谭待任总裁。\n- 2023 年起以「低价 + 豆包」切入大模型 API 市场，掀起中国 MaaS 价格战。\n- 2024 年营收超 ¥120 亿；2025 年目标翻倍至 ¥250 亿，实际超 ¥200 亿（+100%，◐）。\n- 2026 年日均 Token 调用：2025-12 突破 50 万亿 → 2026-04 超 120 万亿 → 2026-06 达 180 万亿；「万亿 Tokens 俱乐部」200 家。\n- MaaS 调用量份额 49.5%、营收份额 40%+（IDC/Omdia 口径）；豆包大模型是核心。\n- 谭待称「从不赔钱换市场」，否认部分收入传闻；上市/融资未公开。\n\n## 创始人与管理层\n\n- **谭待（火山引擎总裁）**：字节跳动技术背景；主导火山引擎与豆包商业化。\n- **字节跳动管理层**：梁汝波（CEO）、张一鸣（创始人，◐ 现角色待核）。\n- 核心团队：来自字节推荐/基础架构/Seed 模型团队；具体名单待采集。\n- 董事会：字节跳动董事会；火山引擎无独立董事会。\n- 关键人事变动：2025–2026 年 AI 云团队扩张；具体待采集。\n\n## 商业模式\n\n- **收入结构**：IaaS（GPU/算力）、MaaS（豆包 API/火山方舟）、SaaS（veFaaS/数据）、行业方案。\n- **销售动作**：企业直销 + 开发者社区 + 字节生态；AI 初创/互联网/政企。\n- **单位经济**：MaaS 低价策略、规模效应；是否盈利未披露；GPU 转售利润薄。\n- **收入质量**：2025 营收 >¥200 亿；MaaS 份额第一；客户数未披露。\n- **定价趋势**：按 token（豆包）、按 GPU 小时、按订阅；持续降价。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 豆包大模型 | 文本/多模态/语音 | 按 token | 主力 |\n| 火山方舟 | MaaS/模型托管/agent | 按 token | 主力 |\n| GPU 云 | GPU 实例/集群 | 按小时 | 增长 |\n| Seedance | 视频生成 | 按 token/秒 | 增长 |\n| veFaaS | Serverless/边缘 | 按调用 | 增长 |\n| 数据/推荐 | 数据分析、推荐 | 按用量 | 增长 |\n\n- 包装：MaaS + IaaS + 行业方案；字节生态捆绑。\n- 路线图：豆包 2.x、Seedance、agent、全球化。\n\n## 技术栈与壁垒\n\n- **架构**：字节自建数据中心/GPU 集群；推荐/基础架构复用。\n- **AI 路线**：豆包（Seed）+ 火山方舟 + Seedance；低价 API 获客。\n- **壁垒**：豆包模型、字节流量/数据、低价、开发者生态；弱点：盈利、芯片供应、客户集中。\n- **依赖与债务**：NVIDIA/国产芯片供应、价格战、母公司依赖。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| AI 初创 | 豆包 API/方舟 | 未披露具体数字 | 官网 |\n| 互联网企业 | 推荐/数据/云 | 未披露具体数字 | 官网 |\n| 政企/金融 | 行业大模型 | 未披露具体数字 | 官网 |\n\n- 客户结构：AI 初创、互联网、政企；具体名单未披露。\n- 集中度：未披露；字节内部/生态客户占比待核。\n- 续约/流失：MaaS 用量增长快；价格敏感。\n\n## 商业进展\n\n- 2025 营收 >¥200 亿（+100%）；MaaS 调用量份额 49.5%。\n- 2026 年日均 Token 180 万亿；豆包 2.x/Seedance 迭代。\n- 谭待称「从不赔钱换市场」；否认部分收入传闻；上市未公开。\n- 字节 2026 年 AI capex 高企；火山引擎承接对外商业化。\n- 竞争：阿里云百炼、腾讯云、华为云、百度智能云。\n\n## 经营业绩\n\n| 指标 | 2023 | 2024 | 2025 | 说明 |\n|---|---|---|---|---|\n| 营收 | 未披露 | >¥120 亿 | >¥200 亿 | +100%（◐） |\n| 增速 | — | 高增长 | +100% | 高速 |\n| 毛利率 | 未披露 | 未披露 | 未披露 | — |\n| 营业利润 | 未披露 | 未披露 | 未披露 | — |\n| 员工 | 未披露 | 约 1 万（产品+研发） | 待核 | 2024 口径 |\n\n- 运营指标：日均 Token 180 万亿（2026-06）；MaaS 份额 49.5%。\n- 指引：未披露；2030 年营收目标曾上调。\n- 市场预期：MaaS 份额与盈利路径。\n\n## 股权、融资与股票\n\n- **不适用（未上市）**：火山引擎为字节跳动业务单元，无独立股票。\n- 估值：不适用；字节跳动整体估值未公开（◐）。\n- 股东：字节跳动 100%。\n- 融资：无独立融资；字节整体融资/回购待核。\n- 流动性：无公开市场；上市计划未公开。\n\n## 团队与人员\n\n- 产品+研发约 1 万人（2024 口径）；2026 年可能扩张。\n- 北京总部；上海/深圳/杭州等；海外待核。\n- 招聘：2026 年 AI/云岗位扩张；具体待采集。\n- 薪酬/股权激励：字节 RSU/期权；流失率未披露。\n- 组织：谭待（总裁）；字节 Seed/基础架构团队协同。\n\n## 竞争格局\n\n- 直接竞品：阿里云（百炼/通义）、腾讯云、华为云、百度智能云。\n- 国际竞品：AWS Bedrock、Azure OpenAI、Google Vertex AI。\n- 差异：豆包模型、低价、字节生态/流量；弱点：盈利、芯片、政企渠道。\n- 竞争动态：MaaS 价格战；阿里云/华为云反击；模型能力竞争。\n- 份额：中国 MaaS 调用量 49.5%，第一（IDC/Omdia，◐）。\n\n## 风险与争议\n\n- 经营：价格战、盈利、客户集中、字节内部依赖。\n- 技术：芯片供应、模型能力、agent 生态。\n- 法律/监管：数据安全、AI 监管、内容合规。\n- 治理：字节跳动整体治理；上市未定。\n- 争议：低价换份额能否持续、收入口径（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中；字节 Seed 页可作模型侧参照）。缺口：营收/利润、客户数、员工数、MaaS 收入均未入库。建议跟踪：① MaaS 份额；② 2026 营收/盈利；③ 豆包/Seedance 迭代；④ 芯片供应；⑤ 与阿里云的竞争。\n\n## 信源与口径\n\n- 2025 营收：https://finance.sina.cn/stock/jdts/2025-12-30/detail-inheqqfn4227034.d.html\n- 谭待专访：https://zhuanlan.zhihu.com/p/1985078847855674386\n- Token/份额：https://www.tmtpost.com/7998067.html\n- 员工：https://m.bjnews.com.cn/detail/1734936694129853.html\n- 口径：营收为媒体口径；员工数为 2024 口径；◐ 表示待核。' },
      { id: 'dell', name: 'Dell', def: 'AI 服务器最大受益者之一：FY2026 营收 $1,135 亿，AI 订单 $640 亿。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 1984 / Round Rock, TX | 官网 |\n| 上市地 / 代码 | NYSE: DELL | 2018 重新上市 |\n| 最新财年营收 | FY2026 $1,135 亿（创纪录） | 2026-02 发布 |\n| 盈利 | FY2026 净利待核；EPS 创纪录 | ◐ |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露；企业、云厂商、AI labs | ◐ |\n| 员工 | 约 108,000 人（FY2025 口径） | ◐ |\n| 市值 / 估值 | 约 $2,698 亿（2026-11-02）；股价约 $424 | Macrotrends/Yahoo |\n| 主要股东 | Michael Dell、机构 | ◐ |\n| 数据截至 | FY2026（2026-01）；行情 2026-11-02 | — |\n\n## 定位与沿革\n\nPC 与服务器巨头，AI 服务器最大受益者之一：FY2026 营收 $1,135 亿创纪录，AI 优化服务器订单超 $640 亿、出货超 $250 亿；FY2027 单季 AI 订单一度达 $609 亿、backlog $950 亿。\n\n- 1984 年由 Michael Dell 创立；2013 年私有化，2018 年重新上市（DELL）。\n- 业务：CSG（PC/外设）、ISG（服务器/存储/网络）、VMware（2021 年分拆）。\n- FY2026 营收 $1,135 亿、EPS/现金流创纪录；ISG 收入创纪录 $318 亿（+89%），AI 服务器收入 $164 亿（+757%）。\n- FY2026 全年 AI 订单 >$640 亿、AI 服务器出货 >$250 亿；FY2027 单季 AI 订单 $609 亿、backlog $950 亿。\n- 2026 年股价一度涨超 229% YTD，5 月 29 日单日 +32%（史上最佳）；9 月 18 日创 $595.51 高点后回落。\n- 2026 年裁员约 11,000 人，同时推进 AI 服务器与 RTO。\n\n## 创始人与管理层\n\n- **Michael Dell（创始人、董事长 & CEO）**：1984 年创立；2013 年私有化、2018 年重新上市。\n- **Jeff Clarke（副董事长 & COO）**：负责产品与运营；财报主要对外面孔。\n- **Yvonne McGill（CFO）**：财务负责人（◐ 任期待核）。\n- 董事会：Michael Dell + 独立董事；具体席位待核。\n- 关键人事变动：2026 年裁员/RTO；AI 服务器团队扩张。\n\n## 商业模式\n\n- **收入结构**：CSG（PC/外设）、ISG（服务器/存储/网络）、服务/融资；硬件为主。\n- **销售动作**：企业直销 + 渠道 + 云厂商/AI labs 大单；AI 服务器项目制。\n- **单位经济**：硬件毛利低；AI 服务器规模大但毛利薄；服务/融资补充。\n- **收入质量**：AI 订单/backlog 高；客户集中度上升（AI labs/云厂商）。\n- **定价趋势**：AI 服务器按机柜/集群；PC 按台；服务按合同。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| PowerEdge | 服务器（通用/AI） | 按台/机柜 | 主力 |\n| AI Factory | AI 算力集群方案 | 按项目 | 主力 |\n| PowerStore/PowerScale | 存储 | 按容量 | 主力 |\n| PowerSwitch | 网络 | 按端口 | 增长 |\n| PC/显示器 | 商用/消费终端 | 按台 | 主力 |\n| 服务/融资 | 部署、支持、租赁 | 按合同 | 增长 |\n\n- 包装：硬件 + 服务 + 融资；AI Factory 整柜方案。\n- 路线图：AI 服务器、液冷、GB200/下一代 GPU 平台。\n\n## 技术栈与壁垒\n\n- **架构**：服务器/存储/网络硬件 + 供应链；AI Factory 参考架构。\n- **AI 路线**：NVIDIA/AMD/自研加速卡的整机柜集成；液冷。\n- **壁垒**：全球供应链、企业渠道、AI 服务器交付能力、Michael Dell 品牌。\n- **依赖与债务**：AI 服务器毛利、GPU 供应、客户集中、PC 周期。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| AI labs/云厂商 | AI 服务器/集群 | 订单 >$640 亿（FY2026） | 公司披露 |\n| 大型企业 | 私有云/AI Factory | 未披露具体数字 | 官网 |\n| PC 客户 | 商用/消费终端 | 未披露具体数字 | 官网 |\n\n- 客户结构：企业、政府、云厂商、AI labs；全球覆盖。\n- 集中度：AI 大客户占比上升（◐）；PC 客户分散。\n- 续约/流失：AI backlog 是核心；PC 换机周期。\n\n## 商业进展\n\n- FY2026 营收 $1,135 亿、AI 订单 >$640 亿、出货 >$250 亿。\n- FY2027 单季 AI 订单 $609 亿、backlog $950 亿；上调全年指引。\n- 2026 年股价 +229% YTD（5 月单日 +32%），9 月高点后回落。\n- 2026 年裁员约 11,000 人；AI 服务器/液冷扩张。\n- 竞争：HPE、Supermicro、Lenovo、浪潮信息、华为。\n\n## 经营业绩\n\n| 指标 | FY2024 | FY2025 | FY2026 | 说明 |\n|---|---|---|---|---|\n| 营收 | $884 亿 | $956 亿 | $1,135 亿 | FY2026 创纪录 |\n| 增速 | -14% | +8% | +19% | 加速 |\n| 毛利率 | 约 23% | 约 22% | 待核 | 硬件 |\n| 营业利润 | 待核 | 待核 | 待核 | — |\n| 净利 | $32 亿 | $46 亿 | 待核 | ◐ |\n\n- 运营指标：AI 订单 >$640 亿（FY2026）；ISG $318 亿（+89%）；AI 服务器 $164 亿（+757%）。\n- 指引：FY2027 上调；AI backlog $950 亿。\n- 市场预期：AI 服务器增长 vs 毛利/客户集中。\n\n## 股权、融资与股票\n\n- 上市：NYSE DELL；2018 年重新上市。\n- 行情（2026-11-02）：股价约 $424；市值约 $2,698 亿；P/E 24.67；52 周高 $595.51（2026-09-18）。\n- 估值：PE 24.67x；PS 约 2.4x；AI 服务器分部估值待重估。\n- 股东：Michael Dell、机构；具体持股待核。\n- 资本动作：回购/分红待查；2026 年股价大涨。\n- 风险提示：AI 服务器毛利、客户集中、PC 周期。\n\n## 团队与人员\n\n- 员工约 108,000 人（FY2025 口径；◐）。\n- 研发/制造/销售结构待补；Round Rock 总部 + 全球。\n- 招聘/裁员：2026 年裁员约 11,000 人；AI 岗位扩张。\n- 薪酬/股权激励：RSU；Michael Dell 持股待核。\n- 组织：Michael Dell（CEO）、Jeff Clarke（COO）、Yvonne McGill（CFO）。\n\n## 竞争格局\n\n- 直接竞品：HPE、Supermicro、Lenovo、浪潮信息、华为、Foxconn/Quanta（ODM）。\n- 替代方案：白牌服务器、云厂商自建。\n- 差异：全球供应链、企业渠道、AI Factory 整柜交付；弱点：AI 毛利、客户集中。\n- 竞争动态：AI 服务器需求爆发；Supermicro 价格/速度竞争；HPE 靠 Juniper 网络。\n- 份额：全球服务器市场份额前三（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：AI 服务器毛利、客户集中、PC 周期、裁员执行。\n- 技术：液冷/整柜、GPU 供应、交付能力。\n- 法律/监管：出口管制、数据安全、证券披露。\n- 治理：Michael Dell 控制权、裁员/RTO 争议。\n- 争议：AI 订单与收入确认节奏、股价波动（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：AI 服务器毛利、客户名单、backlog 转化均未入库。建议跟踪：① AI 订单/backlog；② ISG 毛利；③ 客户集中度；④ PC 周期；⑤ 裁员/组织。\n\n## 信源与口径\n\n- FY2026 业绩：https://www.sec.gov/Archives/edgar/data/1571996/000157199626000003/exhibit991earnings8kq4fy26.htm\n- AI 订单/股价：https://www.cnbc.com/2026/05/29/dell-stock-earnings-ai-servers.html\n- Fortune：https://fortune.com/2026/09/08/dell-earnings-reveal-ai-buildout-on-premise/\n- 行情：https://www.macrotrends.net/stocks/charts/DELL/dell/market-cap\n- 口径：FY2026 截至 2026-01；员工数为 FY2025 口径；◐ 表示待核。' },
      { id: 'hpe', name: 'HPE', def: '网络centric转型：Juniper 并表后网络收入翻倍，AI 服务器与 GreenLake 并进。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2015（HPE 分拆）/ Spring, TX | 官网 |\n| 上市地 / 代码 | NYSE: HPE | 2015 分拆上市 |\n| 最新财年营收 | FY2025 约 $330 亿（◐）；FY2026 Q3 $122 亿（+34%） | HPE 财报 |\n| 盈利 | FY2026 Q3 non-GAAP 营业利润 $20 亿；EPS $1.11 | 2026-09 发布 |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露；企业/政府 | ◐ |\n| 员工 | 约 67,000 人 | Perplexity Finance（◐） |\n| 市值 / 估值 | 约 $731 亿（2026-11-02）；股价约 $55 | Macrotrends/Yahoo |\n| 主要股东 | 机构为主 | ◐ |\n| 数据截至 | FY2026 Q3；行情 2026-11-02 | — |\n\n## 定位与沿革\n\n从企业硬件转向「网络为中心」：2025-07 完成 $140 亿收购 Juniper Networks，网络收入翻倍；同时保留 ProLiant/Cray 服务器、GreenLake 订阅与 AI 服务器。\n\n- 2015 年从 HP 分拆上市；Antonio Neri 2018 年起任 CEO。\n- 2025-07 完成 Juniper Networks 收购（约 $140 亿），网络产品线（Aruba + Juniper）大幅扩张。\n- FY2026 Q1 网络收入 $27 亿（+152%）；FY2026 Q3 总收入 $122 亿（+34%）、non-GAAP 营业利润 $20 亿、EPS $1.11，创纪录。\n- 网络产品九个月同比 +117%；Juniper 整合是增长主线。\n- AI 服务器/GreenLake 订阅并进；AI 订单与 backlog 待采集。\n- 2026 年上调网络收入指引；股价约 $55，市值约 $731 亿。\n\n## 创始人与管理层\n\n- **Antonio Neri（CEO）**：2018 年起任 HPE CEO；主导 Juniper 收购与网络转型。\n- **Juniper 管理层**：Rami Rahim 等并入 HPE 网络业务（◐ 角色待核）。\n- **CFO/COO**：名单待补。\n- 董事会：HPE 董事会；Juniper 交易后席位待核。\n- 关键人事变动：Juniper 整合、网络业务组织调整。\n\n## 商业模式\n\n- **收入结构**：服务器（ProLiant/Cray）、网络（Aruba/Juniper）、存储、GreenLake 订阅、服务。\n- **销售动作**：企业直销 + 渠道；政府/企业；GreenLake 订阅。\n- **单位经济**：硬件毛利低；网络/订阅毛利更高；Juniper 整合协同。\n- **收入质量**：网络收入高增长；AI 服务器订单待采集；GreenLake ARR 待核。\n- **定价趋势**：硬件按台/端口；GreenLake 按用量/订阅；网络按端口/许可。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| ProLiant | 通用服务器 | 按台 | 主力 |\n| Cray | 超算/AI 集群 | 按项目 | 增长 |\n| Aruba/Juniper | 网络（园区/数据中心） | 按端口/许可 | 主力 |\n| GreenLake | 混合云订阅 | 按用量/订阅 | 增长 |\n| Storage | 存储阵列 | 按容量 | 主力 |\n| AI 服务器 | GPU 整机/集群 | 按项目 | 增长 |\n\n- 包装：硬件 + 网络 + GreenLake 订阅；企业/政府方案。\n- 路线图：Juniper 整合、AI 网络、GreenLake 扩张。\n\n## 技术栈与壁垒\n\n- **架构**：服务器/存储硬件 + Aruba/Juniper 网络；GreenLake 云平台。\n- **AI 路线**：AI 服务器 + 网络（AI 集群互联）；Juniper 的 AIOps/Mist。\n- **壁垒**：企业渠道、网络产品线、GreenLake 订阅、政府客户。\n- **依赖与债务**：Juniper 整合、AI 服务器毛利、网络竞争、债务。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 企业/政府 | 网络、服务器、GreenLake | 未披露具体数字 | 官网 |\n| 大型园区/数据中心 | Aruba/Juniper 网络 | 未披露具体数字 | 官网 |\n| AI 客户 | AI 服务器/集群 | 未披露具体数字 | 官网 |\n\n- 客户结构：企业、政府、教育、电信；全球覆盖。\n- 集中度：未披露；政府/大企业占比高。\n- 续约/流失：GreenLake 订阅续约；网络维保。\n\n## 商业进展\n\n- 2025-07 完成 Juniper 收购（$140 亿）；网络收入 Q1 FY2026 +152%。\n- FY2026 Q3 营收 $122 亿（+34%）、营业利润 $20 亿、EPS $1.11，创纪录。\n- 2026 年上调网络收入指引；Juniper 整合协同。\n- AI 服务器/GreenLake 并进；AI 订单待采集。\n- 竞争：Dell、Supermicro、Cisco、Lenovo、华为。\n\n## 经营业绩\n\n| 指标 | FY2023 | FY2024 | FY2025 | FY2026 Q3 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | $291 亿 | $301 亿 | 约 $330 亿 | $122 亿 | FY2026 Q3 +34% |\n| 增速 | +2% | +3% | 约 +10% | +34% | Juniper 并表 |\n| 毛利率 | 约 34% | 约 34% | 待核 | 待核 | ◐ |\n| 营业利润 | 待核 | 待核 | 待核 | $20 亿 | non-GAAP |\n| EPS | 待核 | 待核 | 待核 | $1.11 | non-GAAP |\n\n- 运营指标：网络收入 Q1 FY2026 $27 亿（+152%）；九个月 +117%。\n- 指引：2026 年网络收入指引上调；AI 服务器待采集。\n- 市场预期：Juniper 整合与网络增长。\n\n## 股权、融资与股票\n\n- 上市：NYSE HPE；2015 年分拆上市。\n- 行情（2026-11-02）：股价约 $55.09；市值约 $731 亿；P/E 28.4；EV $872 亿。\n- 估值：PE 28.4x；PS 约 1.86x；网络/订阅分部待重估。\n- 股东：机构为主；具体持股待核。\n- 资本动作：Juniper 收购融资/债务；回购/分红待查。\n- 风险提示：整合风险、AI 服务器毛利、网络竞争。\n\n## 团队与人员\n\n- 员工约 67,000 人（◐）；Juniper 并表后增加。\n- 研发/销售/服务结构待补；Spring, TX 总部。\n- 招聘/裁员：Juniper 整合可能带来重叠岗位优化；具体待采集。\n- 薪酬/股权激励：RSU；Juniper 员工留任计划。\n- 组织：Antonio Neri（CEO）；网络业务由 Juniper 团队整合。\n\n## 竞争格局\n\n- 直接竞品：Dell、Supermicro、Cisco、Lenovo、华为、浪潮信息。\n- 网络竞品：Cisco、Arista、华为、新华三。\n- 差异：Juniper/Aruba 网络 + 服务器 + GreenLake；弱点：整合风险、AI 服务器规模小于 Dell。\n- 竞争动态：Cisco 网络强势；Dell AI 服务器领先；HPE 靠网络差异化。\n- 份额：企业网络/服务器市场份额前三（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：Juniper 整合、AI 服务器毛利、网络竞争、债务。\n- 技术：网络/AI 集群互联、GreenLake 平台。\n- 法律/监管：反垄断（Juniper 交易已获批）、数据安全。\n- 治理：Juniper 整合组织、管理层变动。\n- 争议：收购协同与 AI 服务器订单透明度（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：AI 服务器订单、GreenLake ARR、Juniper 协同均未入库。建议跟踪：① 网络收入增速；② Juniper 整合；③ AI 服务器订单；④ GreenLake ARR；⑤ 与 Cisco/Dell 的竞争。\n\n## 信源与口径\n\n- FY2026 Q3：https://www.linkedin.com/posts/antonio-neri-hpe_hpe-reports-fiscal-2026-third-quarter-results-activity-7501015763982520320-MRXR\n- Juniper 整合：https://www.crn.com/news/ai/2025/hpe-increases-networking-revenue-forecast-in-wake-of-juniper-networks-integration-momentum\n- 行情：https://www.macrotrends.net/stocks/charts/HPE/hewlett-packard-enterprise/market-cap\n- 口径：FY2025 全年为估算；FY2026 Q3 为公司披露；◐ 表示待核。' },
      { id: 'supermicro', name: 'Supermicro', def: 'AI 服务器快枪手：FY2026 营收 $391 亿，液冷与整机柜交付见长。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 1993 / San Jose | 官网 |\n| 上市地 / 代码 | NASDAQ: SMCI | 2007 IPO |\n| 最新财年营收 | FY2026 $391 亿（+77.8%） | 2026-08 发布 |\n| 盈利 | FY2026 营业利润约 $28 亿；净利约 $22 亿 | ◐ 待 10-K |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露；AI labs/云厂商/企业 | ◐ |\n| 员工 | 约 5,000–6,000 人（◐） | — |\n| 市值 / 估值 | 约 $216.5 亿（2026-11-02）；股价约 $33 | Yahoo/Macrotrends |\n| 主要股东 | Charles Liang 等 | ◐ |\n| 数据截至 | FY2026（2026-06）；行情 2026-11-02 | — |\n\n## 定位与沿革\n\nAI 服务器「快枪手」：以液冷、整机柜与快速交付见长，FY2026 营收 $391 亿（+77.8%），成为 AI 服务器最大受益者之一。\n\n- 1993 年由 Charles Liang 在圣何塞创立；2007 年上市（SMCI）；Charles Liang 任 CEO/董事长。\n- 早期做主板/服务器；AI 时代以 GPU 服务器、液冷与整机柜快速放量。\n- FY2026 营收 $391 亿（+77.8%）；Q4 净销售 $111.2 亿、Q3 $102.4 亿；营业利润约 $28 亿（+121%）、净利约 $22 亿。\n- 2025-11 将 FY2026 指引从 $330 亿上调至至少 $360 亿；2026 年订单/backlog 强劲（媒体称 $600 亿订单）。\n- 2026-06 以 $27.50/股发行 4,545 万股，融资扩产 AI 订单；股价约 $33，市值约 $216.5 亿。\n- 历史争议：2024 年做空报告/审计延迟，2025 年更换审计师并补交财报（◐ 待核）。\n\n## 创始人与管理层\n\n- **Charles Liang（创始人、董事长 & CEO）**：1993 年创立，任职 30+ 年；2026 年仍任 CEO；年薪 $1（媒体口径）。\n- **David Weigand（CFO）**：财务负责人（◐ 任期待核）。\n- 核心团队：硬件/供应链背景；具体名单待采集。\n- 董事会：Charles Liang + 独立董事；2024–2025 年治理争议后有所调整。\n- 关键人事变动：2024 年审计/做空争议、2025 年补交财报；具体待核。\n\n## 商业模式\n\n- **收入结构**：GPU/通用服务器、整机柜、存储、液冷；硬件为主。\n- **销售动作**：直销 + 渠道 + ODM；AI labs/云厂商大单。\n- **单位经济**：硬件毛利低（约 10–15%）；规模/周转是核心；液冷/整柜溢价。\n- **收入质量**：AI 订单/backlog 高；客户集中度上升；历史财报可信度是折价因素。\n- **定价趋势**：按服务器/机柜；AI 整柜按项目。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| GPU 服务器 | NVIDIA/AMD GPU 整机 | 按台/机柜 | 主力 |\n| 整机柜 | GB200/液冷整柜 | 按项目 | 主力 |\n| 通用服务器 | 企业/云服务器 | 按台 | 主力 |\n| 存储 | 高性能存储 | 按容量 | 增长 |\n| 液冷 | DLC 液冷方案 | 按项目 | 增长 |\n| 边缘/工作站 | 边缘 AI/工作站 | 按台 | 增长 |\n\n- 包装：硬件 + 液冷 + 整柜；AI 集群方案。\n- 路线图：GB200/下一代 GPU、液冷、美国/全球产能。\n\n## 技术栈与壁垒\n\n- **架构**：快速硬件设计/供应链；液冷（DLC）；整机柜集成。\n- **AI 路线**：NVIDIA GPU 服务器 + 液冷；与 GPU 厂商同步迭代。\n- **壁垒**：速度/成本、液冷工程、美国产能、客户关系；弱点：毛利低、治理历史、客户集中。\n- **依赖与债务**：GPU 供应、客户集中、毛利、融资/稀释。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| AI labs/云厂商 | GPU 服务器/整柜 | 未披露具体数字 | 媒体 |\n| 企业 | 通用/GPU 服务器 | 未披露具体数字 | 官网 |\n| 液冷客户 | 数据中心液冷 | 未披露具体数字 | 官网 |\n\n- 客户结构：AI labs、云厂商、企业；具体名单未披露。\n- 集中度：未披露；AI 大客户占比上升（◐）。\n- 续约/流失：订单/backlog 是核心；历史财报可信度影响客户信心。\n\n## 商业进展\n\n- FY2026 营收 $391 亿（+77.8%）；Q4 $111.2 亿、Q3 $102.4 亿。\n- 2025-11 上调 FY2026 指引至至少 $360 亿；2026 年订单强劲（媒体称 $600 亿）。\n- 2026-06 股权融资 $27.50/股（4,545 万股）扩产；股价约 $33。\n- 液冷/整柜是差异化；美国产能扩张。\n- 竞争：Dell、HPE、Lenovo、浪潮信息、Foxconn/Quanta。\n\n## 经营业绩\n\n| 指标 | FY2024 | FY2025 | FY2026 | 说明 |\n|---|---|---|---|---|\n| 营收 | $149 亿 | $220 亿 | $391 亿 | +77.8% |\n| 增速 | +110% | +47% | +77.8% | 高速 |\n| 毛利率 | 约 14% | 约 11% | 待核 | 硬件 |\n| 营业利润 | 待核 | 约 $12.7 亿 | 约 $28 亿 | +121% |\n| 净利 | 待核 | 待核 | 约 $22 亿 | ◐ |\n\n- 运营指标：Q4 净销售 $111.2 亿；AI 订单/backlog 待核。\n- 指引：FY2027 指引待核；2026 年融资扩产。\n- 市场预期：AI 服务器增长 vs 毛利/治理。\n\n## 股权、融资与股票\n\n- 上市：NASDAQ SMCI；2007 IPO。\n- 行情（2026-11-02）：股价约 $32.95；市值约 $216.5 亿；P/E 10.11；EV $271.1 亿。\n- 估值：PE 10.11x；PS 约 0.59x；低估值反映治理/毛利折价。\n- 股东：Charles Liang 等；机构；具体持股待核。\n- 资本动作：2026-06 股权融资 $27.50/股（4,545 万股）；可转债待核。\n- 风险提示：毛利、客户集中、治理历史、稀释。\n\n## 团队与人员\n\n- 员工约 5,000–6,000 人（◐）；制造/工程为主。\n- 圣何塞总部；美国/台湾/马来西亚产能。\n- 招聘：2026 年扩产；具体待采集。\n- 薪酬/股权激励：RSU；Charles Liang 年薪 $1（媒体口径）。\n- 组织：Charles Liang（CEO）；CFO/COO 待补。\n\n## 竞争格局\n\n- 直接竞品：Dell、HPE、Lenovo、浪潮信息、Foxconn/Quanta（ODM）、华为。\n- 替代方案：白牌服务器、云厂商自建。\n- 差异：速度/成本、液冷、整柜、美国产能；弱点：毛利、治理、客户集中。\n- 竞争动态：Dell 规模更大；Supermicro 以速度/液冷差异化。\n- 份额：AI 服务器市场份额前列（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：毛利低、客户集中、融资稀释、AI 需求波动。\n- 技术：液冷/整柜、GPU 供应、产能。\n- 法律/监管：2024 年做空报告/审计延迟、证券披露；待补诉讼。\n- 治理：Charles Liang 控制权、董事会独立性、审计历史。\n- 争议：财报可信度与估值折价（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：AI 订单/backlog、毛利率、客户名单、治理整改进展均未入库。建议跟踪：① FY2027 指引；② 液冷/整柜占比；③ 毛利率；④ 客户集中；⑤ 审计/治理。\n\n## 信源与口径\n\n- FY2026 Q3：https://ir.supermicro.com/news/news-details/2026/Supermicro-Announces-Third-Quarter-Fiscal-Year-2026-Financial-Results/default.aspx\n- 10-K：https://www.sec.gov/Archives/edgar/data/1375365/000137536526000008/smci-20260303.htm\n- 行情：https://www.macrotrends.net/stocks/charts/SMCI/super-micro-computer/market-cap\n- 融资：https://ir.supermicro.com/news/news-details/2026/Supermicro-Announces-Pricing-of-Equity-and-Equity-Linked-Financing-Transactions-To-Fund-AI-Orders/default.aspx\n- 口径：FY2026 截至 2026-06；员工数为估算；◐ 表示待核。' },
      { id: 'inspur', name: '浪潮信息', def: '中国服务器龙头：AI 服务器放量，2025 营收 1,648 亿但净利仅 24 亿。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 1998（◐）/ 济南 | 官网/年报 |\n| 上市地 / 代码 | 深交所 000977 | 2000 IPO |\n| 最新财年营收 | FY2025 ¥1,647.82 亿（+43.25%） | 2025 年报 |\n| 盈利 | 归母净利 ¥24.13 亿（+5.20%） | 2025 年报 |\n| 现金流 | 经营现金流大幅改善（◐） | 年报 |\n| 客户 | 未披露；互联网/政企 | ◐ |\n| 员工 | 6,896 人 | Google/TradingView |\n| 市值 / 估值 | 约 ¥795–825 亿（2026-10-30）；股价 ¥54.18 | 新浪/雪球/富途 |\n| 主要股东 | 浪潮集团 | 国资 |\n| 数据截至 | FY2025；2026 Q3 预告 | — |\n\n## 定位与沿革\n\n中国服务器龙头：以 NF/元脑系列 AI 服务器、存储与边缘计算为主，2025 年营收 ¥1,647.82 亿（+43.25%），但净利仅 ¥24.13 亿（+5.2%），呈现「增收不增利」的剪刀差。\n\n- 1998 年前后成立（◐），浪潮集团旗下上市公司；2000 年深交所上市（000977）。\n- 业务：服务器（通用/AI）、存储、边缘计算、云服务；AI 服务器是增长主线。\n- FY2025 营收 ¥1,647.82 亿（+43.25%）、归母净利 ¥24.13 亿（+5.2%）；低毛利与高存货拖累盈利。\n- 2026 H1 归母净利 ¥29.52 亿（+269.59%）；2026 前三季度预告净利 ¥38–41 亿（+156%–177%），盈利修复。\n- 2026 年市值约 ¥795–825 亿；股价 ¥54.18（2026-10-30）；52 周 ¥55.36–96.37。\n- 董事长彭震（2025 年薪酬 ¥375 万）；总经理胡雷钧；CFO/董秘许燕燕。\n\n## 创始人与管理层\n\n- **彭震（董事长）**：1972 年生；2025 年薪酬 ¥375 万；主导 AI 服务器战略。\n- **胡雷钧（总经理）**：负责经营；2025 年薪酬 ¥368.5 万。\n- **许燕燕（CFO/董秘）**：财务与资本市场。\n- 控股股东：浪潮集团（山东国资）；具体持股比例待核。\n- 关键人事变动：2026 年管理层稳定；AI 服务器团队扩张。\n\n## 商业模式\n\n- **收入结构**：服务器（通用/AI）为主，存储、边缘、云服务为辅；硬件为主。\n- **销售动作**：互联网大客户 + 政企渠道；AI 服务器项目制。\n- **单位经济**：毛利率低（约 5–10%）；规模/周转是核心；存货/现金流压力大。\n- **收入质量**：营收 ¥1,648 亿、净利 ¥24 亿，净利率约 1.5%；互联网客户集中。\n- **定价趋势**：AI 服务器按台/机柜；通用服务器价格战。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| NF/元脑 AI 服务器 | GPU/训练推理服务器 | 按台/机柜 | 主力 |\n| 通用服务器 | 企业/云服务器 | 按台 | 主力 |\n| 存储 | 分布式/全闪存 | 按容量 | 主力 |\n| 边缘计算 | 边缘服务器/网关 | 按台 | 增长 |\n| 云服务 | 政务云/行业云 | 按项目/订阅 | 增长 |\n| 液冷 | 冷板/浸没液冷 | 按项目 | 增长 |\n\n- 包装：硬件 + 方案 + 云服务；互联网/政企。\n- 路线图：AI 服务器、液冷、国产芯片适配。\n\n## 技术栈与壁垒\n\n- **架构**：服务器/存储硬件 + 液冷 + 云平台；国产芯片（昇腾/海光等）适配。\n- **AI 路线**：AI 服务器/元脑平台；大模型训推一体。\n- **壁垒**：中国服务器份额、互联网客户、供应链、国资背景；弱点：毛利低、存货、芯片供应。\n- **依赖与债务**：GPU/芯片供应、互联网客户集中、低毛利、存货。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 互联网大客户 | AI/通用服务器 | 未披露具体数字 | 年报/媒体 |\n| 政企客户 | 政务云、服务器 | 未披露具体数字 | 官网 |\n| 金融/电信 | 存储/服务器 | 未披露具体数字 | 官网 |\n\n- 客户结构：互联网、政企、金融、电信；互联网大客户占比高（◐）。\n- 集中度：未披露；前五大客户占比可能较高。\n- 续约/流失：项目制；AI 服务器订单是核心。\n\n## 商业进展\n\n- FY2025 营收 ¥1,647.82 亿（+43.25%）、净利 ¥24.13 亿（+5.2%）。\n- 2026 H1 净利 ¥29.52 亿（+269.59%）；前三季度预告 ¥38–41 亿（+156%–177%）。\n- AI 服务器/液冷是增长主线；国产芯片适配。\n- 2026 年市值约 ¥795–825 亿；股价从 7 月高点回落约 15%。\n- 竞争：华为、新华三、联想、中科曙光、Dell。\n\n## 经营业绩\n\n| 指标 | FY2023 | FY2024 | FY2025 | 2026 H1 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | 未披露 | 约 ¥1,150 亿 | ¥1,647.82 亿 | 待核 | FY2025 +43.25% |\n| 增速 | 未披露 | 未披露 | +43.25% | 待核 | 高速 |\n| 毛利率 | 未披露 | 约 5–10% | 约 5–10% | 待核 | 低毛利 |\n| 营业利润 | 未披露 | 未披露 | 未披露 | 未披露 | — |\n| 归母净利 | 未披露 | 约 ¥22.9 亿 | ¥24.13 亿 | ¥29.52 亿 | +5.2%/+269.59% |\n\n- 运营指标：员工 6,896；净利率约 1.5%（FY2025）；存货/现金流待核。\n- 指引：2026 前三季度净利 ¥38–41 亿（+156%–177%）。\n- 市场预期：AI 服务器放量、盈利修复。\n\n## 股权、融资与股票\n\n- 上市：深交所 000977；2000 年 IPO。\n- 行情（2026-10-30）：股价 ¥54.18；市值约 ¥795–825 亿；总股本 14.68 亿股；PE 16.4–17.4。\n- 估值：PE 16–17x；PS 约 0.5x；低毛利折价。\n- 股东：浪潮集团（国资）；机构；具体持股待核。\n- 资本动作：分红/融资待查；2026 年股价波动。\n- 风险提示：低毛利、存货、芯片供应、客户集中。\n\n## 团队与人员\n\n- 员工 6,896 人（2026-10 口径）；研发/制造/销售结构待补。\n- 济南总部；全国/全球服务网络。\n- 招聘：2026 年 AI 服务器/液冷岗位扩张；具体待采集。\n- 薪酬/股权激励：国资背景；股权激励待查。\n- 组织：彭震（董事长）、胡雷钧（总经理）、许燕燕（CFO）。\n\n## 竞争格局\n\n- 直接竞品：华为、新华三、联想、中科曙光、Dell、HPE。\n- 替代方案：白牌服务器、云厂商自建。\n- 差异：中国服务器份额、互联网客户、AI 服务器规模；弱点：毛利低、芯片供应。\n- 竞争动态：华为昇腾生态；新华三/联想政企；Dell/HPE 国际。\n- 份额：中国服务器市场份额领先（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：低毛利、存货、客户集中、芯片供应。\n- 技术：AI 服务器/液冷、国产芯片适配。\n- 法律/监管：出口管制、国资监管、数据安全。\n- 治理：国资控制、管理层激励。\n- 争议：增收不增利、股价从高点回落（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：AI 服务器收入、毛利率、客户名单、存货均未入库。建议跟踪：① AI 服务器订单；② 毛利率；③ 存货/现金流；④ 国产芯片适配；⑤ 与华为/新华三的份额。\n\n## 信源与口径\n\n- 2025 年报：https://vip.stock.finance.sina.com.cn/corp/view/vCB_AllBulletinDetail.php?stockid=000977&id=12081456\n- 业绩分析：https://www.nbd.com.cn/articles/2026-04-11/4335187.html\n- 2026 H1：https://money.finance.sina.com.cn/corp/view/vCB_AllBulletinDetail.php?stockid=000977&id=12571681\n- 行情/员工：https://quote.eastmoney.com/sz000977.html ；https://www.google.com/finance/beta/quote/000977:SHE\n- 口径：FY2025 为年报；员工数为第三方；◐ 表示待核。' },
      { id: 'cambricon', name: '寒武纪', def: '国产 AI 芯片第一股：2025 年首次年度盈利，云端产品线放量。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2016 / 北京 | 官网/年报 |\n| 上市地 / 代码 | 科创板 688256 | 2020-07 IPO |\n| 最新财年营收 | FY2025 ¥64.97 亿（+453.21%） | 2025 年报 |\n| 盈利 | 归母净利 ¥20.59 亿（首次年度盈利） | 2025 年报 |\n| 现金流 | 经营现金流明显改善 | 年报 |\n| 客户 | 未披露；云端产品线 ¥64.77 亿 | 年报 |\n| 员工 | 约 1,107 人；研发 887 人（80.13%） | 年报推算 |\n| 市值 / 估值 | 约 ¥5,534 亿（2026-11-02）；股价约 ¥861–880 | Google Finance |\n| 主要股东 | 陈天石等创始团队 | ◐ 待核 |\n| 数据截至 | FY2025；行情 2026-11-02 | — |\n\n## 定位与沿革\n\n国产 AI 芯片第一股：以思元（MLU）云端/边缘 AI 芯片与加速卡为核心，2025 年营收 ¥64.97 亿（+453.21%）、归母净利 ¥20.59 亿，上市以来首次年度盈利。\n\n- 2016 年由陈天石（中科院计算所背景）创立；2020-07 科创板上市（688256）。\n- 产品：思元 MLU 系列云端训练/推理芯片、加速卡、边缘 AI、IP 授权。\n- 2025 年营收 ¥64.97 亿（+453.21%）；云端产品线 ¥64.77 亿（+455.34%），占绝对主体；归母净利 ¥20.59 亿（上年亏损 ¥4.52 亿）。\n- 2025 年季度增速逐季回落：Q1/Q2 同比 40 倍以上，Q3 降至 13 倍，Q4 营收 ¥18.90 亿（+91%）。\n- 2026 年 Q1 单季利润超 ¥10 亿；2026-06 市值盘中突破 ¥1 万亿，成为科创板首家万亿市值公司；2026-11 回落至约 ¥5,534 亿。\n- 2026 年 9 月向 944 名员工授予约 ¥30 亿股权激励。\n\n## 创始人与管理层\n\n- **陈天石（创始人 & 董事长/CEO）**：中科院计算所博士，AI 芯片领域科学家创业者；持股比例待核。\n- **核心团队**：中科院计算所背景；研发 887 人（80.13%）。\n- 董事会：陈天石 + 投资方；具体席位待核。\n- 关键人事变动：2025–2026 年研发/交付团队扩张；具体待采集。\n\n## 商业模式\n\n- **收入结构**：云端 AI 芯片/加速卡为主（99%+），边缘/IP 为辅；硬件+方案。\n- **销售动作**：政企/智算中心项目制 + 渠道；客户集中度未披露。\n- **单位经济**：芯片毛利较高（2025 年毛利率待核）；研发投入 ¥11.69 亿（占营收 17.99%）。\n- **收入质量**：2025 年营收爆发式增长；Q4 增速回落；客户/订单集中度是风险。\n- **定价趋势**：按芯片/加速卡/集群；国产替代溢价。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 思元 MLU（云端） | 训练/推理 AI 芯片 | 按芯片/卡 | 主力 |\n| 加速卡/整机 | AI 加速卡、服务器 | 按卡/整机 | 主力 |\n| 边缘 AI | 边缘推理芯片 | 按芯片 | 增长 |\n| IP 授权 | NPU IP | 按授权 | 增长 |\n| 软件栈 | Cambricon BANG | 随硬件 | 主力 |\n\n- 包装：芯片 + 加速卡 + 整机 + 软件栈；政企/智算方案。\n- 路线图：下一代云端芯片、推理优化、国产供应链。\n\n## 技术栈与壁垒\n\n- **架构**：自研 NPU/MLU 架构 + BANG 软件栈；云端/边缘全覆盖。\n- **AI 路线**：训练/推理芯片；与国产大模型/智算中心适配。\n- **壁垒**：国产 AI 芯片先发、中科院背景、软件栈、科创板融资。\n- **依赖与债务**：先进制程/代工、出口管制、客户集中、估值高。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 智算中心/政企 | 云端训练/推理 | 未披露具体数字 | 年报/媒体 |\n| 互联网客户 | AI 加速卡 | 未披露具体数字 | 媒体 |\n| 边缘客户 | 边缘推理 | 未披露具体数字 | 官网 |\n\n- 客户结构：智算中心、政企、互联网；具体名单未披露。\n- 集中度：未披露；云端产品线占 99%+，客户集中度可能较高（◐）。\n- 续约/流失：项目制；订单节奏影响季度收入。\n\n## 商业进展\n\n- FY2025 营收 ¥64.97 亿（+453.21%）、净利 ¥20.59 亿，首次年度盈利。\n- 2026 Q1 单季利润超 ¥10 亿；2026-06 市值破 ¥1 万亿，2026-11 回落至约 ¥5,534 亿。\n- 2026-09 向 944 名员工授予约 ¥30 亿股权激励。\n- 云端产品线/国产替代是增长主线；Q4 增速回落需关注。\n- 竞争：华为昇腾、海光信息、燧原科技、天数智芯、NVIDIA。\n\n## 经营业绩\n\n| 指标 | 2023 | 2024 | 2025 | 说明 |\n|---|---|---|---|---|\n| 营收 | ¥7.09 亿 | ¥11.74 亿 | ¥64.97 亿 | +453.21% |\n| 增速 | -2.7% | +65.6% | +453.21% | 爆发 |\n| 毛利率 | 待核 | 待核 | 待核 | 芯片 |\n| 营业利润 | 亏损 | 亏损 | 盈利 | — |\n| 归母净利 | -¥8.48 亿 | -¥4.52 亿 | ¥20.59 亿 | 首次盈利 |\n\n- 研发：¥11.69 亿（17.99%）；研发 887 人（80.13%）。\n- 运营指标：云端产品线 ¥64.77 亿（+455.34%）；Q4 营收 ¥18.90 亿（+91%）。\n- 指引：未披露；2026 年增长持续性待观察。\n\n## 股权、融资与股票\n\n- 上市：科创板 688256；2020-07 IPO。\n- 行情（2026-11-02）：股价约 ¥861–880；市值约 ¥5,534 亿；52 周 ¥649.66–1,620。\n- 估值：PE 约 133x（按 2025 净利）；PS 约 85x；高估值。\n- 股东：陈天石等创始团队；机构；具体持股待核。\n- 资本动作：2026 年股权激励约 ¥30 亿；再融资待查。\n- 风险提示：高估值、Q4 增速回落、客户集中。\n\n## 团队与人员\n\n- 员工约 1,107 人；研发 887 人（80.13%）；员工持股 58.72%。\n- 北京总部；研发为主。\n- 招聘：2026 年 AI 芯片/软件岗位扩张；具体待采集。\n- 薪酬/股权激励：2026 年 ¥30 亿股权激励（944 人）。\n- 组织：陈天石（创始人/CEO）；核心高管名单待补。\n\n## 竞争格局\n\n- 直接竞品：华为昇腾、海光信息、燧原科技、天数智芯、NVIDIA。\n- 替代方案：GPU（NVIDIA/AMD/国产 GPU）、ASIC 自研。\n- 差异：国产 AI 芯片先发、软件栈、中科院背景；弱点：客户集中、制程/代工、估值。\n- 竞争动态：国产替代/智算中心放量；华为昇腾生态强势；GPU 厂商挤压。\n- 份额：国产 AI 芯片第一梯队（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：客户集中、订单波动、Q4 增速回落、估值高。\n- 技术：先进制程/代工、软件生态、下一代芯片。\n- 法律/监管：出口管制、科创板披露、信创合规。\n- 治理：创始人控制权、股权激励稀释。\n- 争议：高市值与盈利可持续性（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：客户名单、毛利率、订单/backlog、下一代芯片进度均未入库。建议跟踪：① 2026 营收/利润；② 客户集中度；③ 云端产品线增速；④ 下一代芯片；⑤ 与华为昇腾/海光的份额。\n\n## 信源与口径\n\n- 2025 年报：https://dataclouds.cninfo.com.cn/shgonggao/hsomarket/2026/20260312/05ca784762a7401b9ed371d917e436dc.PDF\n- 业绩：https://epaper.stcn.com/con/202603/13/content_2897916.html\n- 市值/员工：https://www.google.com/finance/quote/688256:SHA\n- 股权激励：https://www.chinaventure.com.cn/news/114-20260902-393073.html\n- 口径：FY2025 为年报；员工数为研发占比推算；◐ 表示待核。' },
      { id: 'enflame', name: '燧原科技', def: '腾讯系云端 AI 芯片：邃思系列，2026 科创板上市首日市值破 1,700 亿。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2018 / 上海 | 官网/招股书 |\n| 上市地 / 代码 | 科创板（2026 上市） | 2026 过会/上市 |\n| 最新财年营收 | FY2025 ¥9.90 亿 | 招股书/媒体 |\n| 盈利 | 亏损；三年累计约 ¥40 亿 | 招股书 |\n| 现金流 | 待核 | ◐ |\n| 客户 | 腾讯占 83.79%（2025） | 招股书 |\n| 员工 | 未披露 | — |\n| 市值 / 估值 | 上市首日约 ¥1,700 亿；Pre-IPO 约 ¥205 亿 | 媒体 |\n| 主要股东 | 腾讯等（腾讯连投 6 轮） | 媒体 |\n| 数据截至 | FY2025；IPO 2026 | — |\n\n## 定位与沿革\n\n腾讯系云端 AI 芯片公司：以邃思（DTU）系列训练/推理芯片与加速卡为核心，2026 年科创板上市，首日开盘暴涨 188%、市值突破 ¥1,700 亿。\n\n- 2018 年成立于上海；创始人/CEO 赵立东（前 AMD 高管，◐ 待核）；腾讯连续投资 6 轮。\n- 产品：邃思云端 AI 芯片、训练/推理加速卡、智算集群。\n- 2023–2025 营收 ¥3.01/7.20/9.90 亿，三年复合增速约 81%；2026 H1 营收 ¥11.2 亿，已超 2025 全年。\n- 2025 年对腾讯直接/间接销售 AI 加速卡及模组收入占营收 83.79%，客户高度集中。\n- 2024 年增资估值 ¥166 亿；2026-01 完成 IPO 辅导，估值约 ¥205 亿；IPO 拟募资 ¥60 亿，发行市值约 ¥400 亿。\n- 2026 年科创板上市，首日开盘 +188%，市值突破 ¥1,700 亿；三年累计亏损约 ¥40 亿。\n\n## 创始人与管理层\n\n- **赵立东（创始人 & CEO）**：前 AMD 高管（◐ 具体职务待核）；主导云端 AI 芯片路线。\n- 核心团队：来自 AMD、NVIDIA、华为等；具体名单待采集。\n- 董事会：腾讯等投资方席位待核。\n- 关键人事变动：IPO 前后团队稳定；研发投入高。\n\n## 商业模式\n\n- **收入结构**：AI 加速卡/模组 + 智算集群；腾讯是最大客户。\n- **销售动作**：大客户直销（腾讯）+ 政企/智算项目；客户集中度极高。\n- **单位经济**：芯片毛利待核；研发投入高，三年亏损约 ¥40 亿。\n- **收入质量**：腾讯占 83.79%；2026 H1 营收超 2025 全年，增长快但依赖单一大客户。\n- **定价趋势**：按加速卡/集群；国产替代溢价。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 邃思 DTU | 云端训练/推理芯片 | 按芯片/卡 | 主力 |\n| 加速卡/模组 | AI 加速卡 | 按卡 | 主力 |\n| 智算集群 | 训练/推理集群 | 按项目 | 增长 |\n| 软件栈 | 编译器/框架适配 | 随硬件 | 主力 |\n| 边缘 AI | 边缘推理 | 按芯片 | 试验 |\n\n- 包装：芯片 + 加速卡 + 集群 + 软件；腾讯/政企方案。\n- 路线图：下一代邃思、推理优化、国产供应链。\n\n## 技术栈与壁垒\n\n- **架构**：自研 DTU 架构 + 软件栈；云端训练/推理。\n- **AI 路线**：大模型训练/推理；与腾讯云/混元适配。\n- **壁垒**：腾讯投资/订单、云端芯片团队、科创板融资；弱点：客户集中、亏损、生态。\n- **依赖与债务**：先进制程/代工、出口管制、腾讯依赖、亏损。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 腾讯 | AI 加速卡/模组 | 占营收 83.79%（2025） | 招股书 |\n| 政企/智算中心 | 训练/推理集群 | 未披露具体数字 | 官网 |\n| 其他互联网客户 | AI 加速 | 未披露具体数字 | 官网 |\n\n- 客户结构：腾讯为主，政企/智算为辅；客户高度集中。\n- 集中度：83.79%（2025）；单一大客户风险。\n- 续约/流失：腾讯订单是核心；其他客户拓展待采集。\n\n## 商业进展\n\n- 2026 年科创板上市，首日 +188%，市值破 ¥1,700 亿；IPO 募资 ¥60 亿。\n- 2025 营收 ¥9.90 亿；2026 H1 ¥11.2 亿，超 2025 全年；前三季度预计 +325%–455%。\n- 腾讯连投 6 轮；2025 年腾讯收入占比 83.79%。\n- 三年累计亏损约 ¥40 亿；研发投入高。\n- 竞争：寒武纪、海光、天数智芯、华为昇腾、NVIDIA。\n\n## 经营业绩\n\n| 指标 | 2023 | 2024 | 2025 | 2026 H1 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | ¥3.01 亿 | ¥7.20 亿 | ¥9.90 亿 | ¥11.2 亿 | 2025 +37.5% |\n| 增速 | — | +139% | +37.5% | 待核 | 2026 加速 |\n| 毛利率 | 待核 | 待核 | 待核 | 待核 | ◐ |\n| 营业利润 | 亏损 | 亏损 | 亏损 | 亏损 | — |\n| 净利 | 亏损 | 亏损 | 亏损 | 亏损 | 三年累计约 -¥40 亿 |\n\n- 客户：腾讯 83.79%（2025）；其他客户待采集。\n- 研发：投入高；具体金额待核。\n- 指引：2026 前三季度营收 +325%–455%（媒体口径）。\n\n## 股权、融资与股票\n\n- 上市：科创板；2026 年上市（具体日期待核）。\n- 行情：上市首日市值约 ¥1,700 亿；当前市值待刷新（◐）。\n- 估值：Pre-IPO ¥205 亿；发行市值约 ¥400 亿；首日 ¥1,700 亿。\n- 股东：腾讯（连投 6 轮）、其他机构；具体持股待核。\n- 资本动作：IPO 募资 ¥60 亿；是否再融资待采集。\n- 风险提示：客户集中、亏损、估值高。\n\n## 团队与人员\n\n- 员工数未披露；研发为主。\n- 上海总部；团队来自 AMD/NVIDIA/华为。\n- 招聘：2026 年芯片/软件岗位扩张；具体待采集。\n- 薪酬/股权激励：科创板上市，有员工持股平台；流失率未披露。\n- 组织：赵立东（CEO）；核心高管名单待补。\n\n## 竞争格局\n\n- 直接竞品：寒武纪、海光信息、天数智芯、华为昇腾、NVIDIA。\n- 替代方案：GPU、ASIC 自研。\n- 差异：腾讯订单/投资、云端 DTU、科创板融资；弱点：客户集中、亏损、生态。\n- 竞争动态：国产 AI 芯片集中上市；腾讯系 vs 阿里系/华为系。\n- 份额：国产云端 AI 芯片第一梯队（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：腾讯依赖（83.79%）、亏损、估值高。\n- 技术：先进制程/代工、软件生态、下一代芯片。\n- 法律/监管：出口管制、科创板披露、关联交易。\n- 治理：腾讯作为股东/客户的关联交易；创始人控制权。\n- 争议：单一大客户与独立获客能力（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：员工数、毛利率、腾讯以外客户、下一代芯片均未入库。建议跟踪：① 腾讯收入占比；② 2026 营收/亏损；③ 新客户拓展；④ 下一代邃思；⑤ 与寒武纪/海光的份额。\n\n## 信源与口径\n\n- IPO/估值：https://www.esmchina.com/news/14587.html\n- 营收/客户：https://www.yicai.com/news/103230658.html\n- 融资/估值：https://m.caixin.com/m/2026-01-04/102399822.html\n- 亏损：https://znyj.ofweek.com/news/2026-09/ART-23001-12003-30701248.html\n- 口径：财务为招股书/媒体；员工数未披露；◐ 表示待核。' },
      { id: 'hygon', name: '海光信息', def: '国产 CPU+DCU 双轮：2025 营收 143.8 亿，DCU 接棒 AI 算力。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2014 / 天津、北京 | 官网 |\n| 上市地 / 代码 | 科创板 688041 | 2022-08 IPO |\n| 最新财年营收 | FY2025 ¥143.77 亿（+56.92%） | 2025 年报 |\n| 盈利 | 归母净利 ¥25.45 亿（+31.79%） | 2025 年报 |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露；服务器/政企 | ◐ |\n| 员工 | 3,333 人 | 年报/媒体 |\n| 市值 / 估值 | 约 ¥4,000–4,400 亿（2026-11）；股价 ¥170–190 | 东方财富/Google |\n| 主要股东 | 中科院系/国资 | ◐ |\n| 数据截至 | FY2025；2026 Q3 | — |\n\n## 定位与沿革\n\n国产 CPU + DCU 双轮：海光通用处理器（CPU）是基本盘，深算 DCU（类 CUDA AI 加速卡）接棒 AI 算力；2025 年营收 ¥143.77 亿（+56.92%）、净利 ¥25.45 亿（+31.79%）。\n\n- 2014 年成立，源自中科院系/AMD x86 技术授权合作；2022-08 科创板上市（688041）。\n- 产品：海光 CPU（服务器/桌面）、深算 DCU（AI 训练/推理）、加速卡/整机。\n- FY2025 营收 ¥143.77 亿（+56.92%）、归母净利 ¥25.45 亿（+31.79%）、毛利率约 57.83%；分红 10 派 1.5 元。\n- 2026 年加速：Q1 营收约 ¥40.65 亿（+69%）；H1 营收 ¥90.99 亿（+66.52%）、净利 ¥17.98 亿（+49.69%）；前三季度营收 ¥149.55 亿（+57.58%）、净利 ¥28.47 亿（+45.12%）。\n- 员工 3,333 人；员工持股 18.33%；2026-01 市值一度突破 ¥7,000 亿，2026-11 回落至约 ¥4,000–4,400 亿。\n- 业务结构：「CPU 压舱、DCU 扬帆」；DCU 是 AI 增量。\n\n## 创始人与管理层\n\n- **中科院系创始团队**：海光由中科院系推动成立；具体创始人名单待核。\n- **总经理/董事长**：沙超群等（◐ 职务待核）。\n- 核心团队：芯片设计/服务器背景；员工 3,333 人。\n- 董事会：中科院系/国资 + 投资方；具体席位待核。\n- 关键人事变动：2025–2026 年管理层稳定；员工持股计划。\n\n## 商业模式\n\n- **收入结构**：CPU + DCU + 加速卡/整机；硬件为主。\n- **销售动作**：服务器厂商/政企/信创渠道；CPU 基本盘 + DCU 增量。\n- **单位经济**：毛利率约 57.83%（2025）；研发投入高；净利率约 17.7%。\n- **收入质量**：政企/信创客户为主；DCU 收入占比上升；客户集中度未披露。\n- **定价趋势**：CPU/DCU 按芯片/整机；国产替代溢价。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 海光 CPU | 服务器/桌面 x86 兼容 CPU | 按芯片 | 主力 |\n| 深算 DCU | AI 训练/推理加速卡 | 按卡 | 增长 |\n| 加速卡/整机 | DCU 服务器/集群 | 按整机 | 增长 |\n| 软件栈 | DCU 编译器/框架适配 | 随硬件 | 主力 |\n| 信创方案 | 政企/金融信创 | 按项目 | 主力 |\n\n- 包装：CPU + DCU + 整机 + 软件；信创/智算方案。\n- 路线图：下一代 CPU/DCU、国产工艺、AI 集群。\n\n## 技术栈与壁垒\n\n- **架构**：x86 兼容 CPU + GPGPU 类 DCU；国产工艺适配。\n- **AI 路线**：深算 DCU 支持大模型训练/推理；类 CUDA 生态。\n- **壁垒**：x86 兼容生态、中科院系/国资、信创渠道、DCU 先发。\n- **依赖与债务**：x86 授权/地缘政治、先进制程/代工、客户集中、估值。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 服务器厂商 | 海光 CPU/DCU 整机 | 未披露具体数字 | 年报/媒体 |\n| 政企/金融 | 信创服务器、DCU | 未披露具体数字 | 官网 |\n| 智算中心 | DCU 集群 | 未披露具体数字 | 媒体 |\n\n- 客户结构：服务器厂商、政企、金融、智算中心；具体名单未披露。\n- 集中度：未披露；信创/服务器客户占比高（◐）。\n- 续约/流失：项目制；DCU 订单是增量。\n\n## 商业进展\n\n- FY2025 营收 ¥143.77 亿（+56.92%）、净利 ¥25.45 亿（+31.79%）。\n- 2026 前三季度营收 ¥149.55 亿（+57.58%）、净利 ¥28.47 亿（+45.12%）。\n- DCU 高速增长；CPU 基本盘稳定；信创/智算需求。\n- 2026-01 市值一度破 ¥7,000 亿；2026-11 约 ¥4,000–4,400 亿。\n- 竞争：Intel/AMD、华为昇腾、寒武纪、燧原、天数。\n\n## 经营业绩\n\n| 指标 | 2023 | 2024 | 2025 | 2026 前三季度 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | 未披露 | ¥91.62 亿 | ¥143.77 亿 | ¥149.55 亿 | 2025 +56.92% |\n| 增速 | 未披露 | +? | +56.92% | +57.58% | 高速 |\n| 毛利率 | 未披露 | 约 57% | 57.83% | 待核 | — |\n| 营业利润 | 未披露 | 未披露 | 未披露 | 未披露 | — |\n| 归母净利 | 未披露 | ¥19.31 亿 | ¥25.45 亿 | ¥28.47 亿 | +31.79%/+45.12% |\n\n- 运营指标：员工 3,333；员工持股 18.33%；毛利率 57.83%。\n- 指引：2026 年机构目标价 ¥304–325（现价 ¥177，折价明显）。\n- 市场预期：DCU 放量、信创需求。\n\n## 股权、融资与股票\n\n- 上市：科创板 688041；2022-08 IPO，发行价 ¥36。\n- 行情（2026-11）：股价约 ¥170–190；市值约 ¥4,000–4,400 亿；总股本约 23.24 亿股；PE 约 119x。\n- 估值：PE 119x；PS 约 28x；高估值。\n- 股东：中科院系/国资、机构；员工持股 18.33%。\n- 资本动作：2025 年分红 10 派 1.5 元；员工持股计划。\n- 风险提示：估值高、x86 授权/地缘政治、客户集中。\n\n## 团队与人员\n\n- 员工 3,333 人；研发占比待补；员工持股 18.33%（1.41 亿股，占总股本 6.09%）。\n- 天津/北京；研发为主。\n- 招聘：2026 年 DCU/AI 岗位扩张；具体待采集。\n- 薪酬/股权激励：员工持股计划；人均创利约 ¥76 万。\n- 组织：中科院系管理层；具体名单待补。\n\n## 竞争格局\n\n- 直接竞品：Intel、AMD（CPU/GPU）、华为昇腾、寒武纪、燧原、天数。\n- 替代方案：国产 GPU、ASIC 自研、ARM 服务器。\n- 差异：x86 兼容 CPU + 类 CUDA DCU、信创渠道；弱点：授权/制程、生态、估值。\n- 竞争动态：信创/智算放量；华为昇腾生态强势；海光 DCU 差异化。\n- 份额：国产服务器 CPU 领先（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：估值高、客户集中、DCU 竞争、毛利率。\n- 技术：x86 授权/地缘政治、先进制程/代工、软件生态。\n- 法律/监管：出口管制、信创合规、证券披露。\n- 治理：中科院系/国资控制、员工持股。\n- 争议：高估值与业绩增速匹配度（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：DCU 收入占比、客户名单、毛利率、授权风险均未入库。建议跟踪：① DCU 收入/订单；② 毛利率；③ x86 授权/制裁；④ 信创需求；⑤ 与华为昇腾/寒武纪的份额。\n\n## 信源与口径\n\n- 2025 年报：https://money.finance.sina.com.cn/corp/view/vCB_AllBulletinDetail.php?stockid=688041&id=12066610\n- 业绩：https://www.stcn.com/article/detail/3730253.html\n- 2026 三季报：https://m.sohu.com/a/1089966170_122014422\n- 市值：https://data.eastmoney.com/gzfx/detail/688041.html\n- 口径：FY2025 为年报；市值为 2026-11 第三方；◐ 表示待核。' },
      { id: 'iluvatar', name: '天数智芯', def: '港股通用 GPU：天垓训练 + 彤央推理，2025 营收 10.34 亿。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2015/2016 / 上海 | 招股书 |\n| 上市地 / 代码 | 港交所 09903 | 2025-12 招股，2026 上市 |\n| 最新财年营收 | FY2025 ¥10.34 亿（+91.6%） | 2025 年报 |\n| 盈利 | 经调整净亏损收窄；累计亏损 >¥28 亿 | 年报/媒体 |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露（匿名客户 A/B） | 招股书 |\n| 员工 | 未披露 | — |\n| 市值 / 估值 | 上市初约 ¥330.67 亿；后一度千亿 | 媒体 |\n| 主要股东 | 大钲资本、红杉中国等 | 招股书 |\n| 数据截至 | FY2025；IPO 2025-12/2026 | — |\n\n## 定位与沿革\n\n港股通用 GPU 厂商：以天垓（训练）与彤央（推理）系列覆盖云、边、端，2025 年营收 ¥10.34 亿（+91.6%），通用 GPU 收入 ¥9.23 亿（+149.6%）。\n\n- 2015/2016 年成立于上海；国产 GPU「四小龙」之一；曾经历创始人出走、两次换帅、战略摇摆（媒体口径）。\n- 产品：天垓训练 GPU、彤央推理 GPU、加速卡/智算集群。\n- FY2025 营收 ¥10.34 亿（+91.6%）；毛利率从 49.1% 升至 54%；通用 GPU 收入 ¥9.23 亿（+149.6%），占 89.3%。\n- 天垓系列收入 ¥5.837 亿（2024 ¥2.694 亿），占通用 GPU 收入 63.3%；天垓 Gen2/天垓 150 是主力。\n- 2025-12 港交所招股，发售价 HK$144.6，净募资约 HK$34.79 亿；发行市值约 ¥330.67 亿（按 2025H1 营收，PS 约 51x）。\n- 上市后股价大涨，出现「千亿市值」报道；Pre-IPO 估值约 ¥120 亿；历史累计亏损 >¥28 亿。\n\n## 创始人与管理层\n\n- **创始团队**：上海 GPU 创业团队；具体创始人姓名待核（媒体称创始人曾出走）。\n- **管理层**：经历两次换帅；现任 CEO/CTO 名单待采集。\n- 董事会：大钲资本、红杉中国等投资方席位待核。\n- 关键人事变动：创始人出走、两次换帅、战略摇摆（媒体口径，◐）。\n\n## 商业模式\n\n- **收入结构**：通用 GPU（天垓/彤央）+ 加速卡/集群；硬件为主。\n- **销售动作**：政企/智算项目制 + 渠道；客户匿名披露。\n- **单位经济**：毛利率 54%（2025）；研发投入高，累计亏损 >¥28 亿。\n- **收入质量**：营收 ¥10.34 亿；客户 A/B 匿名，集中度待核。\n- **定价趋势**：按 GPU/集群；国产替代溢价。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 天垓 | 训练 GPU | 按卡/集群 | 主力 |\n| 彤央 | 推理 GPU | 按卡 | 增长 |\n| 加速卡/整机 | GPU 加速卡、服务器 | 按卡/整机 | 主力 |\n| 智算集群 | 训练/推理集群 | 按项目 | 增长 |\n| 软件栈 | 编译器/框架适配 | 随硬件 | 主力 |\n\n- 包装：GPU + 加速卡 + 集群 + 软件；云边端方案。\n- 路线图：天垓 Gen3、推理优化、国产供应链。\n\n## 技术栈与壁垒\n\n- **架构**：通用 GPU（GPGPU）+ 软件栈；训练/推理全覆盖。\n- **AI 路线**：天垓训练/彤央推理；与国产大模型/智算适配。\n- **壁垒**：国产 GPU 先发、港股融资、云边端产品线；弱点：治理历史、亏损、客户集中。\n- **依赖与债务**：先进制程/代工、出口管制、亏损、客户集中。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 客户 A/B（匿名） | 训练/推理 GPU | 未披露具体数字 | 招股书 |\n| 政企/智算中心 | 智算集群 | 未披露具体数字 | 官网 |\n| 边缘客户 | 推理 GPU | 未披露具体数字 | 官网 |\n\n- 客户结构：政企、智算中心、边缘；具体名单匿名。\n- 集中度：未披露；客户 A/B 占比可能较高（◐）。\n- 续约/流失：项目制；天垓 Gen2 出货是核心。\n\n## 商业进展\n\n- 2025-12 港交所招股，发售价 HK$144.6，净募资约 HK$34.79 亿；2026 年上市。\n- FY2025 营收 ¥10.34 亿（+91.6%）、毛利率 54%；通用 GPU ¥9.23 亿（+149.6%）。\n- 天垓系列 ¥5.837 亿，占通用 GPU 63.3%；天垓 Gen2/150 主力。\n- 上市后股价大涨，市值一度千亿；Pre-IPO 估值 ¥120 亿。\n- 竞争：寒武纪、燧原、海光、摩尔线程、壁仞、沐曦、NVIDIA。\n\n## 经营业绩\n\n| 指标 | 2023 | 2024 | 2025 | 说明 |\n|---|---|---|---|---|\n| 营收 | 待核 | ¥5.40 亿 | ¥10.34 亿 | +91.6% |\n| 增速 | — | 待核 | +91.6% | 高速 |\n| 毛利率 | 待核 | 49.1% | 54% | 改善 |\n| 营业利润 | 亏损 | 亏损 | 亏损 | — |\n| 净利 | 亏损 | 亏损 | 经调整亏损收窄 | 累计 >-¥28 亿 |\n\n- 运营指标：通用 GPU 占 89.3%；天垓占 GPU 收入 63.3%。\n- 指引：未披露；天垓 Gen3 待发布。\n- 市场预期：国产 GPU 上市潮与估值。\n\n## 股权、融资与股票\n\n- 上市：港交所 09903；2025-12 招股，2026 上市。\n- 行情：发行市值约 ¥330.67 亿；上市后一度千亿；当前待刷新（◐）。\n- 估值：发行 PS 约 51x（按 2025H1 营收年化）；亏损，PE 不适用。\n- 股东：大钲资本、红杉中国、Princeville、沄柏等；具体持股待核。\n- 资本动作：IPO 净募资约 HK$34.79 亿；再融资待采集。\n- 风险提示：治理历史、亏损、客户集中、估值。\n\n## 团队与人员\n\n- 员工数未披露；研发为主。\n- 上海总部；团队来自 GPU/芯片公司。\n- 招聘：2026 年 GPU/软件岗位扩张；具体待采集。\n- 薪酬/股权激励：港股上市，有员工持股平台；流失率未披露。\n- 组织：经历两次换帅；现任管理层待补。\n\n## 竞争格局\n\n- 直接竞品：寒武纪、燧原、海光、摩尔线程、壁仞、沐曦、NVIDIA。\n- 替代方案：GPU、ASIC 自研。\n- 差异：通用 GPU 云边端、港股融资、天垓先发；弱点：治理、亏损、客户集中。\n- 竞争动态：国产 GPU 集中上市；资本/订单竞争激烈。\n- 份额：国产 GPU 第一梯队（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：治理历史（创始人出走/换帅）、亏损、客户集中、估值。\n- 技术：先进制程/代工、软件生态、天垓 Gen3。\n- 法律/监管：出口管制、港股披露、信创合规。\n- 治理：创始人/管理层变动、投资方控制。\n- 争议：战略摇摆与上市估值（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：客户名单、员工数、毛利率、天垓 Gen3 均未入库。建议跟踪：① 天垓 Gen3；② 2026 营收/亏损；③ 客户集中度；④ 治理/管理层；⑤ 与摩尔线程/壁仞的份额。\n\n## 信源与口径\n\n- 2025 年报：https://www.hkexnews.hk/listedco/listconews/sehk/2026/0427/2026042701285_c.pdf\n- 营收：https://m.bjnews.com.cn/detail/1774921830168210.html\n- IPO：https://www.futuhk.com/hans/blog/detail-iluvatar-corex-ipo-100-251269003\n- 治理：https://wallstreetcn.com/articles/3762560\n- 口径：FY2025 为年报；员工数未披露；◐ 表示待核。' },
      { id: 'marvell', name: 'Marvell', def: '定制 AI 芯片与数据中心互联：FY2026 营收 $82 亿，定制芯片 $15 亿。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 1995 / Wilmington, DE（运营 Santa Clara） | 官网 |\n| 上市地 / 代码 | NASDAQ: MRVL | 2000 IPO |\n| 最新财年营收 | FY2026 约 $82 亿；数据中心 $61 亿 | 投资者日/研报 |\n| 盈利 | 待核 | ◐ |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露；主要 hyperscalers | 公司口径 |\n| 员工 | 约 7,042 人 | 2026-04 估算 |\n| 市值 / 估值 | 约 $2,190 亿（2026-10）；股价约 $243.57 | 媒体/行情 |\n| 主要股东 | 机构为主 | ◐ |\n| 数据截至 | FY2026；行情 2026-10 | — |\n\n## 定位与沿革\n\n定制 AI 芯片与数据中心互联厂商：FY2026 营收约 $82 亿，其中数据中心 $61 亿、定制芯片约 $15 亿；客户覆盖主要 hyperscalers，AI 定制 ASIC 是增长主线。\n\n- 1995 年成立，总部 Wilmington, DE；Matt Murphy 2016 年起任 CEO。\n- 业务：定制 ASIC、光电互联、交换、存储、连接芯片；数据中心占比持续提升。\n- FY2026 营收约 $82 亿，数据中心约 $61 亿；定制芯片约 $15 亿，已向所有主要 hyperscalers 出货（CEO 口径）。\n- Q1 FY2027 营收 $24.18 亿（+28%），创纪录；FY2027 指引上调至约 $165 亿。\n- 2026-10 投资者日：FY2028 营收目标上调至约 $200 亿；2031 年目标最高 $900 亿；2030 年 TAM 约 $4,000 亿。\n- 员工约 7,042 人；市值约 $2,190 亿（2026-10）。\n\n## 创始人与管理层\n\n- **Matt Murphy（董事长 & CEO）**：2016 年起任 CEO；主导数据中心/定制芯片转型。\n- **核心高管**：CFO/CTO/业务线负责人名单待采集。\n- 董事会：机构 + 管理层；具体席位待核。\n- 关键人事变动：2025–2026 年 AI/定制芯片团队扩张；具体待采集。\n- 创始人：1995 年由 Sehat Sutardja 等创立（◐ 历史细节待核）。\n\n## 商业模式\n\n- **收入结构**：数据中心（定制 ASIC、光电、交换）、企业网络、运营商、汽车/消费。\n- **销售动作**：大客户直销（hyperscalers）+ 渠道；定制 ASIC 项目制。\n- **单位经济**：芯片毛利较高；定制 ASIC 前期 NRE、后期量产放量。\n- **收入质量**：数据中心占比高；客户集中（hyperscalers）；AI 订单是增量。\n- **定价趋势**：定制 ASIC 按项目/晶圆；光电/交换按端口/芯片。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 定制 ASIC | AI 训练/推理定制芯片 | 按项目/晶圆 | 主力 |\n| 光电互联 | 800G/1.6T 光模块/DSP | 按端口/芯片 | 主力 |\n| 交换芯片 | 数据中心交换 | 按端口 | 增长 |\n| 存储/连接 | SSD 控制器、PHY | 按芯片 | 主力 |\n| 汽车/企业网络 | 车载/企业网络芯片 | 按芯片 | 增长 |\n\n- 包装：芯片 + 参考设计 + 软件；hyperscaler 定制。\n- 路线图：2nm/3nm 定制 ASIC、1.6T 光电、AI 集群互联。\n\n## 技术栈与壁垒\n\n- **架构**：SerDes/光电/DSP + 定制 ASIC 设计；先进制程。\n- **AI 路线**：为 hyperscalers 定制训练/推理芯片；光电互联解决集群瓶颈。\n- **壁垒**：SerDes/光电 IP、定制 ASIC 交付记录、hyperscaler 关系。\n- **依赖与债务**：客户集中、先进制程/代工、定制项目波动、竞争。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 主要 hyperscalers | 定制 AI ASIC | 未披露具体数字 | CEO 口径 |\n| 云厂商 | 光电/交换 | 未披露具体数字 | 官网 |\n| 企业/汽车 | 网络/存储芯片 | 未披露具体数字 | 官网 |\n\n- 客户结构：hyperscalers、云厂商、企业、汽车；集中度高。\n- 集中度：未披露；hyperscaler 定制项目占比高（◐）。\n- 续约/流失：定制 ASIC 项目周期长；量产放量是核心。\n\n## 商业进展\n\n- FY2026 营收约 $82 亿、数据中心 $61 亿、定制芯片 $15 亿。\n- Q1 FY2027 营收 $24.18 亿（+28%），FY2027 指引约 $165 亿。\n- 2026-10 投资者日：FY2028 目标约 $200 亿；2031 年最高 $900 亿；TAM $4,000 亿。\n- 定制 ASIC 已向所有主要 hyperscalers 出货；AI 需求驱动。\n- 竞争：Broadcom、Alchip、Arm、NVIDIA、AMD。\n\n## 经营业绩\n\n| 指标 | FY2024 | FY2025 | FY2026 | 说明 |\n|---|---|---|---|---|\n| 营收 | $55.1 亿 | $57.7 亿 | 约 $82 亿 | 数据中心驱动 |\n| 增速 | -7% | +5% | +42% | 加速 |\n| 毛利率 | 约 60% | 约 60% | 待核 | ◐ |\n| 营业利润 | 待核 | 待核 | 待核 | — |\n| 净利 | 亏损/微利 | 待核 | 待核 | ◐ |\n\n- 运营指标：数据中心 $61 亿；定制芯片 $15 亿；员工 7,042。\n- 指引：FY2027 约 $165 亿；FY2028 约 $200 亿；2031 年最高 $900 亿。\n- 市场预期：AI 定制 ASIC 与光电互联。\n\n## 股权、融资与股票\n\n- 上市：NASDAQ MRVL；2000 年 IPO。\n- 行情（2026-10）：股价约 $243.57；市值约 $2,190 亿；52 周区间待补（◐）。\n- 估值：PS 约 26x（按 FY2026 $82 亿）；PE 待核。\n- 股东：机构为主；创始人持股待核。\n- 资本动作：回购/分红待查；2026 年股价上涨。\n- 风险提示：客户集中、定制项目波动、估值。\n\n## 团队与人员\n\n- 员工约 7,042 人（2026-04 估算）；研发为主。\n- Wilmington/Santa Clara；全球研发中心。\n- 招聘：2026 年 AI/定制芯片岗位扩张；具体待采集。\n- 薪酬/股权激励：RSU；流失率未披露。\n- 组织：Matt Murphy（CEO）；业务线负责人待补。\n\n## 竞争格局\n\n- 直接竞品：Broadcom（定制 ASIC）、Alchip、GUC、NVIDIA、AMD。\n- 替代方案：GPU、自研 ASIC、FPGA。\n- 差异：SerDes/光电 + 定制 ASIC、hyperscaler 关系；弱点：客户集中、定制波动。\n- 竞争动态：Broadcom 主导定制 ASIC；Marvell 以光电/互联差异化。\n- 份额：定制 AI ASIC 第二（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：客户集中、定制项目波动、AI capex、竞争。\n- 技术：先进制程/代工、2nm/3nm、光电。\n- 法律/监管：出口管制、数据安全。\n- 治理：管理层/董事会；并购整合。\n- 争议：高估值与客户集中（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：定制 ASIC 客户、订单/backlog、毛利率均未入库。建议跟踪：① 数据中心增速；② 定制 ASIC 项目；③ FY2027 指引；④ 光电互联；⑤ 与 Broadcom 的份额。\n\n## 信源与口径\n\n- FY2026/投资者日：https://www.reuters.com/business/marvell-raises-2028-revenue-forecast-strong-ai-data-center-demand-2026-10-06/\n- 管理层：https://www.marvell.com/company/leadership/matt-murphy.html\n- 研报：https://velocityfinancialbrokers.com/research/ideas/2026-10-27-marvell-company-report.pdf\n- 行情/员工：https://www.macrotrends.net/stocks/charts/MRVL/marvell/market-cap\n- 口径：FY2026 为投资者日/研报口径；◐ 表示待核。' },
      { id: 'alchip', name: '世芯电子', def: 'AI ASIC 设计服务商：2025 营收 NT$309 亿，2026 年 3nm 放量。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2003 / 台北 | 官网 |\n| 上市地 / 代码 | 台交所 3661 | 2014 上市 |\n| 最新财年营收 | FY2025 NT$309.24 亿（-39%） | 2025 年报/媒体 |\n| 盈利 | Q4 2025 净利约 US$48M；毛利率 42% | ◐ 口径待核 |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露；北美/亚太 CSP | 法说会 |\n| 员工 | 未披露 | — |\n| 市值 / 估值 | 约 NT$2,000–4,000 亿（◐ 口径不一） | 富邦/媒体 |\n| 主要股东 | 未披露 | — |\n| 数据截至 | FY2025；2026 月度营收 | — |\n\n## 定位与沿革\n\nAI ASIC 设计服务商：为北美/亚太 CSP 提供 3nm/2nm 定制芯片的 NRE + turnkey 服务；2025 年营收 NT$309.24 亿（-39%），2026 年随 3nm 量产放量，9 月单月营收 NT$99.79 亿（+496%）。\n\n- 2003 年成立于台北；台交所上市（3661）；专注 AI/HPC ASIC 设计服务。\n- 业务：ASIC/SoC 设计（NRE）、turnkey 量产、先进封装/测试。\n- FY2025 营收 NT$309.24 亿（约 US$9.92 亿），同比 -39%（2024 约 US$16 亿），受产能/项目节奏影响。\n- Q4 2025 净利约 US$48M（环比 +8%、同比 -16%），毛利率 42%（NRE 占比提升）。\n- 2026 年 3nm 量产放量：9 月单月营收 NT$99.79 亿（+496%）；2026 年营收目标 US$10 亿。\n- 客户：北美/亚太 CSP，第三代 ASIC；ADAS 新订单；员工数未披露。\n\n## 创始人与管理层\n\n- **创始团队**：台湾 ASIC 设计服务背景；具体创始人姓名待核。\n- **CEO/管理层**：法说会管理层；具体名单待采集。\n- 董事会：台湾上市公司治理；席位待核。\n- 关键人事变动：2025–2026 年管理层稳定；3nm 项目团队扩张。\n\n## 商业模式\n\n- **收入结构**：NRE（设计服务）+ turnkey（量产）/ wafer 销售；ASIC 项目制。\n- **销售动作**：CSP/系统厂商直销；项目周期 12–24 个月。\n- **单位经济**：NRE 毛利高、量产毛利低；2025 年毛利率 42%（NRE 占比提升）。\n- **收入质量**：客户集中（少数 CSP）；项目节奏导致营收波动。\n- **定价趋势**：NRE 按人月/项目；量产按 wafer/芯片。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| AI ASIC 设计 | 训练/推理定制芯片 | NRE/项目 | 主力 |\n| HPC ASIC | 高性能计算定制 | NRE/项目 | 主力 |\n| Turnkey 量产 | 晶圆/封装/测试 | 按 wafer/芯片 | 主力 |\n| 3nm/2nm | 先进制程设计 | 项目 | 增长 |\n| ADAS/汽车 | 车规 ASIC | 项目 | 增长 |\n\n- 包装：NRE + turnkey；CSP 定制。\n- 路线图：3nm/2nm、先进封装、汽车 ASIC。\n\n## 技术栈与壁垒\n\n- **架构**：先进制程 ASIC 设计/验证/物理实现；与台积电等代工合作。\n- **AI 路线**：CSP 定制 AI 芯片；3nm/2nm 项目。\n- **壁垒**：先进制程设计经验、CSP 客户关系、台积电产能。\n- **依赖与债务**：客户集中、台积电产能、项目节奏、人才。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 北美 CSP | AI ASIC 设计/量产 | 未披露具体数字 | 法说会 |\n| 亚太 CSP | HPC/AI ASIC | 未披露具体数字 | 法说会 |\n| 汽车客户 | ADAS ASIC | 未披露具体数字 | 法说会 |\n\n- 客户结构：北美/亚太 CSP、汽车；客户集中。\n- 集中度：未披露；少数 CSP 贡献大部分收入（◐）。\n- 续约/流失：项目制；3nm 量产是 2026 核心。\n\n## 商业进展\n\n- FY2025 营收 NT$309.24 亿（-39%）；Q4 净利约 US$48M、毛利率 42%。\n- 2026 年 3nm 量产放量；9 月单月营收 NT$99.79 亿（+496%）。\n- 2026 年营收目标 US$10 亿；ADAS 新订单。\n- 市值约 NT$2,000–4,000 亿（◐）；股价随 3nm 放量波动。\n- 竞争：Broadcom、Marvell、GUC（创意电子）、Faraday。\n\n## 经营业绩\n\n| 指标 | 2023 | 2024 | 2025 | 2026 9M | 说明 |\n|---|---|---|---|---|---|\n| 营收 | 待核 | 约 US$16 亿 | NT$309.24 亿（US$9.92 亿） | 月度放量 | 2025 -39% |\n| 增速 | 待核 | 高增长 | -39% | +496%（9 月） | 波动 |\n| 毛利率 | 待核 | 待核 | 42% | 待核 | NRE 提升 |\n| 营业利润 | 待核 | 待核 | 待核 | 待核 | — |\n| 净利 | 待核 | 待核 | Q4 约 US$48M | 待核 | ◐ |\n\n- 运营指标：2026 年营收目标 US$10 亿；3nm 项目放量。\n- 指引：2026 年 US$10 亿；具体毛利率指引待核。\n- 市场预期：3nm 量产与 CSP 订单。\n\n## 股权、融资与股票\n\n- 上市：台交所 3661；2014 年上市。\n- 行情：市值约 NT$2,000–4,000 亿（◐ 口径不一）；股价待刷新。\n- 估值：PS 约 6–12x（按 2025 营收 NT$309 亿）；PE 待核。\n- 股东：创始团队/机构；具体持股待核。\n- 资本动作：分红/融资待查；2026 年 3nm 放量。\n- 风险提示：客户集中、项目节奏、估值波动。\n\n## 团队与人员\n\n- 员工数未披露；以 ASIC 设计工程师为主。\n- 台北总部；北美/亚太业务团队。\n- 招聘：2026 年 3nm/2nm 项目扩张；具体待采集。\n- 薪酬/股权激励：台湾上市 RSU/员工分红；流失率未披露。\n- 组织：CEO/管理层；具体名单待补。\n\n## 竞争格局\n\n- 直接竞品：Broadcom、Marvell、GUC（创意电子）、Faraday（智原）。\n- 替代方案：CSP 自研团队、EDA/设计服务外包。\n- 差异：先进制程 ASIC 设计、CSP 关系、台积电产能；弱点：客户集中、项目波动。\n- 竞争动态：Broadcom 主导；Marvell 光电/ASIC；GUC 台积电生态。\n- 份额：AI ASIC 设计服务前列（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：客户集中、项目节奏、台积电产能、营收波动。\n- 技术：3nm/2nm、先进封装、设计人才。\n- 法律/监管：出口管制、台湾监管、客户合规。\n- 治理：台湾上市公司治理；管理层稳定。\n- 争议：2025 营收 -39% 与 2026 爆发的反差（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：客户名单、员工数、3nm 项目、毛利率均未入库。建议跟踪：① 3nm 量产；② 2026 营收 US$10 亿目标；③ CSP 客户；④ 毛利率；⑤ 与 Broadcom/Marvell 的份额。\n\n## 信源与口径\n\n- 2025 营收：https://www.nstock.tw/%E4%B8%96%E8%8A%AF-KY%E5%81%9A%E4%BB%80%E9%BA%BC.html\n- 2026 月度营收：https://statementdog.com/analysis/3661/monthly-revenue\n- 法说会：https://www.esunsec.com.tw/market/news?id=6108880\n- 年报：https://www.alchip.com/upload/2026_03_06/6_20260306133144q7eoyv73L0.pdf\n- 口径：2025 营收为 NT$；净利/毛利率为媒体口径；◐ 表示待核。' },
      { id: 'arm', name: 'Arm', def: 'CPU IP 与版税帝国：FY2026 营收 $49 亿，AI 数据中心与端侧双轮。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 1990 / Cambridge, UK | 官网 |\n| 上市地 / 代码 | NASDAQ: ARM | 2023-09 IPO |\n| 最新财年营收 | FY2026 $49 亿 | 2026-05 发布 |\n| 盈利 | 待核 | ◐ |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露；芯片厂商/云厂商 | ◐ |\n| 员工 | 约 7,000 人（◐） | — |\n| 市值 / 估值 | 约 $2,200 亿（2026-11-02）；股价约 $228.77 | Macrotrends |\n| 主要股东 | SoftBank（控股）、公众股东 | ◐ |\n| 数据截至 | FY2026（2026-03）；行情 2026-11-02 | — |\n\n## 定位与沿革\n\nCPU IP 与版税帝国：以 Arm 架构授权（licensing）+ 版税（royalties）覆盖手机、数据中心、汽车与 IoT；FY2026 营收 $49 亿，AI 数据中心与端侧是增长双轮。\n\n- 1990 年成立于英国剑桥；2016 年被 SoftBank 收购；2023-09 在纳斯达克重新上市（ARM）。\n- 商业模式：IP 授权（前期 license fee）+ 每颗芯片版税；客户包括 Apple、Qualcomm、NVIDIA、云厂商等。\n- FY2025 营收 $49.2 亿（+22.8%）；FY2026 营收约 $49 亿。\n- FY2026 Q3 版税 $7.37 亿（+27%，创纪录）；Q4 授权 $8.19 亿（+29%）、版税 $6.71 亿（+11%）。\n- 2026-03 CEO Rene Haas 提出 2031 年营收 $250 亿目标；此前目标为 2030 年前 $150 亿。\n- 2026 年股价大起大落：6 月 22 日高点 $445.05，7 月 29 日低点 $201.32；11 月约 $228.77，市值约 $2,200 亿。\n\n## 创始人与管理层\n\n- **Rene Haas（CEO）**：2022 年起任 Arm CEO；前 NVIDIA 高管（◐ 履历待核）；主导数据中心/汽车扩张。\n- **SoftBank/孙正义**：控股股东；推动 Arm 的 AI 战略。\n- **核心团队**：IP/芯片设计背景；具体名单待采集。\n- 董事会：SoftBank + 独立董事；2023 IPO 后治理结构。\n- 关键人事变动：2022 年 CEO 交接；2023 年 IPO。\n\n## 商业模式\n\n- **收入结构**：授权费（license）+ 版税（royalty）；版税随芯片出货量。\n- **销售动作**：IP 授权直销 + 生态；芯片厂商/云厂商。\n- **单位经济**：授权毛利高、版税稳定；研发投入大。\n- **收入质量**：版税经常性；授权波动；AI/数据中心提升单芯片版税。\n- **定价趋势**：按 IP/架构授权 + 按芯片版税；新架构（Armv9/Compute Subsystems）提升单价。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| CPU IP | Cortex/X 系列 CPU | 授权+版税 | 主力 |\n| GPU/NPU IP | Mali/Immortalis/Ethos | 授权+版税 | 增长 |\n| Compute Subsystems | 预集成计算子系统 | 授权 | 增长 |\n| 数据中心 | Neoverse 服务器 CPU | 授权+版税 | 增长 |\n| 汽车/IoT | 车规/IoT IP | 授权+版税 | 增长 |\n\n- 包装：IP 授权 + 版税；CSS 提升集成度/单价。\n- 路线图：Neoverse、Armv9、AI IP、汽车。\n\n## 技术栈与壁垒\n\n- **架构**：Arm ISA + CPU/GPU/NPU IP；生态（编译器/OS/工具链）。\n- **AI 路线**：CPU+NPU 组合；数据中心 Neoverse；端侧 AI。\n- **壁垒**：ISA 生态、IP 组合、芯片厂商关系、版税模式。\n- **依赖与债务**：RISC-V 竞争、SoftBank 控制、AI capex、客户自研。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| Apple/Qualcomm | 手机/PC CPU | 未披露具体数字 | 生态 |\n| NVIDIA/云厂商 | 数据中心 CPU/GPU 配套 | 未披露具体数字 | 生态 |\n| 汽车/IoT 厂商 | 车规/IoT | 未披露具体数字 | 官网 |\n\n- 客户结构：手机、PC、数据中心、汽车、IoT；全球芯片厂商。\n- 集中度：未披露；少数大客户版税占比高（◐）。\n- 续约/流失：长期架构授权；版税随出货。\n\n## 商业进展\n\n- FY2026 营收约 $49 亿；Q4 授权 $8.19 亿（+29%）、版税 $6.71 亿（+11%）。\n- Q3 FY2026 版税 $7.37 亿（+27%，创纪录）；AI/数据中心驱动。\n- 2026-03 提出 2031 年 $250 亿营收目标；股价 6 月高点 $445、7 月低点 $201。\n- SoftBank 控股；AI 战略/IPO 后资本运作。\n- 竞争：RISC-V、x86、Imagination、Synopsys。\n\n## 经营业绩\n\n| 指标 | FY2024 | FY2025 | FY2026 | 说明 |\n|---|---|---|---|---|\n| 营收 | $32.3 亿 | $49.2 亿 | 约 $49 亿 | FY2025 +22.8% |\n| 增速 | +? | +22.8% | 约持平 | 授权/版税 |\n| 毛利率 | 约 95% | 约 95% | 待核 | IP 模式 |\n| 营业利润 | 待核 | 待核 | 待核 | — |\n| 净利 | 待核 | 待核 | 待核 | ◐ |\n\n- 运营指标：版税/授权结构；AI 数据中心占比待核。\n- 指引：2031 年 $250 亿目标。\n- 市场预期：AI 数据中心/端侧版税增长。\n\n## 股权、融资与股票\n\n- 上市：NASDAQ ARM；2023-09 IPO。\n- 行情（2026-11-02）：股价约 $228.77；市值约 $2,200 亿；52 周 $201.32–$445.05。\n- 估值：PS 约 45x；PE 待核；高估值。\n- 股东：SoftBank 控股（约 90%，◐）；公众流通盘小。\n- 资本动作：IPO 后无大额融资；SoftBank 减持/质押待核。\n- 风险提示：SoftBank 控制、估值高、RISC-V。\n\n## 团队与人员\n\n- 员工约 7,000 人（◐）；研发/IP 授权团队。\n- Cambridge 总部；全球办公室。\n- 招聘：2026 年 AI/数据中心岗位扩张；具体待采集。\n- 薪酬/股权激励：RSU；流失率未披露。\n- 组织：Rene Haas（CEO）；SoftBank 控股。\n\n## 竞争格局\n\n- 直接竞品：RISC-V（开源）、x86（Intel/AMD）、Imagination（GPU IP）、Synopsys（IP）。\n- 替代方案：自研 ISA、RISC-V、开源核。\n- 差异：ISA 生态、IP 组合、版税模式；弱点：RISC-V、SoftBank 控制、估值。\n- 竞争动态：RISC-V 在 IoT/边缘崛起；x86 在服务器反击；Arm 进数据中心。\n- 份额：CPU IP 市场领先（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：客户自研/RISC-V、AI capex、授权波动。\n- 技术：Neoverse/AI IP、生态工具链。\n- 法律/监管：反垄断、出口管制、SoftBank 控制。\n- 治理：SoftBank 控股、公众股东影响力小。\n- 争议：高估值与营收持平（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：版税/授权拆分、客户集中、AI 数据中心收入均未入库。建议跟踪：① 版税增速；② 数据中心 Neoverse；③ RISC-V 竞争；④ 2031 目标；⑤ SoftBank 资本动作。\n\n## 信源与口径\n\n- FY2026 Q4：https://www.sec.gov/Archives/edgar/data/1973239/000197323926000062/exhibit992fye26q431-marx26.htm\n- FY2025：https://group.softbank/en/ir/financials/annual_reports/2026/message/arm\n- 目标/股价：https://www.cnbc.com/2026/03/24/arm-stock-pops-haas-chip-cpu.html\n- 行情：https://www.macrotrends.net/stocks/charts/ARM/arm-holdings/market-cap\n- 口径：FY2026 截至 2026-03；员工数为估算；◐ 表示待核。' },
      { id: 'ascend', name: '华为昇腾', def: '国产 AI 芯片生态核心：2025 出货 81.2 万卡，占国内近半。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2018（昇腾品牌）/ 深圳 | 华为业务单元 |\n| 上市地 / 代码 | 未上市；华为业务单元 | 不适用 |\n| 最新财年营收 | 未单独披露；华为 FY2025 ¥8,809 亿 | 华为年报 |\n| 盈利 | 未单独披露 | — |\n| 现金流 | 并表 | — |\n| 客户 | 未披露；政企/智算中心/运营商 | ◐ |\n| 员工 | 未单独披露；华为约 16.5 万 | 华为年报 |\n| 市值 / 估值 | 不适用（未上市） | — |\n| 主要股东 | 华为 100% | 并表 |\n| 数据截至 | 2025 出货；2026 路线图 | — |\n\n## 定位与沿革\n\n华为的 AI 芯片与计算生态：昇腾（Ascend）系列 AI 芯片 + Atlas 超节点 + CANN 软件栈，是中国国产 AI 算力的核心供给；2025 年出货 81.2 万卡，占国内 AI 芯片出货约 49.2%。\n\n- 2018 年华为发布昇腾品牌；昇腾 910/910B/910C 用于训练，310 用于推理。\n- 2025 年昇腾 910C 随 Atlas 900 超节点规模部署；受美国制裁影响，2025 年大部分时间供应受限。\n- 2025 年中国云 AI 加速卡市场：昇腾出货 81.2 万卡，份额约 49.2%，接近一半。\n- 2026 年路线图（徐直军 2025-09）：昇腾 950PR（2026 Q1）、950DT（2026 Q4）、960（2027）、970（2028?）三代芯片；自研 HBM。\n- 2026 年计划生产约 60 万颗昇腾 910C，约为 2025 年两倍（Bloomberg，2025-09）。\n- 生态：CANN、MindSpore、昇腾伙伴（恒为科技、利和兴等）；华为云/Atlas 超节点。\n\n## 创始人与管理层\n\n- **华为管理层**：任正非（CEO）、轮值董事长（梁华/徐直军/胡厚崑等）；徐直军是昇腾路线图的主要发布人。\n- **昇腾业务负责人**：华为计算产品线/昇腾计算业务负责人；具体姓名待采集。\n- 董事会：华为投资控股董事会；昇腾无独立董事会。\n- 关键人事变动：轮值董事长轮换；计算业务组织调整待采集。\n\n## 商业模式\n\n- **收入结构**：AI 芯片/加速卡、Atlas 服务器/超节点、CANN 软件与生态、智算中心方案。\n- **销售动作**：政企/运营商/智算中心直销 + 伙伴；华为云捆绑。\n- **单位经济**：未单独披露；芯片+整机+方案；研发投入高。\n- **收入质量**：政企/智算项目制；供应受制裁影响；生态伙伴贡献。\n- **定价趋势**：按芯片/整机/集群；国产替代溢价。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 昇腾 910C | 训练 AI 芯片 | 按卡/整机 | 主力 |\n| 昇腾 950PR/DT | 下一代训练/推理 | 按卡/整机 | 2026 路线图 |\n| 昇腾 310 | 推理芯片 | 按卡 | 主力 |\n| Atlas 900/950 | AI 超节点/集群 | 按项目 | 主力 |\n| CANN | 异构计算软件栈 | 随硬件 | 主力 |\n| MindSpore | AI 框架 | 开源 | 生态 |\n\n- 包装：芯片 + 整机 + 超节点 + 软件；政企/智算方案。\n- 路线图：950PR/950DT（2026）、960（2027）、970；自研 HBM。\n\n## 技术栈与壁垒\n\n- **架构**：达芬奇 NPU 架构 + 自研 HBM/互联；Atlas 超节点。\n- **AI 路线**：训练/推理芯片 + CANN/MindSpore；国产大模型适配。\n- **壁垒**：华为品牌/政企渠道、CANN 生态、超节点互联、国产替代。\n- **依赖与债务**：美国制裁/先进制程、HBM 供应、软件生态、产能。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 政企/智算中心 | 训练/推理集群 | 未披露具体数字 | 官网/媒体 |\n| 运营商 | 智算中心 | 未披露具体数字 | 媒体 |\n| 昇腾伙伴 | 整机/方案 | 未披露具体数字 | 生态 |\n\n- 客户结构：政企、运营商、智算中心、AI 公司；具体名单未披露。\n- 集中度：未披露；政企/智算项目占比高（◐）。\n- 续约/流失：项目制；供应/生态决定复购。\n\n## 商业进展\n\n- 2025 年出货 81.2 万卡，国内份额约 49.2%；910C/Atlas 900 规模部署。\n- 2026 年计划生产约 60 万颗 910C（约为 2025 年两倍）。\n- 2025-09 徐直军发布路线图：950PR（2026 Q1）、950DT（2026 Q4）、960（2027）、970。\n- 自研 HBM、超节点互联；华为云/Atlas 生态。\n- 竞争：NVIDIA、寒武纪、海光、燧原、天数、摩尔线程。\n\n## 经营业绩\n\n| 指标 | 2024 | 2025 | 2026 | 说明 |\n|---|---|---|---|---|\n| 出货 | 待核 | 81.2 万卡 | 计划 60 万颗 910C | 份额 49.2%（2025） |\n| 营收 | 未单独披露 | 未单独披露 | 未单独披露 | 华为并表 |\n| 增速 | — | 高增长 | 高增长 | 供应受限 |\n| 毛利率 | 未披露 | 未披露 | 未披露 | — |\n| 利润 | 未披露 | 未披露 | 未披露 | — |\n\n- 运营指标：2025 出货 81.2 万卡；国内份额 49.2%；2026 计划 60 万颗 910C。\n- 指引：路线图 950PR/950DT/960/970；产能待核。\n- 市场预期：国产替代/智算中心需求。\n\n## 股权、融资与股票\n\n- **不适用（未上市）**：昇腾为华为业务单元，无独立股票。\n- 股权：华为 100%（员工持股平台）。\n- 估值：无独立估值；华为整体未上市。\n- 融资：无独立融资；华为内部/债务融资。\n- 流动性：无公开市场；无独立 IPO 计划。\n\n## 团队与人员\n\n- 昇腾团队人数未披露；华为约 16.5 万员工，研发 11.4 万。\n- 深圳/北京/上海等研发中心；CANN/MindSpore 团队。\n- 招聘：2026 年 AI 芯片/软件岗位扩张；具体待采集。\n- 薪酬/股权激励：华为员工持股；流失率未披露。\n- 组织：华为计算产品线；徐直军发布路线图。\n\n## 竞争格局\n\n- 直接竞品：NVIDIA、寒武纪、海光、燧原、天数、摩尔线程、壁仞、沐曦。\n- 替代方案：GPU、ASIC 自研、云厂商自研芯片。\n- 差异：华为品牌/政企渠道、CANN 生态、超节点、国产替代；弱点：制裁/制程、HBM、软件生态。\n- 竞争动态：国产替代加速；NVIDIA 受限；寒武纪/海光追赶。\n- 份额：中国 AI 芯片出货约 49.2%，第一（2025）。\n\n## 风险与争议\n\n- 经营：美国制裁/先进制程、HBM 供应、产能、客户集中。\n- 技术：CANN 生态、芯片性能、自研 HBM。\n- 法律/监管：出口管制、实体清单、数据安全。\n- 治理：华为轮值/员工持股；业务单元优先级。\n- 争议：出货份额与生态成熟度、供应限制（◐）。\n\n## 本库追踪\n\n本库覆盖集中在华为算力侧（昇腾路线、国产芯片训练等线索/档案）；**昇腾作为独立芯片业务的收入/出货明细覆盖为零**。缺口：客户名单、CANN 生态、950 路线图进展均未入库。建议跟踪：① 910C/950 出货；② 国内份额；③ 自研 HBM；④ CANN 生态；⑤ 制裁/产能。\n\n## 信源与口径\n\n- 华为 2025 年报：https://www.huawei.com/cn/news/2026/3/annual-report-2025\n- 昇腾路线图：https://m.c114.com.cn/w126-1297313.html\n- 出货/份额：https://www.cinn.cn/2026/05-25/GDBjZNKD.html\n- 910C 产量：https://www.rfi.fr/cn/%E4%B8%AD%E5%9B%BD/20250929\n- 超节点：https://www.huawei.com/cn/news/2025/9/hc-xu-keynote-speech\n- 口径：出货/份额为第三方市场报告；营收未单独披露；◐ 表示待核。' },
      { id: 'tsmc', name: 'TSMC（台积电）', def: '全球先进制程代工龙头：2025 营收 $1,224 亿，2nm 2026 年放量。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 1987 / 新竹 | 官网 |\n| 上市地 / 代码 | 台交所 2330；NYSE: TSM | 1994/1997 上市 |\n| 最新财年营收 | FY2025 $1,224 亿（+35.9%） | 2026-01-15 发布 |\n| 盈利 | 净利约 $550 亿（+51.2%，◐） | 2025 财报 |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露；Apple、NVIDIA、AMD 等 | ◐ |\n| 员工 | 约 76,000 人（◐） | — |\n| 市值 / 估值 | 约 $2.1 万亿（2026-09-30） | TSMC IR |\n| 主要股东 | 机构/ADR；台湾官方基金等 | ◐ |\n| 数据截至 | FY2025；2026 Q3 | — |\n\n## 定位与沿革\n\n全球先进制程代工龙头：纯代工模式（pure-play foundry），先进制程（3nm/2nm）与 CoWoS 先进封装是 AI 芯片的关键瓶颈；2025 年营收 $1,224 亿（+35.9%），2026 Q3 营收 $467.2 亿（+41.2%）。\n\n- 1987 年由张忠谋创立，开创纯代工模式；台交所 2330、NYSE TSM。\n- 制程：3nm 量产、2nm（N2）2025 年底量产；2026 Q3 2nm 占营收约 8%，良率 70–80%。\n- FY2025 营收 $1,224 亿（+35.9%）、净利 +51.2%；2025 资本开支 $409 亿。\n- 2026 Q1 营收 $359 亿（+40.6%）；Q3 营收 $467.2 亿（+41.2%），第六个连续季度利润纪录；Q4 指引 $523–543 亿。\n- 2026 资本开支指引 $520–560 亿，为历史最大单年 capex；2nm/CoWoS 扩产。\n- 客户：Apple、NVIDIA、AMD、Qualcomm 等；AI/HPC 是增长主引擎。\n\n## 创始人与管理层\n\n- **张忠谋（创始人）**：1987 年创立 TSMC，开创纯代工模式；2018 年退休。\n- **魏哲家（C.C. Wei，董事长 & CEO）**：2018 年接任 CEO，2024 年任董事长；主导先进制程/AI 扩产。\n- **CFO/业务负责人**：名单待补。\n- 董事会：台湾上市公司治理；具体席位待核。\n- 关键人事变动：2024 年董事长交接；2025–2026 年 AI 扩产组织。\n\n## 商业模式\n\n- **收入结构**：晶圆代工（按制程/节点）+ 先进封装（CoWoS/SoIC）+ 其他。\n- **销售动作**：大客户直销（fabless/IDM）；产能预订/长约。\n- **单位经济**：先进制程毛利高；capex 巨大；产能利用率/良率是核心。\n- **收入质量**：AI/HPC 占比上升；客户集中（Apple/NVIDIA 等）；长约锁定。\n- **定价趋势**：先进制程溢价；2026 年可能提价（◐）；CoWoS 按产能。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 2nm（N2） | 先进制程 | 按 wafer | 增长 |\n| 3nm（N3） | 先进制程 | 按 wafer | 主力 |\n| 5nm/7nm | 成熟先进制程 | 按 wafer | 主力 |\n| CoWoS/SoIC | 先进封装 | 按产能 | 主力 |\n| 成熟制程 | 28nm 等 | 按 wafer | 主力 |\n\n- 包装：制程 + 封装 + 设计生态（OIP）。\n- 路线图：2nm 放量、A16/1.4nm、CoWoS 扩产、海外厂（美国/日本/德国）。\n\n## 技术栈与壁垒\n\n- **架构**：先进制程 + 先进封装 + 设计生态；EUV 依赖。\n- **AI 路线**：AI GPU/ASIC 代工 + CoWoS；HBM 配套。\n- **壁垒**：制程领先、良率、产能、客户信任、OIP 生态。\n- **依赖与债务**：地缘政治（台海）、EUV/设备、capex、客户集中。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| Apple | 手机/PC 芯片 | 未披露具体数字 | 媒体 |\n| NVIDIA | AI GPU | 未披露具体数字 | 媒体 |\n| AMD/Qualcomm | CPU/GPU/手机 | 未披露具体数字 | 媒体 |\n\n- 客户结构：fabless/IDM、AI/HPC、手机、汽车；全球。\n- 集中度：未披露；前两大客户占比高（◐）。\n- 续约/流失：长约/产能预订；先进制程粘性强。\n\n## 商业进展\n\n- FY2025 营收 $1,224 亿（+35.9%）；2026 Q3 $467.2 亿（+41.2%）。\n- 2nm 2025 年底量产，2026 Q3 占营收 8%；良率 70–80%。\n- 2026 capex $520–560 亿；CoWoS/2nm 扩产；海外厂推进。\n- AI/HPC 需求强劲；Q4 2026 指引 $523–543 亿。\n- 竞争：Samsung Foundry、Intel Foundry、SMIC。\n\n## 经营业绩\n\n| 指标 | 2023 | 2024 | 2025 | 2026 Q3 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | $693 亿 | $900 亿 | $1,224 亿 | $467.2 亿 | +35.9%/+41.2% |\n| 增速 | -8.7% | +30% | +35.9% | +41.2% | 加速 |\n| 毛利率 | 约 54% | 约 56% | 约 58% | 待核 | ◐ |\n| 营业利润 | 待核 | 待核 | 待核 | 待核 | — |\n| 净利 | 待核 | 待核 | 约 $550 亿 | 待核 | +51.2% |\n\n- 运营指标：2026 capex $520–560 亿；2nm 占比 8%（Q3 2026）。\n- 指引：Q4 2026 营收 $523–543 亿。\n- 市场预期：AI 需求/2nm 放量。\n\n## 股权、融资与股票\n\n- 上市：台交所 2330；NYSE TSM（ADR）。\n- 行情：市值约 $2.1 万亿（2026-09-30）；股价/52 周待刷新（◐）。\n- 估值：PS 约 17x（按 2025 营收）；PE 待核。\n- 股东：机构/ADR；台湾官方基金等；具体持股待核。\n- 资本动作：分红/资本开支；海外厂投资。\n- 风险提示：地缘政治、客户集中、capex。\n\n## 团队与人员\n\n- 员工约 76,000 人（◐）；研发/制造为主。\n- 新竹总部；美国/日本/德国厂。\n- 招聘：2026 年海外厂/2nm 扩产；具体待采集。\n- 薪酬/股权激励：RSU/分红；流失率未披露。\n- 组织：魏哲家（董事长/CEO）；业务/厂区负责人待补。\n\n## 竞争格局\n\n- 直接竞品：Samsung Foundry、Intel Foundry、SMIC、GlobalFoundries、UMC。\n- 替代方案：IDM 自建、其他代工。\n- 差异：先进制程/良率/产能、CoWoS、OIP 生态；弱点：地缘政治、客户集中、capex。\n- 竞争动态：Samsung 2nm 追赶；Intel Foundry 转型；SMIC 成熟制程。\n- 份额：全球纯代工约 60%+（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：地缘政治（台海）、客户集中、capex 回报。\n- 技术：2nm/1.4nm、EUV、良率。\n- 法律/监管：出口管制、海外厂补贴、反垄断。\n- 治理：台湾上市公司治理；海外厂管理。\n- 争议：AI 需求可持续性、海外扩产成本（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：2nm 客户、CoWoS 产能、海外厂进度均未入库。建议跟踪：① 2nm 占比；② CoWoS 扩产；③ 2026 capex；④ 地缘政治；⑤ 与 Samsung/Intel 的份额。\n\n## 信源与口径\n\n- FY2025/2026 Q3：https://investor.tsmc.com/english/fundamentals\n- 2025 年报：https://investor.tsmc.com/english/annual-reports\n- Q3 2026：https://futurumgroup.com/insights/tsmc-q3-fy-2026-earnings-beat-and-raise-on-ai-and-hpc-demand/\n- 市值：https://investor.tsmc.com/english/fundamentals\n- 口径：FY2025 为美元口径；净利为推算；◐ 表示待核。' },
      { id: 'samsungfoundry', name: 'Samsung Foundry', def: '全球第二大代工：2nm GAA 追赶台积电，份额与良率仍是关键。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2017（代工事业部）/ 韩国华城、平泽 | 三星电子 |\n| 上市地 / 代码 | 不独立上市；母公司 Samsung Electronics（005930.KS） | 并表 |\n| 最新财年营收 | 2026 Q2 约 $32.6 亿（季度） | TrendForce/媒体 |\n| 盈利 | 未单独披露 | — |\n| 现金流 | 并表 | — |\n| 客户 | 未披露；AI/HPC/移动 | ◐ |\n| 员工 | 未单独披露；三星电子约 27 万 | ◐ |\n| 市值 / 估值 | 不适用；三星电子市值待核 | — |\n| 主要股东 | Samsung Electronics 100% | 并表 |\n| 数据截至 | 2026 Q2 | — |\n\n## 定位与沿革\n\n全球第二大纯代工厂：以 2nm GAA、3nm GAA 与先进封装追赶台积电；2026 年 Q2 代工营收约 $32.6 亿，份额约 5.9%–11.5%（口径不一），良率与客户信任是核心变量。\n\n- 2017 年三星电子将代工业务独立为 Foundry 事业部；总部韩国，主要厂区华城/平泽/美国泰勒。\n- 制程：3nm GAA 量产（2022）、2nm GAA 2025 年底量产；2nm 良率 2025 年底约 55–60%。\n- 2026 Q1 代工产能利用率约 80%（新客户导入）；Q2 代工营收约 $32.6 亿，同期台积电约 $402 亿。\n- 份额口径冲突：Counterpoint 口径约 11.5%（2026 Q2），另一报道称降至 5.9%（可能口径不同）。\n- 路线图：2nm 扩产、1.4nm、美国泰勒厂；AI/HPC 客户是增长关键。\n- 三星电子整体：存储（HBM/DRAM/NAND）+ 代工 + 终端；代工不单独披露利润。\n\n## 创始人与管理层\n\n- **三星电子管理层**：会长李在镕（◐ 实际角色待核）；代工事业部负责人待采集。\n- **Samsung Foundry 负责人**：具体姓名/任期待核。\n- 董事会：三星电子董事会；代工无独立董事会。\n- 关键人事变动：2025–2026 年代工负责人/美国厂团队调整待采集。\n\n## 商业模式\n\n- **收入结构**：晶圆代工（先进制程/成熟制程）+ 先进封装；三星电子并表。\n- **销售动作**：大客户直销（AI/HPC/移动/汽车）；产能预订。\n- **单位经济**：代工毛利受良率/利用率影响；2nm 初期成本高。\n- **收入质量**：客户集中；份额落后台积电；美国厂补贴。\n- **定价趋势**：先进制程溢价；与台积电价格竞争。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 2nm GAA | 先进制程 | 按 wafer | 增长 |\n| 3nm GAA | 先进制程 | 按 wafer | 主力 |\n| 4nm/5nm | 先进制程 | 按 wafer | 主力 |\n| 成熟制程 | 8nm/14nm/28nm | 按 wafer | 主力 |\n| 先进封装 | 2.5D/3D、HBM 配套 | 按产能 | 增长 |\n\n- 包装：制程 + 封装 + 存储（HBM）捆绑。\n- 路线图：2nm 扩产、1.4nm、美国泰勒厂。\n\n## 技术栈与壁垒\n\n- **架构**：GAA 晶体管 + EUV；先进封装；存储协同。\n- **AI 路线**：AI/HPC 代工 + HBM；与三星存储业务协同。\n- **壁垒**：三星电子资本/存储协同、GAA 先发、美国厂；弱点：良率、客户信任、份额。\n- **依赖与债务**：良率、EUV/设备、地缘政治、客户集中。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| AI/HPC 客户 | 2nm/3nm 代工 | 未披露具体数字 | 媒体 |\n| 移动客户 | 手机 SoC | 未披露具体数字 | 媒体 |\n| 汽车客户 | 车规芯片 | 未披露具体数字 | 官网 |\n\n- 客户结构：AI/HPC、移动、汽车；具体名单未披露。\n- 集中度：未披露；大客户导入是关键。\n- 续约/流失：先进制程粘性；良率决定复购。\n\n## 商业进展\n\n- 2nm GAA 2025 年底量产；2026 年产能利用率约 80%（Q1）。\n- 2026 Q2 代工营收约 $32.6 亿；份额口径 5.9%–11.5%。\n- 美国泰勒厂推进；1.4nm 路线图。\n- AI/HPC 客户导入；与三星存储/HBM 协同。\n- 竞争：TSMC、Intel Foundry、SMIC、GlobalFoundries。\n\n## 经营业绩\n\n| 指标 | 2024 | 2025 | 2026 Q2 | 说明 |\n|---|---|---|---|---|\n| 代工营收 | 未单独披露 | 未单独披露 | 约 $32.6 亿 | 季度 |\n| 增速 | — | — | 待核 | — |\n| 毛利率 | 未单独披露 | 未单独披露 | 未单独披露 | 并表 |\n| 营业利润 | 未单独披露 | 未单独披露 | 未单独披露 | — |\n| 份额 | 约 10% | 约 8–10% | 5.9%–11.5% | 口径不一 |\n\n- 运营指标：2nm 良率 55–60%（2025 年底）；利用率约 80%（2026 Q1）。\n- 指引：未单独披露；三星电子整体指引待查。\n- 市场预期：2nm 客户导入与份额恢复。\n\n## 股权、融资与股票\n\n- **不适用（业务单元）**：Samsung Foundry 不独立上市；母公司 Samsung Electronics（005930.KS）。\n- 行情：三星电子市值/股价待核（◐）。\n- 估值：代工业务无独立估值；三星电子整体 PE 待核。\n- 股东：三星电子 100%；无独立股东。\n- 资本动作：美国厂投资/补贴；三星电子整体资本配置。\n\n## 团队与人员\n\n- 代工员工数未单独披露；三星电子约 27 万（◐）。\n- 韩国华城/平泽；美国泰勒厂。\n- 招聘：2026 年美国厂/2nm 扩产；具体待采集。\n- 薪酬/股权激励：三星电子体系；流失率未披露。\n- 组织：代工事业部负责人；具体名单待补。\n\n## 竞争格局\n\n- 直接竞品：TSMC、Intel Foundry、SMIC、GlobalFoundries、UMC。\n- 替代方案：IDM 自建、其他代工。\n- 差异：GAA 先发、存储/HBM 协同、美国厂；弱点：良率、客户信任、份额。\n- 竞争动态：TSMC 2nm 领先；Intel 18A 追赶；SMIC 成熟制程。\n- 份额：全球纯代工第二，约 6–11%（口径不一，◐）。\n\n## 风险与争议\n\n- 经营：良率、客户流失、份额下滑、美国厂成本。\n- 技术：2nm/1.4nm、EUV、封装。\n- 法律/监管：出口管制、美国补贴、反垄断。\n- 治理：三星电子治理；代工负责人变动。\n- 争议：份额口径冲突、2nm 良率真实性（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：代工营收/利润、2nm 客户、良率均未入库。建议跟踪：① 2nm 客户导入；② 份额；③ 良率；④ 美国厂；⑤ 与 TSMC 的差距。\n\n## 信源与口径\n\n- 份额：https://counterpointresearch.com/cn/insights/global-semiconductor-foundry-market-share\n- 2nm/利用率：https://semiwiki.com/forum/threads/more-clients-leads-to-80-utilization-at-samsung-foundry-in-1q2026.24627/\n- 2026 Q2：https://images.samsung.com/is/content/samsung/assets/global/ir/docs/2026_2Q_conference_eng.pdf\n- 口径：代工营收/份额为第三方；员工数为三星电子整体；◐ 表示待核。' },
      { id: 'smic', name: '中芯国际', def: '中国最大晶圆代工：2025 营收 673 亿元，成熟制程 + 先进制程并举。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2000 / 上海 | 官网 |\n| 上市地 / 代码 | 科创板 688981；港股 00981 | A+H |\n| 最新财年营收 | FY2025 ¥673.23 亿（+16.5%）/ $93.27 亿 | 2025 年报 |\n| 盈利 | 归母净利 ¥50.41 亿（+36.3%） | 2025 年报 |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露；中国 IC 设计公司 | ◐ |\n| 员工 | 未披露 | — |\n| 市值 / 估值 | 待核；2025-09 曾讨论「万亿市值」 | ◐ |\n| 主要股东 | 大唐电信/国家大基金等 | ◐ |\n| 数据截至 | FY2025；2026 H1 | — |\n\n## 定位与沿革\n\n中国最大晶圆代工厂：成熟制程（28nm 及以上）为基本盘，先进制程（14nm/FinFET）受出口管制约束；FY2025 营收 ¥673.23 亿（+16.5%）、归母净利 ¥50.41 亿（+36.3%）。\n\n- 2000 年成立于上海；A+H 两地上市（688981/00981）；中国半导体国产化的核心代工平台。\n- 制程：28nm/40nm/55nm 成熟制程为主；14nm FinFET 及更先进制程受美国出口管制限制。\n- FY2025 营收 ¥673.23 亿（+16.5%，约 $93.27 亿）、归母净利 ¥50.41 亿（+36.3%）；研发投入 ¥55.19 亿（8.2%）。\n- 2026 H1 营收 ¥386.35 亿；2026 Q1 营收约 $25 亿；产能利用率/资本开支维持高位。\n- 2025 年资本开支维持较大规模；2025-09 媒体讨论「万亿市值」逻辑；当前市值待刷新。\n- 客户：中国 IC 设计公司、手机/消费/工业；国产替代是主要需求。\n\n## 创始人与管理层\n\n- **张汝京（创始人）**：2000 年创立中芯国际；后离开。\n- **管理层**：董事长/CEO/CFO 名单待核；2025–2026 年管理层稳定。\n- 董事会：大唐电信、国家大基金等；具体席位待核。\n- 关键人事变动：2025–2026 年待采集。\n\n## 商业模式\n\n- **收入结构**：晶圆代工（按制程/应用）+ 光掩模/其他；成熟制程为主。\n- **销售动作**：中国 IC 设计公司直销 + 渠道；国产替代。\n- **单位经济**：成熟制程毛利受价格/利用率影响；先进制程资本开支高。\n- **收入质量**：中国客户为主；国产替代驱动；客户集中度未披露。\n- **定价趋势**：成熟制程价格竞争；先进制程溢价（受限）。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 28nm/40nm | 成熟制程 | 按 wafer | 主力 |\n| 55nm/65nm | 成熟制程 | 按 wafer | 主力 |\n| 14nm FinFET | 先进制程 | 按 wafer | 受限 |\n| BCD/eNVM | 电源/嵌入式 | 按 wafer | 增长 |\n| 光掩模 | 掩模服务 | 按项目 | 增长 |\n\n- 包装：制程 + 掩模 + 设计服务；国产替代方案。\n- 路线图：成熟制程扩产、先进制程自主化（受限）。\n\n## 技术栈与壁垒\n\n- **架构**：成熟制程 + FinFET；国产设备/材料适配。\n- **AI 路线**：AI 芯片代工（成熟/先进）；受出口管制约束。\n- **壁垒**：中国最大代工产能、国产替代、客户关系、资本开支。\n- **依赖与债务**：美国出口管制、先进设备、资本开支、价格竞争。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 中国 IC 设计公司 | 成熟制程代工 | 未披露具体数字 | 年报 |\n| 手机/消费电子 | 电源/射频/存储 | 未披露具体数字 | 年报 |\n| 工业/汽车 | BCD/eNVM | 未披露具体数字 | 官网 |\n\n- 客户结构：中国 IC 设计、手机/消费、工业/汽车；国产替代。\n- 集中度：未披露；中国客户为主。\n- 续约/流失：产能预订；国产替代粘性。\n\n## 商业进展\n\n- FY2025 营收 ¥673.23 亿（+16.5%）、净利 ¥50.41 亿（+36.3%）。\n- 2026 H1 营收 ¥386.35 亿；Q1 营收约 $25 亿；产能利用率高位。\n- 资本开支维持较大规模；成熟制程扩产。\n- 先进制程受出口管制；国产设备/材料适配。\n- 竞争：TSMC、Samsung、华虹、UMC、GlobalFoundries。\n\n## 经营业绩\n\n| 指标 | 2024 | 2025 | 2026 H1 | 说明 |\n|---|---|---|---|---|\n| 营收 | ¥577.96 亿 | ¥673.23 亿 | ¥386.35 亿 | 2025 +16.5% |\n| 增速 | +27.7% | +16.5% | 待核 | 放缓 |\n| 毛利率 | 约 18% | 待核 | 待核 | ◐ |\n| 营业利润 | 待核 | 待核 | 待核 | — |\n| 归母净利 | ¥36.99 亿 | ¥50.41 亿 | 待核 | +36.3% |\n\n- 运营指标：研发投入 ¥55.19 亿（8.2%）；资本开支高位。\n- 指引：2026 年扩产/资本开支待查。\n- 市场预期：国产替代/成熟制程需求。\n\n## 股权、融资与股票\n\n- 上市：科创板 688981；港股 00981。\n- 行情：市值待核；2025-09 媒体讨论「万亿市值」。\n- 估值：PE/PS 待按最新行情计算（◐）。\n- 股东：大唐电信、国家大基金等；具体持股待核。\n- 资本动作：资本开支/融资；分红待查。\n- 风险提示：出口管制、价格竞争、资本开支。\n\n## 团队与人员\n\n- 员工数未披露；研发/制造为主。\n- 上海总部；北京/深圳/天津等厂区。\n- 招聘：2026 年成熟制程扩产；具体待采集。\n- 薪酬/股权激励：A+H 上市，有股权激励；流失率未披露。\n- 组织：管理层名单待补；国家大基金/大唐影响。\n\n## 竞争格局\n\n- 直接竞品：TSMC、Samsung Foundry、华虹、UMC、GlobalFoundries。\n- 替代方案：其他中国代工厂、IDM。\n- 差异：中国最大代工产能、国产替代、成熟制程；弱点：先进制程受限、价格竞争。\n- 竞争动态：国产替代加速；成熟制程价格战；先进制程受限。\n- 份额：中国晶圆代工第一，全球约 5–6%（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：出口管制、价格竞争、资本开支、客户集中。\n- 技术：先进制程/设备、良率、国产化。\n- 法律/监管：美国实体清单/出口管制、数据安全。\n- 治理：国资/大基金控制、管理层。\n- 争议：先进制程能力与「万亿市值」叙事（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：员工数、毛利率、先进制程进展、客户名单均未入库。建议跟踪：① 成熟制程利用率；② 先进制程国产化；③ 资本开支；④ 出口管制；⑤ 与华虹的份额。\n\n## 信源与口径\n\n- 2025 年报：https://static.cninfo.com.cn/finalpage/2026-03-27/1225037057.PDF\n- 业绩：https://wallstreetcn.com/articles/3768471\n- 2026 H1：https://vip.stock.finance.sina.com.cn/corp/view/vCB_AllBulletinDetail.php?stockid=688981&id=12559855\n- 市值讨论：https://www.21jingji.com/article/20250919/herald/22948dac4982a0d38af0e95bf6923967.html\n- 口径：FY2025 为年报；员工数未披露；◐ 表示待核。' },
      { id: 'huahong', name: '华虹半导体', def: '特色工艺代工：功率/模拟/嵌入式，2025 营收 $24 亿。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 1996/2005 / 上海 | 官网 |\n| 上市地 / 代码 | 科创板 688347；港股 01347 | A+H |\n| 最新财年营收 | FY2025 $24.02 亿（+19.9%） | 公司 IR |\n| 盈利 | 归母净利 $5,490 万（-5.5%） | 2025 财报 |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露；功率/模拟/嵌入式 | ◐ |\n| 员工 | 未披露 | — |\n| 市值 / 估值 | 约 ¥2,070 亿（2026-03） | 东方财富 |\n| 主要股东 | 华虹集团/国家大基金等 | ◐ |\n| 数据截至 | FY2025；2026 Q1 | — |\n\n## 定位与沿革\n\n特色工艺晶圆代工：聚焦功率器件、模拟/电源管理、嵌入式存储（eNVM）与 MCU，成熟制程差异化；FY2025 营收 $24.02 亿（+19.9%），毛利率 11.8%。\n\n- 1996/2005 年成立于上海（华虹 NEC/华虹宏力沿革）；A+H 上市（688347/01347）。\n- 工艺：55nm/40nm/28nm 特色工艺；BCD、eNVM、功率分立器件、模拟。\n- FY2025 营收 $24.02 亿（+19.9%）、毛利 $2.829 亿（毛利率 11.8%）、归母净利 $5,490 万（-5.5%）。\n- 2025 Q3 营收 $6.352 亿（+20.7%，创纪录）、毛利率 13.5%、净利约 $2,570 万。\n- 2026 Q1 营收 ¥46.25 亿（+18.22%）、归母净利 ¥1.4 亿。\n- 市值约 ¥2,070 亿（2026-03）；华虹集团/国家大基金为股东。\n\n## 创始人与管理层\n\n- **华虹集团**：上海国资背景；具体创始人/管理层名单待核。\n- **管理层**：董事长/CEO/CFO 待采集；2025–2026 年稳定。\n- 董事会：华虹集团、国家大基金等；具体席位待核。\n- 关键人事变动：2026 年 A+H 融资/扩产；具体待采集。\n\n## 商业模式\n\n- **收入结构**：晶圆代工（特色工艺）+ 掩模/其他；成熟制程。\n- **销售动作**：中国 IC 设计公司/IDM 直销；功率/模拟/嵌入式。\n- **单位经济**：毛利率 11.8%（2025）；成熟制程价格竞争；扩产折旧。\n- **收入质量**：中国客户为主；消费/工业/汽车；客户集中度未披露。\n- **定价趋势**：成熟制程价格竞争；特色工艺溢价。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 功率器件 | MOSFET/IGBT/SiC | 按 wafer | 主力 |\n| 模拟/电源管理 | BCD/PMIC | 按 wafer | 主力 |\n| 嵌入式存储 | eNVM/MCU | 按 wafer | 主力 |\n| 逻辑/混合信号 | 55/40/28nm | 按 wafer | 主力 |\n| 掩模服务 | 光掩模 | 按项目 | 增长 |\n\n- 包装：特色工艺 + 掩模 + 设计服务；汽车/工业方案。\n- 路线图：12 英寸扩产、SiC/功率、特色工艺。\n\n## 技术栈与壁垒\n\n- **架构**：成熟制程 + 特色工艺（BCD/eNVM/功率）；12 英寸厂。\n- **AI 路线**：AI 芯片配套电源/模拟；非先进制程。\n- **壁垒**：特色工艺、中国客户、华虹集团/国资、A+H 融资。\n- **依赖与债务**：成熟制程价格竞争、扩产折旧、设备/材料。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 中国 IC 设计公司 | 功率/模拟/嵌入式 | 未披露具体数字 | 年报 |\n| 汽车/工业 | 功率器件/PMIC | 未披露具体数字 | 官网 |\n| 消费电子 | MCU/电源 | 未披露具体数字 | 官网 |\n\n- 客户结构：中国 IC 设计、汽车/工业、消费；具体名单未披露。\n- 集中度：未披露；中国客户为主。\n- 续约/流失：特色工艺粘性；价格竞争影响。\n\n## 商业进展\n\n- FY2025 营收 $24.02 亿（+19.9%）、毛利率 11.8%、净利 $5,490 万。\n- 2025 Q3 营收 $6.352 亿（+20.7%，创纪录）。\n- 2026 Q1 营收 ¥46.25 亿（+18.22%）、净利 ¥1.4 亿。\n- 12 英寸扩产/特色工艺；A+H 融资。\n- 竞争：中芯国际、TSMC、UMC、GlobalFoundries、士兰微。\n\n## 经营业绩\n\n| 指标 | 2023 | 2024 | 2025 | 2026 Q1 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | 待核 | $20.04 亿 | $24.02 亿 | ¥46.25 亿 | +19.9% |\n| 增速 | 待核 | 待核 | +19.9% | +18.22% | 增长 |\n| 毛利率 | 待核 | 10.2% | 11.8% | 待核 | 改善 |\n| 营业利润 | 待核 | 待核 | 待核 | 待核 | — |\n| 归母净利 | 待核 | $5,810 万 | $5,490 万 | ¥1.4 亿 | -5.5% |\n\n- 运营指标：毛利率 11.8%；12 英寸产能扩张。\n- 指引：2026 年扩产/价格待查。\n- 市场预期：特色工艺/国产替代。\n\n## 股权、融资与股票\n\n- 上市：科创板 688347；港股 01347。\n- 行情：市值约 ¥2,070 亿（2026-03）；A 股约 ¥132–141；港股约 HK$60.7（◐）。\n- 估值：PE 约 30x（A 股，◐）；PS 待核。\n- 股东：华虹集团、国家大基金等；具体持股待核。\n- 资本动作：A+H 融资/扩产；分红待查。\n- 风险提示：成熟制程价格竞争、毛利率、扩产折旧。\n\n## 团队与人员\n\n- 员工数未披露；制造/研发为主。\n- 上海总部；无锡/上海厂区。\n- 招聘：2026 年 12 英寸扩产；具体待采集。\n- 薪酬/股权激励：A+H 上市，有股权激励；流失率未披露。\n- 组织：华虹集团/国资；管理层名单待补。\n\n## 竞争格局\n\n- 直接竞品：中芯国际、TSMC、UMC、GlobalFoundries、士兰微。\n- 替代方案：其他特色工艺代工、IDM。\n- 差异：特色工艺（功率/模拟/嵌入式）、中国客户、华虹集团；弱点：毛利率低、价格竞争。\n- 竞争动态：成熟制程价格战；国产替代；汽车/工业需求。\n- 份额：中国特色工艺代工领先（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：成熟制程价格竞争、毛利率、扩产折旧。\n- 技术：特色工艺、12 英寸、SiC。\n- 法律/监管：出口管制、A+H 披露、国资监管。\n- 治理：华虹集团/国资控制。\n- 争议：低毛利率与扩产回报（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：员工数、客户名单、毛利率、12 英寸产能均未入库。建议跟踪：① 毛利率；② 12 英寸扩产；③ 特色工艺需求；④ 价格竞争；⑤ 与中芯国际的份额。\n\n## 信源与口径\n\n- 公司 IR：https://www.huahonggrace.com/s/ir_financial.php\n- 2025 Q3：https://www.stcn.com/article/detail/3482543.html\n- 市值：https://data.eastmoney.com/stockdata/688347.html\n- 2025 年报：https://stockn.xueqiu.com/01347/20260326035878.pdf\n- 口径：FY2025 为美元口径；员工数未披露；◐ 表示待核。' },
      { id: 'asml', name: 'ASML', def: 'EUV 光刻垄断者：2026 营收指引 €43–45B，High-NA 决定先进制程上限。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 1984 / Veldhoven, 荷兰 | 官网 |\n| 上市地 / 代码 | Euronext: ASML；NASDAQ: ASML | 1995 上市 |\n| 最新财年营收 | FY2025 €327 亿（毛利率 52.8%） | 2026-01 发布 |\n| 盈利 | FY2025 净利待核；2026 Q3 净利 €50 亿 | ◐ |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露；TSMC、Samsung、Intel 等 | ◐ |\n| 员工 | 约 44,000 人 | Perplexity Finance |\n| 市值 / 估值 | 约 $6,030 亿（2026） | MarketCapWatch |\n| 主要股东 | 机构为主 | ◐ |\n| 数据截至 | FY2025；2026 Q3 | — |\n\n## 定位与沿革\n\nEUV 光刻机的全球垄断者：EUV/High-NA EUV 是先进制程（7nm 以下）的瓶颈设备；2025 年营收 €327 亿（毛利率 52.8%），2026 年指引 €43–45B，Q3 2026 单季营收 €117 亿、毛利率 57.5%、净利 €50 亿。\n\n- 1984 年从 Philips 分拆成立；总部荷兰 Veldhoven；Euronext/纳斯达克上市。\n- 产品：EUV（NXE）、High-NA EUV（EXE）、DUV（ArFi/ArF/KrF）、量测/检测。\n- FY2025 营收 €327 亿、毛利率 52.8%；2026 Q2 营收 €93 亿、毛利率 54%；Q3 营收 €117 亿、毛利率 57.5%、净利 €50 亿。\n- 2026 年营收指引上调至 €43–45B（毛利率 54–56%）；High-NA EUV 开始交付。\n- 客户：TSMC、Samsung、Intel、SK 海力士/美光等；中国客户受出口管制限制。\n- 员工约 44,000 人；市值约 $6,030 亿（2026）。\n\n## 创始人与管理层\n\n- **Christophe Fouquet（CEO）**：2024 年接任 CEO；此前负责 EUV 业务；主导 High-NA/客户合作。\n- **Roger Dassen（CFO）**：财务负责人；财报电话会主要对外。\n- **创始人**：1984 年从 Philips 分拆；具体创始人名单待核。\n- 董事会：荷兰上市公司治理；具体席位待核。\n- 关键人事变动：2024 年 CEO 交接；2025–2026 年 High-NA 团队扩张。\n\n## 商业模式\n\n- **收入结构**：设备销售（EUV/DUV/量测）+ 服务/现场选项（Installed Base Management）。\n- **销售动作**：大客户直销（TSMC/Samsung/Intel/存储厂商）；产能预订/长约。\n- **单位经济**：EUV 单台价格高（€1.5–2 亿+）、毛利高；服务收入稳定。\n- **收入质量**：客户集中；设备周期性强；服务/升级提供经常性收入。\n- **定价趋势**：High-NA 溢价；EUV 按台/配置；服务按合同。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| EUV（NXE） | 13.5nm 光刻 | 按台 | 主力 |\n| High-NA EUV（EXE） | 下一代高数值孔径 | 按台 | 增长 |\n| DUV（ArFi/ArF/KrF） | 成熟制程光刻 | 按台 | 主力 |\n| 量测/检测 | 套刻/缺陷量测 | 按台 | 增长 |\n| 服务/升级 | 维护、现场选项 | 按合同 | 主力 |\n\n- 包装：设备 + 服务 + 升级；客户产能规划绑定。\n- 路线图：High-NA 放量、EUV 产能、下一代光刻。\n\n## 技术栈与壁垒\n\n- **架构**：EUV 光源/光学/精密机械；High-NA 光学；与 Zeiss 等供应链深度绑定。\n- **AI 路线**：AI 用于设备控制/良率/预测维护；非 AI 芯片直接产品。\n- **壁垒**：EUV 专利/供应链、客户认证、精度/良率、服务网络。\n- **依赖与债务**：出口管制（中国）、客户集中、供应链（Zeiss/光源）、周期。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| TSMC | 3nm/2nm EUV | 未披露具体数字 | 媒体 |\n| Samsung/Intel | 先进制程 EUV | 未披露具体数字 | 媒体 |\n| 存储厂商 | DRAM/HBM EUV | 未披露具体数字 | 媒体 |\n\n- 客户结构：先进制程代工/IDM、存储；全球少数大客户。\n- 集中度：极高；前三大客户占比高（◐）。\n- 续约/流失：设备生命周期长；服务/升级粘性强。\n\n## 商业进展\n\n- FY2025 营收 €327 亿、毛利率 52.8%；2026 Q3 营收 €117 亿、毛利率 57.5%、净利 €50 亿。\n- 2026 年营收指引 €43–45B；High-NA EUV 开始交付。\n- 客户资本开支（TSMC/Samsung/Intel/存储）驱动；AI/HBM 需求。\n- 中国出口管制影响 DUV/EUV 销售；公司维持指引。\n- 竞争：Nikon、Canon（DUV）、上海微电子（国产光刻）。\n\n## 经营业绩\n\n| 指标 | 2023 | 2024 | 2025 | 2026 Q3 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | €276 亿 | €283 亿 | €327 亿 | €117 亿 | 2025 +15.5% |\n| 增速 | +30% | +2.6% | +15.5% | +? | 加速 |\n| 毛利率 | 约 51% | 约 51% | 52.8% | 57.5% | 改善 |\n| 营业利润 | 待核 | 待核 | 待核 | 待核 | — |\n| 净利 | €78 亿 | €76 亿 | 待核 | €50 亿 | ◐ |\n\n- 运营指标：EUV/High-NA 出货；服务收入占比待核。\n- 指引：2026 年 €43–45B、毛利率 54–56%。\n- 市场预期：AI/HBM 资本开支、High-NA 放量。\n\n## 股权、融资与股票\n\n- 上市：Euronext ASML；NASDAQ ASML（ADR）。\n- 行情：市值约 $6,030 亿（2026）；股价/52 周待刷新（◐）。\n- 估值：PS 约 18x（按 2025 营收）；PE 待核。\n- 股东：机构为主；具体持股待核。\n- 资本动作：分红/回购；研发/产能投资。\n- 风险提示：出口管制、客户集中、周期。\n\n## 团队与人员\n\n- 员工约 44,000 人；研发/制造/服务为主。\n- Veldhoven 总部；全球客户支持。\n- 招聘：2026 年 High-NA/服务岗位扩张；具体待采集。\n- 薪酬/股权激励：RSU/绩效；CEO 薪酬含员工满意度指标（媒体）。\n- 组织：Christophe Fouquet（CEO）、Roger Dassen（CFO）。\n\n## 竞争格局\n\n- 直接竞品：Nikon、Canon（DUV）；上海微电子（国产光刻）。\n- 替代方案：DUV 多重曝光、其他光刻路线（纳米压印等，早期）。\n- 差异：EUV/High-NA 垄断、精度/良率、服务网络；弱点：出口管制、客户集中。\n- 竞争动态：High-NA 竞赛；中国国产光刻追赶；客户资本开支周期。\n- 份额：EUV 100%、高端光刻绝对领先（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：客户集中、半导体周期、出口管制。\n- 技术：High-NA 良率/成本、下一代光刻。\n- 法律/监管：美国/荷兰出口管制、中国客户限制。\n- 治理：荷兰上市公司治理；供应链（Zeiss）。\n- 争议：对华出口限制与营收影响（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：High-NA 出货、中国收入占比、客户资本开支均未入库。建议跟踪：① High-NA 交付；② 2026 营收指引；③ 中国出口管制；④ 客户 capex；⑤ 国产光刻进展。\n\n## 信源与口径\n\n- Q3 2026：https://investor.asml.com/news-releases/news-release-details/q2-2026-financial-results\n- 2026 指引：https://finance.biggo.com/news/69d3fa9d-7754-437a-aafb-4a8b34b2a5ac\n- 市值：https://www.marketcapwatch.com/company/asml-marketcap\n- 员工：https://www.perplexity.ai/finance/ASML/earnings\n- 口径：财务为欧元；市值/员工为第三方；◐ 表示待核。' },
      { id: 'appliedmaterials', name: 'Applied Materials', def: '半导体设备平台之王：沉积/刻蚀/离子注入全覆盖，FY2026 订单爆满。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 1967 / Santa Clara | 官网 |\n| 上市地 / 代码 | NASDAQ: AMAT | 1972 IPO |\n| 最新财年营收 | FY2025 约 $300 亿 | 年报/推算 |\n| 盈利 | FY2025 净利约 $74 亿 | 推算（◐） |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露；TSMC、Samsung、Intel、中芯 | ◐ |\n| 员工 | 约 38,000–39,000 人 | 推算（◐） |\n| 市值 / 估值 | 约 $3,948 亿（2026-07） | MarketCapRanked |\n| 主要股东 | 机构为主 | ◐ |\n| 数据截至 | FY2025；Q3 FY2026 | — |\n\n## 定位与沿革\n\n半导体设备平台之王：沉积（CVD/PVD/ALD）、刻蚀、离子注入、CMP、量测全覆盖，是先进逻辑/存储/HBM 扩产的核心供应商；FY2026 Q3 营收 $91.2 亿创纪录，Q4 指引 $102.5 亿。\n\n- 1967 年成立，总部 Santa Clara；1972 年上市（AMAT）。\n- 产品：沉积、刻蚀、离子注入、CMP、热处理、量测/检测、显示设备。\n- FY2025 营收约 $300 亿、净利约 $74 亿（推算）；CEO 称客户给出「八个季度」的forecast，AI 需求强劲。\n- FY2026 Q3 营收 $91.2 亿（创纪录）、GAAP 毛利率 50.3%、营业利润创纪录；Q4 指引 $102.5 亿 ±$5 亿（约 +51% YoY）。\n- 市场：先进逻辑、HBM/DRAM、先进封装；中国收入受出口管制影响。\n- 市值约 $3,948 亿（2026-07）；员工约 38,000–39,000（推算）。\n\n## 创始人与管理层\n\n- **Gary Dickerson（总裁 & CEO）**：2013 年起任 CEO；主导 AI/先进制程战略。\n- **CFO/CTO**：名单待补。\n- 创始人：1967 年创立；具体创始人待核。\n- 董事会：机构 + 管理层；具体席位待核。\n- 关键人事变动：2025–2026 年 AI/先进封装团队扩张。\n\n## 商业模式\n\n- **收入结构**：半导体系统（沉积/刻蚀/注入/CMP）+ 服务/备件 + 显示。\n- **销售动作**：大客户直销（代工/存储/IDM）；设备+服务。\n- **单位经济**：设备毛利约 47–50%；服务收入稳定；研发投入高。\n- **收入质量**：客户集中；设备周期性强；服务/备件提供经常性收入。\n- **定价趋势**：先进设备溢价；按台/配置；服务按合同。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 沉积 | CVD/PVD/ALD | 按台 | 主力 |\n| 刻蚀 | 导体/介质刻蚀 | 按台 | 主力 |\n| 离子注入 | 掺杂设备 | 按台 | 主力 |\n| CMP | 化学机械抛光 | 按台 | 主力 |\n| 量测/检测 | 缺陷/膜厚 | 按台 | 增长 |\n| 服务/备件 | 维护、升级 | 按合同 | 主力 |\n\n- 包装：设备 + 服务 + 工艺方案；先进逻辑/存储/HBM。\n- 路线图：先进封装、HBM、GAA、2nm 设备。\n\n## 技术栈与壁垒\n\n- **架构**：材料工程/工艺设备平台；与客户共同开发。\n- **AI 路线**：AI 用于工艺控制/良率；设备支持 AI 芯片制造。\n- **壁垒**：工艺 know-how、客户共同开发、设备平台广度、服务网络。\n- **依赖与债务**：出口管制（中国）、客户集中、周期、供应链。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| TSMC/Samsung/Intel | 先进逻辑设备 | 未披露具体数字 | 媒体 |\n| 存储厂商 | HBM/DRAM 设备 | 未披露具体数字 | 媒体 |\n| 中芯/华虹 | 成熟制程设备 | 未披露具体数字 | 媒体 |\n\n- 客户结构：代工、存储、IDM；全球。\n- 集中度：前几大客户占比高（◐）。\n- 续约/流失：设备生命周期长；服务粘性。\n\n## 商业进展\n\n- FY2025 营收约 $300 亿、净利约 $74 亿（推算）。\n- FY2026 Q3 营收 $91.2 亿创纪录；Q4 指引 $102.5 亿（+51%）。\n- AI/HBM/先进封装需求强劲；客户给八季度 forecast。\n- 中国出口管制影响；公司调整区域结构。\n- 竞争：Lam、TEL、ASML、KLA。\n\n## 经营业绩\n\n| 指标 | FY2023 | FY2024 | FY2025 | Q3 FY2026 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | $265 亿 | $272 亿 | 约 $300 亿 | $91.2 亿 | 创纪录 |\n| 增速 | -? | +2.6% | +10% | +? | 加速 |\n| 毛利率 | 约 46% | 约 47% | 约 48% | 50.3% | 改善 |\n| 营业利润 | 待核 | 待核 | 待核 | 创纪录 | — |\n| 净利 | $68.6 亿 | $71.8 亿 | 约 $74 亿 | $25.4 亿 | ◐ |\n\n- 运营指标：Q4 FY2026 指引 $102.5 亿；服务收入占比待核。\n- 指引：Q4 FY2026 $102.5 亿 ±$5 亿；EPS $4.02 ±$0.20（non-GAAP）。\n- 市场预期：AI 资本开支/先进封装。\n\n## 股权、融资与股票\n\n- 上市：NASDAQ AMAT；1972 IPO。\n- 行情：市值约 $3,948 亿（2026-07）；股价/52 周待刷新（◐）。\n- 估值：PS 约 13x（按 FY2025）；PE 待核。\n- 股东：机构为主；具体持股待核。\n- 资本动作：分红/回购；研发/产能投资。\n- 风险提示：出口管制、客户集中、周期。\n\n## 团队与人员\n\n- 员工约 38,000–39,000（推算）；研发/制造/服务。\n- Santa Clara 总部；全球。\n- 招聘：2026 年 AI/先进封装岗位扩张；具体待采集。\n- 薪酬/股权激励：RSU；流失率未披露。\n- 组织：Gary Dickerson（CEO）；业务线负责人待补。\n\n## 竞争格局\n\n- 直接竞品：Lam Research、Tokyo Electron、ASML、KLA。\n- 替代方案：其他设备商、国产设备替代。\n- 差异：平台广度（沉积/刻蚀/注入/CMP）、客户共同开发；弱点：出口管制、客户集中。\n- 竞争动态：Lam 刻蚀强势；TEL 涂胶/刻蚀；国产设备追赶。\n- 份额：半导体设备全球第一/第二（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：出口管制（中国）、客户集中、周期。\n- 技术：GAA/2nm、先进封装、HBM。\n- 法律/监管：美国出口管制、反垄断。\n- 治理：管理层/董事会；供应链。\n- 争议：中国收入占比与管制影响（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：中国收入占比、HBM 设备订单、服务收入均未入库。建议跟踪：① Q4 FY2026 指引；② 中国出口管制；③ HBM/先进封装；④ 客户 capex；⑤ 与 Lam/TEL 的份额。\n\n## 信源与口径\n\n- Q3 FY2026：https://ir.appliedmaterials.com/news-releases/news-release-details/applied-materials-announces-third-quarter-2026-results/\n- SEC 8-K：https://www.sec.gov/Archives/edgar/data/6951/000162828026056699/exhibit991q32026earningsre.htm\n- 市值：https://marketcapranked.com/company/applied-materials-inc/\n- 口径：FY2025 为年报/推算；员工数为推算；◐ 表示待核。' },
      { id: 'lamresearch', name: 'Lam Research', def: '刻蚀与沉积龙头：Q1 FY2027 营收 $82.2 亿，AI/HBM 驱动 WFE 上修。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 1980 / Fremont, CA | 官网 |\n| 上市地 / 代码 | NASDAQ: LRCX | 1984 IPO |\n| 最新财年营收 | FY2026 约 $220 亿（◐ 汇总） | 财报 |\n| 盈利 | 待核 | ◐ |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露；存储/代工/IDM | ◐ |\n| 员工 | 约 23,300 人 | Macrotrends |\n| 市值 / 估值 | 约 $2,987 亿（2026-11-02） | StockAnalysis/Yahoo |\n| 主要股东 | 机构为主 | ◐ |\n| 数据截至 | FY2026；Q1 FY2027 | — |\n\n## 定位与沿革\n\n刻蚀与沉积设备龙头：在导体/介质刻蚀、ALD/PECVD、清洗与先进封装设备上领先；AI/HBM 需求推动 WFE 上修，Q1 FY2027 营收 $82.2 亿、毛利率 52.3%。\n\n- 1980 年成立，总部 Fremont；1984 年上市（LRCX）。\n- 产品：刻蚀、沉积（ALD/PECVD）、清洗、先进封装、客户支持。\n- FY2026 Q4 营收 $67.2 亿（创纪录 6 月季）；Q1 FY2027 营收 $82.2 亿、毛利率 52.3%。\n- 2026 年 WFE 预测上调至 $1,400 亿（此前 $1,350 亿）；AI/HBM/先进封装驱动。\n- 客户：存储（DRAM/NAND）、代工/逻辑、IDM；中国收入受出口管制影响。\n- 员工约 23,300 人；市值约 $2,987 亿（2026-11-02）。\n\n## 创始人与管理层\n\n- **Tim Archer（总裁 & CEO）**：2019 年起任 CEO；主导 WFE 上修/先进封装。\n- **CFO/CTO**：名单待补。\n- 创始人：1980 年创立；具体创始人待核。\n- 董事会：机构 + 管理层；具体席位待核。\n- 关键人事变动：2025–2026 年先进封装团队扩张。\n\n## 商业模式\n\n- **收入结构**：刻蚀/沉积/清洗设备 + 客户支持（服务/备件）。\n- **销售动作**：大客户直销（存储/代工）；设备+服务。\n- **单位经济**：设备毛利约 48–52%；服务收入稳定；研发投入高。\n- **收入质量**：客户集中；存储周期影响大；服务/备件提供经常性收入。\n- **定价趋势**：先进设备溢价；按台/配置；服务按合同。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 刻蚀 | 导体/介质刻蚀 | 按台 | 主力 |\n| 沉积 | ALD/PECVD | 按台 | 主力 |\n| 清洗 | 晶圆清洗 | 按台 | 主力 |\n| 先进封装 | 2.5D/3D、HBM | 按台 | 增长 |\n| 客户支持 | 服务/备件/升级 | 按合同 | 主力 |\n\n- 包装：设备 + 服务 + 工艺方案；存储/先进封装。\n- 路线图：HBM/先进封装、GAA、下一代刻蚀。\n\n## 技术栈与壁垒\n\n- **架构**：等离子刻蚀/沉积工艺；与客户共同开发。\n- **AI 路线**：AI 用于工艺控制/良率；设备支持 AI 芯片/HBM 制造。\n- **壁垒**：刻蚀工艺 know-how、客户共同开发、设备平台、服务网络。\n- **依赖与债务**：存储周期、出口管制（中国）、客户集中。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 存储厂商 | DRAM/NAND/HBM 刻蚀 | 未披露具体数字 | 媒体 |\n| 代工/逻辑 | 先进制程刻蚀 | 未披露具体数字 | 媒体 |\n| 先进封装 | HBM/2.5D/3D | 未披露具体数字 | 媒体 |\n\n- 客户结构：存储、代工/逻辑、IDM；全球。\n- 集中度：前几大客户占比高（◐）。\n- 续约/流失：设备生命周期长；服务粘性。\n\n## 商业进展\n\n- FY2026 Q4 营收 $67.2 亿（创纪录）；Q1 FY2027 营收 $82.2 亿、毛利率 52.3%。\n- 2026 年 WFE 预测上调至 $1,400 亿；AI/HBM/先进封装驱动。\n- 先进封装收入增长；HBM 设备需求强劲。\n- 中国出口管制影响；公司调整区域结构。\n- 竞争：AMAT、TEL、KLA、ASML。\n\n## 经营业绩\n\n| 指标 | FY2024 | FY2025 | FY2026 | Q1 FY2027 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | $149 亿 | $182 亿 | 约 $220 亿 | $82.2 亿 | 创纪录 |\n| 增速 | -? | +22% | +21% | +? | 加速 |\n| 毛利率 | 约 47% | 约 48% | 约 49% | 52.3% | 改善 |\n| 营业利润 | 待核 | 待核 | 待核 | 待核 | — |\n| 净利 | $38 亿 | $46 亿 | 待核 | 待核 | ◐ |\n\n- 运营指标：WFE $1,400 亿（2026）；先进封装收入占比待核。\n- 指引：Q2 FY2027 指引待核。\n- 市场预期：AI/HBM 资本开支。\n\n## 股权、融资与股票\n\n- 上市：NASDAQ LRCX；1984 IPO。\n- 行情（2026-11-02）：市值约 $2,987 亿；股价/52 周待刷新（◐）。\n- 估值：PS 约 13.6x（按 FY2026）；PE 待核。\n- 股东：机构为主；具体持股待核。\n- 资本动作：分红/回购；研发/产能投资。\n- 风险提示：存储周期、出口管制、客户集中。\n\n## 团队与人员\n\n- 员工约 23,300 人；研发/制造/服务。\n- Fremont 总部；全球。\n- 招聘：2026 年先进封装/AI 岗位扩张；具体待采集。\n- 薪酬/股权激励：RSU；流失率未披露。\n- 组织：Tim Archer（CEO）；业务线负责人待补。\n\n## 竞争格局\n\n- 直接竞品：Applied Materials、Tokyo Electron、KLA、ASML。\n- 替代方案：其他设备商、国产设备替代。\n- 差异：刻蚀/沉积领先、先进封装/HBM；弱点：存储周期、出口管制。\n- 竞争动态：AMAT 平台广度；TEL 涂胶/刻蚀；国产设备追赶。\n- 份额：刻蚀设备全球领先（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：存储周期、出口管制（中国）、客户集中。\n- 技术：GAA/2nm、HBM/先进封装。\n- 法律/监管：美国出口管制、反垄断。\n- 治理：管理层/董事会；供应链。\n- 争议：WFE 上修的可持续性（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：中国收入占比、HBM 设备订单、先进封装收入均未入库。建议跟踪：① WFE 预测；② HBM/先进封装；③ 中国出口管制；④ 客户 capex；⑤ 与 AMAT/TEL 的份额。\n\n## 信源与口径\n\n- Q4 FY2026：https://www.prnewswire.com/news-releases/lam-research-corporation-reports-financial-results-for-the-quarter-ended-june-28-2026-302838154.html\n- Q1 FY2027：https://investor.lamresearch.com/\n- 市值/员工：https://stockanalysis.com/stocks/lrcx/market-cap/ ；https://www.macrotrends.net/stocks/charts/LRCX/lam-research/number-of-employees\n- 口径：FY2026 为季度汇总；◐ 表示待核。' },
      { id: 'kla', name: 'KLA', def: '过程控制龙头：检测量测市占约 58%，FY2026 营收 $135.8 亿。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 1975/1997 / Milpitas, CA | 官网 |\n| 上市地 / 代码 | NASDAQ: KLAC | 1980 IPO |\n| 最新财年营收 | FY2026 $135.8 亿 | 2026-07-28 发布 |\n| 盈利 | FY2026 净利 $48.3 亿 | FY2026 财报 |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露；代工/逻辑/存储 | ◐ |\n| 员工 | 约 17,000 人 | Bullfincher/Revelio |\n| 市值 / 估值 | 约 $2,057 亿（2026-11） | Macrotrends/Yahoo |\n| 主要股东 | 机构为主 | ◐ |\n| 数据截至 | FY2026（2026-06）；Q1 FY2027 | — |\n\n## 定位与沿革\n\n过程控制（检测/量测）龙头：在缺陷检测、膜厚/套刻量测、良率软件上市占约 58%；FY2026 营收 $135.8 亿、净利 $48.3 亿，Q1 FY2027 营收 $41.4 亿（+29%）创纪录。\n\n- 1975/1997 年沿革（KLA Instruments + Tencor 合并）；总部 Milpitas；1980 年上市（KLAC）。\n- 产品：缺陷检测、量测（膜厚/套刻/关键尺寸）、良率管理软件、先进封装检测。\n- FY2026 营收 $135.8 亿、GAAP 净利 $48.3 亿、EPS $3.66（10 拆 1 后）；Q4 FY2026 营收约 $36.6 亿。\n- FY2025 营收 $121.6 亿（对比基数）；Q1 FY2027 营收 $41.4 亿（+29%）创纪录。\n- 先进封装检测从 2025 年 $6.35 亿增长；AI/HBM 驱动。\n- 员工约 17,000 人；市值约 $2,057 亿（2026-11）。\n\n## 创始人与管理层\n\n- **Rick Wallace（CEO）**：2006 年起任 CEO；任职约 20 年；主导过程控制/先进封装。\n- **CFO/CTO**：名单待补。\n- 创始人：KLA Instruments/Tencor 历史；具体待核。\n- 董事会：机构 + 管理层；具体席位待核。\n- 关键人事变动：2025–2026 年先进封装团队扩张。\n\n## 商业模式\n\n- **收入结构**：检测/量测设备 + 服务（备件/升级/软件）。\n- **销售动作**：大客户直销（代工/存储/IDM）；设备+服务。\n- **单位经济**：设备毛利约 60%；服务收入稳定；研发投入高。\n- **收入质量**：客户集中；设备周期性强；服务/软件提供经常性收入。\n- **定价趋势**：先进检测溢价；按台/配置；服务按合同。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 缺陷检测 | 晶圆/掩模缺陷 | 按台 | 主力 |\n| 量测 | 膜厚/套刻/关键尺寸 | 按台 | 主力 |\n| 良率软件 | 数据分析/良率管理 | 按许可 | 增长 |\n| 先进封装检测 | HBM/2.5D/3D | 按台 | 增长 |\n| 服务/升级 | 维护、备件、升级 | 按合同 | 主力 |\n\n- 包装：设备 + 服务 + 软件；先进逻辑/存储/HBM。\n- 路线图：先进封装、HBM、2nm 检测。\n\n## 技术栈与壁垒\n\n- **架构**：光学/电子束检测、量测算法、良率软件。\n- **AI 路线**：AI 用于缺陷分类/良率分析；设备支持 AI 芯片制造。\n- **壁垒**：检测/量测精度、客户认证、良率数据、服务网络。\n- **依赖与债务**：客户集中、出口管制（中国）、周期。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| TSMC/Samsung/Intel | 先进制程检测 | 未披露具体数字 | 媒体 |\n| 存储厂商 | HBM/DRAM 检测 | 未披露具体数字 | 媒体 |\n| 先进封装厂 | HBM/2.5D/3D 检测 | 未披露具体数字 | 媒体 |\n\n- 客户结构：代工/逻辑、存储、IDM、封测；全球。\n- 集中度：前几大客户占比高（◐）。\n- 续约/流失：设备生命周期长；服务粘性。\n\n## 商业进展\n\n- FY2026 营收 $135.8 亿、净利 $48.3 亿；Q1 FY2027 营收 $41.4 亿（+29%）创纪录。\n- 先进封装检测增长；AI/HBM 驱动。\n- 过程控制市占约 58%；10 拆 1 拆股。\n- 中国出口管制影响；公司调整区域结构。\n- 竞争：ASML、AMAT、Hitachi High-Tech、Onto Innovation。\n\n## 经营业绩\n\n| 指标 | FY2024 | FY2025 | FY2026 | Q1 FY2027 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | $96.6 亿 | $121.6 亿 | $135.8 亿 | $41.4 亿 | +29% |\n| 增速 | -? | +26% | +11.7% | +29% | 加速 |\n| 毛利率 | 约 60% | 约 60% | 约 60% | 待核 | ◐ |\n| 营业利润 | 待核 | 待核 | 待核 | 待核 | — |\n| 净利 | $27.6 亿 | $40.6 亿 | $48.3 亿 | 待核 | 增长 |\n\n- 运营指标：过程控制市占约 58%；先进封装检测增长。\n- 指引：Q2 FY2027 指引待核。\n- 市场预期：AI/HBM/先进封装。\n\n## 股权、融资与股票\n\n- 上市：NASDAQ KLAC；1980 IPO。\n- 行情（2026-11）：市值约 $2,057 亿；股价/52 周待刷新（◐）。\n- 估值：PS 约 15x（按 FY2026）；PE 待核。\n- 股东：机构为主；具体持股待核。\n- 资本动作：分红/回购；10 拆 1 拆股（2026）。\n- 风险提示：出口管制、客户集中、周期。\n\n## 团队与人员\n\n- 员工约 17,000 人；研发/制造/服务。\n- Milpitas 总部；全球。\n- 招聘：2026 年先进封装/AI 岗位扩张；具体待采集。\n- 薪酬/股权激励：RSU；CEO 薪酬约 $2,995 万（媒体）。\n- 组织：Rick Wallace（CEO）；业务线负责人待补。\n\n## 竞争格局\n\n- 直接竞品：ASML（检测）、Applied Materials、Hitachi High-Tech、Onto Innovation。\n- 替代方案：其他检测/量测设备商、国产设备替代。\n- 差异：过程控制市占/精度、良率软件、先进封装；弱点：出口管制、客户集中。\n- 竞争动态：先进封装检测增长；国产设备追赶。\n- 份额：过程控制约 58%，第一（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：出口管制（中国）、客户集中、周期。\n- 技术：2nm/先进封装、HBM 检测。\n- 法律/监管：美国出口管制、反垄断。\n- 治理：管理层/董事会；供应链。\n- 争议：高市占与增长可持续性（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：中国收入占比、先进封装检测收入、客户名单均未入库。建议跟踪：① Q1 FY2027 增速；② 先进封装；③ 中国出口管制；④ 客户 capex；⑤ 与 ASML/AMAT 的份额。\n\n## 信源与口径\n\n- FY2026 Q4：https://ir.kla.com/news-events/press-releases/detail/518/kla-corporation-reports-fiscal-2026-fourth-quarter-and-full\n- Q3 FY2026：https://ir.kla.com/news-events/press-releases/detail/514/kla-corporation-reports-fiscal-2026-third-quarter-results\n- 市值/员工：https://www.macrotrends.net/stocks/charts/KLAC/kla/market-cap ；https://bullfincher.io/companies/kla-corporation/number-of-employees\n- 口径：FY2026 截至 2026-06；◐ 表示待核。' },
      { id: 'naura', name: '北方华创', def: '国产半导体设备平台：2025 营收 394 亿，2.1 万人覆盖刻蚀/薄膜/炉管。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2001 / 北京 | 官网 |\n| 上市地 / 代码 | 深交所 002371 | 2010 IPO |\n| 最新财年营收 | FY2025 约 ¥393.6 亿 | 2025 年报 |\n| 盈利 | 归母净利约 ¥32.3 亿（◐ 待核） | 2025 年报 |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露；中芯/华虹/长存/长鑫 | ◐ |\n| 员工 | 21,101 人 | 2025 年报/ESG |\n| 市值 / 估值 | 约 ¥3,600–3,700 亿（2026-11） | 股价×股本推算 |\n| 主要股东 | 北京电控/国资 | ◐ |\n| 数据截至 | FY2025；2026 Q3 | — |\n\n## 定位与沿革\n\n国产半导体设备平台：覆盖刻蚀、薄膜沉积（PVD/CVD/ALD）、炉管、清洗、热处理等，是中国晶圆厂扩产的核心国产设备供应商；2025 年营收约 ¥393.6 亿，员工 21,101 人。\n\n- 2001 年成立，总部北京；2010 年深交所上市（002371）；北京电控/国资背景。\n- 产品：刻蚀、PVD/CVD/ALD、氧化/扩散炉、清洗、热处理、气体/液体系统。\n- FY2025 营收约 ¥393.6 亿（Q4 单季 ¥120.5 亿创纪录）；归母净利约 ¥32.3 亿（◐ 待核）。\n- 2026 H1 营收 ¥201.61 亿（+24.90%）、归母净利 ¥33.70 亿（+5.05%）；Q1–Q3 营收 ¥314.67 亿（+15.26%）、净利 ¥53.92 亿。\n- 2025 年利润阶段性承压（研发/人员投入、毛利率），但收入保持增长；平台化布局深化。\n- 员工 21,101 人（2025 年末）；2025 年员工持股计划覆盖 2,293 人；市值约 ¥3,600–3,700 亿（2026-11）。\n\n## 创始人与管理层\n\n- **赵晋荣（董事长，◐ 待核）**：北方华创董事长；具体履历待补。\n- **管理层**：总经理/CFO 名单待采集；北京电控/国资背景。\n- 董事会：北京电控/国资 + 机构；具体席位待核。\n- 关键人事变动：2025 年员工持股计划；2026 年组织扩张。\n\n## 商业模式\n\n- **收入结构**：半导体设备（刻蚀/薄膜/炉管/清洗）+ 电子元器件/其他。\n- **销售动作**：中国晶圆厂直销（中芯/华虹/长存/长鑫）+ 渠道；国产替代。\n- **单位经济**：设备毛利约 40%；研发/人员投入大；规模效应。\n- **收入质量**：中国客户为主；国产替代驱动；客户集中度未披露。\n- **定价趋势**：国产设备价格优势；按台/配置；服务/备件。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 刻蚀 | 导体/介质刻蚀 | 按台 | 主力 |\n| 薄膜沉积 | PVD/CVD/ALD | 按台 | 主力 |\n| 炉管/热处理 | 氧化/扩散/退火 | 按台 | 主力 |\n| 清洗 | 晶圆清洗 | 按台 | 增长 |\n| 气体/液体系统 | 工艺配套 | 按套 | 增长 |\n\n- 包装：设备 + 工艺 + 服务；国产替代方案。\n- 路线图：先进制程设备、平台化、海外扩张。\n\n## 技术栈与壁垒\n\n- **架构**：刻蚀/沉积/炉管/清洗设备平台；国产零部件适配。\n- **AI 路线**：AI 用于设备控制/良率；非 AI 芯片直接产品。\n- **壁垒**：国产设备平台广度、中国客户关系、国资背景、服务网络。\n- **依赖与债务**：出口管制/零部件、客户集中、毛利率、研发投入。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 中芯国际/华虹 | 成熟/先进制程设备 | 未披露具体数字 | 媒体 |\n| 长江存储/长鑫存储 | 3D NAND/DRAM 设备 | 未披露具体数字 | 媒体 |\n| 其他中国晶圆厂 | 刻蚀/薄膜/炉管 | 未披露具体数字 | 官网 |\n\n- 客户结构：中国晶圆厂/存储/功率；国产替代。\n- 集中度：未披露；中国客户为主。\n- 续约/流失：设备生命周期长；服务/备件粘性。\n\n## 商业进展\n\n- FY2025 营收约 ¥393.6 亿；Q4 单季 ¥120.5 亿创纪录；净利约 ¥32.3 亿。\n- 2026 H1 营收 ¥201.61 亿（+24.90%）、净利 ¥33.70 亿（+5.05%）。\n- 2026 Q1–Q3 营收 ¥314.67 亿（+15.26%）、净利 ¥53.92 亿。\n- 2025 年员工持股计划（2,293 人）；研发/人员投入加大。\n- 竞争：AMAT、Lam、TEL、中微公司、拓荆科技。\n\n## 经营业绩\n\n| 指标 | 2023 | 2024 | 2025 | 2026 Q1–Q3 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | 待核 | 约 ¥298 亿 | 约 ¥393.6 亿 | ¥314.67 亿 | +15.26% |\n| 增速 | 待核 | +35% | +32% | +15.26% | 放缓 |\n| 毛利率 | 待核 | 约 42% | 待核 | 待核 | 承压 |\n| 营业利润 | 待核 | 待核 | 待核 | 待核 | — |\n| 归母净利 | 待核 | 约 ¥56.2 亿 | 约 ¥32.3 亿 | ¥53.92 亿 | 利润承压 |\n\n- 运营指标：员工 21,101；员工持股 2,293 人；Q4 2025 营收 ¥120.5 亿。\n- 指引：2026 年营收/利润待查；平台化/国产替代。\n- 市场预期：国产设备份额提升、利润修复。\n\n## 股权、融资与股票\n\n- 上市：深交所 002371；2010 IPO。\n- 行情（2026-11）：股价约 ¥504；市值约 ¥3,600–3,700 亿；52 周 ¥386.62–968.00。\n- 估值：PE 约 50x（按 2025 净利，◐）；PS 约 9x。\n- 股东：北京电控/国资、机构；具体持股待核。\n- 资本动作：2025 年员工持股计划；分红/融资待查。\n- 风险提示：利润承压、估值、出口管制。\n\n## 团队与人员\n\n- 员工 21,101 人（2025 年末）；研发/制造/服务。\n- 北京总部；全国厂区/服务网络。\n- 招聘：2026 年先进制程设备岗位扩张；具体待采集。\n- 薪酬/股权激励：2025 年员工持股计划（2,293 人，1,040.305 万份期权）。\n- 组织：赵晋荣（董事长，◐）；管理层名单待补。\n\n## 竞争格局\n\n- 直接竞品：AMAT、Lam、TEL、中微公司、拓荆科技、盛美上海。\n- 替代方案：进口设备、其他国产设备。\n- 差异：国产设备平台广度、中国客户、国资背景；弱点：先进制程/零部件、毛利率。\n- 竞争动态：国产替代加速；中微刻蚀竞争；AMAT/Lam 技术领先。\n- 份额：中国半导体设备国产份额领先（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：客户集中、毛利率、研发投入、出口管制/零部件。\n- 技术：先进制程设备、平台化、良率。\n- 法律/监管：美国出口管制、国资监管。\n- 治理：北京电控/国资控制、员工持股。\n- 争议：利润下滑与估值（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：毛利率、客户名单、先进制程设备进展均未入库。建议跟踪：① 2026 营收/利润；② 毛利率；③ 先进制程设备；④ 国产替代份额；⑤ 与中微的竞争。\n\n## 信源与口径\n\n- 2025 年报：https://vip.stock.finance.sina.com.cn/corp/view/vCB_AllBulletinDetail.php?stockid=002371&id=12113807\n- 员工：https://www.naura.com/Public/Upload/file/20260518/177906937626569e796dd06b51.pdf\n- 2026 三季报：https://www.sohu.com/a/1095329687_115377\n- 行情：https://q.stock.sohu.com/cn/002371/information.shtml\n- 口径：FY2025 为年报；净利/市值为推算；◐ 表示待核。' },
      { id: 'amec', name: '中微公司', def: '国产刻蚀龙头：2025 营收 124 亿，薄膜设备成为第二增长曲线。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2004 / 上海 | 官网 |\n| 上市地 / 代码 | 科创板 688012 | 2019 IPO |\n| 最新财年营收 | FY2025 ¥123.85 亿（+36.62%） | 2025 年报/预告 |\n| 盈利 | 归母净利待核；2026 Q3 ¥41.34 亿 | ◐ |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露；中芯/华虹/长存/台积电 | ◐ |\n| 员工 | 约 3,680 人；研发 1,908 人（51.85%） | 2026 半年报推算 |\n| 市值 / 估值 | 约 ¥2,624 亿（2026-10-22） | 媒体 |\n| 主要股东 | 尹志尧等创始团队/机构 | ◐ |\n| 数据截至 | FY2025；2026 Q3 | — |\n\n## 定位与沿革\n\n国产刻蚀设备龙头：以 CCP/ICP 刻蚀、MOCVD 与薄膜设备为核心，2025 年营收 ¥123.85 亿（+36.62%），薄膜设备营收同比 +224%，成为第二增长曲线。\n\n- 2004 年由尹志尧（前 Applied Materials/ Lam 高管）等创立，总部上海；2019 年科创板上市（688012）。\n- 产品：CCP/ICP 刻蚀、MOCVD、薄膜沉积、检测；已开发 54 种高端设备。\n- FY2025 营收 ¥123.85 亿（+36.62%）；刻蚀为主力，薄膜设备 +224.23%。\n- 2026 H1 营收 ¥66.91 亿（+34.89%）、归母净利 ¥28.25 亿（+300.22%，含非经常性收益）；扣非净利 ¥10–12 亿。\n- 2026 Q1–Q3 归母净利 ¥41.34 亿（+241.31%）；研发人员 1,908 人（51.85%）。\n- 2026-10-22 股价 ¥264.18、市值约 ¥2,624 亿；创始人尹志尧四次入选福布斯中国最佳 CEO。\n\n## 创始人与管理层\n\n- **尹志尧（创始人、董事长）**：前 Applied Materials/ Lam 高管；2004 年创立中微；2026 年第四次入选福布斯中国最佳 CEO。\n- **管理层**：总经理/CFO 名单待采集；研发团队 1,908 人。\n- 董事会：创始团队 + 机构；具体席位待核。\n- 关键人事变动：2025–2026 年研发/产能扩张；临港新片区布局。\n\n## 商业模式\n\n- **收入结构**：刻蚀设备（CCP/ICP）+ MOCVD + 薄膜设备 + 检测/服务。\n- **销售动作**：中国晶圆厂直销（中芯/华虹/长存）+ 海外客户；国产替代。\n- **单位经济**：设备毛利约 40–45%；研发投入高；薄膜设备新增长。\n- **收入质量**：中国客户为主；刻蚀基本盘 + 薄膜增量；客户集中度未披露。\n- **定价趋势**：国产设备价格优势；按台/配置；服务/备件。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| CCP 刻蚀 | 介质刻蚀 | 按台 | 主力 |\n| ICP 刻蚀 | 导体刻蚀 | 按台 | 主力 |\n| MOCVD | LED/功率/GaN | 按台 | 主力 |\n| 薄膜设备 | CVD/ALD | 按台 | 增长 |\n| 检测/服务 | 设备检测、备件 | 按合同 | 增长 |\n\n- 包装：设备 + 工艺 + 服务；国产替代方案。\n- 路线图：先进刻蚀、薄膜、临港产能。\n\n## 技术栈与壁垒\n\n- **架构**：CCP/ICP 刻蚀 + MOCVD + 薄膜；国产零部件适配。\n- **AI 路线**：AI 用于设备控制/良率；非 AI 芯片直接产品。\n- **壁垒**：刻蚀工艺、客户认证、研发团队、科创板融资。\n- **依赖与债务**：客户集中、出口管制/零部件、研发投入、估值。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 中芯国际/华虹 | 刻蚀/薄膜设备 | 未披露具体数字 | 媒体 |\n| 长江存储 | 3D NAND 刻蚀 | 未披露具体数字 | 媒体 |\n| 台积电/海外客户 | 刻蚀设备 | 未披露具体数字 | 媒体 |\n\n- 客户结构：中国晶圆厂/存储、海外代工；国产替代。\n- 集中度：未披露；中国客户为主。\n- 续约/流失：设备生命周期长；服务/备件粘性。\n\n## 商业进展\n\n- FY2025 营收 ¥123.85 亿（+36.62%）；薄膜设备 +224.23%。\n- 2026 H1 营收 ¥66.91 亿（+34.89%）、净利 ¥28.25 亿（+300.22%）。\n- 2026 Q1–Q3 净利 ¥41.34 亿（+241.31%）；研发人员 1,908 人。\n- 已开发 54 种高端设备；临港新片区布局。\n- 竞争：Lam、AMAT、TEL、北方华创。\n\n## 经营业绩\n\n| 指标 | 2023 | 2024 | 2025 | 2026 Q1–Q3 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | ¥62.6 亿 | ¥90.65 亿 | ¥123.85 亿 | 待核 | +36.62% |\n| 增速 | +32% | +45% | +36.62% | 待核 | 高速 |\n| 毛利率 | 约 45% | 约 42% | 待核 | 待核 | ◐ |\n| 营业利润 | 待核 | 待核 | 待核 | 待核 | — |\n| 归母净利 | ¥17.9 亿 | ¥16.2 亿 | 待核 | ¥41.34 亿 | 2026 含非经常性 |\n\n- 运营指标：研发 1,908 人（51.85%）；54 种高端设备；临港布局。\n- 指引：2026 年营收/利润待查；薄膜设备目标。\n- 市场预期：刻蚀/薄膜国产替代。\n\n## 股权、融资与股票\n\n- 上市：科创板 688012；2019 IPO。\n- 行情（2026-10-22）：股价 ¥264.18；市值约 ¥2,624 亿；总股本约 6.26 亿股。\n- 估值：PE 约 63x（按 2025 净利，◐）；PS 约 21x。\n- 股东：尹志尧等创始团队/机构；具体持股待核。\n- 资本动作：2025 年分红 10 派 3.50 元；再融资待查。\n- 风险提示：估值高、客户集中、出口管制。\n\n## 团队与人员\n\n- 员工约 3,680 人；研发 1,908 人（51.85%）。\n- 上海总部；临港新片区布局。\n- 招聘：2026 年薄膜/先进刻蚀岗位扩张；具体待采集。\n- 薪酬/股权激励：科创板上市，有股权激励；流失率未披露。\n- 组织：尹志尧（董事长）；管理层名单待补。\n\n## 竞争格局\n\n- 直接竞品：Lam Research、Applied Materials、Tokyo Electron、北方华创。\n- 替代方案：进口设备、其他国产设备。\n- 差异：刻蚀工艺/客户认证、薄膜第二曲线、研发团队；弱点：规模小于 AMAT/Lam、零部件。\n- 竞争动态：国产替代加速；北方华创平台化竞争；Lam/AMAT 技术领先。\n- 份额：国产刻蚀设备领先（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：客户集中、毛利率、研发投入、估值。\n- 技术：先进刻蚀、薄膜设备、零部件。\n- 法律/监管：美国出口管制、科创板披露。\n- 治理：创始人控制权、股权激励。\n- 争议：2026 净利含非经常性收益，扣非质量需区分（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：毛利率、客户名单、薄膜设备收入、临港产能均未入库。建议跟踪：① 薄膜设备收入；② 2026 营收/扣非净利；③ 先进刻蚀；④ 出口管制；⑤ 与北方华创的竞争。\n\n## 信源与口径\n\n- 2025 年报摘要：https://static.cninfo.com.cn/finalpage/2026-03-31/1225062430.PDF\n- 2026 三季报：https://stockmc.xueqiu.com/202610/688012_20261031_WWHS.pdf\n- 业绩说明会：https://www.amec-inc.com/news/708.html\n- 市值/员工：https://q.stock.sohu.com/cn/688012/index.shtml ；https://www.amec-inc.com/\n- 口径：FY2025 为年报/预告；员工数为 2026 半年报推算；◐ 表示待核。' },
      { id: 'amkor', name: 'Amkor', def: '全球第二大封测厂：先进封装占 82%，亚利桑那厂承接 AI 订单。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 1968 / Tempe, AZ | 官网 |\n| 上市地 / 代码 | NASDAQ: AMKR | 1998 IPO |\n| 最新财年营收 | FY2025 约 $64 亿（◐） | 年报/推算 |\n| 盈利 | FY2025 净利约 $4 亿（◐）；Q3 2026 $1.91 亿 | ◐ |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露；TSMC、NVIDIA、Apple 等 | ◐ |\n| 员工 | 30,591 人（2026-03） | Revelio |\n| 市值 / 估值 | 约 $98 亿（2026-10） | Macrotrends/StockAnalysis |\n| 主要股东 | 机构/创始家族 | ◐ |\n| 数据截至 | FY2025；Q3 2026 | — |\n\n## 定位与沿革\n\n全球第二大封测厂（OSAT）：提供先进封装（2.5D/3D、SiP、Flip Chip）、测试与交钥匙服务；先进封装约占收入 82%，亚利桑那厂承接 TSMC/NVIDIA 的 AI 订单。\n\n- 1968 年成立，总部 Tempe, AZ；工厂主要在亚洲（菲律宾/韩国/日本/中国/越南）与美国亚利桑那。\n- 产品：先进封装、传统封装、测试、SiP、CPO（共封装光学）。\n- FY2025 营收约 $64 亿（◐）；FY2026 Q3 营收 $19.9 亿、净利 $1.91 亿、EPS $0.76。\n- 2026 年 capex 指引 $25–30 亿（2025 约 $9.5 亿），亚利桑那厂/2.5D 扩产。\n- 与 TSMC/NVIDIA 的长期合作；AI/HPC 封装需求强劲。\n- 员工 30,591 人（2026-03）；市值约 $98 亿（2026-10）。\n\n## 创始人与管理层\n\n- **Giel Rutten（总裁 & CEO）**：2019 年起任 CEO（◐ 任期待核）；主导先进封装/美国扩产。\n- **CFO/CTO**：名单待补。\n- 创始人：1968 年创立；创始家族仍为股东（◐）。\n- 董事会：机构 + 创始家族；具体席位待核。\n- 关键人事变动：2025–2026 年美国厂/先进封装团队扩张。\n\n## 商业模式\n\n- **收入结构**：先进封装（2.5D/3D、SiP）+ 传统封装 + 测试；交钥匙服务。\n- **销售动作**：大客户直销（fabless/IDM/代工）；客户提供晶圆，Amkor 做封装测试。\n- **单位经济**：先进封装毛利较高；capex 大；产能利用率是关键。\n- **收入质量**：客户集中；AI/HPC 订单增长；消费/汽车周期影响。\n- **定价趋势**：先进封装按产能/项目；传统封装按颗；测试按小时。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 先进封装 | 2.5D/3D、SiP、Flip Chip | 按项目/产能 | 主力 |\n| 传统封装 | QFN/BGA/引线键合 | 按颗 | 主力 |\n| 测试 | 晶圆/成品测试 | 按小时 | 主力 |\n| CPO | 共封装光学 | 按项目 | 试验 |\n| 交钥匙 | 设计+封装+测试 | 按项目 | 增长 |\n\n- 包装：先进封装 + 测试 + 交钥匙；AI/HPC/汽车方案。\n- 路线图：亚利桑那厂、2.5D/3D、CPO。\n\n## 技术栈与壁垒\n\n- **架构**：封装/测试工艺 + 先进封装（2.5D/3D）；全球工厂网络。\n- **AI 路线**：AI/HPC 先进封装；CPO；与 TSMC/NVIDIA 合作。\n- **壁垒**：先进封装工艺、客户认证、全球产能、交钥匙服务。\n- **依赖与债务**：客户集中、capex、消费/汽车周期、地缘政治。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| TSMC/NVIDIA | AI/HPC 先进封装 | 未披露具体数字 | 媒体 |\n| Apple/手机客户 | SiP/传统封装 | 未披露具体数字 | 媒体 |\n| 汽车/工业 | 车规封装测试 | 未披露具体数字 | 官网 |\n\n- 客户结构：fabless/IDM/代工、手机、汽车；全球。\n- 集中度：前几大客户占比高（◐）。\n- 续约/流失：封装认证周期长；先进封装粘性。\n\n## 商业进展\n\n- FY2025 营收约 $64 亿；Q3 2026 营收 $19.9 亿、净利 $1.91 亿。\n- 2026 capex $25–30 亿；亚利桑那厂/2.5D 扩产。\n- 与 TSMC/NVIDIA 长期合作；CPO 加入技术平台。\n- AI/HPC 需求强劲；消费/汽车复苏待观察。\n- 竞争：ASE、JCET、TFME、TSMC（CoWoS）、华天。\n\n## 经营业绩\n\n| 指标 | FY2023 | FY2024 | FY2025 | Q3 2026 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | $65.0 亿 | $63.2 亿 | 约 $64 亿 | $19.9 亿 | 持平 |\n| 增速 | -? | -3% | +1% | +? | 复苏 |\n| 毛利率 | 约 14% | 约 15% | 约 16% | 18.3% | 改善 |\n| 营业利润 | 待核 | 待核 | 待核 | $2.25 亿 | — |\n| 净利 | $3.6 亿 | $3.5 亿 | 约 $4 亿 | $1.91 亿 | ◐ |\n\n- 运营指标：先进封装占 82%；2026 capex $25–30 亿；员工 30,591。\n- 指引：Q4 2026 待核；2026 全年 capex $25–30 亿。\n- 市场预期：AI/HPC 先进封装、亚利桑那厂。\n\n## 股权、融资与股票\n\n- 上市：NASDAQ AMKR；1998 IPO。\n- 行情（2026-10）：股价约 $41.21；市值约 $98 亿；52 周待核（◐）。\n- 估值：PS 约 1.5x；PE 待核。\n- 股东：机构/创始家族；具体持股待核。\n- 资本动作：capex/债务；分红待查。\n- 风险提示：客户集中、capex、周期。\n\n## 团队与人员\n\n- 员工 30,591 人（2026-03）；制造为主。\n- Tempe 总部；亚洲/美国工厂。\n- 招聘：2026 年亚利桑那厂/先进封装；具体待采集。\n- 薪酬/股权激励：RSU；流失率未披露。\n- 组织：Giel Rutten（CEO）；业务线负责人待补。\n\n## 竞争格局\n\n- 直接竞品：ASE、JCET、TFME、华天科技、TSMC（CoWoS）。\n- 替代方案：IDM 自封装、其他 OSAT。\n- 差异：先进封装/全球产能/交钥匙；弱点：客户集中、capex、周期。\n- 竞争动态：TSMC CoWoS 强势；ASE 规模第一；中国 OSAT 追赶。\n- 份额：全球 OSAT 第二（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：客户集中、capex、消费/汽车周期。\n- 技术：2.5D/3D、CPO、良率。\n- 法律/监管：出口管制、地缘政治。\n- 治理：创始家族/机构；董事会。\n- 争议：美国厂成本与补贴（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：客户名单、先进封装收入、亚利桑那厂进度均未入库。建议跟踪：① AI/HPC 封装订单；② capex；③ 亚利桑那厂；④ 毛利率；⑤ 与 ASE/TSMC 的份额。\n\n## 信源与口径\n\n- Q3 2026：https://ir.amkor.com/news-releases/news-release-details/amkor-technology-reports-financial-results-second-quarter-2026\n- FY2025 10-K：https://www.sec.gov/Archives/edgar/data/1047127/000104712726000014/amkr-20251231.htm\n- 市值/员工：https://www.macrotrends.net/stocks/charts/AMKR/amkor-technology/market-cap ；https://www.reveliolabs.com/companies/amkor-technology/employees\n- 口径：FY2025 为推算；◐ 表示待核。' },
      { id: 'ase', name: '日月光', def: '全球第一大封测厂：先进封装 LEAP 2026 超 $40 亿，资本开支 $105 亿。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 1984 / 高雄 | 官网 |\n| 上市地 / 代码 | 台交所 3711；NYSE: ASX | 1989/2000 上市 |\n| 最新财年营收 | FY2025 约 NT$6,500 亿（◐） | 年报/推算 |\n| 盈利 | 2026 Q2 净利 NT$210.68 亿；Q3 NT$270 亿 | 2026 财报 |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露；AI/HPC/手机/汽车 | ◐ |\n| 员工 | 约 119,000 人 | Morningstar/Google |\n| 市值 / 估值 | 约 $883 亿（2026-11-01） | Macrotrends |\n| 主要股东 | 机构为主 | ◐ |\n| 数据截至 | FY2025；2026 Q3 | — |\n\n## 定位与沿革\n\n全球第一大封测厂（OSAT）：提供封装、测试、SiP 与先进封装（LEAP）；2026 年先进封装收入目标超 $40 亿，资本开支上调至 $105 亿，AI/HBM 需求驱动。\n\n- 1984 年成立于高雄；台交所 3711、NYSE ASX。\n- 业务：IC 封装/测试、SiP、先进封装（2.5D/3D、Fan-Out）、EMS/系统级组装。\n- FY2025 营收约 NT$6,500 亿（◐）；2026 Q2 营收 NT$1,910.64 亿（+27%）、净利 NT$210.68 亿（+180%）。\n- 2026 Q3 净利 NT$270 亿、EPS NT$6.13；营收环比 +28%，超指引。\n- 2026 年 LEAP（先进封装/测试）收入目标由 $26 亿上调至超 $40 亿；2027 年目标翻倍。\n- 2026 年资本开支由 $85 亿上调至 $105 亿（+23.5%），创历史新高。\n- 员工约 119,000 人；市值约 $883 亿（2026-11-01）。\n\n## 创始人与管理层\n\n- **张虔生（董事长）**：日月光集团创始人/董事长（◐ 角色待核）。\n- **管理层**：CEO/CFO 名单待采集；先进封装/测试团队。\n- 董事会：台湾上市公司治理；具体席位待核。\n- 关键人事变动：2025–2026 年先进封装扩产组织。\n\n## 商业模式\n\n- **收入结构**：封装/测试（IC ATM）+ SiP/EMS + 先进封装（LEAP）。\n- **销售动作**：大客户直销（fabless/IDM）；交钥匙/产能预订。\n- **单位经济**：先进封装毛利较高；capex 大；产能利用率关键。\n- **收入质量**：客户集中；AI/HPC 先进封装增长；手机/汽车周期。\n- **定价趋势**：先进封装按产能/项目；传统封装按颗；测试按小时。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 先进封装（LEAP） | 2.5D/3D、Fan-Out、SiP | 按项目/产能 | 主力 |\n| 传统封装 | BGA/QFN/引线键合 | 按颗 | 主力 |\n| 测试 | 晶圆/成品测试 | 按小时 | 主力 |\n| SiP/EMS | 系统级封装/组装 | 按项目 | 增长 |\n| 汽车/工业 | 车规封装测试 | 按项目 | 增长 |\n\n- 包装：先进封装 + 测试 + SiP/EMS；AI/HPC/汽车方案。\n- 路线图：LEAP 扩产、2.5D/3D、海外厂。\n\n## 技术栈与壁垒\n\n- **架构**：封装/测试工艺 + 先进封装；全球工厂网络。\n- **AI 路线**：AI/HPC 先进封装、HBM 配套；CPO 待核。\n- **壁垒**：规模/全球产能、先进封装工艺、客户认证、交钥匙服务。\n- **依赖与债务**：客户集中、capex、周期、地缘政治。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| AI/HPC 客户 | 先进封装/测试 | LEAP 2026 >$40 亿 | 公司口径 |\n| 手机客户 | SiP/传统封装 | 未披露具体数字 | 媒体 |\n| 汽车/工业 | 车规封装测试 | 未披露具体数字 | 官网 |\n\n- 客户结构：fabless/IDM、手机、汽车；全球。\n- 集中度：前几大客户占比高（◐）。\n- 续约/流失：封装认证周期长；先进封装粘性。\n\n## 商业进展\n\n- 2026 Q2 营收 NT$1,910.64 亿（+27%）、净利 NT$210.68 亿（+180%）。\n- 2026 Q3 净利 NT$270 亿、EPS NT$6.13；营收环比 +28%，超指引。\n- LEAP 2026 收入目标 >$40 亿；2027 年目标翻倍。\n- 2026 capex 上调至 $105 亿（+23.5%），历史新高。\n- 竞争：Amkor、JCET、TFME、TSMC（CoWoS）。\n\n## 经营业绩\n\n| 指标 | 2024 | 2025 | 2026 Q2 | 2026 Q3 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | 约 NT$5,810 亿 | 约 NT$6,500 亿 | NT$1,910.64 亿 | 待核 | +27%（Q2） |\n| 增速 | +? | +12% | +27% | +28% 环比 | 加速 |\n| 毛利率 | 约 17% | 约 18% | 待核 | 待核 | ◐ |\n| 营业利润 | 待核 | 待核 | 待核 | 待核 | — |\n| 净利 | 待核 | 待核 | NT$210.68 亿 | NT$270 亿 | +180% |\n\n- 运营指标：LEAP 2026 >$40 亿；capex $105 亿；员工 119,000。\n- 指引：2026 LEAP >$40 亿；2027 翻倍。\n- 市场预期：AI/HBM 先进封装、capex 回报。\n\n## 股权、融资与股票\n\n- 上市：台交所 3711；NYSE ASX（ADR）。\n- 行情（2026-11-01）：市值约 $883 亿；股价/52 周待刷新（◐）。\n- 估值：PS 约 13x（按 2025 营收）；PE 待核。\n- 股东：机构为主；具体持股待核。\n- 资本动作：capex $105 亿；分红/融资待查。\n- 风险提示：客户集中、capex、周期。\n\n## 团队与人员\n\n- 员工约 119,000 人；制造为主。\n- 高雄总部；全球工厂（中国/东南亚/美洲）。\n- 招聘：2026 年先进封装扩产；具体待采集。\n- 薪酬/股权激励：RSU/分红；流失率未披露。\n- 组织：张虔生（董事长）；CEO/CFO 待补。\n\n## 竞争格局\n\n- 直接竞品：Amkor、JCET、TFME、华天科技、TSMC（CoWoS）。\n- 替代方案：IDM 自封装、其他 OSAT。\n- 差异：规模/全球产能/先进封装/交钥匙；弱点：客户集中、capex、周期。\n- 竞争动态：TSMC CoWoS 强势；Amkor 美国厂；中国 OSAT 追赶。\n- 份额：全球 OSAT 第一（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：客户集中、capex、周期、地缘政治。\n- 技术：2.5D/3D、CPO、良率。\n- 法律/监管：出口管制、海外厂补贴。\n- 治理：台湾上市公司治理；家族/管理层。\n- 争议：$105 亿 capex 的回报周期（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：LEAP 收入、客户名单、capex 回报均未入库。建议跟踪：① LEAP 收入；② capex；③ AI/HBM 订单；④ 毛利率；⑤ 与 Amkor/TSMC 的份额。\n\n## 信源与口径\n\n- 2026 Q2：https://www.prnewswire.com/news-releases/ase-technology-holding-co-ltd-reports-its-unaudited-consolidated-financial-results-for-the-second-quarter-of-2026-302838714.html\n- LEAP/capex：https://ee.ofweek.com/2026-08/ART-12003-2815-30699744.html\n- 市值/员工：https://www.macrotrends.net/stocks/charts/ASX/ase-technology-holding/market-cap ；https://www.morningstar.com/stocks/xnys/asx/quote\n- 口径：FY2025 为推算；◐ 表示待核。' },
      { id: 'jcet', name: '长电科技', def: '中国封测龙头：2025 营收 388.7 亿，先进封装与汽车电子并进。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 1972 / 江阴 | 官网 |\n| 上市地 / 代码 | 上交所 600584 | 2003 IPO |\n| 最新财年营收 | FY2025 ¥388.7 亿（+8.09%） | 2025 年报 |\n| 盈利 | 归母净利 ¥15.65 亿（-2.75%） | 2025 年报 |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露；AI/HPC/汽车/手机 | ◐ |\n| 员工 | 24,952 人 | 2025 年报/媒体 |\n| 市值 / 估值 | 约 ¥1,050 亿（2026-08） | 股价×股本推算 |\n| 主要股东 | 大基金/中芯系等 | ◐ |\n| 数据截至 | FY2025；2026 Q3 | — |\n\n## 定位与沿革\n\n中国封测龙头：提供封装/测试、SiP、先进封装与汽车电子；2025 年营收 ¥388.7 亿（+8.09%）、归母净利 ¥15.65 亿（-2.75%），2026 年利润修复。\n\n- 1972 年成立，总部江阴；2003 年上交所上市（600584）；中国最大 OSAT。\n- 业务：封装/测试、SiP、先进封装（2.5D/3D、Fan-Out）、汽车电子、存储封测。\n- FY2025 营收 ¥388.7 亿（+8.09%）、归母净利 ¥15.65 亿（-2.75%）；Q4 营收 ¥102.0 亿、净利 ¥6.1 亿。\n- 2026 Q1 营收 ¥91.71 亿、净利 ¥2.90 亿（+42.74%）；2026 Q3 营收 ¥114.25 亿（+13.53%）、净利 ¥7.73 亿（+59.99%）。\n- 2026 年固定资产投资预算约 ¥100 亿；先进封装/汽车电子扩产。\n- 员工 24,952 人；市值约 ¥1,050 亿（2026-08）。\n\n## 创始人与管理层\n\n- **管理层**：董事长/CEO/CFO 名单待采集；大基金/中芯系股东。\n- 创始人：1972 年江阴晶体管厂沿革；具体待核。\n- 董事会：大基金/国资 + 机构；具体席位待核。\n- 关键人事变动：2025–2026 年先进封装/汽车团队扩张。\n\n## 商业模式\n\n- **收入结构**：封装/测试（传统/先进）+ SiP + 汽车电子 + 存储封测。\n- **销售动作**：大客户直销（fabless/IDM）；交钥匙/产能预订。\n- **单位经济**：传统封装毛利低；先进封装/汽车毛利较高；capex 大。\n- **收入质量**：客户集中；AI/HPC/汽车增长；消费周期。\n- **定价趋势**：先进封装按项目/产能；传统按颗；测试按小时。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 先进封装 | 2.5D/3D、Fan-Out、SiP | 按项目/产能 | 主力 |\n| 传统封装 | BGA/QFN/引线键合 | 按颗 | 主力 |\n| 测试 | 晶圆/成品测试 | 按小时 | 主力 |\n| 汽车电子 | 车规封装测试 | 按项目 | 增长 |\n| 存储封测 | DRAM/NAND 封装 | 按颗 | 增长 |\n\n- 包装：先进封装 + 测试 + 汽车/存储；AI/HPC 方案。\n- 路线图：2.5D/3D、汽车、存储、海外厂。\n\n## 技术栈与壁垒\n\n- **架构**：封装/测试工艺 + 先进封装；全球工厂网络。\n- **AI 路线**：AI/HPC 先进封装、HBM 配套；汽车/存储。\n- **壁垒**：中国最大 OSAT、客户认证、先进封装、汽车资质。\n- **依赖与债务**：客户集中、capex、毛利率、周期。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| AI/HPC 客户 | 先进封装/测试 | 未披露具体数字 | 媒体 |\n| 汽车客户 | 车规封装 | 未披露具体数字 | 官网 |\n| 存储/手机客户 | 存储/传统封装 | 未披露具体数字 | 媒体 |\n\n- 客户结构：fabless/IDM、汽车、存储、手机；全球。\n- 集中度：前几大客户占比高（◐）。\n- 续约/流失：封装认证周期长；先进封装粘性。\n\n## 商业进展\n\n- FY2025 营收 ¥388.7 亿（+8.09%）、净利 ¥15.65 亿（-2.75%）。\n- 2026 Q1 营收 ¥91.71 亿、净利 ¥2.90 亿（+42.74%）。\n- 2026 Q3 营收 ¥114.25 亿（+13.53%）、净利 ¥7.73 亿（+59.99%）。\n- 2026 年固定资产投资约 ¥100 亿；先进封装/汽车扩产。\n- 竞争：ASE、Amkor、TFME、华天科技。\n\n## 经营业绩\n\n| 指标 | 2023 | 2024 | 2025 | 2026 Q3 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | ¥296.6 亿 | ¥359.6 亿 | ¥388.7 亿 | ¥114.25 亿 | +8.09% |\n| 增速 | -12% | +21% | +8.09% | +13.53% | 复苏 |\n| 毛利率 | 约 14% | 约 13% | 待核 | 待核 | ◐ |\n| 营业利润 | 待核 | 待核 | 待核 | 待核 | — |\n| 归母净利 | ¥14.7 亿 | ¥16.1 亿 | ¥15.65 亿 | ¥7.73 亿 | -2.75%/+59.99% |\n\n- 运营指标：员工 24,952；2026 capex 约 ¥100 亿；Q4 2025 营收 ¥102.0 亿。\n- 指引：2026 年营收/利润待查；先进封装/汽车。\n- 市场预期：利润修复、先进封装。\n\n## 股权、融资与股票\n\n- 上市：上交所 600584；2003 IPO。\n- 行情（2026-08）：股价约 ¥58.48；市值约 ¥1,050 亿；总股本约 17.9 亿股。\n- 估值：PE 约 67x（按 2025 净利）；PS 约 2.7x。\n- 股东：大基金/中芯系、机构；具体持股待核。\n- 资本动作：2026 capex ¥100 亿；定增/融资待查。\n- 风险提示：毛利率、客户集中、capex。\n\n## 团队与人员\n\n- 员工 24,952 人；制造为主。\n- 江阴总部；全球工厂（中国/新加坡/韩国）。\n- 招聘：2026 年先进封装/汽车扩产；具体待采集。\n- 薪酬/股权激励：A 股上市，有股权激励；流失率未披露。\n- 组织：管理层名单待补；大基金/国资影响。\n\n## 竞争格局\n\n- 直接竞品：ASE、Amkor、TFME、华天科技、TSMC（CoWoS）。\n- 替代方案：IDM 自封装、其他 OSAT。\n- 差异：中国最大 OSAT、先进封装/汽车/存储；弱点：毛利率、客户集中。\n- 竞争动态：ASE/Amkor 规模领先；TFME 靠 AMD；中国 OSAT 扩产。\n- 份额：中国 OSAT 第一、全球第三（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：毛利率、客户集中、capex、周期。\n- 技术：2.5D/3D、HBM、汽车。\n- 法律/监管：出口管制、A 股披露。\n- 治理：大基金/国资、管理层。\n- 争议：增收不增利（2025 净利 -2.75%）（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：客户名单、先进封装收入、毛利率均未入库。建议跟踪：① 毛利率；② 先进封装/汽车订单；③ capex；④ 与 TFME 的份额；⑤ 海外厂。\n\n## 信源与口径\n\n- 2025 年报：https://pdf.dfcfw.com/pdf/H2_AN202604091821102768_1.pdf\n- 业绩新闻：https://www.prnasia.com/story/528551-1.shtml\n- 2026 Q3：https://www.tmtpost.com/7984929.html\n- 员工/市值：https://q.stock.sohu.com/cn/600584/index.shtml\n- 口径：FY2025 为年报；市值为股价×股本推算；◐ 表示待核。' },
      { id: 'tfme', name: '通富微电', def: 'AMD 核心封测伙伴：2025 净利 12.2 亿，2.5D 先进封装放量。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 1997 / 南通 | 官网 |\n| 上市地 / 代码 | 深交所 002156 | 2007 IPO |\n| 最新财年营收 | FY2025 ¥279.21 亿（+16.92%） | 2025 年报 |\n| 盈利 | 归母净利 ¥12.19 亿（+79.86%） | 2025 年报 |\n| 现金流 | 待核 | ◐ |\n| 客户 | AMD 为核心；未披露其他 | 年报/媒体 |\n| 员工 | 25,446 人 | 2025 年报 |\n| 市值 / 估值 | 约 ¥600 亿（2026-11） | 股价×股本推算 |\n| 主要股东 | 南通国资/机构；AMD 历史持股待核 | ◐ |\n| 数据截至 | FY2025；2026 Q3 | — |\n\n## 定位与沿革\n\nAMD 核心封测伙伴：为 AMD 提供 CPU/GPU 封装测试与 2.5D 先进封装；2025 年营收 ¥279.21 亿（+16.92%）、归母净利 ¥12.19 亿（+79.86%），2026 年利润爆发。\n\n- 1997 年成立，总部南通；2007 年深交所上市（002156）；中国封测龙头之一。\n- 业务：封装/测试、2.5D/3D 先进封装、CPU/GPU 封测、存储封测、汽车电子。\n- FY2025 营收 ¥279.21 亿（+16.92%）、归母净利 ¥12.19 亿（+79.86%）；约 98% 收入来自集成电路封装测试。\n- 2026 H1 营收 ¥160.41 亿（+23.03%）、归母净利 ¥17.17 亿（+316.77%）；Q2 营收 ¥85.59 亿、净利 ¥13.88 亿（+346.86%）。\n- 2026 Q3 营收 ¥88.44 亿（+24.95%）、净利 ¥13.43 亿（+199.54%）。\n- AMD 是核心客户（其数据中心收入翻倍，EPYC/Instinct 驱动）；2.5D 平台量产。\n- 员工 25,446 人；市值约 ¥600 亿（2026-11）；2026 年 44 亿元定增。\n\n## 创始人与管理层\n\n- **管理层**：董事长/CEO/CFO 名单待采集；南通国资背景。\n- 创始人：1997 年南通富士通沿革；具体待核。\n- 董事会：南通国资 + 机构；具体席位待核。\n- 关键人事变动：2025–2026 年先进封装/存储团队扩张。\n\n## 商业模式\n\n- **收入结构**：封装/测试（CPU/GPU、存储、汽车）+ 2.5D 先进封装。\n- **销售动作**：大客户直销（AMD 为核心）；交钥匙/产能预订。\n- **单位经济**：传统封装毛利低；先进封装/AMD 高端产品毛利较高；capex 大。\n- **收入质量**：AMD 依赖度高；AI/HPC 驱动；客户集中。\n- **定价趋势**：先进封装按项目/产能；传统按颗；测试按小时。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| CPU/GPU 封测 | AMD 处理器封装测试 | 按项目/颗 | 主力 |\n| 2.5D 先进封装 | Chiplet/2.5D | 按项目/产能 | 增长 |\n| 存储封测 | DRAM/NAND | 按颗 | 增长 |\n| 汽车电子 | 车规封装 | 按项目 | 增长 |\n| 传统封装 | BGA/QFN | 按颗 | 主力 |\n\n- 包装：先进封装 + 测试 + 存储/汽车；AMD 方案。\n- 路线图：2.5D、存储、汽车、44 亿定增扩产。\n\n## 技术栈与壁垒\n\n- **架构**：封装/测试工艺 + 2.5D 先进封装；AMD 联合开发。\n- **AI 路线**：AMD GPU/CPU 封测、2.5D Chiplet；AI/HPC。\n- **壁垒**：AMD 关系、2.5D 工艺、客户认证、成本。\n- **依赖与债务**：AMD 集中、capex、毛利率、周期。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| AMD | CPU/GPU 封测、2.5D | 未披露具体数字 | 年报/媒体 |\n| 存储客户 | DRAM/NAND 封测 | 未披露具体数字 | 官网 |\n| 汽车客户 | 车规封装 | 未披露具体数字 | 官网 |\n\n- 客户结构：AMD 为核心，存储/汽车/其他；客户集中。\n- 集中度：AMD 占比高（◐ 具体待核）。\n- 续约/流失：AMD 合作长期；先进封装粘性。\n\n## 商业进展\n\n- FY2025 营收 ¥279.21 亿（+16.92%）、净利 ¥12.19 亿（+79.86%）。\n- 2026 H1 营收 ¥160.41 亿（+23.03%）、净利 ¥17.17 亿（+316.77%）。\n- 2026 Q3 营收 ¥88.44 亿（+24.95%）、净利 ¥13.43 亿（+199.54%）。\n- AMD 数据中心收入翻倍；2.5D 平台量产；44 亿元定增。\n- 竞争：ASE、Amkor、JCET、华天科技。\n\n## 经营业绩\n\n| 指标 | 2023 | 2024 | 2025 | 2026 Q3 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | ¥222.7 亿 | ¥238.8 亿 | ¥279.21 亿 | ¥88.44 亿 | +16.92% |\n| 增速 | +? | +7% | +16.92% | +24.95% | 加速 |\n| 毛利率 | 约 11% | 约 12% | 待核 | 待核 | ◐ |\n| 营业利润 | 待核 | 待核 | 待核 | 待核 | — |\n| 归母净利 | ¥1.7 亿 | ¥6.8 亿 | ¥12.19 亿 | ¥13.43 亿 | +79.86%/+199.54% |\n\n- 运营指标：员工 25,446；2026 年 44 亿定增；2.5D 量产。\n- 指引：2026 年营收/利润待查；AMD 需求。\n- 市场预期：AMD AI GPU/CPU 封测、2.5D。\n\n## 股权、融资与股票\n\n- 上市：深交所 002156；2007 IPO。\n- 行情（2026-11）：股价约 ¥39.68；市值约 ¥600 亿；总股本约 15.18 亿股；52 周 ¥34.65–84.70。\n- 估值：PE 约 49x（按 2025 净利）；PS 约 2.1x。\n- 股东：南通国资/机构；AMD 历史持股待核。\n- 资本动作：2026 年 44 亿元定增（存储/先进封装/补流）。\n- 风险提示：AMD 集中、capex、估值。\n\n## 团队与人员\n\n- 员工 25,446 人（2025 年末）；制造为主。\n- 南通总部；全球工厂（中国/马来西亚）。\n- 招聘：2026 年先进封装/存储扩产；具体待采集。\n- 薪酬/股权激励：A 股上市，有股权激励；流失率未披露。\n- 组织：管理层名单待补；南通国资。\n\n## 竞争格局\n\n- 直接竞品：ASE、Amkor、JCET、华天科技、TSMC（CoWoS）。\n- 替代方案：IDM 自封装、其他 OSAT。\n- 差异：AMD 核心伙伴、2.5D、成本；弱点：AMD 集中、毛利率。\n- 竞争动态：AMD 份额提升带动；JCET/华天竞争；台积电 CoWoS。\n- 份额：中国 OSAT 第二/第三（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：AMD 集中、capex、毛利率、周期。\n- 技术：2.5D、Chiplet、存储。\n- 法律/监管：出口管制、A 股披露。\n- 治理：南通国资、管理层。\n- 争议：AMD 依赖度与定增摊薄（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：AMD 收入占比、2.5D 收入、毛利率均未入库。建议跟踪：① AMD 订单；② 2.5D 量产；③ 44 亿定增；④ 毛利率；⑤ 与 JCET 的份额。\n\n## 信源与口径\n\n- 2025 年报：https://static.cninfo.com.cn/finalpage/2026-04-17/1225112762.PDF\n- 2026 半年报：https://money.finance.sina.com.cn/corp/view/vCB_AllBulletinDetail.php?stockid=002156&id=12568723\n- 2026 Q3：https://money.finance.sina.com.cn/corp/view/vCB_AllBulletinDetail.php?stockid=002156&id=12568725\n- 行情/员工：https://q.stock.sohu.com/cn/002156/index.shtml\n- 口径：FY2025 为年报；市值为股价×股本推算；◐ 表示待核。' },
      { id: 'synopsys', name: 'Synopsys', def: 'EDA 龙头 + Ansys 仿真：$350 亿并购后覆盖芯片到系统设计。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 1986 / Sunnyvale, CA | 官网 |\n| 上市地 / 代码 | NASDAQ: SNPS | 1992 IPO |\n| 最新财年营收 | FY2025 约 $68 亿（◐）；FY2026 约 $95 亿（含 Ansys） | 财报/指引 |\n| 盈利 | Q3 FY2026 non-GAAP 营业利润率 41.6% | 2026-08 发布 |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露；芯片设计公司/系统厂商 | ◐ |\n| 员工 | 约 24,000 人（含 Ansys） | Wikipedia |\n| 市值 / 估值 | 约 $895 亿（2026-11-02） | Trefis |\n| 主要股东 | 机构为主 | ◐ |\n| 数据截至 | FY2025；Q3 FY2026 | — |\n\n## 定位与沿革\n\nEDA 龙头 + Ansys 仿真：以数字/模拟设计、验证、IP 与物理实现工具覆盖芯片设计全流程；2025-07 完成 $350 亿收购 Ansys，把能力扩展到系统/仿真，TAM 约 $310 亿。\n\n- 1986 年成立，总部 Sunnyvale；1992 年上市（SNPS）；Aart de Geus 创办并长期任 CEO。\n- 产品：EDA（Design Compiler、VCS、PrimeTime、Fusion Compiler）、IP、硬件仿真、Ansys 仿真（结构/流体/电磁）。\n- FY2025 营收约 $68 亿（◐）；Q3 FY2026 营收 $24.77 亿（+42%）、non-GAAP 营业利润率 41.6%、EPS $3.91。\n- FY2026 指引包含约 $29.8 亿 Ansys 收入；Q2 FY2026 Ansys 贡献 $6.524 亿。\n- 2025-07-17 完成 Ansys 收购（$350 亿，现金+股票）；合并后员工约 24,000 人。\n- 市值约 $895 亿（2026-11-02）；Q1 FY2026 backlog $113 亿。\n\n## 创始人与管理层\n\n- **Aart de Geus（创始人/前 CEO）**：1986 年创办 Synopsys；长期任 CEO，现任执行董事长（◐）。\n- **Sassine Ghazi（总裁 & CEO）**：2024 年起任 CEO；主导 Ansys 整合/AI EDA。\n- **CFO/CTO**：名单待补。\n- 董事会：机构 + 管理层；具体席位待核。\n- 关键人事变动：2024 年 CEO 交接；2025 年 Ansys 整合。\n\n## 商业模式\n\n- **收入结构**：EDA 软件授权/订阅 + IP 授权 + 硬件仿真 + Ansys 仿真/服务。\n- **销售动作**：大客户直销（芯片设计公司/系统厂商）；多年订阅/EDA 合同。\n- **单位经济**：软件毛利高（约 80%+）；IP 版税；Ansys 订阅。\n- **收入质量**：经常性收入高；客户集中；中国出口管制影响。\n- **定价趋势**：按订阅/席位/IP 版税；Ansys 按订阅。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 数字 EDA | 综合/布局布线/时序 | 订阅 | 主力 |\n| 验证 | 仿真/形式验证/原型 | 订阅 | 主力 |\n| IP | 接口/处理器/存储 IP | 授权+版税 | 主力 |\n| 硬件仿真 | ZeBu/FPGA 原型 | 硬件+订阅 | 增长 |\n| Ansys 仿真 | 结构/流体/电磁 | 订阅 | 增长（2025 并入） |\n\n- 包装：EDA + IP + 仿真；芯片到系统方案。\n- 路线图：AI EDA、Ansys 整合、系统级设计。\n\n## 技术栈与壁垒\n\n- **架构**：EDA 算法/工具链 + IP + 仿真；与代工厂工艺绑定。\n- **AI 路线**：AI 用于设计优化/验证/良率；Synopsys.ai。\n- **壁垒**：EDA 工具链、IP 组合、代工认证、客户迁移成本。\n- **依赖与债务**：中国出口管制、客户集中、Ansys 整合、估值。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 芯片设计公司 | 数字/模拟 EDA | 未披露具体数字 | 官网 |\n| 系统厂商 | Ansys 仿真 | 未披露具体数字 | 官网 |\n| 代工厂 | 工艺认证/PDK | 未披露具体数字 | 媒体 |\n\n- 客户结构：fabless/IDM/系统厂商；全球。\n- 集中度：前几大客户占比高（◐）。\n- 续约/流失：EDA 迁移成本高；订阅粘性强。\n\n## 商业进展\n\n- 2025-07 完成 Ansys 收购（$350 亿）；TAM 约 $310 亿。\n- Q3 FY2026 营收 $24.77 亿（+42%）、non-GAAP 营业利润率 41.6%。\n- FY2026 指引含 Ansys 约 $29.8 亿；Q2 FY2026 Ansys 贡献 $6.524 亿。\n- AI EDA/系统级设计是增长主线；中国出口管制影响。\n- 竞争：Cadence、Siemens EDA。\n\n## 经营业绩\n\n| 指标 | FY2024 | FY2025 | FY2026 指引 | Q3 FY2026 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | $61.3 亿 | 约 $68 亿 | 约 $95 亿 | $24.77 亿 | +42% |\n| 增速 | +15% | +11% | +40% | +42% | Ansys 并表 |\n| 毛利率 | 约 80% | 约 80% | 待核 | 待核 | ◐ |\n| 营业利润率 | 约 38% | 待核 | 待核 | 41.6% | non-GAAP |\n| 净利 | 待核 | 待核 | 待核 | 待核 | ◐ |\n\n- 运营指标：backlog $113 亿（Q1 FY2026）；Ansys 收入 $29.8 亿（FY2026 指引）。\n- 指引：FY2026 约 $95 亿（含 Ansys）；双位数增长。\n- 市场预期：Ansys 整合/AI EDA。\n\n## 股权、融资与股票\n\n- 上市：NASDAQ SNPS；1992 IPO。\n- 行情（2026-11-02）：股价约 $467；市值约 $895 亿；52 周待核（◐）。\n- 估值：PS 约 9.4x（按 FY2026 指引）；PE 待核。\n- 股东：机构为主；具体持股待核。\n- 资本动作：Ansys 收购（现金+股票）；回购/分红待查。\n- 风险提示：中国出口管制、Ansys 整合、估值。\n\n## 团队与人员\n\n- 员工约 24,000 人（含 Ansys）；研发为主。\n- Sunnyvale 总部；全球。\n- 招聘：2026 年 AI EDA/Ansys 整合；具体待采集。\n- 薪酬/股权激励：RSU；流失率未披露。\n- 组织：Sassine Ghazi（CEO）、Aart de Geus（执行董事长）。\n\n## 竞争格局\n\n- 直接竞品：Cadence、Siemens EDA、Ansys（已并入）。\n- 替代方案：自研 EDA、开源 EDA（早期）。\n- 差异：EDA 全流程 + IP + Ansys 仿真；弱点：中国管制、整合、估值。\n- 竞争动态：Cadence 数字/验证强势；Siemens EDA PCB/DFT；AI EDA 竞赛。\n- 份额：EDA 约 31%，第一（2024，SemiWiki 口径）。\n\n## 风险与争议\n\n- 经营：中国出口管制、客户集中、Ansys 整合、估值。\n- 技术：AI EDA、系统级设计、工具链。\n- 法律/监管：美国出口管制、反垄断。\n- 治理：CEO 交接、Ansys 整合。\n- 争议：$350 亿并购的协同与估值（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：中国收入占比、Ansys 协同、AI EDA 收入均未入库。建议跟踪：① Ansys 整合；② FY2026 指引；③ 中国管制；④ AI EDA；⑤ 与 Cadence 的份额。\n\n## 信源与口径\n\n- Q3 FY2026：https://investor.synopsys.com/news/news-details/2026/Synopsys-Posts-Financial-Results-for-Third-Quarter-Fiscal-Year-2026/default.aspx\n- Ansys 收购：https://investors.ansys.com/news-releases/news-release-details/synopsys-completes-acquisition-ansys/\n- 市值/员工：https://www.trefis.com/data/companies/SNPS ；https://en.wikipedia.org/wiki/Synopsys\n- 口径：FY2025 为推算；FY2026 为指引；◐ 表示待核。' },
      { id: 'cadence', name: 'Cadence', def: 'EDA 第二极：FY2025 营收 $53 亿，仿真/验证与 IP 并进。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 1988 / San Jose, CA | 官网 |\n| 上市地 / 代码 | NASDAQ: CDNS | 1987/1988 上市 |\n| 最新财年营收 | FY2025 $53 亿（+14%） | 2026-02-17 发布 |\n| 盈利 | 待核 | ◐ |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露；芯片设计公司/系统厂商 | ◐ |\n| 员工 | 约 13,800 人（推算） | ◐ |\n| 市值 / 估值 | 约 $812 亿（2026-09） | Yahoo/Proxy |\n| 主要股东 | 机构为主 | ◐ |\n| 数据截至 | FY2025；Q3 2026 | — |\n\n## 定位与沿革\n\nEDA 第二极：以数字/模拟设计、验证、仿真（Palladium）、IP 与 PCB/系统设计为核心；FY2025 营收 $53 亿（+14%），Q3 2026 营收 $16.33 亿（+22%），FY2026 指引 $63.87–64.17 亿。\n\n- 1988 年成立，总部 San Jose；纳斯达克上市（CDNS）；Anirudh Devgan 任 CEO。\n- 产品：数字 EDA（Innovus/Genus）、模拟（Virtuoso）、验证（Palladium/Xcelium）、IP、PCB（Allegro）、系统分析。\n- FY2025 营收 $53 亿（+14%）；Q3 2026 营收 $16.33 亿（+22%）、Q2 $15.84 亿。\n- FY2026 营收指引 $63.87–64.17 亿；AI/先进制程/系统设计驱动。\n- 市值约 $812 亿（2026-09）；员工约 13,800 人（按人均营收推算）。\n- CEO Anirudh Devgan 2025 年薪酬 $5,670 万（媒体，含股权）。\n\n## 创始人与管理层\n\n- **Anirudh Devgan（总裁 & CEO）**：2017 年任 CEO（◐ 任期待核）；主导 AI/系统设计。\n- **CFO/CTO**：名单待补。\n- 创始人：1988 年成立；具体创始人待核。\n- 董事会：机构 + 管理层；具体席位待核。\n- 关键人事变动：2025–2026 年 AI/系统设计团队扩张。\n\n## 商业模式\n\n- **收入结构**：EDA 软件授权/订阅 + 硬件仿真 + IP + 服务。\n- **销售动作**：大客户直销（芯片设计/系统厂商）；多年订阅。\n- **单位经济**：软件毛利高（约 85%+）；硬件仿真毛利较低；IP 版税。\n- **收入质量**：经常性收入高；客户集中；中国出口管制影响。\n- **定价趋势**：按订阅/席位/IP 版税；硬件仿真按系统。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 数字 EDA | 综合/布局布线/时序 | 订阅 | 主力 |\n| 模拟 EDA | Virtuoso 设计 | 订阅 | 主力 |\n| 验证/仿真 | Palladium/Xcelium | 硬件+订阅 | 主力 |\n| IP | 接口/处理器/存储 | 授权+版税 | 增长 |\n| PCB/系统 | Allegro/系统分析 | 订阅 | 增长 |\n\n- 包装：EDA + 验证 + IP + 系统；芯片到系统方案。\n- 路线图：AI EDA、系统分析、3D-IC。\n\n## 技术栈与壁垒\n\n- **架构**：EDA 算法/工具链 + 硬件仿真 + IP；与代工厂工艺绑定。\n- **AI 路线**：AI 用于设计优化/验证；Cadence.AI。\n- **壁垒**：EDA 工具链、硬件仿真、IP、客户迁移成本。\n- **依赖与债务**：中国出口管制、客户集中、估值、竞争。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 芯片设计公司 | 数字/模拟 EDA | 未披露具体数字 | 官网 |\n| AI/HPC 客户 | 验证/仿真 | 未披露具体数字 | 媒体 |\n| 系统厂商 | PCB/系统分析 | 未披露具体数字 | 官网 |\n\n- 客户结构：fabless/IDM/系统厂商；全球。\n- 集中度：前几大客户占比高（◐）。\n- 续约/流失：EDA 迁移成本高；订阅粘性强。\n\n## 商业进展\n\n- FY2025 营收 $53 亿（+14%）；Q3 2026 营收 $16.33 亿（+22%）。\n- FY2026 营收指引 $63.87–64.17 亿；AI/先进制程驱动。\n- 硬件仿真/验证需求强劲；IP 增长。\n- 中国出口管制影响；公司调整区域结构。\n- 竞争：Synopsys、Siemens EDA。\n\n## 经营业绩\n\n| 指标 | FY2023 | FY2024 | FY2025 | Q3 2026 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | $40.9 亿 | $46.4 亿 | $53 亿 | $16.33 亿 | +14%/+22% |\n| 增速 | +15% | +13% | +14% | +22% | 加速 |\n| 毛利率 | 约 85% | 约 85% | 约 85% | 待核 | ◐ |\n| 营业利润率 | 约 30% | 约 30% | 待核 | 待核 | ◐ |\n| 净利 | 待核 | 待核 | 待核 | 待核 | ◐ |\n\n- 运营指标：FY2026 指引 $63.87–64.17 亿；人均营收约 $38.4 万。\n- 指引：FY2026 营收 $63.87–64.17 亿。\n- 市场预期：AI EDA/系统设计。\n\n## 股权、融资与股票\n\n- 上市：NASDAQ CDNS；1987/1988 上市。\n- 行情（2026-09）：市值约 $812 亿；股价/52 周待刷新（◐）。\n- 估值：PS 约 12.7x（按 FY2026 指引）；PE 待核。\n- 股东：机构为主；具体持股待核。\n- 资本动作：回购/分红；并购待查。\n- 风险提示：中国出口管制、估值、客户集中。\n\n## 团队与人员\n\n- 员工约 13,800 人（推算）；研发为主。\n- San Jose 总部；全球。\n- 招聘：2026 年 AI/系统设计岗位扩张；具体待采集。\n- 薪酬/股权激励：RSU；CEO 薪酬 $5,670 万（2025，媒体）。\n- 组织：Anirudh Devgan（CEO）；业务线负责人待补。\n\n## 竞争格局\n\n- 直接竞品：Synopsys、Siemens EDA。\n- 替代方案：自研 EDA、开源 EDA（早期）。\n- 差异：数字/模拟/验证/硬件仿真/IP/系统；弱点：规模小于 Synopsys、中国管制。\n- 竞争动态：Synopsys + Ansys 系统级扩张；Siemens EDA PCB/DFT；AI EDA 竞赛。\n- 份额：EDA 约 30%，第二（2024，SemiWiki 口径）。\n\n## 风险与争议\n\n- 经营：中国出口管制、客户集中、估值。\n- 技术：AI EDA、3D-IC、系统分析。\n- 法律/监管：美国出口管制、反垄断。\n- 治理：CEO 薪酬/股权激励争议（媒体）。\n- 争议：高估值与增长匹配（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：中国收入占比、硬件仿真收入、AI EDA 收入均未入库。建议跟踪：① FY2026 指引；② AI EDA；③ 中国管制；④ 硬件仿真；⑤ 与 Synopsys 的份额。\n\n## 信源与口径\n\n- Q3 2026：https://investor.cadence.com/news/news-details/2026/Cadence-Reports-Third-Quarter-2026-Financial-Results/\n- FY2025：https://www.sec.gov/Archives/edgar/data/813672/000081367226000013/cdns02172026ex9901.htm\n- 市值/员工：https://finance.yahoo.com/quote/CDNS/ ；https://bullfincher.io/companies/cadence-design-systems/overview\n- 口径：FY2025 为公司披露；员工数为推算；◐ 表示待核。' },
      { id: 'siemenseda', name: 'Siemens EDA', def: 'EDA 第三极：Calibre 物理验证 + PCB 强势，份额约 13%。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 1981（Mentor Graphics）/ Wilsonville, OR | Siemens 业务 |\n| 上市地 / 代码 | 不独立上市；母公司 Siemens AG（SIE.DE） | 并表 |\n| 最新财年营收 | 未单独披露；约 $20–25 亿（◐） | 行业估算 |\n| 盈利 | 并表，未单独披露 | — |\n| 现金流 | 并表 | — |\n| 客户 | 未披露；芯片设计/PCB/系统厂商 | ◐ |\n| 员工 | 未单独披露（约 15,000，◐） | — |\n| 市值 / 估值 | 不适用；Siemens 市值待核 | — |\n| 主要股东 | Siemens AG 100% | 并表 |\n| 数据截至 | FY2025 | — |\n\n## 定位与沿革\n\nEDA 第三极：以 Calibre 物理验证、Questa 仿真、Xpedition PCB 与 Tessent DFT 为核心，全球 EDA 份额约 13%；在 PCB/系统级设计上强势。\n\n- 1981 年 Mentor Graphics 成立；2017 年被 Siemens 以约 $45 亿收购，更名 Siemens EDA。\n- 产品：Calibre（物理验证/OPC）、Questa（仿真）、Xpedition（PCB）、Tessent（DFT）、Aprisa（布局布线）。\n- 隶属于 Siemens Digital Industries Software；不单独披露收入/利润。\n- 2025 年收入增速约 3%（LinkedIn 分析），低于 Synopsys/Cadence；PCB/系统设计是差异化。\n- 全球 EDA 份额约 13%（2024，SemiWiki 口径），第三；PCB 份额在北美/欧洲/亚太领先。\n- Siemens 整体员工约 31.8 万；Siemens EDA 员工数未单独披露（约 15,000，◐）。\n\n## 创始人与管理层\n\n- **Siemens EDA 管理层**：CEO/CTO 名单待采集；隶属 Siemens Digital Industries Software。\n- **Siemens 管理层**：CEO Roland Busch、CFO Ralf Thomas（◐ 任期待核）。\n- 创始人：Mentor Graphics 1981 年创立；具体创始人待核。\n- 董事会：Siemens AG 董事会；Siemens EDA 无独立董事会。\n- 关键人事变动：2017 年收购后整合；2025–2026 年 AI EDA 团队。\n\n## 商业模式\n\n- **收入结构**：EDA 软件授权/订阅 + 硬件仿真 + 服务；并表 Siemens。\n- **销售动作**：大客户直销（芯片设计/PCB/系统）；Siemens 工业软件捆绑。\n- **单位经济**：软件毛利高；并表不单独披露。\n- **收入质量**：经常性收入；客户集中；增长慢于头部。\n- **定价趋势**：按订阅/席位；Siemens 工业软件捆绑。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| Calibre | 物理验证/OPC | 订阅 | 主力 |\n| Questa | 仿真/验证 | 订阅 | 主力 |\n| Xpedition | PCB 设计 | 订阅 | 主力 |\n| Tessent | DFT/测试 | 订阅 | 增长 |\n| Aprisa | 布局布线 | 订阅 | 增长 |\n\n- 包装：EDA + PCB + 工业软件；Siemens 捆绑。\n- 路线图：AI EDA、PCB/系统、3D-IC。\n\n## 技术栈与壁垒\n\n- **架构**：EDA 工具链 + PCB/系统设计；与 Siemens 工业软件协同。\n- **AI 路线**：AI 用于验证/PCB/良率；Siemens 工业 AI。\n- **壁垒**：Calibre 物理验证、PCB 份额、Siemens 渠道。\n- **依赖与债务**：份额第三、增长慢、中国管制、整合。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 芯片设计公司 | Calibre/Questa | 未披露具体数字 | 官网 |\n| PCB/系统厂商 | Xpedition | 未披露具体数字 | 官网 |\n| 汽车/工业 | 系统设计 | 未披露具体数字 | 官网 |\n\n- 客户结构：芯片设计、PCB/系统、汽车/工业；全球。\n- 集中度：未披露；Siemens 工业客户协同。\n- 续约/流失：EDA 迁移成本高；订阅粘性。\n\n## 商业进展\n\n- 2025 年收入增速约 3%，低于 Synopsys/Cadence；PCB/系统设计是重点。\n- Siemens 工业软件/AI 投资；Calibre/Questa 持续迭代。\n- 中国出口管制影响；Siemens 全球合规。\n- 竞争：Synopsys、Cadence、Ansys（已并入 Synopsys）。\n- 2026 年 AI EDA/PCB 投资待采集。\n\n## 经营业绩\n\n| 指标 | FY2023 | FY2024 | FY2025 | 说明 |\n|---|---|---|---|---|\n| 营收 | 未单独披露 | 未单独披露 | 未单独披露 | 并表 |\n| 增速 | 未披露 | 未披露 | 约 +3% | LinkedIn 分析 |\n| 毛利率 | 未披露 | 未披露 | 未披露 | — |\n| 营业利润 | 未披露 | 未披露 | 未披露 | — |\n| 员工 | 未披露 | 未披露 | 约 15,000 | ◐ |\n\n- 运营指标：EDA 份额约 13%；PCB 份额领先。\n- 指引：并表 Siemens；不单独指引。\n- 市场预期：AI EDA/PCB 增长。\n\n## 股权、融资与股票\n\n- **不适用（业务单元）**：Siemens EDA 不独立上市；母公司 Siemens AG（SIE.DE）。\n- 行情：Siemens 市值/股价待核（◐）。\n- 估值：EDA 业务无独立估值；Siemens 整体 PE 待核。\n- 股东：Siemens AG 100%。\n- 资本动作：Siemens 整体分红/回购；EDA 投资。\n- 风险提示：份额第三、增长慢、中国管制。\n\n## 团队与人员\n\n- 员工数未单独披露（约 15,000，◐）；研发/销售。\n- Wilsonville, OR / 全球；Siemens 工业软件体系。\n- 招聘：2026 年 AI EDA/PCB 岗位；具体待采集。\n- 薪酬/股权激励：Siemens 体系；流失率未披露。\n- 组织：Siemens Digital Industries Software；EDA 负责人待补。\n\n## 竞争格局\n\n- 直接竞品：Synopsys、Cadence、Ansys（已并入 Synopsys）。\n- 替代方案：自研 EDA、开源 EDA（早期）。\n- 差异：Calibre 物理验证、PCB/系统、Siemens 渠道；弱点：份额第三、增长慢。\n- 竞争动态：Synopsys + Ansys 系统级；Cadence 数字/验证；Siemens PCB/DFT。\n- 份额：EDA 约 13%，第三（2024，SemiWiki 口径）。\n\n## 风险与争议\n\n- 经营：份额第三、增长慢、客户集中。\n- 技术：AI EDA、3D-IC、PCB。\n- 法律/监管：出口管制、Siemens 合规。\n- 治理：Siemens 集团控制；整合。\n- 争议：EDA 增长放缓与投资不足（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：EDA 单独收入、员工数、AI EDA 进展均未入库。建议跟踪：① 收入增速；② Calibre/Questa 份额；③ PCB/系统；④ 中国管制；⑤ 与 Synopsys/Cadence 的差距。\n\n## 信源与口径\n\n- Siemens 2025 年报：https://assets.new.siemens.com/siemens/assets/api/uuid:6f0a40f1-9119-4007-b012-5b973b42574d/Annual-Financial-Report-FY2025.pdf\n- EDA 份额：https://semiwiki.com/wikis/company-wikis/mentor-graphics-wiki/\n- 增长分析：https://www.linkedin.com/posts/kit-yu-27753534_electronic-design-automation-eda-used-activity-7424124281011363841-UBYA\n- 口径：收入/员工未单独披露；◐ 表示待核。' },
      { id: 'samsungelectronics', name: 'Samsung Electronics', def: '存储 + 代工 + 封装一体：HBM4 与先进封装决定 AI 存储份额。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 1969 / 韩国水原 | 官网 |\n| 上市地 / 代码 | KRX: 005930 | 1975 上市 |\n| 最新财年营收 | FY2025 KRW 333.6 万亿 | 2026-01-29 发布 |\n| 盈利 | FY2025 营业利润 KRW 43.6 万亿；净利待核 | 2025 财报 |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露；云厂商/手机/汽车 | ◐ |\n| 员工 | 约 27 万（◐） | — |\n| 市值 / 估值 | 约 KRW 1.3–1.4 千万亿（约 $1 万亿，2026-11） | WSJ/Leonteq |\n| 主要股东 | 李在镕/国民年金/机构 | ◐ |\n| 数据截至 | FY2025；2026 Q3 | — |\n\n## 定位与沿革\n\n存储 + 代工 + 封装一体的综合半导体巨头：DRAM/HBM、NAND、Foundry、先进封装（I-Cube/X-Cube）与终端（手机/显示/Harman）协同；FY2025 营收 KRW 333.6 万亿、营业利润 KRW 43.6 万亿。\n\n- 1969 年成立，总部韩国水原；KRX 005930；李在镕任会长（◐ 实际角色待核）。\n- 业务：DS（存储/代工/系统 LSI）、MX（手机）、SDC（显示）、Harman。\n- FY2025 营收 KRW 333.6 万亿、营业利润 KRW 43.6 万亿；Q4 2025 营收 KRW 93.8 万亿（历史最高单季）。\n- HBM4 是 AI 存储关键：公司称 HBM4 在速度/能效上设新基准，计划按时出货。\n- 先进封装：I-Cube/X-Cube、2.5D/3D、HBM4 封装；与代工/存储协同。\n- 2026 年 Q1 营业利润超过 FY2025 全年（媒体）；Q3 2026 营收/营业利润媒体口径 KRW 195.3 万亿/107.4 万亿（◐ 待核）。\n- 市值约 $1 万亿（2026-11，◐）；员工约 27 万。\n\n## 创始人与管理层\n\n- **李秉喆（创始人）**：1938 年三星商会、1969 年三星电子。\n- **李在镕（会长）**：三星集团实际控制人；2014 年起实际掌舵（◐）。\n- **CEO/业务负责人**：DS/MX 部门负责人名单待采集。\n- 董事会：三星电子董事会；具体席位待核。\n- 关键人事变动：2025–2026 年 HBM/代工负责人调整待采集。\n\n## 商业模式\n\n- **收入结构**：存储（DRAM/NAND/HBM）、代工、系统 LSI、手机、显示、Harman。\n- **销售动作**：大客户直销（云厂商/手机/汽车）+ 渠道；存储周期性强。\n- **单位经济**：存储毛利随价格周期波动；代工/封装投入大；终端稳定。\n- **收入质量**：存储占比高；HBM/AI 存储是增量；客户集中。\n- **定价趋势**：HBM 按堆栈/合约；DRAM/NAND 现货/合约；代工按 wafer。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| DRAM/HBM | AI 存储/HBM4 | 按堆栈/合约 | 主力 |\n| NAND | 存储/SSD | 按颗/合约 | 主力 |\n| Foundry | 2nm/3nm 代工 | 按 wafer | 增长 |\n| 先进封装 | I-Cube/X-Cube/2.5D | 按项目 | 增长 |\n| 手机/显示 | Galaxy/OLED | 按台/面板 | 主力 |\n| Harman | 汽车电子/音响 | 按项目 | 增长 |\n\n- 包装：存储 + 代工 + 封装 + 终端；AI/HBM 方案。\n- 路线图：HBM4、2nm 代工、先进封装、AI 终端。\n\n## 技术栈与壁垒\n\n- **架构**：DRAM/NAND 制程 + 代工 + 先进封装；垂直整合。\n- **AI 路线**：HBM4、AI 存储、代工 AI 芯片、封装。\n- **壁垒**：存储规模/制程、垂直整合、客户关系、资本开支。\n- **依赖与债务**：存储周期、HBM 竞争、代工良率、地缘政治。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 云厂商/AI 芯片公司 | HBM4/先进封装 | 未披露具体数字 | 媒体 |\n| 手机厂商 | DRAM/NAND/OLED | 未披露具体数字 | 媒体 |\n| 汽车客户 | 存储/芯片 | 未披露具体数字 | 官网 |\n\n- 客户结构：云厂商、手机、汽车、消费；全球。\n- 集中度：前几大客户占比高（◐）。\n- 续约/流失：存储合约；HBM 认证周期长。\n\n## 商业进展\n\n- FY2025 营收 KRW 333.6 万亿、营业利润 KRW 43.6 万亿；Q4 2025 营收 KRW 93.8 万亿。\n- HBM4 按时出货；AI 存储需求强劲。\n- 2026 Q1 营业利润超过 FY2025 全年；Q3 2026 媒体口径营收 KRW 195.3 万亿（◐）。\n- 先进封装/2nm 代工投资；与云厂商/AI 芯片公司合作。\n- 竞争：SK 海力士、Micron（存储）；TSMC（代工）；Apple（终端）。\n\n## 经营业绩\n\n| 指标 | FY2023 | FY2024 | FY2025 | 2026 Q3 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | KRW 258.9 万亿 | KRW 300.9 万亿 | KRW 333.6 万亿 | KRW 195.3 万亿（◐） | +10.9% |\n| 增速 | -14% | +16% | +10.9% | 待核 | 复苏 |\n| 毛利率 | 待核 | 待核 | 待核 | 待核 | — |\n| 营业利润 | KRW 6.6 万亿 | KRW 32.7 万亿 | KRW 43.6 万亿 | KRW 107.4 万亿（◐） | +33% |\n| 净利 | 待核 | 待核 | 待核 | 待核 | ◐ |\n\n- 运营指标：HBM4 出货；先进封装产能；员工约 27 万。\n- 指引：2026 年 HBM/AI 存储增长；具体待核。\n- 市场预期：HBM4 份额、存储周期。\n\n## 股权、融资与股票\n\n- 上市：KRX 005930；1975 年上市。\n- 行情（2026-11-02）：股价约 KRW 229,000；市值约 KRW 1.3–1.4 千万亿（约 $1 万亿）；52 周 KRW 94,500–374,500。\n- 估值：PE 待核；存储周期股。\n- 股东：李在镕/国民年金/机构；具体持股待核。\n- 资本动作：分红/回购（2026 年最大股东回报）；capex。\n- 风险提示：存储周期、HBM 竞争、代工良率。\n\n## 团队与人员\n\n- 员工约 27 万（◐）；研发/制造/全球。\n- 水原总部；韩国/全球工厂。\n- 招聘：2026 年 HBM/代工/封装岗位；具体待采集。\n- 薪酬/股权激励：三星体系；流失率未披露。\n- 组织：李在镕（会长）；DS/MX 部门负责人待补。\n\n## 竞争格局\n\n- 存储：SK 海力士、Micron、长江存储/长鑫存储（中国）。\n- 代工：TSMC、Intel Foundry、SMIC。\n- 封装：TSMC（CoWoS）、日月光、Amkor。\n- 终端：Apple、中国手机厂商。\n- 差异：垂直整合/存储规模/HBM4；弱点：代工良率、HBM 竞争、治理。\n\n## 风险与争议\n\n- 经营：存储周期、HBM 竞争、代工良率、资本开支。\n- 技术：HBM4、2nm、先进封装。\n- 法律/监管：出口管制、反垄断、治理。\n- 治理：李在镕/三星集团、工会。\n- 争议：HBM 份额与代工亏损（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中；Samsung Foundry 页可作代工侧参照）。缺口：HBM4 份额、代工收入、封装产能均未入库。建议跟踪：① HBM4 出货；② 存储价格；③ 2nm 代工；④ 先进封装；⑤ 与 SK 海力士/TSMC 的份额。\n\n## 信源与口径\n\n- FY2025：https://news.samsung.com/global/samsung-electronics-announces-fourth-quarter-and-fy-2025-results\n- 4Q 2025 演示：https://images.samsung.com/is/content/samsung/assets/global/ir/docs/2025_4Q_conference_eng.pdf\n- 2026 Q3：https://images.samsung.com/is/content/samsung/assets/global/ir/docs/2026_3Q_conference_eng.pdf\n- 市值：https://www.wsj.com/market-data/quotes/KR/XKRX/005930\n- 口径：FY2025 为公司披露；2026 Q3/市值为媒体口径；◐ 表示待核。' },
      { id: 'huatian', name: '华天科技', def: '中国第三大封测：2025 营收 172 亿，扇出/存储封装放量。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2003 / 甘肃天水 | 官网 |\n| 上市地 / 代码 | 深交所 002185 | 2007 IPO |\n| 最新财年营收 | FY2025 ¥172.14 亿（+19.03%） | 2025 年报 |\n| 盈利 | 归母净利 ¥7.11 亿（+15.3%） | 2025 年报 |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露；存储/手机/汽车 | ◐ |\n| 员工 | 33,887 人 | 2025 年报 |\n| 市值 / 估值 | 约 ¥800 亿（2026） | 媒体 |\n| 主要股东 | 天水华天/国资 | ◐ |\n| 数据截至 | FY2025；2026 Q3 | — |\n\n## 定位与沿革\n\n中国第三大封测厂：以扇出型封装、存储封装、晶圆级封装与汽车电子为主；2025 年营收 ¥172.14 亿（+19.03%）、归母净利 ¥7.11 亿（+15.3%），2026 年利润爆发。\n\n- 2003 年成立，总部甘肃天水；2007 年深交所上市（002185）；中国封测龙头之一。\n- 业务：传统封装、扇出型（Fan-Out）、晶圆级封装（WLP）、存储封装、汽车电子、Bumping。\n- FY2025 营收 ¥172.14 亿（+19.03%）、归母净利 ¥7.11 亿（+15.3%）；封装 628.80 亿只（+9.33%）、晶圆级 211.99 万片（+20.16%）。\n- 2026 H1 营收 ¥105.11 亿（+35.09%）、归母净利 ¥8.13 亿（+259.15%）。\n- 2026 Q1–Q3 营收 ¥167.72 亿、归母净利 ¥11 亿（+102.8%）。\n- 员工 33,887 人；市值约 ¥800 亿（2026，媒体口径）。\n\n## 创始人与管理层\n\n- **管理层**：董事长/CEO/CFO 名单待采集；天水华天/国资背景。\n- 创始人：2003 年成立；具体创始人待核。\n- 董事会：天水华天/国资 + 机构；具体席位待核。\n- 关键人事变动：2025–2026 年先进封装/汽车团队扩张。\n\n## 商业模式\n\n- **收入结构**：传统封装 + 先进封装（扇出/WLP/Bumping）+ 存储/汽车封测。\n- **销售动作**：大客户直销（fabless/IDM）；交钥匙/产能预订。\n- **单位经济**：传统封装毛利低；先进封装/汽车毛利较高；capex 大。\n- **收入质量**：客户集中；存储/手机/汽车；先进封装增量。\n- **定价趋势**：先进封装按项目/产能；传统按颗；测试按小时。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 扇出型封装 | Fan-Out/WLP | 按项目/产能 | 增长 |\n| 传统封装 | BGA/QFN/引线键合 | 按颗 | 主力 |\n| 存储封装 | DRAM/NAND | 按颗 | 主力 |\n| 汽车电子 | 车规封装 | 按项目 | 增长 |\n| Bumping/测试 | 凸块/测试 | 按项目 | 增长 |\n\n- 包装：先进封装 + 传统 + 存储/汽车；国产替代方案。\n- 路线图：扇出/WLP、汽车、存储、先进封装扩产。\n\n## 技术栈与壁垒\n\n- **架构**：封装/测试工艺 + 扇出/WLP；中国工厂网络。\n- **AI 路线**：AI 芯片封装（扇出/2.5D）；存储/汽车。\n- **壁垒**：中国封测规模、客户认证、成本、汽车资质。\n- **依赖与债务**：客户集中、capex、毛利率、周期。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 存储客户 | DRAM/NAND 封装 | 未披露具体数字 | 年报 |\n| 手机/消费客户 | 传统/扇出封装 | 未披露具体数字 | 官网 |\n| 汽车客户 | 车规封装 | 未披露具体数字 | 官网 |\n\n- 客户结构：存储、手机/消费、汽车；中国为主。\n- 集中度：前几大客户占比高（◐）。\n- 续约/流失：封装认证周期长；先进封装粘性。\n\n## 商业进展\n\n- FY2025 营收 ¥172.14 亿（+19.03%）、净利 ¥7.11 亿（+15.3%）。\n- 2026 H1 营收 ¥105.11 亿（+35.09%）、净利 ¥8.13 亿（+259.15%）。\n- 2026 Q1–Q3 营收 ¥167.72 亿、净利 ¥11 亿（+102.8%）。\n- 扇出/WLP/存储/汽车扩产；先进封装产能建成投产。\n- 竞争：长电科技、通富微电、日月光、Amkor。\n\n## 经营业绩\n\n| 指标 | 2023 | 2024 | 2025 | 2026 Q1–Q3 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | ¥112.9 亿 | ¥144.62 亿 | ¥172.14 亿 | ¥167.72 亿 | +19.03% |\n| 增速 | -? | +28% | +19.03% | 待核 | 增长 |\n| 毛利率 | 约 14% | 约 15% | 待核 | 待核 | ◐ |\n| 营业利润 | 待核 | 待核 | 待核 | 待核 | — |\n| 归母净利 | ¥2.3 亿 | ¥6.16 亿 | ¥7.11 亿 | ¥11 亿 | +15.3%/+102.8% |\n\n- 运营指标：员工 33,887；封装 628.80 亿只；晶圆级 211.99 万片。\n- 指引：2026 年营收/利润待查；先进封装扩产。\n- 市场预期：扇出/存储/汽车。\n\n## 股权、融资与股票\n\n- 上市：深交所 002185；2007 IPO。\n- 行情（2026）：股价约 ¥14.4–15.0；市值约 ¥800 亿；PE 待核。\n- 估值：PE 约 70x（按 2025 净利，◐）；PS 约 3.7x。\n- 股东：天水华天/国资、机构；具体持股待核。\n- 资本动作：定增/扩产；分红待查。\n- 风险提示：毛利率、客户集中、估值。\n\n## 团队与人员\n\n- 员工 33,887 人；制造为主。\n- 天水总部；西安/昆山/南京等基地。\n- 招聘：2026 年先进封装/汽车扩产；具体待采集。\n- 薪酬/股权激励：A 股上市，有股权激励；流失率未披露。\n- 组织：管理层名单待补；天水华天/国资。\n\n## 竞争格局\n\n- 直接竞品：长电科技、通富微电、日月光、Amkor、华天。\n- 替代方案：IDM 自封装、其他 OSAT。\n- 差异：中国封测规模、扇出/WLP、存储/汽车；弱点：毛利率、客户集中。\n- 竞争动态：长电/通富规模领先；日月光/Amkor 先进封装；中国 OSAT 扩产。\n- 份额：中国 OSAT 第三（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：毛利率、客户集中、capex、周期。\n- 技术：扇出/WLP、2.5D、汽车。\n- 法律/监管：出口管制、A 股披露。\n- 治理：国资/管理层。\n- 争议：低毛利与扩产回报（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：客户名单、先进封装收入、毛利率均未入库。建议跟踪：① 扇出/WLP 收入；② 2026 利润；③ 存储/汽车订单；④ 毛利率；⑤ 与长电/通富的份额。\n\n## 信源与口径\n\n- 2025 年报：https://money.finance.sina.com.cn/corp/view/vCB_AllBulletinDetail.php?stockid=002185&id=12045582\n- 业绩：https://finance.eastmoney.com/a/202603313690183164.html\n- 2026 H1：https://ee.ofweek.com/2026-07/ART-12003-2815-30694473.html\n- 行情：https://q.stock.sohu.com/cn/002185/index.shtml\n- 口径：FY2025 为年报；市值为媒体口径；◐ 表示待核。' },
      { id: 'besi', name: 'Besi', def: '混合键合设备龙头：2026 营收翻倍，HBM/3D 封装关键设备。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 1995 / Duiven, 荷兰 | 官网 |\n| 上市地 / 代码 | Euronext: BESI | 1995 上市 |\n| 最新财年营收 | FY2025 €5.91 亿 | 2026-02-19 发布 |\n| 盈利 | FY2025 净利待核；Q3 2026 €1.072 亿 | ◐ |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露；代工/存储/OSAT | ◐ |\n| 员工 | 1,856 FTE + 108 临时（2025 末） | 2025 年报 |\n| 市值 / 估值 | 约 €140 亿（2026） | 媒体 |\n| 主要股东 | 机构为主 | ◐ |\n| 数据截至 | FY2025；Q3 2026 | — |\n\n## 定位与沿革\n\n混合键合（Hybrid Bonding）设备龙头：以 die attach、热压键合与混合键合设备覆盖先进封装/3D 集成；2026 年营收随 HBM/3D 封装放量翻倍，Q3 2026 营收 €2.834 亿（+113.6%）、净利 €1.072 亿（+323.7%）。\n\n- 1995 年成立，总部荷兰 Duiven；Euronext BESI。\n- 产品：die attach、热压键合（TCB）、混合键合（Hybrid Bonding）、先进封装设备。\n- FY2025 营收 €5.91 亿；Q4 2025 营收 €1.664 亿、净利 €4,280 万。\n- 2026 年 Q2 营收 €2.499 亿、净利 €8,900 万；Q3 营收 €2.834 亿（+113.6%）、净利 €1.072 亿（+323.7%）。\n- 2026 年 YTD 营收 €7.181 亿（+69%）；混合键合/数据中心需求驱动。\n- 2026-06 投资者日：长期营收目标上调至 €17–22 亿（原 €15–19 亿）。\n- 员工 1,856 FTE + 108 临时（2025 末）；市值约 €140 亿（2026）。\n\n## 创始人与管理层\n\n- **管理层**：CEO/CFO 名单待采集；荷兰上市公司治理。\n- 创始人：1995 年成立；具体创始人待核。\n- 董事会：机构 + 管理层；具体席位待核。\n- 关键人事变动：2026 年投资者日/扩产；具体待采集。\n\n## 商业模式\n\n- **收入结构**：die attach/混合键合设备 + 服务/备件；先进封装设备为主。\n- **销售动作**：大客户直销（代工/存储/OSAT）；设备+服务。\n- **单位经济**：设备毛利高（约 60%+）；研发投入高；订单周期。\n- **收入质量**：客户集中；HBM/3D 封装驱动；周期性强。\n- **定价趋势**：混合键合设备溢价；按台/配置；服务按合同。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 混合键合 | 3D 集成/HBM | 按台 | 主力 |\n| 热压键合（TCB） | 先进封装 | 按台 | 主力 |\n| Die Attach | 固晶/贴片 | 按台 | 主力 |\n| 服务/备件 | 维护、升级 | 按合同 | 主力 |\n| 先进封装方案 | 2.5D/3D | 按项目 | 增长 |\n\n- 包装：设备 + 服务 + 工艺方案；HBM/3D 封装。\n- 路线图：混合键合扩产、TCB、3D 集成。\n\n## 技术栈与壁垒\n\n- **架构**：精密运动/键合工艺 + 混合键合；与客户共同开发。\n- **AI 路线**：HBM/3D 封装设备；AI 芯片封装。\n- **壁垒**：混合键合工艺、客户认证、精度/良率、服务网络。\n- **依赖与债务**：客户集中、周期、研发投入、竞争。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 代工/存储客户 | 混合键合/TCB | 未披露具体数字 | 媒体 |\n| OSAT 客户 | 先进封装设备 | 未披露具体数字 | 官网 |\n| HBM 客户 | 3D 集成 | 未披露具体数字 | 媒体 |\n\n- 客户结构：代工、存储、OSAT；全球。\n- 集中度：前几大客户占比高（◐）。\n- 续约/流失：设备生命周期长；服务粘性。\n\n## 商业进展\n\n- FY2025 营收 €5.91 亿；Q4 营收 €1.664 亿、净利 €4,280 万。\n- 2026 Q2 营收 €2.499 亿、净利 €8,900 万；Q3 营收 €2.834 亿（+113.6%）、净利 €1.072 亿。\n- 2026 YTD 营收 €7.181 亿（+69%）；混合键合/数据中心驱动。\n- 2026-06 投资者日：长期目标 €17–22 亿。\n- 竞争：ASMPT、Kulicke & Soffa、EV Group、SUSS MicroTec。\n\n## 经营业绩\n\n| 指标 | 2023 | 2024 | 2025 | Q3 2026 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | €5.79 亿 | €5.15 亿 | €5.91 亿 | €2.834 亿 | +113.6% |\n| 增速 | -? | -11% | +15% | +113.6% | 爆发 |\n| 毛利率 | 约 63% | 约 62% | 待核 | 待核 | ◐ |\n| 营业利润 | 待核 | 待核 | 待核 | 待核 | — |\n| 净利 | €1.77 亿 | €1.28 亿 | 待核 | €1.072 亿 | +323.7% |\n\n- 运营指标：员工 1,856 FTE + 108 临时；2026 YTD 营收 €7.181 亿。\n- 指引：2026 年营收/利润待查；长期目标 €17–22 亿。\n- 市场预期：混合键合/HBM。\n\n## 股权、融资与股票\n\n- 上市：Euronext BESI；1995 年上市。\n- 行情：市值约 €140 亿（2026）；股价/52 周待刷新（◐）。\n- 估值：PS 约 12x（按 2026 年化营收）；PE 待核。\n- 股东：机构为主；具体持股待核。\n- 资本动作：分红/回购；研发/产能投资。\n- 风险提示：客户集中、周期、估值。\n\n## 团队与人员\n\n- 员工 1,856 FTE + 108 临时（2025 末）；研发/制造。\n- Duiven 总部；亚洲/全球。\n- 招聘：2026 年混合键合扩产；具体待采集。\n- 薪酬/股权激励：RSU；流失率未披露。\n- 组织：管理层名单待补。\n\n## 竞争格局\n\n- 直接竞品：ASMPT、Kulicke & Soffa、EV Group、SUSS MicroTec。\n- 替代方案：TCB/其他键合技术。\n- 差异：混合键合精度/客户认证；弱点：客户集中、周期。\n- 竞争动态：HBM/3D 封装扩产；ASMPT/K&S 竞争。\n- 份额：混合键合设备领先（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：客户集中、周期、研发投入。\n- 技术：混合键合良率/精度、3D 集成。\n- 法律/监管：出口管制、欧洲监管。\n- 治理：荷兰上市公司治理。\n- 争议：高估值与订单波动（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：客户名单、混合键合订单、毛利率均未入库。建议跟踪：① 混合键合订单；② 2026 营收；③ HBM/3D 封装；④ 毛利率；⑤ 与 ASMPT/K&S 的份额。\n\n## 信源与口径\n\n- FY2025：https://www.besi.com/investor-relations/press-releases/details/be-semiconductor-industries-nv-announces-q4-25-and-full-year-2025-results/\n- Q3 2026：https://www.besi.com/investor-relations/press-releases/2026/\n- 员工：https://www.marketscreener.com/news/be-semiconductor-industries-n-annual-report-2025-ce7e5cdcdd8bf026\n- 市值/目标：https://quartr.com/events/be-semiconductor-industries-n-v-besi-investor-day-2026_3eFihPox\n- 口径：FY2025 为公司披露；◐ 表示待核。' },
      { id: 'asmpt', name: 'ASMPT', def: '先进封装设备平台：TCB/混合键合，2026 先进封装收入创纪录。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 1975 / 新加坡 | 官网 |\n| 上市地 / 代码 | 港交所 0522 | 1989 上市 |\n| 最新财年营收 | FY2025 约 US$17.6 亿 | 2025 年报/媒体 |\n| 盈利 | FY2025 经调整净利 HK$4.667 亿（+24.5%） | 2026-03-04 发布 |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露；代工/OSAT/存储 | ◐ |\n| 员工 | 约 9,000 人 | Perplexity |\n| 市值 / 估值 | 约 US$86 亿（2026） | Perplexity |\n| 主要股东 | 机构为主 | ◐ |\n| 数据截至 | FY2025；2026 Q2 | — |\n\n## 定位与沿革\n\n先进封装设备平台：以热压键合（TCB）、混合键合、固晶机与 SMT 设备覆盖先进封装/表面贴装；2026 年先进封装收入创纪录，Q3 2026 营收指引 US$6.3–6.9 亿（+46.3% YoY）。\n\n- 1975 年成立，总部新加坡；港交所 0522。\n- 业务：半导体解决方案（先进封装/TCB/混合键合/固晶）、SMT 解决方案。\n- FY2025 营收约 US$17.6 亿（+10%）；先进封装收入 US$5.321 亿；半导体/SMT 占比约 50.8%/43.8%。\n- FY2025 经调整净利 HK$4.667 亿（+24.5%）。\n- 2026 Q1 净利 HK$3.352 亿（+193.5%）；H1 先进封装收入 US$3.39 亿（+17%），创纪录。\n- Q3 2026 营收指引 US$6.3–6.9 亿（+4.8% QoQ、+46.3% YoY）；AI/TCB 驱动。\n- 员工约 9,000 人；市值约 US$86 亿（2026）。\n\n## 创始人与管理层\n\n- **管理层**：Group CEO Bassel Haddad（2026-08 起，◐）；前 CEO Robin Ng。\n- **CFO/CTO**：名单待补。\n- 创始人：1975 年成立；具体创始人待核。\n- 董事会：机构 + 管理层；具体席位待核。\n- 关键人事变动：2026-08 CEO 交接。\n\n## 商业模式\n\n- **收入结构**：半导体解决方案（先进封装/TCB/混合键合/固晶）+ SMT 设备 + 服务。\n- **销售动作**：大客户直销（代工/OSAT/存储）；设备+服务。\n- **单位经济**：设备毛利较高；研发投入高；订单周期。\n- **收入质量**：客户集中；AI/先进封装驱动；SMT 周期。\n- **定价趋势**：TCB/混合键合溢价；按台/配置；服务按合同。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| TCB | 热压键合 | 按台 | 主力 |\n| 混合键合 | 3D 集成 | 按台 | 增长 |\n| 固晶机 | Die Attach | 按台 | 主力 |\n| SMT | 表面贴装 | 按台 | 主力 |\n| 服务/备件 | 维护、升级 | 按合同 | 主力 |\n\n- 包装：设备 + 服务 + 工艺方案；AI/先进封装。\n- 路线图：TCB/混合键合、AI 封装、SMT。\n\n## 技术栈与壁垒\n\n- **架构**：精密运动/键合工艺 + TCB/混合键合；与客户共同开发。\n- **AI 路线**：AI 芯片先进封装设备；HBM/3D。\n- **壁垒**：TCB/混合键合工艺、客户认证、全球服务网络。\n- **依赖与债务**：客户集中、周期、研发投入、竞争。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 代工/OSAT | TCB/混合键合 | 未披露具体数字 | 媒体 |\n| 存储客户 | HBM/3D 封装 | 未披露具体数字 | 媒体 |\n| SMT 客户 | 表面贴装 | 未披露具体数字 | 官网 |\n\n- 客户结构：代工、OSAT、存储、SMT；全球。\n- 集中度：前几大客户占比高（◐）。\n- 续约/流失：设备生命周期长；服务粘性。\n\n## 商业进展\n\n- FY2025 营收约 US$17.6 亿；经调整净利 HK$4.667 亿（+24.5%）。\n- 2026 Q1 净利 HK$3.352 亿（+193.5%）；H1 先进封装收入 US$3.39 亿（+17%），创纪录。\n- Q3 2026 营收指引 US$6.3–6.9 亿（+46.3% YoY）。\n- 2026-08 CEO 交接（Bassel Haddad）；AI/TCB 驱动。\n- 竞争：Besi、Kulicke & Soffa、EV Group。\n\n## 经营业绩\n\n| 指标 | 2023 | 2024 | 2025 | 2026 Q2 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | US$16.0 亿 | US$16.0 亿 | US$17.6 亿 | 待核 | +10% |\n| 增速 | -? | 0% | +10% | 待核 | 复苏 |\n| 毛利率 | 约 40% | 约 40% | 待核 | 待核 | ◐ |\n| 营业利润 | 待核 | 待核 | 待核 | 待核 | — |\n| 净利 | 待核 | 待核 | HK$4.667 亿（经调整） | 待核 | +24.5% |\n\n- 运营指标：先进封装 FY2025 US$5.321 亿；H1 2026 US$3.39 亿；员工约 9,000。\n- 指引：Q3 2026 US$6.3–6.9 亿。\n- 市场预期：AI/TCB/混合键合。\n\n## 股权、融资与股票\n\n- 上市：港交所 0522；1989 年上市。\n- 行情：市值约 US$86 亿（2026）；股价/52 周待刷新（◐）。\n- 估值：PS 约 4.9x；PE 待核。\n- 股东：机构为主；具体持股待核。\n- 资本动作：分红/回购；研发/产能投资。\n- 风险提示：客户集中、周期、CEO 交接。\n\n## 团队与人员\n\n- 员工约 9,000 人；研发/制造/服务。\n- 新加坡总部；中国/全球。\n- 招聘：2026 年先进封装岗位扩张；具体待采集。\n- 薪酬/股权激励：RSU；流失率未披露。\n- 组织：Bassel Haddad（Group CEO，2026-08 起）。\n\n## 竞争格局\n\n- 直接竞品：Besi、Kulicke & Soffa、EV Group、SUSS MicroTec。\n- 替代方案：TCB/其他键合技术。\n- 差异：TCB/混合键合/SMT 平台、全球服务；弱点：客户集中、周期。\n- 竞争动态：HBM/3D 封装扩产；Besi 混合键合竞争。\n- 份额：先进封装设备领先（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：客户集中、周期、CEO 交接。\n- 技术：TCB/混合键合、AI 封装。\n- 法律/监管：出口管制、港股披露。\n- 治理：管理层交接、股东。\n- 争议：先进封装收入占比与估值（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：客户名单、TCB 订单、净利率均未入库。建议跟踪：① 先进封装收入；② Q3 指引；③ HBM/3D 订单；④ CEO 交接；⑤ 与 Besi/K&S 的份额。\n\n## 信源与口径\n\n- 2025 年报：https://www.asmpt.com/site/assets/files/84854/e_00522ar-20260405.pdf\n- 2026 中期：https://www.asmpt.com/en/investor-relations/news-events/asmpt-announces-2026-interim-results/\n- Q3 指引：https://www.asmpt.com/en/investor-relations/financial-information/\n- 市值/员工：https://www.perplexity.ai/finance/ASMVF\n- 口径：FY2025 为年报/媒体；◐ 表示待核。' },
      { id: 'kns', name: 'Kulicke & Soffa', def: '引线键合老兵：TCB 打开先进封装第二曲线，FY2026 营收翻倍。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 1951 / Fort Washington, PA | 官网 |\n| 上市地 / 代码 | NASDAQ: KLIC | 上市多年 |\n| 最新财年营收 | FY2025 $6.541 亿（-7.4%） | FY2025 财报 |\n| 盈利 | FY2025 营业利润约 -$320 万 | FY2025 |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露；OSAT/IDM/代工 | ◐ |\n| 员工 | 约 2,595 人 | Revelio |\n| 市值 / 估值 | 约 $37–39 亿（2026-11） | Yahoo/Morningstar |\n| 主要股东 | 机构为主 | ◐ |\n| 数据截至 | FY2025；Q3 FY2026 | — |\n\n## 定位与沿革\n\n引线键合设备老兵：以引线键合、TCB（热压键合）与先进封装设备切入 AI 封装；FY2025 营收 $6.541 亿（周期低谷），FY2026 营收预计约 $11.5 亿、实现翻倍。\n\n- 1951 年成立，总部 Fort Washington, PA；纳斯达克 KLIC。\n- 产品：引线键合、TCB、先进封装、固晶、测试。\n- FY2025 营收 $6.541 亿（-7.4%）、毛利率约 42.5%、营业利润约 -$320 万（周期低谷）。\n- FY2026 恢复：Q1 营收 $1.996 亿、净利 $1,680 万；Q3 营收 $3.304 亿、净利 $5,740 万、EPS $1.07。\n- FY2026 全年营收预计约 $11.5 亿；AI/先进封装（TCB）驱动。\n- 员工约 2,595 人；市值约 $37–39 亿（2026-11）；股价约 $74–80。\n\n## 创始人与管理层\n\n- **管理层**：CEO/CFO 名单待采集；美国上市公司治理。\n- 创始人：1951 年成立；具体创始人待核。\n- 董事会：机构 + 管理层；具体席位待核。\n- 关键人事变动：2025–2026 年 TCB/先进封装团队扩张。\n\n## 商业模式\n\n- **收入结构**：引线键合设备 + TCB/先进封装 + 固晶/测试 + 服务。\n- **销售动作**：大客户直销（OSAT/IDM/代工）；设备+服务。\n- **单位经济**：设备毛利约 42–45%；周期性强；TCB 毛利较高。\n- **收入质量**：客户集中；AI/先进封装驱动；传统封装周期。\n- **定价趋势**：TCB 溢价；按台/配置；服务按合同。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 引线键合 | 传统封装 | 按台 | 主力 |\n| TCB | 热压键合/先进封装 | 按台 | 增长 |\n| 先进封装 | 2.5D/3D、Fluxless | 按台 | 增长 |\n| 固晶/测试 | Die Attach/测试 | 按台 | 主力 |\n| 服务/备件 | 维护、升级 | 按合同 | 主力 |\n\n- 包装：设备 + 服务 + 工艺方案；AI/先进封装。\n- 路线图：TCB、混合键合、AI 封装。\n\n## 技术栈与壁垒\n\n- **架构**：引线键合/TCB 工艺 + 精密运动；与客户共同开发。\n- **AI 路线**：AI 芯片先进封装（TCB）；HBM/3D。\n- **壁垒**：引线键合装机量、TCB 工艺、客户认证、服务网络。\n- **依赖与债务**：客户集中、周期、TCB 竞争。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| OSAT/IDM | 引线键合/TCB | 未披露具体数字 | 媒体 |\n| 代工/存储 | 先进封装 | 未披露具体数字 | 媒体 |\n| 汽车/工业 | 传统封装 | 未披露具体数字 | 官网 |\n\n- 客户结构：OSAT、IDM、代工、汽车；全球。\n- 集中度：前几大客户占比高（◐）。\n- 续约/流失：设备生命周期长；服务粘性。\n\n## 商业进展\n\n- FY2025 营收 $6.541 亿（-7.4%）、营业利润约 -$320 万（周期低谷）。\n- FY2026 Q1 营收 $1.996 亿、净利 $1,680 万；Q3 营收 $3.304 亿、净利 $5,740 万。\n- FY2026 全年营收预计约 $11.5 亿；AI/TCB 驱动。\n- 股价 2026 年一度 +122% YTD；市值约 $37–39 亿。\n- 竞争：ASMPT、Besi、EV Group。\n\n## 经营业绩\n\n| 指标 | FY2023 | FY2024 | FY2025 | FY2026E | 说明 |\n|---|---|---|---|---|---|\n| 营收 | $7.06 亿 | $7.06 亿 | $6.541 亿 | 约 $11.5 亿 | 翻倍 |\n| 增速 | -? | 0% | -7.4% | +76% | 复苏 |\n| 毛利率 | 约 47% | 约 47% | 42.5% | 待核 | 承压 |\n| 营业利润 | 待核 | 待核 | -$320 万 | 待核 | 转正 |\n| 净利 | 待核 | 待核 | 待核 | Q3 $5,740 万 | ◐ |\n\n- 运营指标：员工约 2,595；TCB 订单增长。\n- 指引：FY2026 营收约 $11.5 亿。\n- 市场预期：AI/TCB/先进封装。\n\n## 股权、融资与股票\n\n- 上市：NASDAQ KLIC。\n- 行情（2026-11）：股价约 $74–80；市值约 $37–39 亿；52 周 $35–136。\n- 估值：PE 约 32.7x；PS 约 3.4x（按 FY2026E）。\n- 股东：机构为主；具体持股待核。\n- 资本动作：分红/回购；研发/产能投资。\n- 风险提示：周期、客户集中、TCB 竞争。\n\n## 团队与人员\n\n- 员工约 2,595 人（Revelio）；研发/制造/服务。\n- Fort Washington 总部；亚洲/全球。\n- 招聘：2026 年 TCB/先进封装扩张；具体待采集。\n- 薪酬/股权激励：RSU；流失率未披露。\n- 组织：管理层名单待补。\n\n## 竞争格局\n\n- 直接竞品：ASMPT、Besi、EV Group、SUSS MicroTec。\n- 替代方案：TCB/混合键合/其他封装。\n- 差异：引线键合装机量、TCB、服务网络；弱点：周期、客户集中。\n- 竞争动态：HBM/3D 封装扩产；ASMPT/Besi 竞争。\n- 份额：引线键合领先、TCB 追赶（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：周期、客户集中、TCB 竞争。\n- 技术：TCB/混合键合、AI 封装。\n- 法律/监管：出口管制、美国披露。\n- 治理：管理层/董事会。\n- 争议：FY2025 亏损与 FY2026 翻倍的波动（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：客户名单、TCB 收入、毛利率均未入库。建议跟踪：① TCB 订单；② FY2026 营收；③ 毛利率；④ 与 ASMPT/Besi 的份额；⑤ 传统封装周期。\n\n## 信源与口径\n\n- Q3 FY2026：https://investor.kns.com/2026-08-05-Kulicke-Soffa-Reports-Third-Quarter-2026-Results\n- FY2025/营收：https://stockanalysis.com/stocks/klic/revenue/\n- 员工：https://www.reveliolabs.com/companies/kulicke-soffa-inds/employees\n- 行情：https://finance.yahoo.com/quote/KLIC/\n- 口径：FY2025 为财报；FY2026E 为媒体/指引；◐ 表示待核。' },
      { id: 'tokyoseimitsu', name: '东京精密', def: '晶圆减薄/研磨设备：先进封装薄片化的关键工序。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 1934 / 东京 | 官网 |\n| 上市地 / 代码 | 东证 7729 | 上市多年 |\n| 最新财年营收 | FY2025/26 约 ¥1,668 亿 | Perplexity/GlobalData |\n| 盈利 | 净利约 ¥247 亿；净利率 15.16% | ◐ |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露；晶圆厂/OSAT | ◐ |\n| 员工 | 2,890 人 | GlobalData |\n| 市值 / 估值 | 约 $38.4 亿（2026-10-26） | PitchBook |\n| 主要股东 | 机构为主 | ◐ |\n| 数据截至 | FY2025/26；2026 | — |\n\n## 定位与沿革\n\n晶圆减薄/研磨与量测设备厂商：ACCRETECH 品牌的晶圆研磨机、减薄机、划片机与针测机是先进封装（薄片化/3D）的关键工序设备。\n\n- 1934 年成立，总部东京；东证 7729；品牌 ACCRETECH。\n- 产品：晶圆研磨/减薄、划片（dicing）、针测（prober）、量测。\n- FY2025/26 营收约 ¥1,668 亿、净利约 ¥247 亿、净利率 15.16%（◐）。\n- 晶圆减薄是先进封装/3D 集成的关键：薄片化、TSV、HBM 堆叠需要高精度研磨。\n- 2026 年先进封装/HBM 需求驱动；具体订单待采集。\n- 员工 2,890 人；市值约 $38.4 亿（2026-10-26）。\n\n## 创始人与管理层\n\n- **管理层**：CEO/CFO 名单待采集；日本上市公司治理。\n- 创始人：1934 年成立；具体创始人待核。\n- 董事会：机构 + 管理层；具体席位待核。\n- 关键人事变动：2025–2026 年先进封装团队扩张。\n\n## 商业模式\n\n- **收入结构**：半导体设备（研磨/减薄/划片/针测/量测）+ 服务。\n- **销售动作**：大客户直销（晶圆厂/OSAT）；设备+服务。\n- **单位经济**：设备毛利较高；研发投入；周期性强。\n- **收入质量**：客户集中；先进封装/HBM 驱动；传统封装周期。\n- **定价趋势**：高精度设备溢价；按台/配置；服务按合同。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 晶圆研磨/减薄 | 薄片化/背面研磨 | 按台 | 主力 |\n| 划片机 | 晶圆切割 | 按台 | 主力 |\n| 针测机 | 晶圆测试 | 按台 | 主力 |\n| 量测 | 精度/表面量测 | 按台 | 增长 |\n| 服务/备件 | 维护、升级 | 按合同 | 主力 |\n\n- 包装：设备 + 服务 + 工艺方案；先进封装/HBM。\n- 路线图：高精度减薄、3D 集成、量测。\n\n## 技术栈与壁垒\n\n- **架构**：精密研磨/切割/量测；与客户共同开发。\n- **AI 路线**：AI 芯片先进封装（薄片化）；HBM/3D。\n- **壁垒**：精度/良率、客户认证、服务网络、日本制造。\n- **依赖与债务**：客户集中、周期、竞争。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 晶圆厂 | 晶圆减薄/研磨 | 未披露具体数字 | 官网 |\n| OSAT | 先进封装薄片化 | 未披露具体数字 | 官网 |\n| HBM/3D 客户 | TSV/堆叠 | 未披露具体数字 | 媒体 |\n\n- 客户结构：晶圆厂、OSAT、存储；全球。\n- 集中度：前几大客户占比高（◐）。\n- 续约/流失：设备生命周期长；服务粘性。\n\n## 商业进展\n\n- FY2025/26 营收约 ¥1,668 亿、净利约 ¥247 亿（◐）。\n- 先进封装/HBM 需求驱动；晶圆减薄设备订单待采集。\n- 2026 年市值约 $38.4 亿；股价/订单待核。\n- 竞争：Disco、Okamoto、Applied Materials、东京精密。\n- 2026 年 3D 集成/薄片化趋势。\n\n## 经营业绩\n\n| 指标 | FY2023 | FY2024 | FY2025/26 | 说明 |\n|---|---|---|---|---|\n| 营收 | 待核 | 待核 | 约 ¥1,668 亿 | ◐ |\n| 增速 | 待核 | 待核 | 待核 | — |\n| 毛利率 | 待核 | 待核 | 待核 | ◐ |\n| 营业利润 | 待核 | 待核 | 待核 | — |\n| 净利 | 待核 | 待核 | 约 ¥247 亿 | 净利率 15.16% |\n\n- 运营指标：员工 2,890；先进封装订单待核。\n- 指引：FY2026/27 待查。\n- 市场预期：HBM/3D 封装薄片化。\n\n## 股权、融资与股票\n\n- 上市：东证 7729。\n- 行情（2026-10-26）：股价 $94.52（ADR/美元口径）；市值 $38.4 亿；流通股 40.6M。\n- 估值：PE 待核；PS 约 2.3x。\n- 股东：机构为主；具体持股待核。\n- 资本动作：分红/回购；研发/产能投资。\n- 风险提示：客户集中、周期、日元汇率。\n\n## 团队与人员\n\n- 员工 2,890 人；研发/制造/服务。\n- 东京总部；日本/全球。\n- 招聘：2026 年先进封装岗位扩张；具体待采集。\n- 薪酬/股权激励：日本上市公司治理；流失率未披露。\n- 组织：管理层名单待补。\n\n## 竞争格局\n\n- 直接竞品：Disco、Okamoto、Applied Materials、东京精密。\n- 替代方案：其他研磨/减薄设备。\n- 差异：精度/良率、日本制造、服务网络；弱点：客户集中、周期。\n- 竞争动态：HBM/3D 封装扩产；Disco 领先。\n- 份额：晶圆减薄设备前列（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：客户集中、周期、汇率。\n- 技术：高精度减薄、3D 集成。\n- 法律/监管：出口管制、日本监管。\n- 治理：日本上市公司治理。\n- 争议：先进封装订单的可持续性（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：客户名单、减薄设备订单、毛利率均未入库。建议跟踪：① HBM/3D 订单；② 2026 营收；③ 毛利率；④ 与 Disco 的份额；⑤ 日元汇率。\n\n## 信源与口径\n\n- 公司官网：https://www.accretech.com/en/zh-tw/\n- 财务：https://www.perplexity.ai/finance/7729.T\n- 员工/营收：https://www.globaldata.com/company-profile/tokyo-seimitsu-co-ltd/\n- 市值：https://pitchbook.com/profiles/company/159836-68\n- 口径：FY2025/26 为第三方口径；◐ 表示待核。' },
      { id: 'ucie', name: 'UCIe 联盟', def: 'Chiplet 互连标准：UCIe 3.0 48/64 GT/s，开放生态的接口底座。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2022 / 行业联盟（无实体总部） | uciexpress.org |\n| 上市地 / 代码 | 不适用（标准组织） | — |\n| 最新财年营收 | 不适用（非营利联盟） | — |\n| 盈利 | 不适用 | — |\n| 现金流 | 不适用 | — |\n| 客户 | 130+ 成员（2026-04） | 第三方统计 |\n| 员工 | 不适用（成员公司工程师） | — |\n| 市值 / 估值 | 不适用 | — |\n| 主要股东 | 成员公司（Intel/AMD/Arm/TSMC/Samsung 等） | 联盟治理 |\n| 数据截至 | 2026-04 | — |\n\n## 定位与沿革\n\nChiplet 互连的开放标准联盟：UCIe（Universal Chiplet Interconnect Express）定义 Die-to-Die 接口，让不同厂商的芯粒可互操作；UCIe 3.0 于 2025-08 发布，数据率提升至 48/64 GT/s。\n\n- 2022-03 发布 UCIe 1.0，由 Intel、AMD、Arm、TSMC、Samsung、Qualcomm 等发起。\n- 2024-08 发布 UCIe 2.0，增加 3D 垂直互连与管理架构。\n- 2025-08 发布 UCIe 3.0：48/64 GT/s、扩展边带、向后兼容 1.0/1.1/2.0。\n- 成员数约 130+（2026-04，第三方口径）；主席为 Intel 的 Debendra Das Sharma。\n- 2026 年 Chiplet Summit 主题演讲；生态 webinar/合规测试推进。\n- 采用仍部分：2026 年多数旗舰 AI 加速器仍用私有互连，UCIe 是开放标准的方向。\n\n## 创始人与管理层\n\n- **Debendra Das Sharma（联盟主席）**：Intel Senior Fellow；主导 UCIe 规范。\n- **董事会/工作组**：由 Intel、AMD、Arm、TSMC、Samsung、Qualcomm 等成员公司代表组成。\n- **组织**：非营利联盟；无传统 CEO/员工体系。\n- 关键人事变动：工作组主席/成员公司代表轮换待采集。\n\n## 商业模式\n\n- **收入结构**：成员会费/赞助；非营利。\n- **销售动作**：标准推广、合规测试、生态合作。\n- **单位经济**：不适用；目标是降低 Chiplet 互连门槛。\n- **收入质量**：不适用。\n- **定价趋势**：规范免费下载；合规测试/会员分级。\n\n## 产品矩阵\n\n| 版本 | 关键能力 | 状态 |\n|---|---|---|\n| UCIe 1.0 | 2D/2.5D Die-to-Die | 已发布 |\n| UCIe 1.1 | 改进可靠性/合规 | 已发布 |\n| UCIe 2.0 | 3D 垂直互连、管理架构 | 已发布 |\n| UCIe 3.0 | 48/64 GT/s、边带扩展 | 2025-08 发布 |\n| 合规测试 | 互操作/一致性 | 推进中 |\n\n- 包装：开放规范 + 合规测试 + 生态推广。\n- 路线图：更高带宽密度、3D 集成、互操作测试。\n\n## 技术栈与壁垒\n\n- **架构**：Die-to-Die 物理层/协议层/边带；2D/2.5D/3D。\n- **AI 路线**：Chiplet 互连是 AI 加速器/多芯粒封装的基础。\n- **壁垒**：开放标准生态、成员广度、合规测试；弱点：私有互连竞争、采用碎片化。\n- **依赖与债务**：成员公司投入、标准落地速度、互操作验证。\n\n## 客户与案例\n\n| 成员/生态 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| Intel/AMD/Arm/TSMC/Samsung | 规范制定/产品采用 | 未披露具体数字 | 联盟 |\n| 芯原/奎芯/Alphawave | UCIe IP | 未披露具体数字 | 成员/产品 |\n| 云厂商/AI 芯片公司 | Chiplet 互连 | 未披露具体数字 | 生态 |\n\n- 成员结构：芯片厂商、IP 厂商、代工/封测、云厂商。\n- 集中度：不适用；联盟治理。\n- 续约/流失：成员续费/新成员加入。\n\n## 商业进展\n\n- UCIe 3.0 2025-08 发布（48/64 GT/s）。\n- 成员 130+（2026-04）；Chiplet Summit 2026 主题演讲。\n- 采用仍部分：多数旗舰 AI 加速器用私有互连；UCIe 生态推进中。\n- 合规测试/互操作 demo 推进；具体产品待采集。\n- 竞争：NVLink、Infinity Fabric、BoW、OpenHBI 等私有/开放互连。\n\n## 经营业绩\n\n| 指标 | 2024 | 2025 | 2026 | 说明 |\n|---|---|---|---|---|\n| 成员数 | 约 110 | 约 120 | 130+ | 第三方口径 |\n| 规范版本 | 2.0 | 3.0 | 3.0 推广 | — |\n| 数据率 | 32 GT/s | 48/64 GT/s | 48/64 GT/s | 3.0 |\n| 采用 | 早期 | 部分 | 部分 | 私有互连仍主流 |\n\n- 财务：不适用（非营利）。\n- 指引：不适用。\n- 市场预期：Chiplet 互连市场增长（第三方预测）。\n\n## 股权、融资与股票\n\n- **不适用（标准组织）**：无股票/市值/融资。\n- 治理：成员公司董事会/工作组。\n- 资金：成员会费/赞助。\n- 流动性：不适用。\n\n## 团队与人员\n\n- 无传统员工；成员公司工程师参与工作组。\n- 主席 Debendra Das Sharma（Intel）。\n- 工作组：物理层、协议层、合规、市场。\n- 关键人事：成员代表轮换待采集。\n\n## 竞争格局\n\n- 私有互连：NVIDIA NVLink、AMD Infinity Fabric、Intel EMIB/UCIe、Arm AMBA.\n- 开放标准：BoW（Bunch of Wires）、OpenHBI、UCIe。\n- 差异：开放/多厂商互操作、成员广度；弱点：私有互连性能/生态、采用碎片化。\n- 竞争动态：AI 加速器多芯粒化；UCIe 与私有互连并存。\n- 份额：开放 Die-to-Die 标准领先（本库估算，◐）。\n\n## 风险与争议\n\n- 标准采用慢于预期；私有互连性能优势。\n- 成员公司利益分歧；合规测试复杂度。\n- 地缘政治/出口管制影响成员合作。\n- 治理：联盟决策效率。\n- 争议：UCIe 能否成为主流（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：成员名单、合规产品、采用率均未入库。建议跟踪：① UCIe 3.0 采用；② 成员数；③ 合规测试；④ 与私有互连的竞争；⑤ 中国厂商参与。\n\n## 信源与口径\n\n- 规范：https://www.uciexpress.org/specifications\n- 成员/生态：https://www.uciexpress.org/blog\n- 市场：https://www.fortunebusinessinsights.com/chiplet-interconnect-and-ucie-ecosystem-market-118045\n- 口径：成员数为第三方统计；联盟非营利，无财务数据。' },
      { id: 'alphawave', name: 'Alphawave', def: '高速 SerDes/IP：被 Qualcomm $23 亿收购，数据中心互连拼图。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2017 / 伦敦/多伦多 | 官网 |\n| 上市地 / 代码 | 已被 Qualcomm 收购（2025-12 完成） | 原 LSE: AWE |\n| 最新财年营收 | 年化约 $3.08 亿；H1 2025 $1.03 亿 | 收购/财报 |\n| 盈利 | 待核 | ◐ |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露； hyperscalers/芯片厂商 | ◐ |\n| 员工 | 未披露 | — |\n| 市值 / 估值 | 收购价约 $23–24 亿 | Qualcomm |\n| 主要股东 | Qualcomm 100%（2025-12 起） | 并表 |\n| 数据截至 | H1 2025；收购 2025-12 | — |\n\n## 定位与沿革\n\n高速 SerDes/IP 厂商：提供 112G/224G SerDes、UCIe/Chiplet 互连与连接 IP；2025-06 Qualcomm 宣布以约 $23–24 亿收购，2025-12 完成，成为 Qualcomm 数据中心战略的拼图。\n\n- 2017 年成立，总部伦敦/多伦多；LSE/NASDAQ 上市（AWE）。\n- 产品：SerDes IP（112G/224G）、UCIe IP、Chiplet、连接/存储 IP。\n- H1 2025 营收 $1.03 亿（2024 同期 $9,100 万）；年化约 $3.08 亿。\n- 2025-06 Qualcomm 宣布收购（约 $24/股，$23–24 亿），2025-12 完成；Alphawave 不再独立上市。\n- 收购估值约 7.8x 收入、47x EBITDA（媒体口径）。\n- Qualcomm 2026 Q1 财报确认完成收购；数据中心/AI 互连是战略重点。\n\n## 创始人与管理层\n\n- **Tony Pialis（创始人/CEO）**：Alphawave 创始人；收购后角色待核。\n- **Qualcomm 管理层**：CEO Cristiano Amon；数据中心团队整合。\n- 董事会：收购后并入 Qualcomm；原董事会解散。\n- 关键人事变动：2025-12 收购完成后的整合。\n\n## 商业模式\n\n- **收入结构**：IP 授权（SerDes/UCIe/连接）+ 版税/服务。\n- **销售动作**：大客户直销（hyperscalers/芯片厂商）；IP 授权。\n- **单位经济**：IP 毛利高；研发投入大；授权周期长。\n- **收入质量**：客户集中；数据中心/AI 驱动；收购后并表。\n- **定价趋势**：按 IP 授权/版税；先进 SerDes 溢价。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| SerDes IP | 112G/224G 高速接口 | 授权+版税 | 主力 |\n| UCIe IP | Chiplet 互连 | 授权 | 增长 |\n| 连接 IP | PCIe/CXL/以太网 | 授权 | 主力 |\n| 存储 IP | 控制器/PHY | 授权 | 增长 |\n| 定制 ASIC | 设计服务 | 项目 | 增长 |\n\n- 包装：IP + 设计服务；数据中心/AI 互连。\n- 路线图：224G SerDes、UCIe、Qualcomm 整合。\n\n## 技术栈与壁垒\n\n- **架构**：高速 SerDes/混合信号 + UCIe；先进制程。\n- **AI 路线**：数据中心/AI 芯片互连；Chiplet。\n- **壁垒**：SerDes IP、客户认证、先进制程；弱点：客户集中、收购整合。\n- **依赖与债务**：Qualcomm 整合、客户集中、竞争。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| Hyperscalers | 数据中心互连 | 未披露具体数字 | 媒体 |\n| 芯片厂商 | SerDes/UCIe IP | 未披露具体数字 | 官网 |\n| Qualcomm | 数据中心/AI | 未披露具体数字 | 收购 |\n\n- 客户结构：hyperscalers、芯片厂商；全球。\n- 集中度：前几大客户占比高（◐）。\n- 续约/流失：IP 授权周期长；先进 SerDes 粘性。\n\n## 商业进展\n\n- 2025-06 Qualcomm 宣布收购（约 $23–24 亿）；2025-12 完成。\n- H1 2025 营收 $1.03 亿；年化约 $3.08 亿。\n- 收购估值约 7.8x 收入；Qualcomm 数据中心战略。\n- 2026 年整合进 Qualcomm；UCIe/224G SerDes 推进。\n- 竞争：Synopsys、Cadence、芯原、奎芯。\n\n## 经营业绩\n\n| 指标 | 2023 | 2024 | H1 2025 | 说明 |\n|---|---|---|---|---|\n| 营收 | 待核 | 约 $3.08 亿 | $1.03 亿 | 年化 |\n| 增速 | 待核 | 待核 | +13% | — |\n| 毛利率 | 待核 | 待核 | 待核 | IP 模式 |\n| 营业利润 | 待核 | 待核 | 待核 | — |\n| 净利 | 待核 | 待核 | 待核 | ◐ |\n\n- 运营指标：客户数/授权数未披露；收购后并表 Qualcomm。\n- 指引：不适用（已并表）。\n- 市场预期：Qualcomm 数据中心/AI 互连。\n\n## 股权、融资与股票\n\n- **不适用（已被收购）**：2025-12 并入 Qualcomm；原 LSE AWE 退市。\n- 收购价：约 $23–24 亿（约 $24/股）；估值约 7.8x 收入。\n- 股东：Qualcomm 100%；原股东现金/股票退出。\n- 流动性：并购退出；无独立 IPO。\n\n## 团队与人员\n\n- 员工数未披露；SerDes/IP 工程师为主。\n- 伦敦/多伦多；全球。\n- 收购后并入 Qualcomm 数据中心团队；留任待核。\n- 薪酬/股权激励：Qualcomm 体系；流失率未披露。\n- 组织：Tony Pialis（创始人）；Qualcomm 整合负责人待核。\n\n## 竞争格局\n\n- 直接竞品：Synopsys、Cadence、芯原股份、奎芯科技、Credo。\n- 替代方案：自研 SerDes、其他 IP 厂商。\n- 差异：112G/224G SerDes、UCIe、先进制程；弱点：客户集中、收购整合。\n- 竞争动态：AI 数据中心互连需求；Qualcomm 整合。\n- 份额：高速 SerDes IP 前列（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：客户集中、收购整合、竞争。\n- 技术：224G SerDes、UCIe、先进制程。\n- 法律/监管：出口管制、并购审查。\n- 治理：Qualcomm 整合；创始人角色。\n- 争议：收购估值与协同（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：客户名单、UCIe IP 收入、Qualcomm 整合均未入库。建议跟踪：① Qualcomm 整合；② 224G SerDes；③ UCIe；④ 客户集中；⑤ 与 Synopsys/芯原的份额。\n\n## 信源与口径\n\n- 收购：https://www.qualcomm.com/news/releases/2025/12/qualcomm-completes-acquisition-of-alphawave-semi\n- H1 2025：https://www.directorstalkinterviews.com/alphawave-semi-reports-h1-2025-results-as-qualcomm-acquisition-progresses/4121217971\n- 估值：https://multiples.vc/private-comps/alphawave-semi\n- 口径：H1 2025 为财报；收购价为媒体；◐ 表示待核。' },
      { id: 'verisilicon', name: '芯原股份', def: '中国芯片 IP 第一股：2025 营收 31.5 亿，Chiplet/GPU IP 放量。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2001 / 上海 | 官网 |\n| 上市地 / 代码 | 科创板 688521 | 2020 IPO |\n| 最新财年营收 | FY2025 ¥31.52 亿（+35.77%） | 2025 年报 |\n| 盈利 | 归母净利 -¥5.28 亿（亏损收窄 12.1%） | 2025 年报 |\n| 现金流 | 待核 | ◐ |\n| 客户 | 未披露；芯片设计/系统厂商 | ◐ |\n| 员工 | 约 2,000+；股权激励覆盖 831 人 | ◐ |\n| 市值 / 估值 | 约 ¥450–500 亿（2026-08；峰值 >¥1,000 亿） | 媒体 |\n| 主要股东 | 戴伟民/机构 | ◐ |\n| 数据截至 | FY2025；2026 H1 | — |\n\n## 定位与沿革\n\n中国芯片 IP 第一股：提供 GPU/NPU/VPU/DSP 等处理器 IP、Chiplet IP 与芯片设计服务；2025 年营收 ¥31.52 亿（+35.77%）、净亏 ¥5.28 亿（收窄），在手订单 ¥124.49 亿（2026-06）。\n\n- 2001 年成立，总部上海；2020 年科创板上市（688521）；戴伟民任董事长/CEO。\n- 业务：IP 授权（GPU/NPU/VPU/DSP/接口）、芯片设计服务、量产服务、Chiplet。\n- FY2025 营收 ¥31.52 亿（+35.77%）、归母净利 -¥5.28 亿（亏损收窄 12.1%）；新签订单 ¥59.60 亿（+103.41%）。\n- 2026 H1 营收 ¥18.64 亿（+91.37%）、归母净利 -¥6.12 亿；量产服务 ¥11.63 亿（+185.29%）、设计服务 ¥3.50 亿（+50.73%）。\n- 2026-06 在手订单 ¥124.49 亿（较 Q1 末 +142.52%）；百亿级算力大单。\n- 2026-08 股权激励覆盖 831 人；考核只看营收（2026–2028 增长 30%/69%/120%），引发争议。\n- 市值约 ¥450–500 亿（2026-08）；峰值曾超 ¥1,000 亿。\n\n## 创始人与管理层\n\n- **戴伟民（创始人、董事长 & CEO）**：芯片 IP 行业资深创业者；主导 Chiplet/IP 战略。\n- **核心团队**：IP/设计服务背景；具体名单待采集。\n- 董事会：戴伟民 + 机构；具体席位待核。\n- 关键人事变动：2026 年股权激励/组织扩张。\n\n## 商业模式\n\n- **收入结构**：IP 授权 + 芯片设计服务 + 量产服务（含 Chiplet）。\n- **销售动作**：大客户直销（芯片设计/系统厂商）；IP 授权/项目制。\n- **单位经济**：IP 毛利高；设计服务/量产毛利较低；研发投入大。\n- **收入质量**：在手订单 ¥124.49 亿；客户集中；亏损扩大。\n- **定价趋势**：IP 按授权/版税；设计服务按项目；量产按芯片。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| 处理器 IP | GPU/NPU/VPU/DSP | 授权+版税 | 主力 |\n| Chiplet IP | UCIe/D2D、芯粒 | 授权 | 增长 |\n| 芯片设计服务 | 定制 SoC/ASIC | 项目 | 主力 |\n| 量产服务 | 晶圆/封装/测试 | 按芯片 | 增长 |\n| 接口 IP | PCIe/SerDes/存储 | 授权 | 增长 |\n\n- 包装：IP + 设计 + 量产；Chiplet/算力方案。\n- 路线图：Chiplet、GPU/NPU、先进制程。\n\n## 技术栈与壁垒\n\n- **架构**：处理器 IP + 设计服务 + Chiplet；先进制程。\n- **AI 路线**：GPU/NPU IP、Chiplet、AI 算力大单。\n- **壁垒**：IP 组合、设计服务能力、客户关系、Chiplet。\n- **依赖与债务**：亏损、客户集中、先进制程/代工、估值。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 芯片设计公司 | GPU/NPU IP | 未披露具体数字 | 官网 |\n| 系统厂商 | 定制 SoC/ASIC | 未披露具体数字 | 官网 |\n| 算力客户 | Chiplet/量产 | 在手订单 ¥124.49 亿 | 2026-06 |\n\n- 客户结构：芯片设计、系统厂商、算力；中国为主。\n- 集中度：前几大客户占比高（◐）。\n- 续约/流失：IP 授权/项目制；订单转化是关键。\n\n## 商业进展\n\n- FY2025 营收 ¥31.52 亿（+35.77%）、净亏 ¥5.28 亿（收窄）。\n- 2026 H1 营收 ¥18.64 亿（+91.37%）、净亏 ¥6.12 亿；量产/设计服务高增。\n- 2026-06 在手订单 ¥124.49 亿；百亿级算力大单。\n- 2026-08 股权激励 831 人；考核只营收。\n- 竞争：Synopsys、Cadence、Alphawave、奎芯。\n\n## 经营业绩\n\n| 指标 | 2023 | 2024 | 2025 | 2026 H1 | 说明 |\n|---|---|---|---|---|---|\n| 营收 | ¥23.38 亿 | ¥23.22 亿 | ¥31.52 亿 | ¥18.64 亿 | +35.77%/+91.37% |\n| 增速 | -12% | -0.7% | +35.77% | +91.37% | 加速 |\n| 毛利率 | 约 40% | 约 40% | 待核 | 待核 | ◐ |\n| 营业利润 | 亏损 | 亏损 | 亏损 | 亏损 | — |\n| 归母净利 | -¥2.96 亿 | -¥6.01 亿 | -¥5.28 亿 | -¥6.12 亿 | 亏损 |\n\n- 运营指标：在手订单 ¥124.49 亿；新签订单 ¥59.60 亿（2025）；股权激励 831 人。\n- 指引：2026–2028 营收增长 30%/69%/120%（股权激励考核）。\n- 市场预期：Chiplet/算力大单、扭亏。\n\n## 股权、融资与股票\n\n- 上市：科创板 688521；2020 IPO。\n- 行情（2026-08）：股价约 ¥93.93；市值约 ¥450–500 亿；峰值 >¥1,000 亿。\n- 估值：PS 约 10x（按 2026 年化）；亏损，PE 不适用。\n- 股东：戴伟民/机构；具体持股待核。\n- 资本动作：股权激励；定增/融资待查。\n- 风险提示：亏损、客户集中、估值。\n\n## 团队与人员\n\n- 员工约 2,000+（◐）；股权激励覆盖 831 人。\n- 上海总部；全球研发/销售。\n- 招聘：2026 年 Chiplet/AI 岗位扩张；具体待采集。\n- 薪酬/股权激励：2026 年股权激励（831 人）；流失率未披露。\n- 组织：戴伟民（董事长/CEO）；业务线负责人待补。\n\n## 竞争格局\n\n- 直接竞品：Synopsys、Cadence、Alphawave、奎芯科技、芯原。\n- 替代方案：自研 IP/设计团队、其他 IP 厂商。\n- 差异：IP 组合/设计服务/Chiplet/中国客户；弱点：亏损、客户集中。\n- 竞争动态：Chiplet/AI 算力需求；国际 IP 厂商竞争。\n- 份额：中国芯片 IP 领先（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：亏损、客户集中、订单转化、估值。\n- 技术：Chiplet、GPU/NPU、先进制程。\n- 法律/监管：出口管制、科创板披露。\n- 治理：创始人控制权、股权激励争议。\n- 争议：只考核营收不考核利润的激励（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：客户名单、Chiplet 收入、毛利率均未入库。建议跟踪：① 在手订单转化；② 2026 营收/亏损；③ Chiplet 收入；④ 股权激励；⑤ 与国际 IP 厂商的份额。\n\n## 信源与口径\n\n- 2025 年报：https://vip.stock.finance.sina.com.cn/corp/view/vCB_AllBulletinDetail.php?stockid=688521&id=12043618\n- 2025 业绩：https://wallstreetcn.com/articles/3768772\n- 2026 H1：https://www.ifnews.com/news.html?aid=860747&cid=49\n- 市值/股权激励：https://finance.sina.cn/stock/ssgs/2026-08-18/detail-inintxxq3188052.d.html\n- 口径：FY2025 为年报；员工总数为估算；◐ 表示待核。' },
      { id: 'kuixin', name: '奎芯科技', def: '国产 UCIe/接口 IP：32Gbps UCIe 硅验证，2026 年被并购。', body: '## 公司快照\n\n| 字段 | 值 | 口径 |\n|---|---|---|\n| 成立 / 总部 | 2021 / 上海 | 官网/融资报道 |\n| 上市地 / 代码 | 未上市；2026 被上市公司跨界收购（◐） | 媒体 |\n| 最新财年营收 | 未披露 | — |\n| 盈利 | 未披露 | — |\n| 现金流 | 未披露 | — |\n| 客户 | 未披露；芯片设计/系统厂商 | ◐ |\n| 员工 | 未披露 | — |\n| 市值 / 估值 | Pre-A/A 轮超亿元；2026 并购估值待核 | 融资/并购 |\n| 主要股东 | 达泰资本、国芯科技、海松资本、铸美投资等 | 融资报道 |\n| 数据截至 | 融资 2023；并购 2026 | — |\n\n## 定位与沿革\n\n国产高速接口 IP/Chiplet 公司：聚焦 UCIe、LPDDR5X、ONFI 5.1 等接口 IP；32Gbps UCIe IP 于 2025-07 完成硅验证，2026 年传出被上市公司跨界收购。\n\n- 2021 年成立于上海；专注高速接口 IP 与 Chiplet。\n- 融资：2021 年底 Pre-A 超亿元；2023-01 A 轮超亿元，达泰资本、国芯科技、海松资本、铸美投资。\n- 产品：UCIe IP、LPDDR5X、ONFI 5.1、Chiplet 方案；已加入 UCIe 联盟。\n- 2025-07 标准封装 32Gbps UCIe IP 完成硅验证，支持 25mm 长距离 Die-to-Die（无需硅中介层）。\n- 2026-09 全球 AI 芯片峰会谈内存定制化/UCIe；2026-10 国芯展 Chiplet 方案。\n- 2026 年媒体报道被一家加油站业务上市公司跨界收购，附业绩承诺/补偿（◐ 估值待核）。\n\n## 创始人与管理层\n\n- **王晓阳（管理层/发言人）**：2026 年全球 AI 芯片峰会代表公司谈 UCIe/内存定制化（◐ 职务待核）。\n- **创始团队**：接口 IP/芯片设计背景；具体名单待采集。\n- 董事会：投资方席位待核。\n- 关键人事变动：2026 年并购后的整合待核。\n\n## 商业模式\n\n- **收入结构**：IP 授权（UCIe/LPDDR/ONFI）+ Chiplet 设计服务。\n- **销售动作**：芯片设计/系统厂商直销；IP 授权/项目制。\n- **单位经济**：IP 毛利高；研发投入大；早期公司。\n- **收入质量**：未披露；客户集中；并购后并表。\n- **定价趋势**：IP 按授权/版税；Chiplet 按项目。\n\n## 产品矩阵\n\n| 产品线 | 功能 | 计价 | 状态 |\n|---|---|---|---|\n| UCIe IP | Die-to-Die/Chiplet | 授权 | 主力 |\n| LPDDR5X IP | 内存接口 | 授权 | 主力 |\n| ONFI 5.1 IP | NAND 接口 | 授权 | 增长 |\n| Chiplet 方案 | 芯粒集成 | 项目 | 增长 |\n| 定制接口 IP | 高速接口 | 授权 | 增长 |\n\n- 包装：IP + Chiplet 方案；国产替代。\n- 路线图：UCIe 2.0/3.0、LPDDR6、Chiplet。\n\n## 技术栈与壁垒\n\n- **架构**：高速接口 IP（UCIe/LPDDR/ONFI）+ Chiplet。\n- **AI 路线**：Chiplet/内存接口；AI 芯片互连。\n- **壁垒**：UCIe 硅验证、国产替代、客户认证；弱点：规模小、并购整合。\n- **依赖与债务**：先进制程/代工、客户集中、并购整合。\n\n## 客户与案例\n\n| 客户 | 场景 | 量化效果 | 口径 |\n|---|---|---|---|\n| 芯片设计公司 | UCIe/接口 IP | 未披露具体数字 | 官网 |\n| 存储/系统厂商 | LPDDR/ONFI | 未披露具体数字 | 官网 |\n| Chiplet 客户 | 芯粒集成 | 未披露具体数字 | 媒体 |\n\n- 客户结构：芯片设计、存储/系统；中国为主。\n- 集中度：未披露；早期客户集中。\n- 续约/流失：IP 授权周期长；硅验证是门槛。\n\n## 商业进展\n\n- 2021 Pre-A、2023 A 轮超亿元；加入 UCIe 联盟。\n- 2025-07 32Gbps UCIe IP 硅验证（25mm 长距离）。\n- 2026-09 全球 AI 芯片峰会；2026-10 国芯展 Chiplet 方案。\n- 2026 年被上市公司跨界收购（◐ 估值/业绩承诺待核）。\n- 竞争：Alphawave、Synopsys、Cadence、芯原。\n\n## 经营业绩\n\n| 指标 | 2023 | 2025 | 2026 | 说明 |\n|---|---|---|---|---|\n| 营收 | 未披露 | 未披露 | 未披露 | 早期 |\n| 增速 | — | — | — | — |\n| 毛利率 | 未披露 | 未披露 | 未披露 | IP 模式 |\n| 营业利润 | 未披露 | 未披露 | 未披露 | — |\n| 员工 | 未披露 | 未披露 | 未披露 | — |\n\n- 运营指标：UCIe IP 硅验证；客户数未披露。\n- 指引：不适用（私有/并购）。\n- 市场预期：国产 UCIe/Chiplet。\n\n## 股权、融资与股票\n\n- **不适用（未上市）**：2026 年被上市公司跨界收购（◐）。\n- 融资：Pre-A 超亿元（2021）、A 轮超亿元（2023）；估值未披露。\n- 股东：达泰资本、国芯科技、海松资本、铸美投资等。\n- 流动性：并购退出；具体对价/业绩承诺待核。\n\n## 团队与人员\n\n- 员工数未披露；接口 IP/芯片设计团队。\n- 上海总部；研发为主。\n- 招聘：2026 年 UCIe/Chiplet 岗位；具体待采集。\n- 薪酬/股权激励：早期公司期权；并购后待核。\n- 组织：王晓阳（管理层，◐）；创始团队待补。\n\n## 竞争格局\n\n- 直接竞品：Alphawave、Synopsys、Cadence、芯原股份。\n- 替代方案：自研接口 IP、其他国产 IP。\n- 差异：UCIe 硅验证、国产替代、Chiplet；弱点：规模小、并购整合。\n- 竞争动态：国产 UCIe/IP 需求；国际厂商领先。\n- 份额：国产 UCIe IP 早期（本库估算，◐）。\n\n## 风险与争议\n\n- 经营：规模小、客户集中、并购整合。\n- 技术：UCIe 2.0/3.0、LPDDR6、先进制程。\n- 法律/监管：出口管制、并购审批。\n- 治理：并购后控制权/业绩承诺。\n- 争议：跨界并购与估值（◐）。\n\n## 本库追踪\n\n本库覆盖为零（线索、大事记、档案均无命中）。缺口：营收、客户、UCIe 订单、并购条款均未入库。建议跟踪：① 并购整合；② UCIe IP 客户；③ LPDDR6；④ 业绩承诺；⑤ 与 Alphawave/芯原的竞争。\n\n## 信源与口径\n\n- 融资：https://m.leiphone.com/category/chips/XY206FlBh6Q1xDmK.html\n- UCIe 硅验证：https://www.sohu.com/a/1088649721_115479\n- 2026 峰会：https://m.jiemian.com/article/15132024.html\n- 口径：私有公司未披露财务；并购估值待核；◐ 表示待核。' },
    ]},
    { key: 'biz', name: '商业模式', en: 'Business Models', desc: '智能如何收费：十种主流模式的适配条件与坑。', pages: [
      { id: 'api-maas', name: 'API / MaaS 按量计费', def: '按 token 计费的模型分销，行业默认商业模式。', body: '## 定义\n\n模型能力按调用量收费（输入/输出差价），开发者即客户。\n\n## 适配与坑\n\n- 适配：能力稀缺、开发者渠道强（前沿 lab 与开源双轮玩家）\n- 坑：同质化后陷入价格战（GLM 1/40 定价）；毛利被推理成本吃掉\n- 关键变量：推理成本曲线下降速度 vs 定价下降速度的赛跑' },
      { id: 'subscription', name: '订阅制（Pro / Max）', def: '面向个人与团队的固定月费，消费级与生产力工具主流。', body: '## 定义\n\nChatGPT Plus/Pro、Claude Max、Cursor Teams：以月费换取更高额度与更强模型。\n\n## 适配与坑\n\n- 适配：高频刚需场景（编码/办公/陪伴），用量可预测\n- 坑：重度用户成本倒挂（推理时扩展让 token 消耗暴增）；需要限额与降级设计\n- 信号：额度政策每次收紧都是成本压力的公开信号' },
      { id: 'ads', name: '广告变现', def: 'ChatGPT Ads 跑通后成为消费 AI 的第二曲线。', body: '## 定义\n\n在对话/答案流中插入商业结果：年化 10 亿美元级（ChatGPT Ads，2026-08）已验证。\n\n## 适配与坑\n\n- 适配：高流量消费入口、商业意图可识别（「推荐一台相机」）\n- 坑：信任税——答案的中立性是产品根基，广告必须与生成内容显式区隔\n- 关键变量：广告相关性引擎能否复用推荐系统积累' },
      { id: 'open-service', name: '开源开放 + 托管服务', def: '权重开源获客，托管/企业版收钱；MongoDB 式路线。', body: '## 定义\n\n开源权重建立生态与标准，向缺运维能力的企业卖托管、企业版与合规保障。\n\n## 适配与坑\n\n- 适配：开源社区强（Qwen/GLM/DeepSeek）、企业要私有化\n- 坑：开源用户自部署分流收入；许可证变更反噬社区\n- 关键变量：开源与闭源旗舰的能力差距（差距小则托管难卖）' },
      { id: 'enterprise', name: '私有化与企业授权', def: '模型 + 交付 + 合规打包卖给企业，客单价最高。', body: '## 定义\n\n私有化部署 + 定制微调 + SLA + 合规审计的企业合同；智谱/Anthropic/大模型集成商的主战场。\n\n## 适配与坑\n\n- 适配：数据不出域、强合规（金融/医疗/政府）\n- 坑：交付重、周期长、成为项目制公司；标准化程度决定能否规模化\n- 关键变量：企业愿意为「数据不出域」付多少溢价' },
      { id: 'outcome', name: '按效果付费', def: '按解决结果而非 token 收费：智能体时代的定价发明。', body: '## 定义\n\n按完成的任务/解决的工单/回收的欠款计费，把模型不确定性从客户侧转移到自己侧。\n\n## 适配与坑\n\n- 适配：结果可客观验证（编码任务、客服工单、回款）\n- 坑：边界纠纷（什么算「解决」）；成本失控（一个难任务烧穿利润）\n- 关键变量：验证器质量——能多精确地判定「完成」' },
      { id: 'compute', name: '算力租赁与转售', def: '把 GPU 与集群按卡时/token 转售，卖铲子的生意。', body: '## 定义\n\nCoreWeave 式算力云 + GPU 租赁 + 云厂商转售；产业链上游的现金流形态。\n\n## 适配与坑\n\n- 适配：资本充足、供应链锁卡能力、大客户长约\n- 坑：重资产 + 技术迭代（卡贬值快）；需求波动导致空转\n- 关键变量：长约锁价与卡代际更替的赛跑' },
      { id: 'data-licensing', name: '数据授权', def: '语料、标注与版权数据向模型方授权收费。', body: '## 定义\n\n版权方（媒体/图库/社区）向训练方授权语料；数据供应链从灰色走向合约化。\n\n## 适配与坑\n\n- 适配：独家高质量语料持有者（Reddit/新闻集团/图库）\n- 坑：定价缺锚；授权一次 vs 按模型迭代的合约设计\n- 关键变量：司法判例（Suno 案等）重塑议价权' },
      { id: 'device', name: 'AI 硬件终端', def: '把模型装进眼镜/耳机/机器人，硬件毛利 + 订阅双收。', body: '## 定义\n\n专用 AI 硬件（眼镜/耳机/玩具/机器人）以硬件 + 订阅双收费，绕开手机入口垄断。\n\n## 适配与坑\n\n- 适配：交互形态与手机差异化明显（无屏幕/全天候/物理动作）\n- 坑：上一代 AI Pin 全军覆没——供应链、良率、需求三重风险\n- 关键变量：端侧模型能力能否撑起「离线也有用」' },
      { id: 'marketplace', name: '开发者生态与分成', def: 'Agent 商店、技能市场与插件分成的平台税。', body: '## 定义\n\n平台聚合第三方 agent/技能/连接器，按使用分成（App Store 模式向 agent 迁移）。\n\n## 适配与坑\n\n- 适配：入口地位稳固、第三方供给丰富（编码 agent / 技能市场先行）\n- 坑：先有鸡还是先有蛋；抽成比例与开发者经济学\n- 关键变量：MCP 类协议让「迁移成本」下降后，平台税还能抽多少' }
    ]},
    { key: 'career', name: '职业路径', en: 'Career Paths', desc: 'AI 行业的职业模式：路径描述、关键动作与风险。', pages: [
      { id: 'lab-track', name: '实验室晋升线', def: '前沿 lab 内的 IC 深耕：初级 → 资深 → Distinguished Fellow。', body: '## 路径\n\n研究科学家/研究工程师入职 → 独立带项目 → 资深（定义方向）→ Distinguished/研究主管。晋升以影响力（论文、能力跃迁、开源）计，而非人数。\n\n## 关键动作\n\n- 前 18 个月做出一个「被组织记住」的贡献\n- 保持一条能长期复利的专长线（如评测、对齐、infra）\n- 风险：lab 竞争剧烈，项目裁撤频繁——押注方向要分散' },
      { id: 'res-eng-dual', name: '研究 ↔ 工程双轨', def: '在研究与工程之间往返：最能积累稀缺组合的路线。', body: '## 路径\n\n工程岗起步 → 参与研究项目 → 沉淀研究品味 → 回工程带团队；双轨切换者比单轨者更稀缺（研究工程师溢价即证明）。\n\n## 关键动作\n\n- 每次切换都要留下可展示资产：论文 or 生产系统\n- 选一个「研究与工程都绕不开」的领域（评测、推理优化、agent）\n- 风险：两头都是深井，浅尝辄止则两头平庸' },
      { id: 'spinout', name: '学术 / 实验室孵化创业', def: '以论文与团队为资产拆出公司：DeepSeek/Mistral 式路线。', body: '## 路径\n\nlab 内做出可产品化成果 → 核心成员带成果拆分 → 融资独立。Mistral（Meta 出走）、DeepSeek（量化基金孵化）皆此形态。\n\n## 关键动作\n\n- 成果必须「可演示」且站在能力前沿的第一排\n- 融资叙事 = 团队 + 一条别人没有的路线（效率/开源/垂直）\n- 风险：前沿追不动即出局；算力资本开支是生死线' },
      { id: 'bigco-startup', name: '大厂 → 创业', def: '带走大厂的资源认知与网络，在模型层之下的应用层创业。', body: '## 路径\n\n大厂 AI 相关岗（产品/工程/研究）积累 2-3 年 → 在「模型能力溢出」的缝隙里创业（垂直 agent、工具、数据）。\n\n## 关键动作\n\n- 创业方向避开大厂主航道（基础模型、通用助手）\n- 带走的是认知与口碑，不是代码（法律风险真实存在）\n- 风险：大厂一款功能发布抹掉整个创业方向——选「不性感但刚需」' },
      { id: 'indie', name: '独立开发者 / 超级个体', def: '一人 + 模型杠杆做出订阅收入的产品组合。', body: '## 路径\n\n用 AI 杠杆独立完成设计/开发/文案/客服 → 多个小产品组合订阅收入；「10 人团队做 100 人产出」是 2026 年的普遍现象。\n\n## 关键动作\n\n- 选「窄而痛」的场景，避开平台与大厂射程\n- 分发即命脉：内容/社区/SEO 至少占一半时间\n- 风险：模型一次升级抹平产品差异——建立非模型依赖的壁垒（数据/社区/集成）' },
      { id: 'consult', name: 'AI 咨询与交付', def: '帮企业落地 AI 的服务生意：诊断、POC、交付、培训。', body: '## 路径\n\n技术/业务背景 → 独立顾问或咨询公司 → 沉淀行业 playbook → 产品化（工具/SaaS）。\n\n## 关键动作\n\n- 选 1-2 个行业深耕，把交付经验变成可复用资产\n- 每个项目沉淀案例与模板（这正是咨询的产品化路径）\n- 风险：项目制天花板；不做产品化永远是卖时间' },
      { id: 'fde-track', name: 'AI 咨询与交付 → FDE', def: '从卖时间的咨询跳到对上线结果负责的部署工程师：服务岗里最接近工程薪酬的一条线。', body: '## 路径\n\n咨询/交付/解决方案岗（或乙方工程师）→ 承接带模型能力的交付项目 → 以 FDE 身份进驻客户现场 → 向上成为交付负责人或行业 playbook 的作者，向外被模型厂商自建团队挖走（Palantir、OpenAI 部署工程均在扩编）。\n\n## 关键动作\n\n- 补上硬证据：一个能演示、能过客户验收的模型系统，胜过十份方案 PPT\n- 建立评测习惯：FDE 的分水岭不是会不会调 API，而是能否证明效果并守住验收口径\n- 认路两条成本曲线：厂商自建团队拿薪酬与筹码，渠道与伙伴体系（腾讯云 ADP 的 FDE 认证即此路径）拿项目与返点——别用同一年薪互相比较\n- 每个项目留一份可复用资产：数据接入模板、评测集、客户侧故障清单\n\n## 风险\n\n- 项目制天花板未消失：不做沉淀就只是换了名字的驻场\n- 薪酬口径混杂：挂牌区间、中位数与调研样本三类数字不可跨源比较，谈薪前先确认样本从哪来\n- 纯实施部分最先被压价：模型能力商品化后，定价权留在「不可外包的现场判断」那一侧' },
      { id: 'investor', name: '研究型投资人', def: '以技术判断力为武器的一级/二级投资人。', body: '## 路径\n\n研究/工程背景 → 天使/VC 投资人（或研究员兼任 advisor）→ 以「看得懂架构与数据」为差异化。\n\n## 关键动作\n\n- 建立自己的技术尽调框架（团队能力 × 路线胜率 × 数据壁垒）\n- 公开写作研究判断，吸引项目主动上门\n- 风险：叙事周期与真实能力的错位——用议题账本校准自己' },
      { id: 'oss-career', name: '开源 → 商业化', def: '以开源项目建立声誉与分发，再转化为商业机会。', body: '## 路径\n\n维护有真实用户的开源项目（agent 框架/评测工具/推理库）→ 咨询与赞助 → 商业版/托管服务或被大厂收编（LangChain→MAF 模式）。\n\n## 关键动作\n\n- 项目要解决「维护者自己每天都疼」的问题\n- 文档与 README 即增长引擎；贡献者社区早建\n- 风险：维护负担与收入不成比例；许可证决策要早' },
      { id: 'switch', name: '转行进入 AI', def: '工程/行业专家以「领域 + 模型」组合切入的再定位。', body: '## 路径\n\n存量专业（医疗/金融/法律/机械）+ 6-12 个月 AI 实操 → 领域 AI 应用岗/创业；「行业知识 × 模型能力」的组合比纯模型能力更稀缺。\n\n## 关键动作\n\n- 用公开作品证明实操（带 eval 的项目、可复现的分析）\n- 从「自己行业的最痛点」切入，而不是追通用热点\n- 风险：只学工具不学原理，工具换代即清零——学评测与上下文工程这类底层' },
      { id: 'portfolio', name: '多栖组合', def: '研究 + 写作 + 顾问 + 投资的收入组合拳。', body: '## 路径\n\n以公开研究/内容建立影响力 → 组合收入：顾问（高时薪）+ 内容/课程（杠杆）+ 天使投资（期权）+ 兼职研究（贴前沿）。\n\n## 关键动作\n\n- 一个可引用的「代表作」贯穿全部收入线\n- 时间分配：影响力 50% / 变现 30% / 学习 20%\n- 风险：多线并行则处处平庸——代表作不响，组合塌方' }
    ]},
    { key: 'ops', name: '操盘手册', en: 'Ops Playbook', desc: '研究→行动闭环的方法论：实验设计、红蓝对抗、合规护栏与系统重构的实操手册。', pages: [
      { id: 'exp-fakedoor', name: '假门测试 Fake Door', def: '产品还没做，先用一个「按钮」测真实需求：点击率即付费意愿的下限证据。', body: '## 定义\n\n在落地页或现有流量里放一个功能入口（按钮/定价卡），统计点击与留资。用户以为功能存在——测的是需求，不是产品。\n\n## 要点\n\n- 判据必须事先写死：如「7 天 200 访客，点击率 ≥8% 即通过」，事后改判据等于作弊\n- 点击 ≠ 付费：假门之后立刻接留资或定金页，把意愿再收敛一层\n- 诚实收尾：测试结束要告知参与者真相，别烧掉早期信任\n\n## 本库视角\n\n登记到实验台（exp），verdict 只认 validated / falsified / inconclusive 三态。' },
      { id: 'exp-woz', name: 'Wizard of Oz 绿野仙踪', def: '前端看起来全自动，后台是你人肉跑流程——用人力换开发时间，验证服务本身是否有需求。', body: '## 定义\n\n用户看到的是完整产品体验，背后的「AI/自动化」实际是手工执行。适用于自动化程度存疑、但服务价值可以先验证的场景。\n\n## 要点\n\n- 先人肉 10 单，把每一步耗时记下来——这是未来自动化的需求文档\n- 单位经济要即时核算：人肉成本 × 规模化后还成立吗\n- 对客户不撒谎：可以不主动说明实现方式，但被问及不能虚构\n\n## 本库视角\n\n与假门组合使用：假门测意愿，Woz 测交付。两者都过再写第一行代码。' },
      { id: 'exp-ab', name: 'A/B 与文案实验', def: '同流量两个版本对照，让数据而不是品味决定标题、定价与落地页。', body: '## 定义\n\n把流量随机分成两组，只改一个变量（标题/价格/CTA），以转化率为判据。\n\n## 要点\n\n- OPC 流量小：别做经典 A/B，做序贯实验——先 A 后 B，各 100 访客看方向\n- 一次只改一个变量，否则赢也不知道是谁的功劳\n- 定价实验最值钱：同样的页面，$49 和 $79 的点击质量完全不同\n\n## 本库视角\n\n成本记入成本 ROI（meta/roi），产出记 experiment 数——研究流程本身也要接受 ROI 审计。' },
      { id: 'exp-coldemail', name: '冷邮件批次实验', def: '50 封个性化冷邮件是一次市场调研，不是推销——回复率即痛点强度的直接读数。', body: '## 定义\n\n选一个小而准的名单，发高度个性化的短邮件，测的是「这个痛点值不值得对方花 15 分钟」。\n\n## 要点\n\n- 三句话结构：对方的具体痛点 → 你观察到的证据 → 一个小请求；不谈功能不贴附件\n- 名单质量 > 数量：50 个精准联系人胜过 5000 个买来的地址\n- 读数口径：回复率 >10% 说明痛点真实；0 回复先怀疑名单，再怀疑文案\n- 合规：商业邮件提供可退订路径，不冒充、不批量爬取个人邮箱\n\n## 本库视角\n\n每次批次登记实验，回复率写入实验结果，作为机会卡痛点维度的校准证据。' },
      { id: 'redmethod', name: '红蓝对抗方法论', def: '影子董事会五角色 + 做空报告 + 偏见审计：用流程对抗自己的确认偏误。', body: '## 定义\n\n重大投入前强制过三道认知关卡：① 五位立场极端的角色（CFO/Growth/律师/黑客/做空）轮询拷问；② 整理一份全力论证失败的做空报告；③ 偏见审计清单过滤技术自嗨与类比推理。\n\n## 要点\n\n- 顺序不可反：先让反方说完，再看正方——顺序反了就只剩确认\n- 每个角色的反方证据要落到可查的条目（失败公司名、ToS 条款、数字），不接受「可能不行」\n- 做空失败的标志是「找不到足够反面证据」，这本身是强买入信号\n- 输出存进做空报告（red/short），下一个人复核时看得见上一次的判断\n\n## 本库视角\n\n本台不内置 LLM：每位角色的完整 Prompt 复制到任意模型执行，回答要点人工回填。' },
      { id: 'license', name: '许可合规实操', def: '依赖树里的每一行代码都有主人：传染性对照 + 选型清单的落地做法。', body: '## 定义\n\n引入任何依赖前完成三件事：读 LICENSE 原文、查传递依赖的许可、判断自己的分发形态触发哪些义务。\n\n## 要点\n\n- 分发形态决定义务：SaaS 不分发（GPL 不触发但 AGPL 触发）、桌面/移动分发（GPL 触发）、仅内部工具（最宽松）\n- 模型权重许可独立于代码许可：Llama 类社区许可的用户数与命名条款单独看\n- NOTICE 与版权声明的传递义务最容易漏，交付时附第三方许可清单\n- 拿不准的场景（BSL/SSPL 的生产使用边界）：假设最严格解释，或直接写信问版权方\n\n## 本库视角\n\n对照表在护栏台（risk/license）；引入新依赖后在平台依赖台账记一行。' },
      { id: 'dep-exit', name: '平台依赖退出清单', def: '每一个「离不开」的上游都要有一份写下来的退出预案——写不出来就是真风险。', body: '## 定义\n\n对每个评分 ≥4 的平台依赖，完成一份退出文档：数据怎么导出、功能怎么替代、切换要多少小时、切换期间对客户说什么。\n\n## 要点\n\n- 退出演练每季度一次：真的切到备选跑一遍核心路径，记录耗时与坑\n- 价格波动记入 priceLog：连续两次上调就是启动迁移的信号\n- ToS 风险条款（竞品限制、数据使用、终止权利）逐条摘录并注明日期\n- 永远保持至少一条不经过该平台的完整交付路径（哪怕更贵）\n\n## 本库视角\n\n台账在护栏台（risk/deps）；阈值告警由 depThreshold 控制，与混沌演习（risk/chaos）联动。' },
      { id: 'quarterly', name: '季度重构仪式', def: '每季度 2-3 天不做研究，只优化系统本身：删、并、升级、归档。', body: '## 定义\n\n系统与代码一样会腐烂。固定仪式：删掉无产出的数据源与流程、合并功能重叠的自动化、检查在用模型的经济性、归档只读不用的台账、排期下一季。\n\n## 要点\n\n- 判据用数据不用感觉：成本 ROI 垫底的流程、连败降权的信源、30 天未打开的台账\n- 升级检查对照模型登记册定价对比：同样的活，有没有更便宜的模型能干\n- 重构产出写进执行记录（sys.review）：做了什么、下季重点——留下审计痕迹\n- 仪式本身也要接受审计：连续两季没砍掉任何东西，说明审计在走过场\n\n## 本库视角\n\n清单在系统台（meta/review），排期联动年度日历。警惕「准备悖论」：优化系统的最高形式，是敢于把它关掉去见客户。' }
    ]}
  ]
};
